INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1306368, '더 립', 'The Rip', 'movie', 'https://image.tmdb.org/t/p/w500/o0d6Us9VWOW0nHhoB7ZNIwigARG.jpg', 'https://image.tmdb.org/t/p/original/3F2EXWF1thX0BdrVaKvnm6mAhqh.jpg', '허름한 은닉처에서 수백만 달러의 현금을 발견한 마이애미 경찰. 신뢰에 금이 가기 시작하면서 모든 사람, 모든 것이 의심의 대상이 된다.', '2026-01-16', 7.047, 483.0807, 113, '조 카나한', 676, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1043197, '더스트 바니', 'Dust Bunny', 'movie', 'https://image.tmdb.org/t/p/w500/vobigFZFvbYPf6ElYJu07P9rH8C.jpg', 'https://image.tmdb.org/t/p/original/AecGG1XVCmkk7fT10ko3FC0dLIP.jpg', '“어른도 아이도 함께하는 몬스터 사냥 이야기”  열 살 소녀 오로라는 침대 밑에 숨어 있다고 믿는 정체불명의 괴물 때문에 자신의 가족이 사라졌다고 믿는다. 아무도 그녀의 말을 믿어주지 않자, 오로라는 복도를 사이에 둔 신비로운 이웃 - 몬스터 -를 사냥하는 것으로 보이는 청부살인업자에게 도움을 청한다. 그는 처음엔 의심하면서도 그녀의 부탁을 받아들이고, 두 사람은 함께 진짜 괴물과 맞서며 이들이 마주한 위험한 세상과 서로의 상처를 이해해 가게 되는데…', '2025-12-11', 6.766, 378.7072, 106, 'Bryan Fuller', 93, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1242898, '프레데터: 죽음의 땅', 'Predator: Badlands', 'movie', 'https://image.tmdb.org/t/p/w500/8lpCbwbYh9SSzCFsHDndZHKrcD4.jpg', 'https://image.tmdb.org/t/p/original/ebyxeBh56QNXxSJgTnmz7fXAlwk.jpg', '프레데터로서 존재를 증명하기 위해 우주에서 가장 위험한 행성으로 첫 사냥에 나선 덱. 죽음의 땅에 도사린 모든 것으로부터 공격을 받던 순간, 휴머노이드 티아를 만난다. 최상위 포식자 칼리스크에 맞서게 된 둘은 생존과 각자의 목적을 위해 극한의 사투를 벌이게 되는데…', '2025-11-05', 7.779, 266.6882, 107, '댄 트랙턴버그', 1615, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (83533, '아바타: 불과 재', 'Avatar: Fire and Ash', 'movie', 'https://image.tmdb.org/t/p/w500/l18o0AK18KS118tWeROOKYkF0ng.jpg', 'https://image.tmdb.org/t/p/original/u8DU5fkLoM5tTRukzPC31oGPxaQ.jpg', '인간들과의 전쟁으로 첫째 아들 ‘네테이얌’을 잃은 후, ‘제이크’와 ‘네이티리’는 깊은 슬픔에 빠진다. 상실에 빠진 이들 앞에 ''바랑''이 이끄는 재의 부족이 등장하면서, 판도라는 더욱 큰 위험에 빠지게 되고, ‘설리’ 가족은 선택의 기로에 서게 되는데…', '2025-12-17', 7.326, 264.9358, 195, '제임스 카메론', 1584, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (991494, '스폰지밥 무비: 네모바지를 찾아서', 'The SpongeBob Movie: Search for SquarePants', 'movie', 'https://image.tmdb.org/t/p/w500/2QCGC4toQXYuIsWKj5vJQRAdPjd.jpg', 'https://image.tmdb.org/t/p/original/gbjK8p5S1aLXWCwOoXqr9aWZvqG.jpg', '비키니시티에 사는 스폰지밥은 무시무시한 롤러코스터를 탈 수 있는 용감한 ‘빅 가이’가 꿈이다. 그러던 어느 날, 미지의 세계 ‘언더월드’에 사는 유령선장을 만나 ‘용감무쌍짱 증명서’를 받으면 진정한 ‘빅 가이’가 될 수 있다는 말을 들은 스폰지밥은 절친 뚱이와 함께 해적선을 찾아 위험천만한 모험을 떠난다. 그 사실을 안 집게사장과 징징이, 핑핑이는 스폰지밥을 구하기 위해 따라나서는데…', '2026-01-01', 6.5, 189.9469, 96, 'Derek Drymon', 101, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1084242, '주토피아 2', 'Zootopia 2', 'movie', 'https://image.tmdb.org/t/p/w500/ib6v6qUXzez1x2qIOLN7C0yJNPQ.jpg', 'https://image.tmdb.org/t/p/original/7nfpkR9XsQ1lBNCXSSHxGV7Dkxe.jpg', '미스터리한 뱀 게리가 나타난 순간, 주토피아가 다시 흔들리기 시작했다! 혼란에 빠진 도시를 구하기 위해 환상의 콤비 주디와 닉이 잠입 수사에 나서고 상상 그 이상의 진실과 위협을 마주하게 되는데...!', '2025-11-26', 7.583, 175.0638, 108, '재러드 부시', 1160, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1242501, '아이스폴', 'Icefall', 'movie', 'https://image.tmdb.org/t/p/w500/5jqga2F2nkBHWM4Ip5qha8gANpJ.jpg', 'https://image.tmdb.org/t/p/original/gQimJqYMKCkwHIo8wwYKhmnCfBr.jpg', '극한의 추위가 몰아치는 북미 오지. 젊은 야생동물 관리인이 베테랑 밀렵꾼을 체포하며 사건이 시작된다. 밀렵꾼은 우연히 얼어붙은 호수 아래 추락한 비행기와 수백만 달러의 현금이 있다는 엄청난 비밀을 털어놓는다.  현금의 소문은 순식간에 퍼지고, 부패한 경찰부터 무자비한 범죄자들까지 현장으로 몰려든다. 눈앞의 돈을 차지하려는 인간들의 욕망은 극에 달하고, 추락 지점인 위험천만한 얼음 호수는 삽시간에 아비규환으로 변한다.  언제 깨질지 모르는 살얼음판 위에서, 살아남기 위해 한 팀이 된 관리인과 밀렵꾼은 현금과 목숨을 건 최후의 생존 게임을 시작한다. 과연 그들은 서로를 믿고 이 얼음 지옥에서 탈출할 수 있을까?', '2025-10-16', 6.381, 163.8917, 99, 'Stefan Ruzowitzky', 101, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1368166, '하우스메이드', 'The Housemaid', 'movie', 'https://image.tmdb.org/t/p/w500/fUDX16A4fJXmAuUA5t0pnqzXS0b.jpg', 'https://image.tmdb.org/t/p/original/sK3z0Naed3H1Wuh7a21YRVMxYqt.jpg', '과거를 숨긴 채 완벽한 저택의 가정부로 들어간 밀리가 이상한 행동을 보이는 아내 니나와 그런 아내를 이해하는 모범적인 남편 앤드루와 얽히며 닫힌 문 뒤의 거짓과 마주하게 되는 월드 베스트셀러 원작의 고자극 미스터리 스릴러', '2026-01-28', 7.086, 178.8952, 132, '폴 피그', 504, 0);
