INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1387382, '헌팅시즌', 'Hunting Season', 'movie', 'https://image.tmdb.org/t/p/w500/7OPedgbyapZ8LjIQIMIh72ZEfW6.jpg', 'https://image.tmdb.org/t/p/original/eJ0HooOOD1uzI39CfOQNWIiWKlJ.jpg', '은둔하며 살아가던 생존 전문가와 그의 딸은 강가에서 상처 입은 정체불명의 여자를 구조하게 된다. 그러나 이로 인해 그들은 폭력과 복수의 잔혹한 소용돌이에 휘말리게 되고 살아남기 위해 잔혹한 범죄자와 맞서야만 한다.', '2026-01-23', 7.1, 46.4583, 93, 'Raja Collins', 120, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (911430, 'F1 더 무비', 'F1', 'movie', 'https://image.tmdb.org/t/p/w500/bvVoP1t2gNvmE9ccSrqR1zcGHGM.jpg', 'https://image.tmdb.org/t/p/original/ZtcGMc204JsNqfjS9lU6udRgpo.jpg', '한때 주목받는 유망주였지만 끔찍한 사고로 F1®에서 우승하지 못하고 한순간에 추락한 드라이버 소니 헤이스. 그의 오랜 동료인 루벤 세르반테스에게 레이싱 복귀를 제안받으며 최하위 팀인 APXGP에 합류한다.  그러나 팀 내 떠오르는 천재 드라이버 조슈아 피어스와 소니 헤이스의 갈등은 날이 갈수록 심해지고. 설상가상 우승을 향한 APXGP 팀의 전략 또한 번번이 실패하며 최하위권을 벗어나지 못하고 고전하는데···', '2025-06-25', 7.793, 46.2053, 140, '조셉 코신스키', 3146, 0);
