INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (858024, '햄넷', 'Hamnet', 'movie', 'https://image.tmdb.org/t/p/w500/96ikpEmn7Uxct77x6kTIUgnldh2.jpg', 'https://image.tmdb.org/t/p/original/uRDu9DiTVf97z5sj6qesmyQpYji.jpg', '자연 속에서 자유롭게 살아온 ‘아녜스’는 마을에 새로 온 교사 ‘윌리엄 셰익스피어’와 사랑에 빠져 가정을 이룬다. 어느 날, 두 사람에게 예기치 못한 비극이 찾아오고 삶의 가장 소중한 것을 잃은 참혹한 상실의 고통 속에서 두 사람은 각자의 방식으로 상처와 비극을 극복하게 되는데…', '2026-02-25', 7.8, 45.7592, 126, '클로이 자오', 106, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (575265, '미션 임파서블: 파이널 레코닝', 'Mission: Impossible - The Final Reckoning', 'movie', 'https://image.tmdb.org/t/p/w500/c5pDU8SW0ZbmO5jHfw7fX6keyyR.jpg', 'https://image.tmdb.org/t/p/original/xPNDRM50a58uvv1il2GVZrtWjkZ.jpg', '디지털상의 모든 정보를 통제할 수 있는 사상 초유의 무기로 인해 전 세계 국가와 조직의 기능이 마비되고, 인류 전체가 위협받는 절체절명의 위기가 찾아온다. 이를 막을 수 있는 건 오직 존재 자체가 기밀인 에단 헌트와 그가 소속된 IMF뿐이다. 무기를 무력화하는 데 반드시 필요한 키를 손에 쥔 에단 헌트. 오랜 동료 루터와 벤지, 그리고 새로운 팀원이 된 그레이스, 파리, 드가와 함께 지금껏 경험했던 그 어떤 상대보다도 강력한 적에 맞서 모두의 운명을 건 불가능한 미션에 뛰어든다.', '2025-05-17', 7.196, 44.7626, 170, '크리스토퍼 맥쿼리', 2460, 0);
