INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1218925, '극장판 체인소 맨:  레제편', '劇場版 チェンソーマン レゼ篇', 'movie', 'https://image.tmdb.org/t/p/w500/oTn0PoR8gSMpMqJaT2pUtkkN0Ia.jpg', 'https://image.tmdb.org/t/p/original/7BnTZKp5lVdaA7dlCG6y8TAiL7f.jpg', '데블 헌터로 일하는 소년 ‘덴지’는 조직의 배신으로 죽음에 내몰린 순간 전기톱 악마견 ‘포치타’와의 계약으로 하나로 합쳐져 누구도 막을 수 없는 존재 ‘체인소 맨’으로 다시 태어난다. 악마와 사냥꾼, 그리고 정체불명의 적들이 얽힌 잔혹한 전쟁 속에서 ‘레제’라는 이름의 미스터리한 소녀가 ‘덴지’ 앞에 나타나는데… ‘덴지’는 사랑이라는 감정에 이끌려 지금껏 가장 위험한 배틀에 몸을 던진다!', '2025-09-24', 8.3, 43.2696, 100, '요시하라 타츠야', 637, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1313003, '유리창 너머의 유혹', 'Muori di lei', 'movie', 'https://image.tmdb.org/t/p/w500/7Sw1yOZl9KlUvNK9YZTDPFtnWRb.jpg', 'https://image.tmdb.org/t/p/original/jHDczXDoze03wW8tiextMCk5REA.jpg', '코로나19 팬데믹이 한창인 로마, 팔불출 아버지를 둔 의사 ‘사라’와 고등학교 교사 ‘루카’는 비록 아이는 없지만 안정적인 결혼 생활을 이어가고 있다. 어느 날, 옆집으로 이사 온 매혹적인 댄서 ‘아만다’. 루카는 우연한 계기로 그녀와 대화를 나누게 되고 점차 알 수 없는 끌림에 빠져들어 몰래 작업실에서 건너편 그녀의 방을 엿보기 시작한다. 며칠 후, 수상한 불청객이 아만다의 집을 방문하고 루카는 그가 아만다에게 폭력을 행사하는 것을 목격하게 되는데…', '2025-08-13', 5.6, 42.9979, 104, 'Stefano Sardo', 44, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (157336, '인터스텔라', 'Interstellar', 'movie', 'https://image.tmdb.org/t/p/w500/evoEi8SBSvIIEveM3V6nCJ6vKj8.jpg', 'https://image.tmdb.org/t/p/original/5XNQBqnBwPA9yT0jZ0p3s8bbLh0.jpg', '세계 각국의 정부와 경제가 완전히 붕괴된 미래가 다가온다. 지난 20세기에 범한 잘못이 전 세계적인 식량 부족을 불러왔고, NASA도 해체되었다. 나사 소속 우주비행사였던 쿠퍼는 지구에 몰아친 식량난으로 옥수수나 키우며 살고 있다. 거센 황사가 몰아친 어느 날 알 수 없는 힘에 이끌려 딸과 함께 도착한 곳은 인류가 이주할 행성을 찾는 나사의 비밀본부. 이 때 시공간에 불가사의한 틈이 열리고, 이 곳을 탐험해 인류를 구해야 하는 임무를 위해 쿠퍼는 만류하는 딸을 뒤로한 채 우주선에 탑승하는데...', '2014-11-06', 8.466, 42.9725, 169, '크리스토퍼 놀란', 38688, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1205229, 'Night of the Zoopocalypse', 'Night of the Zoopocalypse', 'movie', 'https://image.tmdb.org/t/p/w500/nCejOVZcOxKS27nnbh28NKXOdXF.jpg', 'https://image.tmdb.org/t/p/original/h2SEtzuABKmcZAnKBJ1za3kETTY.jpg', '', '2025-01-23', 6.585, 42.4492, 92, 'Rodrigo Perez-Castro', 71, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1575337, '초(超) 가구야 공주!', '超かぐや姫！', 'movie', 'https://image.tmdb.org/t/p/w500/4Gh56xcxDoWWPuTclaKpKrZ3J4M.jpg', 'https://image.tmdb.org/t/p/original/tRQZUR3oTHSsSmZHDX77bbDxNxT.jpg', '달에서 도망쳐 온, 자유분방한 가구야가 이로하의 집에 살게 되면서, 이로하의 삶은 궤도를 이탈할 지경이다. 게다가 가구야는 이로하에게 가상 세계에서 함께 무대에 서자고 설득한다.', '2026-01-22', 8.571, 41.2079, 143, '山下清悟', 7, 0);
