INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1100988, '28년 후', '28 Years Later', 'movie', 'https://image.tmdb.org/t/p/w500/zRo90O0bTKJem1aDgVa6Sm0gthE.jpg', 'https://image.tmdb.org/t/p/original/wxxSyWPPgssnkO6FbCAVyntLLSr.jpg', '28년 전 생물학 무기 연구소에서 세상을 재앙으로 몰아넣은 바이러스가 유출된 후, 일부 생존자들이 모여 철저히 격리된 채 살아가는 섬 홀리 아일랜드. 이곳에서 태어나 한 번도 섬 밖을 나가 본 적 없는 소년 스파이크는 어느 날 섬을 떠나 본토에 발을 들이게 되고 난생처음 바이러스에 잠식된 세상을 마주하게 된다. 변이된 바이러스는 10,228일의 시간 동안 감염자들을 더욱 충격적으로 진화시켰고 스파이크는 그 실체를 목격하며 극강의 공포에 휩싸이게 되는데...', '2025-06-19', 6.627, 40.4419, 115, '대니 보일', 2101, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1336189, '딜리버리 런', 'Delivery Run', 'movie', 'https://image.tmdb.org/t/p/w500/eCA5maHDlZtXNTtiLXenwnEw7tc.jpg', 'https://image.tmdb.org/t/p/original/hvut2slhhgJ31UNa9Df7jFfAS0x.jpg', '음식 배달원 한 명이 눈 덮인 미네소타 황무지에서 치명적인 추격전에 휘말린다. 알 수 없는 이유로 미친 제설차 운전사에게 쫓기게 된 그는 목숨을 위협하는 상황 속에서, 끈질긴 추적자를 홀로 따돌려야 한다.', '2025-09-10', 5.721, 40.203, 84, 'Joey Palmroos', 34, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1315303, '프라이메이트', 'Primate', 'movie', 'https://image.tmdb.org/t/p/w500/4Q5IClJJyKUHKNLywQaqwcK00OF.jpg', 'https://image.tmdb.org/t/p/original/isx3gXPkrt37ERtW47hhTdJD0Pg.jpg', '광견병에 걸린 침팬지 ''벤''에게서 벗어나 생존하려는 주인공 ''루시''와 친구들의 이야기를 그린 공포 영화', '2026-01-28', 6.77, 40.0968, 89, 'Johannes Roberts', 50, 0);
