INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1116465, '성룡의 전설', '传说', 'movie', 'https://image.tmdb.org/t/p/w500/ju8tnsveoxWymYx3jQRXNX93pUY.jpg', 'https://image.tmdb.org/t/p/original/7FDVhmCur4LMOfnXMteiSCtsdOb.jpg', '고고학자 첸은 학생들과 발굴 작업 중, 옥으로 만들어진 신비한 목걸이를 발견한다. 때는 한나라, 흉노 족에게 쫓기던 공주 멍윈을 구해준 장군 조전은 나라를 지키기 위한 그들과의 전쟁을 준비한다. 시간은 다시 현재, 목걸이가 꿈속에서 본 과거와 현실을 연결시켜준다는 것을 깨달은 첸은 피할 수 없는 운명의 소용돌이에 휩싸이는데…', '2024-07-05', 6.824, 34.0895, 129, '당계례', 139, 0);
