INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (238, '대부', 'The Godfather', 'movie', 'https://image.tmdb.org/t/p/w500/1yvBkSv4ZLS1GohlmMDmdpSgfYo.jpg', 'https://image.tmdb.org/t/p/original/tSPT36ZKlP2WVHJLM4cQPLSzv3b.jpg', '시실리에서 이민온 뒤, 정치권까지 영향력을 미치는 거물로 자리잡은 돈 꼴레오네는 갖가지 고민을 호소하는 사람들의 문제를 해결해주며 대부라 불리운다. 한편 솔로소라는 인물은 꼴레오네가와 라이벌인 탓타리아 패밀리와 손잡고 새로운 마약 사업을 제안한다. 돈 꼴레오네가 마약 사업에 참여하지 않기로 하자, 돈 꼴레오네를 저격해 그는 중상을 입고 사경을 헤매게 된다. 그 뒤, 돈 꼴레오네의 아들 소니는 조직력을 총 동원해 다른 패밀리들과 피를 부르는 전쟁을 시작하는데... 가족의 사업과 상관없이 대학에 진학한 뒤 인텔리로 지내왔던 막내 아들 마이클은 아버지가 총격을 당한 뒤, 아버지를 구하기 위해 위험천만한 협상 자리에 나선다.', '1972-12-27', 8.687, 30.6647, 175, '프랜시스 포드 코폴라', 22348, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1078605, '웨폰', 'Weapons', 'movie', 'https://image.tmdb.org/t/p/w500/lcu0aRFg7lzmzxGzpkYCeN4XRjh.jpg', 'https://image.tmdb.org/t/p/original/9mKhhHBfIAWy9TNVHAXqMEFokes.jpg', '평범한 수요일, 어느 마을 학교의 같은 반 학생 17명이 등교하지 않는다. 그날 새벽 2시 17분, 잠에서 깬 아이들이 어둠 속으로 달려가 돌아오지 않았기 때문이다. 유일하게 남은 아이는 입을 다물고, 사라진 아이들을 찾으려는 이들은 악몽 같은 현실을 마주하게 되는데…', '2025-10-15', 7.288, 30.0457, 129, '잭 크리거', 2775, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1180831, '트롤의 습격 2', 'Troll 2', 'movie', 'https://image.tmdb.org/t/p/w500/E5eqWkxgKeodl215pspacSucSJ.jpg', 'https://image.tmdb.org/t/p/original/lZYMXx74pWmbj5Q5jp1QaMvmuuR.jpg', '또다시 위험한 트롤이 깨어나 나라 전역을 초토화한다. 이에 노라와 안드레아스, 크리스 소령은 그 어느 때보다 위험천만한 임무에 뛰어드는데.', '2025-12-01', 6.547, 29.4415, 105, '로아르 우테우', 372, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (597, '타이타닉', 'Titanic', 'movie', 'https://image.tmdb.org/t/p/w500/132KjhVrWUqKFVfMAKKNkherytA.jpg', 'https://image.tmdb.org/t/p/original/xnHVX37XZEp33hhCbYlQFq7ux1J.jpg', '"내 인생의 가장 큰 행운은 당신을 만난 거야" 우연한 기회로 티켓을 구해 타이타닉호에 올라탄 자유로운 영혼을 가진 화가 ‘잭’(레오나르도 디카프리오)은 막강한 재력의 약혼자와 함께 1등실에 승선한 ‘로즈’(케이트 윈슬렛)에게 한눈에 반한다. 진실한 사랑을 꿈꾸던 ‘로즈’ 또한 생애 처음 황홀한 감정에 휩싸이고, 둘은 운명 같은 사랑에 빠지는데… 가장 차가운 곳에서 피어난 뜨거운 사랑! 영원히 가라앉지 않는 세기의 사랑이 펼쳐진다!', '1999-03-13', 7.9, 29.0314, 194, '제임스 카메론', 26694, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (278, '쇼생크 탈출', 'The Shawshank Redemption', 'movie', 'https://image.tmdb.org/t/p/w500/qV9BQZdiM8foEzDz0Ag5hGWE5qM.jpg', 'https://image.tmdb.org/t/p/original/zfbjgQE1uSd9wiPTX4VzsLi0rGG.jpg', '촉망받는 은행 간부 앤디 듀프레인은 아내와 그녀의 정부를 살해했다는 누명을 쓴다. 주변의 증언과 살해 현장의 그럴듯한 증거들로 그는 종신형을 선고받고 악질범들만 수용한다는 지옥같은 교도소 쇼생크로 향한다. 인간 말종 쓰레기들만 모인 그곳에서 그는 이루 말할 수 없는 억압과 짐승보다 못한 취급을 당한다. 그러던 어느 날, 간수의 세금을 면제받게 해 준 덕분에 그는 일약 교도소의 비공식 회계사로 일하게 된다. 그 와중에 교도소 소장은 죄수들을 이리저리 부리면서 검은 돈을 긁어 모으고 앤디는 이 돈을 세탁하여 불려주면서 그의 돈을 관리하는데...', '1995-01-28', 8.714, 28.9782, 142, '프랭크 다라본트', 29586, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1422096, '굿 보이', 'Good Boy', 'movie', 'https://image.tmdb.org/t/p/w500/t4HhBZDq9Wjxrm1iKZOwZnyJPFy.jpg', 'https://image.tmdb.org/t/p/original/mPtPJzBkwksUoMEKpkZqxBrlKpZ.jpg', '인간 친구 토드가 며칠 전부터 이상하다. 여기서 토드를 지킬 수 있는 건 나 밖에 없다. 우리의 세계가 무너지지 않도록 내가 나서야 한다.', '2025-10-22', 6.751, 28.8741, 74, 'Ben Leonberg', 480, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1363123, '''패밀리 플랜 2'' - The Family Plan 2', 'The Family Plan 2', 'movie', 'https://image.tmdb.org/t/p/w500/leWNzgtVJwwpukdYdu8aerQFvjP.jpg', 'https://image.tmdb.org/t/p/original/7nAVXGHHtaNcdsqvDXmY6R9N0fG.jpg', '킬러 시절을 뒤로한 댄은 크리스마스에 아이들과 오붓한 시간을 보내고 싶어 한다. 하지만 딸이 따로 계획을 세운 걸 알고, 런던행 가족 여행을 예약해 버린다. 그 결정으로 댄과 가족들은 예상치 못한 적의 표적이 된다.', '2025-11-21', 6.5, 28.76, 106, 'Simon Cellan Jones', 466, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1154725, 'Un monde merveilleux', 'Un monde merveilleux', 'movie', 'https://image.tmdb.org/t/p/w500/eiu1bJEpBQeq5eyNHzuMhYWaLF2.jpg', 'https://image.tmdb.org/t/p/original/nLwMT1wZQvLkhvJOxemP0D4eo77.jpg', '', '2025-04-12', 5.4, 28.4874, 78, 'Giulio Callegari', 23, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (812583, '나이브스 아웃: 웨이크 업 데드 맨', 'Wake Up Dead Man: A Knives Out Mystery', 'movie', 'https://image.tmdb.org/t/p/w500/qFXkslzkBIihZnwyYal9WnQ9OTe.jpg', 'https://image.tmdb.org/t/p/original/fiRDzpcJe7qz3yIR43hdXIE3NHv.jpg', '브누아 블랑이 탐정 인생을 통틀어 가장 위험한 사건으로 돌아온다.어두운 과거를 지닌 작은 마을의 성당. 그곳에서 불가사의한 범죄가 발생한다. 그러자 브누아 블랑 탐정이 신실한 젊은 신부와 함께 수사에 나선다.', '2025-12-12', 7.215, 28.4681, 145, '라이언 존슨', 1879, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1124566, '센티멘탈 밸류', 'Affeksjonsverdi', 'movie', 'https://image.tmdb.org/t/p/w500/8DbSCDlGJG2SO9iOD4GlXOXuKVe.jpg', 'https://image.tmdb.org/t/p/original/vRoIogTQDO5yAmTmH5uGrlPfS0N.jpg', '가족을 버리고 떠난 영화감독 구스타프는 재회한 딸에게 영화 출연을 제안한다. 하지만 노라는 아버지에 대한 불신과 원망으로 단칼에 거절한다.', '2025-09-19', 7.602, 28.2794, 133, '요아킴 트리에', 344, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1197306, '워킹맨', 'A Working Man', 'movie', 'https://image.tmdb.org/t/p/w500/pPokyKVPve6HNSgVliOlrMwU1lM.jpg', 'https://image.tmdb.org/t/p/original/fTrQsdMS2MUw00RnzH0r3JWHhts.jpg', '전직 블랙 옵스 요원이었던 레본 케이드(제이슨 스타뎀)는 평범한 건설 노동자로 살아가며 딸과 함께 조용한 삶을 추구하고 있었으나 그의 상사의 딸이 인신매매 조직에 의해 납치되면서, 다시 과거의 전투 기술을 사용해 그녀를 구하기 위해 나서게 된다. 이 과정에서 시카고의 범죄 조직과 러시아 마피아와 얽히며, 부패와 폭력으로 가득 찬 어두운 세계를 마주하게 되는데...', '2025-10-01', 6.693, 27.9316, 116, '데이비드 에이어', 1751, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (299536, '어벤져스: 인피니티 워', 'Avengers: Infinity War', 'movie', 'https://image.tmdb.org/t/p/w500/kmP6viwzcEkZeoi1LaVcQemcvZh.jpg', 'https://image.tmdb.org/t/p/original/mDfJG3LC3Dqb67AZ52x3Z0jU0uB.jpg', '타노스는 6개의 인피니티 스톤을 획득해 신으로 군림하려 한다. 그것은 곧 인류의 절반을 학살해 우주의 균형을 맞추겠다는 뜻. 타노스는 닥터 스트레인지가 소유한 타임 스톤, 비전의 이마에 박혀 있는 마인드 스톤을 차지하기 위해 지구를 침략한다. 아이언맨과 스파이더맨은 가디언즈 오브 갤럭시의 멤버들과 타노스를 상대한다. 지구에선 캡틴 아메리카, 완다, 블랙 위도우, 블랙 팬서 등이 비전을 지키기 위해 뭉친다.', '2018-04-26', 8.235, 27.9174, 149, '조 루소', 31379, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (79871, '밀도성숙시', '蜜桃成熟時', 'movie', 'https://image.tmdb.org/t/p/w500/vM4Tb2Wxk2X0Sgfy1wAS9bzSZsa.jpg', 'https://image.tmdb.org/t/p/original/5hcouxgjYMIdH3e113LOLK3eD6D.jpg', '아진은 부잣집 외동딸로 방학을 이용해 영국에서 열리는 하계 캠프에 가기로 한다. 단짝 친구 애이미와 그녀의 남자친구가 공항에서 서로의 이별을 아쉬워하 것을 보고 비행기표를 건네주고 영국행을 포기한다. 그녀는 자신의 남자친굴 찾아가는데 다른 여자와 있는 장면을 보고 그와 결별할 것을결심한다. 그리고 그녀는 진정한 사랑을 찾아 여행을 떠나가로 마음 먹는다. 여행길에 진은 여러가지 수난도 당하지만 해변에서 우연히 만난 히피에게 그의 사랑학에 대한 이야기를 듣고, 또한 극작가 지망생인 대위라는 남자를 만나 서로 사랑하게 된다. 하지만 둘 사이에 오해가 생겨 아진은 대위와 헤어지게 되고 다시 사랑을 찾아 떠난다. 그러나 그녀가 사랑할 수 있는 사람은 대위 밖에 없다는 것을 느끼게 된다. 그리고 우연히 다시만난 히피와 이야기를 나누며서 그녀가 진정으로 사랑하는 사람은 대위라는 것이 더욱 확실해 진다. 또한 사랑하는 사이라면 자존심도 버릴줄 알아야 된다고 생각하여 직접 그를 찾아가고 사랑을 확인한다. 그로써 그녀의 사랑 여행도 막을 내리게 된다.', '1993-04-17', 6.268, 27.7356, 77, 'Roman Cheung', 41, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1589891, '용자들의 시간', 'La hora de los valientes', 'movie', 'https://image.tmdb.org/t/p/w500/kidywh4SgwByoR5roudemIpTx86.jpg', 'https://image.tmdb.org/t/p/original/gtuXARxjGdfsGFqEwggBB8zUJza.jpg', '사회봉사 명령을 받은 정신분석가가 배우자의 불륜으로 힘들어하는 한 요원의 심리 상담을 돕는다. 이후 두 사람은 함께 위험을 겪으며 인생의 두 번째 기회를 찾게 된다.', '2025-12-19', 7.592, 27.373, 107, 'Ariel Winograd', 71, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (27205, '인셉션', 'Inception', 'movie', 'https://image.tmdb.org/t/p/w500/zTgjeblxSLSvomt6F6UYtpiD4n7.jpg', 'https://image.tmdb.org/t/p/original/ii8QGacT3MXESqBckQlyrATY0lT.jpg', '타인의 꿈에 들어가 생각을 훔치는 특수 보안요원 코브. 그를 이용해 라이벌 기업의 정보를 빼내고자 하는 사이토는 코브에게 생각을 훔치는 것이 아닌, 생각을 심는 ‘인셉션’ 작전을 제안한다. 성공 조건으로 국제적인 수배자가 되어있는 코브의 신분을 바꿔주겠다는 거부할 수 없는 제안을 하고, 사랑하는 아이들에게 돌아가기 위해 그 제안을 받아들인다. 최강의 팀을 구성, 표적인 피셔에게 접근해서 ‘인셉션’ 작전을 실행하지만 예기치 못한 사건들과 마주하게 되는데… 꿈 VS 현실! 시간, 규칙, 타이밍 모든 것이 완벽해야만 하는, 단 한 번도 성공한 적 없는 ‘인셉션’ 작전이 시작된다!', '2010-07-21', 8.37, 27.0775, 148, '크리스토퍼 놀란', 38552, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1408208, '8번 출구', '８番出口', 'movie', 'https://image.tmdb.org/t/p/w500/h1gB7AgFCHB1gTkb03uKNMsRLTU.jpg', 'https://image.tmdb.org/t/p/original/ie827c44beNPNnxIOi8EM9mCI4A.jpg', '방심하는 순간 영원히 이곳에 갇힌다! 무한루프 속 이상 현상을 찾아 탈출하라! 끝없이 반복되는 지하도에 갇힌 ‘헤매는 남자’. 아래의 규칙에 따라 8번 출구로 탈출해야만 한다. 1. 단 하나의 이상 현상도 놓치지 말 것. 2. 이상 현상을 발견하면 즉시 되돌아갈 것. 3. 이상 현상이 없다면 앞으로 나아갈 것. 4. 8번 출구를 통해서 밖으로 나갈 것.', '2025-10-22', 6.2, 26.932, 96, '카와무라 겐키', 117, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (533535, '데드풀과 울버린', 'Deadpool & Wolverine', 'movie', 'https://image.tmdb.org/t/p/w500/dsfAcQ5J7TPOpJgcX8R1lRBqiMK.jpg', 'https://image.tmdb.org/t/p/original/ufpeVEM64uZHPpzzeiDNIAdaeOD.jpg', '히어로 생활에서 은퇴한 후, 평범한 중고차 딜러로 살아가던 데드풀이 예상치 못한 거대한 위기를 맞아 모든 면에서 상극인 울버린을 찾아가게 되며 펼쳐지는 도파민 폭발 액션 블록버스터.', '2024-07-24', 7.561, 26.7895, 128, '숀 레비', 8187, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1149167, '캐시 아웃 2', 'High Rollers', 'movie', 'https://image.tmdb.org/t/p/w500/h4rwNz4HxVfSPXVpB39zGWoKmOV.jpg', 'https://image.tmdb.org/t/p/original/me3SisKfnxwBP69aOVKAVMw9vDM.jpg', '은퇴한 은행털이범들이 납치된 동료를 구출하는 조건으로 카지노 금고 절도에 나서게 되는 이야기를 그린 극영화', '2025-07-25', 6.6, 26.6062, 101, '랜들 에멧', 101, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1241742, '엑스: 세 개의 이야기', 'EKS', 'movie', 'https://image.tmdb.org/t/p/w500/gcK3HgN6IHNOviXnX11W6aFLTGv.jpg', 'https://image.tmdb.org/t/p/original/2Ve7sjxLb3rKG8qJ1t7QEuNI0UM.jpg', '세 가지 인생, 세 가지 강렬한 자극! 인생에 단 한 번 만나게 되는 에로틱 트릴로지', '2024-03-01', 3.2, 26.5861, 119, 'Roman Perez Jr.', 5, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (120, '반지의 제왕: 반지 원정대', 'The Lord of the Rings: The Fellowship of the Ring', 'movie', 'https://image.tmdb.org/t/p/w500/r18JdjImbWDRwkbVDIzWoLQqkCo.jpg', 'https://image.tmdb.org/t/p/original/a0lfia8tk8ifkrve0Tn8wkISUvs.jpg', '호빗이라 불리우는 난장이 종족 중의 한 명인 프로도는 자신의 삼촌에게서 우연히 절대 반지를 물려받게 되고, 마법사 간달프를 통해서 절대반지가 사우론의 손에 들어가면 악의 세력이 세상을 지배하게 된다는 것을 알게 된다. 하지만 절대반지를 영원히 파괴할 수 있는 유일한 방법은 반지가 만들어진 불의 산의 용암에 그것을 던져 넣는 길 뿐이다. 마침내 프로도와 그의 친구들, 엘프족인 레골라스, 난장이족 김리, 두명의 인간 전사 아라곤과 보로미르, 그리고 마법사 간달프로 구성된 반지 원정대가 길고도 험난한 여정을 떠나게 되는데...', '2001-12-31', 8.427, 26.5673, 227, '피터 잭슨', 26870, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1151272, '시라트', 'Sirāt', 'movie', 'https://image.tmdb.org/t/p/w500/b35VZ5udCZWToWzNpWjcaCLxPvA.jpg', 'https://image.tmdb.org/t/p/original/kOUV5WbisWMg56d8eB45ZHEVxYq.jpg', '광활한 사막 한가운데에서 펼쳐지는 레이브 파티. 그곳에서 루이스는 아들 에스테반과 함께 실종된 딸을 찾아 헤맨다. 하지만 곧 그 길은 신의 심판대로 이어지는데...', '2026-01-21', 6.829, 26.3933, 115, 'Oliver Laxe', 366, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (541671, '발레리나', 'Ballerina', 'movie', 'https://image.tmdb.org/t/p/w500/rGe64vmd9cpvwiTD5OGWJezBnNg.jpg', 'https://image.tmdb.org/t/p/original/1yktYsxkmUtUFTUnCAUaqG6FEiz.jpg', '살해당한 아버지의 복수를 원하는 이브는 전설적인 킬러 존 윅을 배출한 암살자 양성 조직 루스카 로마에서 혹독한 훈련을 거쳐 발레리나이자 킬러로 성장한다. 아버지의 죽음에 얽힌 자들을 쫓던 이브는 루스카 로마를 뛰어넘는 거대한 조직의 정체를 알아차리게 되고, 킬러들의 표적이 된 이브의 눈앞에 존 윅이 나타나는데…', '2025-08-06', 7.288, 26.3524, 125, '렌 와이즈먼', 2239, 0);
