INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1371185, '송 썽 블루', 'Song Sung Blue', 'movie', 'https://image.tmdb.org/t/p/w500/ywhIAXy7MbEv3MAfXYXMniGDHBu.jpg', 'https://image.tmdb.org/t/p/original/mnEx3lTjjQYHMj55ZnZHQZVUlZ.jpg', '언제나 자신만의 무대를 꿈꾸지만 현실은 떠돌이 뮤지션 ‘마이크’. 그의 인생에 운명처럼 나타난 싱글맘 ‘클레어’. 첫눈에 서로의 목소리와 마음을 알아본 두 사람은 사랑과 음악을 함께 꿈꾸며 레전드 가수 닐 다이아몬드의 명곡을 부르는 커버 밴드 ‘라이트닝 & 썬더’를 결성한다. 타고난 쇼맨십과 폭발적인 가창력으로 단숨에 지역 스타로 떠오른 두 사람은 당대 최고 인기 밴드 펄잼의 오프닝 무대까지 장식한다. 그러나 가장 찬란한 순간, 예기치 못한 클레어의 사고가 일어나고 두 사람의 인생과 무대는 한순간에 무너지고 마는데....', '2026-01-14', 7.546, 26.0088, 133, 'Craig Brewer', 87, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1194963, '노이즈', '노이즈', 'movie', 'https://image.tmdb.org/t/p/w500/tPOcNetZHfmn97V93TikhWDXj4T.jpg', 'https://image.tmdb.org/t/p/original/zeMMVjOFwXPfRIW6HzaEr0UQlRY.jpg', '내 집 마련에 성공한 주영과 주희 자매. 어느 날부터 아파트 어딘가에서 들려오는 정체불명의 층간소음에 시달린다. 그러던 중 동생 주희와 연락이 끊기자 불안에 휩싸인 주영은 급히 지방 공장에서 집으로 돌아오고, 주희의 남자친구 기훈과 함께 실종된 동생을 추적하기 시작한다. 한편, 자매와 마찬가지로 층간소음에 시달리던 아랫집 남자는 그 소음의 근원이 윗집 자매에게 있다고 생각해 살인 협박을 하게 되는데….', '2025-06-25', 6.216, 25.8431, 95, '김수진', 37, 0);
