INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1255718, '사복경찰', 'Plainclothes', 'movie', 'https://image.tmdb.org/t/p/w500/bT5QN5QARV5TblAt9jDVQQsnSec.jpg', 'https://image.tmdb.org/t/p/original/zXMWISNY5KnrhtxHA7OUmDFKWmD.jpg', '1990년대 뉴욕, 잠입 경찰 루카스는 쇼핑몰 화장실에서 게이 남성들을 유인해 체포하는 임무를 맡는다. 그러나 앤드루라는 남성과의 만남은 단순한 계획을 넘어선 감정의 불씨가 되고, 루카스는 서서히 자신의 욕망과 정체성을 직면하게 된다. 상부의 압박은 점점 무겁게 다가오고, 어머니의 새해 전야 파티에서 잃어버린 편지는 그의 과거를 불러내며 새로운 위기를 맞게 되는데...', '2025-11-08', 7.272, 24.8549, 95, 'Carmen Emmi', 46, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1354700, '강령: 귀신놀이', '강령: 귀신놀이', 'movie', 'https://image.tmdb.org/t/p/w500/szBqzH2qcUthCm1uDVsBAYZbExW.jpg', 'https://image.tmdb.org/t/p/original/et17Am3i8QE80HA7YUilG82Dz1x.jpg', '문을 열었습니다. 열었습니다. 열었습니다. 공모전에 제출할 독특한 영상을 위해 ‘무엇이든 알려주는 강령술’을 촬영하기로 한 ‘자영’과 친구들. 언니 ‘자영’을 잘 따르는 동생 ‘서우’까지 합류하고, 어두운 밤 6명의 아이들은 폐쇄된 지하 저수조로 향한다. 촬영 도중, 호기심이 발동한 ‘자영’과 친구들은 진짜 강령술을 시도한다. 걱정과 달리 잠잠한 분위기에 안도감과 아쉬움이 교차하던 순간, 빙의자 역할을 하던 ‘서우’가 검은 물을 토하며 쓰러지고, 질문이 적힌 부적에 답이 나타난다. 들어오세요. 들어오세요. 들어오세요. 가벼운 마음으로 시작한 강령술은 곧 끔찍한 저주가 되어, 아이들의 목숨을 위협하기 시작하는데…', '2025-08-06', 6.75, 24.7319, 95, '손동완', 24, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (634649, '스파이더맨: 노 웨이 홈', 'Spider-Man: No Way Home', 'movie', 'https://image.tmdb.org/t/p/w500/fvqoI9r1GU2EFkc0xjZ6dKCuDVR.jpg', 'https://image.tmdb.org/t/p/original/tyQo080tijexyUHBvWPwQt26bZa.jpg', '미스테리오의 계략으로 세상에 정체가 탄로난 스파이더맨 피터 파커는 하루 아침에 평범한 일상을 잃게 된다. 문제를 해결하기 위해 닥터 스트레인지를 찾아가 도움을 청하지만 뜻하지 않게 멀티버스가 열리면서 각기 다른 차원의 불청객들이 나타난다. 닥터 옥토퍼스를 비롯해 스파이더맨에게 깊은 원한을 가진 숙적들의 강력한 공격에 피터 파커는 사상 최악의 위기를 맞게 되는데…', '2021-12-15', 7.934, 24.1318, 148, '존 왓츠', 21473, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1241982, '모아나 2', 'Moana 2', 'movie', 'https://image.tmdb.org/t/p/w500/hwmwTFtMbzxAWbIOp1RyyiOCyx0.jpg', 'https://image.tmdb.org/t/p/original/zo8CIjJ2nfNOevqNajwMRO6Hwka.jpg', '바다를 누볐던 선조들에게서 예기치 못한 부름을 받은 모아나가 마우이와 다시 만나 새로운 선원들과 함께 오랫동안 잊혀진 멀고 위험한 바다 너머로 떠나는 특별한 모험을 담은 이야기', '2024-11-27', 7.002, 24.0937, 100, 'David G. Derrick Jr.', 2900, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (10138, '아이언맨 2', 'Iron Man 2', 'movie', 'https://image.tmdb.org/t/p/w500/ebJbC9OYAZJxy7bRUGryR72hfa2.jpg', 'https://image.tmdb.org/t/p/original/7lmBufEG7P7Y1HClYK3gCxYrkgS.jpg', '세계 최강의 무기업체를 이끄는 CEO이자, 타고난 매력으로 화려한 삶을 살아가던 토니 스타크. 기자회견을 통해 자신이 아이언맨이라고 정체를 밝힌 이후, 정부로부터 아이언맨 수트를 국가에 귀속시키라는 압박을 받지만 이를 거부한다. 스타크 인더스트리의 운영권까지 수석 비서였던 페퍼 포츠에게 일임하고 히어로로서의 인기를 만끽하며 지내던 토니 스타크. 하지만 그 시각, 아이언맨의 수트 기술을 스타크 가문에 빼앗긴 후 쓸쓸히 돌아가신 아버지의 복수를 다짐해 온 위플래시는 수트의 원천 기술 개발에 성공, 치명적인 무기를 들고 직접 토니 스타크를 찾아 나선다.', '2010-04-29', 6.8, 24.0899, 125, '존 파브로', 22000, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (524047, '그린랜드', 'Greenland', 'movie', 'https://image.tmdb.org/t/p/w500/wLgHczwajb3QV2JBgsqNVjuHoJC.jpg', 'https://image.tmdb.org/t/p/original/2Fk3AB8E9dYIBc2ywJkxk8BTyhc.jpg', '혜성의 지구 충돌 속보를 지켜보던 존과 가족들. 미 항공우주국(NASA)의 예측과 달리 해상으로 떨어졌어야 할 파편은 캘리포니아를 비롯해 세계 대도시로 추락해 세계는 순식간에 혼돈에 빠진다. 지구의 3/4을 날려버릴 초대형 혜성 추락까지 남은 시간은 단 48시간. 존과 가족은 지구의 유일한 안전 대피소인 ‘그린란드’의 벙커로 향하는데... 인류의 마지막 카운트다운이 시작된다!', '2020-09-29', 7.124, 23.9209, 120, 'Ric Roman Waugh', 4972, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (862, '토이 스토리', 'Toy Story', 'movie', 'https://image.tmdb.org/t/p/w500/iJbm78MxPjLutWUYixbeege8EVe.jpg', 'https://image.tmdb.org/t/p/original/3Rfvhy1Nl6sSGJwyjb0QiZzZYlB.jpg', '카우보이 인형 우디는 꼬마 주인인 앤디의 가장 사랑받는 장난감이다. 그러나 어느날 버즈라는 새로운 장난감이 등장한다.  버즈는 최신형 장난감으로 레이저 빔 등의 첨단장비를 갖추고 있으나, 버즈는 자신이 장난감임을 인식하지 못하고 자신이 우주에서 온 전사이며 자신이 갖춘 장비로 하늘을 날 수 있다고 믿고 있다. 버즈의 허상을 상처받지 않고 인식시켜 주려는 우디와 친구들. 그러나 뜻밖의 사고가 일어난다. 옆집 개에게 버즈가 납치당하고 이런 버즈를 구하기 위해 우디와 친구들은 구조대를 조직해 버즈를 구하러 가는데...', '1995-12-30', 7.97, 23.8385, 81, '존 라세터', 19473, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (170, '28일 후', '28 Days Later', 'movie', 'https://image.tmdb.org/t/p/w500/yUEgICZTj6NMiPsb0hWs3qYByDe.jpg', 'https://image.tmdb.org/t/p/original/x085XrfEmU31QeXgMFttmuoGr0Y.jpg', '분노 바이러스에 감염되어있던 침팬지들이 우리에서 풀려나고 바이러스는 런던 전역에 퍼진다. 텅 빈 병원에서 깨어난 짐은 감염자들의 공격을 피해 생존자들과 맨체스터로 향한다.', '2003-09-18', 7.237, 23.6973, 113, '대니 보일', 8131, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (496243, '기생충', '기생충', 'movie', 'https://image.tmdb.org/t/p/w500/jjHccoFjbqlfr4VGLVLT7yek0Xn.jpg', 'https://image.tmdb.org/t/p/original/hiKmpZMGZsrkA3cdce8a7Dpos1j.jpg', '전원 백수로 살 길 막막하지만 사이는 좋은 기택 가족. 장남 기우에게 명문대생 친구가 연결시켜 준 고액 과외 자리는 모처럼 싹튼 고정수입의 희망이다. 온 가족의 도움과 기대 속에 박 사장 집으로 향하는 기우. 글로벌 IT기업의 CEO인 박 사장의 저택에 도착하자 젊고 아름다운 사모님 연교와 가정부 문광이 기우를 맞이한다. 큰 문제 없이 박 사장의 딸 다혜의 과외를 시작한 기우. 그러나 이렇게 시작된 두 가족의 만남 뒤로, 걷잡을 수 없는 사건이 기다리고  있는데.....', '2019-05-30', 8.495, 23.6888, 131, '봉준호', 20003, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (38757, '라푼젤', 'Tangled', 'movie', 'https://image.tmdb.org/t/p/w500/sT1vLH38iaezVgoFqmaiihbnTUy.jpg', 'https://image.tmdb.org/t/p/original/cWczNud8Y8i8ab0Z4bxos4myWYO.jpg', '장장 18년을 탑 안에서만 지낸 끈기 만점의 소녀 라푼젤. 어느 날 자신의 탑에 침입한 왕국 최고의 대도를 한 방에 때려잡고, 그를 협박해 꿈에도 그리던 집 밖으로의 모험을 단행한다. 과잉보호 모친의 영향으로 세상을 험난한 곳으로만 상상하던 라푼젤 앞에 왕실 경비마 맥시머스의 추격, 라이더에게 복수의 칼날을 가는 스태빙턴 형제의 위협, 라푼젤의 가짜 엄마 고델의 무서운 음모 등이 얽혀 점점 흥미진진한 사건들이 터지기 시작한다. 그러나 세상물정 모르는 라푼젤은 자신 앞에 펼쳐진 스릴 넘치는 세상을 맘껏 즐기는데...', '2011-02-10', 7.611, 23.616, 100, '네이든 그레노', 12134, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1291608, 'धुरंधर', 'धुरंधर', 'movie', 'https://image.tmdb.org/t/p/w500/8FHOtUpNIk5ZPEay2N2EY5lrxkv.jpg', 'https://image.tmdb.org/t/p/original/yRYgvo2crAeHzqKwXMVtEaDx7Qq.jpg', '', '2025-12-05', 6.744, 23.568, 212, 'Aditya Dhar', 154, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1038392, '컨저링: 마지막 의식', 'The Conjuring: Last Rites', 'movie', 'https://image.tmdb.org/t/p/w500/y9jKDJuf5WCDjSPsqkt1cb0JHGm.jpg', 'https://image.tmdb.org/t/p/original/tcBX2dtkNozZ0uDLVaxXrE6rqyN.jpg', '1986년 미국 펜실베이니아. 자신의 집에 사악한 존재가 들어왔다고 주장하는 스멀 일가를 찾은 워렌 부부. 이들은 그 곳에서 지금껏 마주한 적 없는 가장 위험하고 강력한 악령을 만나게 되고, 그것이 자신들의 과거와 연결된 충격적인 진실을 알게 되는데…', '2025-09-03', 6.913, 23.5584, 136, '마이클 차브스', 1601, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (671, '해리 포터와 마법사의 돌', 'Harry Potter and the Philosopher''s Stone', 'movie', 'https://image.tmdb.org/t/p/w500/8YaP48tVfngbURGldWk1I5odsBK.jpg', 'https://image.tmdb.org/t/p/original/1XAC6RPT01UX9EQGy2JVn5c8pgy.jpg', '해리 포터는 위압적인 버논 숙부와 냉담한 이모 페투니아, 욕심 많고 버릇없는 사촌 더즐리 밑에서 갖은 구박을 견디며 계단 밑 벽장에서 생활한다. 이모네 식구들 역시 해리와의 동거가 불편하기는 마찬가지. 이모 페투니아에겐 해리가 이상한 언니 부부에 관한 기억을 떠올리게 만드는 달갑지 않은 존재다. 11살 생일이 며칠 앞으로 다가왔지만 한번도 생일파티를 치르거나 제대로 된 생일선물을 받아 본 적이 없는 해리로서는 특별히 신날 것도 기대 할 것도 없다. 11살 생일을 며칠 앞둔 어느 날 해리에게 초록색 잉크로 쓰여진 한 통의 편지가 배달된다. 그 편지의 내용은 다름 아닌 해리의 11살 생일을 맞이하여 호그와트에서 보낸 입학 초대장이었다. 그리고 해리의 생일을 축하하러 온 거인 해그리드는 해리가 모르고 있었던 해리의 진정한 정체를 알려주는데...', '2001-12-14', 7.9, 23.0531, 152, '크리스 콜럼버스', 29058, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (354912, '코코', 'Coco', 'movie', 'https://image.tmdb.org/t/p/w500/pQu93NuwR90AaCULzglVD5Ge4Ml.jpg', 'https://image.tmdb.org/t/p/original/g7CHF8gTLGooTbP4GznIGwaqAGL.jpg', '미구엘은 멕시코의 자랑인 에르네스토 델라 크루즈 같은 뮤지션이 되길 꿈꾸지만 미구엘 집안 사람들에게 음악은 금기다. 먼 옛날 조상 중에 음악 때문에 가족을 버린 인물이 있었기 때문. 미구엘은 죽은 자의 날이 되자 실력으로 인정받겠다는 결심을 하고 경연 무대에 오르려 하는데, 우연히 에르네스토의 기타에 손을 댔다가 죽은 자들의 세상에 들어서게 된다. 이승과 저승을 이어주는 마리골드 꽃길을 건너 죽은 자들의 세상에 도착한 미구엘은 거짓말과 위변조가 장기인 헥터를 만난다. 그리고 꿈에 그리던 우상 에르네스토를 만나러 가는 여정에서 가족의 비밀을 알게 된다.', '2018-01-11', 8.198, 22.8101, 105, '리 언크리치', 20587, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (756397, 'Hitpig!', 'Hitpig!', 'movie', 'https://image.tmdb.org/t/p/w500/bYa20LYAZ3Q7lKXtLYybo0yWWTN.jpg', 'https://image.tmdb.org/t/p/original/leobhCk6L86BEBnx1t6URQcIdQW.jpg', '', '2024-11-01', 6.658, 22.7913, 85, 'David Feiss', 38, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1022789, '인사이드 아웃 2', 'Inside Out 2', 'movie', 'https://image.tmdb.org/t/p/w500/x2BHx02jMbvpKjMvbf8XxJkYwHJ.jpg', 'https://image.tmdb.org/t/p/original/p5ozvmdgsmbWe0H8Xk7Rc8SCwAB.jpg', '13살이 된 라일리의 행복을 위해 매일 바쁘게 머릿속 감정 컨트롤 본부를 운영하는 ‘기쁨’, ‘슬픔’, ‘버럭’, ‘까칠’, ‘소심’. 그러던 어느 날, 낯선 감정인 ‘불안’, ‘당황’, ‘따분’, ‘부럽’이가 본부에 등장하고, 언제나 최악의 상황을 대비하며 제멋대로인 ‘불안’이와 기존 감정들은 계속 충돌한다. 결국 새로운 감정들에 의해 본부에서 쫓겨나게 된 기존 감정들은 다시 본부로 돌아가기 위해 위험천만한 모험을 시작하는데…', '2024-06-12', 7.546, 22.6144, 97, '켈시 만', 6410, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (574475, '파이널 데스티네이션: 블러드라인', 'Final Destination Bloodlines', 'movie', 'https://image.tmdb.org/t/p/w500/agaIglFrRGuUQOzkhzlrvcjJgt2.jpg', 'https://image.tmdb.org/t/p/original/uIpJPDNFoeX0TVml9smPrs9KUVx.jpg', '끝없는 악몽에 시달리던 스테파니는 그 원인을 찾던 중 집안 대대로 내려오는 죽음의 저주와 그 실체를 알게 된다. 놀랍게도, 죽음의 순서가 자신의 가족에게 이어졌음을 알게 되는데...  이제, 다음 차례는 누구?', '2025-05-14', 7.092, 22.5983, 110, '애덤 B. 스타인', 2573, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (122, '반지의 제왕: 왕의 귀환', 'The Lord of the Rings: The Return of the King', 'movie', 'https://image.tmdb.org/t/p/w500/n8BPIRqvj1SdTRND828ANXhmSng.jpg', 'https://image.tmdb.org/t/p/original/2u7zbn8EudG6kLlBzUYqP8RyFU4.jpg', '사우론이 인간들의 마지막 요새인 곤도르를 향해 야욕을 드러내고 있는 한편, 아라곤은 쇠락해가고 있는 곤도르의 재건을 위해 왕위 계승을 신중하게 결정지어야만 하는 상황. 이제 중간대륙의 미래는 그의 어깨에 달려있는 것. 사우론이 이끄는 어둠의 군대와의 마지막 전투를 위해 간달프는 곤도르에 흩어져 있던 병사들을 모으고, 로한의 왕 세오덴에게 도움을 받기도 하지만 사우론의 군대에 비하면 열세를 면치 못한다. 그러나 그들은 중간대륙을 사우론의 야욕으로부터 지키려는 사명감과, 마지막 반지 운반자에게 임무를 끝낼 기회를 주기 위해 어둠의 군대를 향해 돌진하게 되는데...', '2003-12-17', 8.492, 22.5222, 199, '피터 잭슨', 25906, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (482600, '일본 엄마', '일본 엄마', 'movie', 'https://image.tmdb.org/t/p/w500/hq1EaYIqUNrPM3QFYAbnH2UHoX8.jpg', NULL, '얼굴은 청순, 가슴은 D컵, 밤 기술은 퍼펙트! ""아들아, 이제부터 네 여친이 아니라 엄마다." 아들 기호가 결혼하겠다며 일본에서 데려온 그녀, 유키. 그러나 기호는 한국에 오자 전 여친을 만나며 바람을 피우기 시작한다. 처음에는 예비 며느리를 달래는 마음으로 유키를 위로하던 민철은 어느 순간부터 자신이 유키를 여자로 보고 있다는 사실을 깨닫는다. 결국, 기호 몰래 민철과 유키의 뜨거운 정사가 펼쳐지는데...', '2017-02-09', 6.6, 22.4262, 91, 'Kim Moo-won', 62, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (588, '사일런트 힐', 'Silent Hill', 'movie', 'https://image.tmdb.org/t/p/w500/jhI1W7nuTmBdV7SW4M5O6oUPcf4.jpg', 'https://image.tmdb.org/t/p/original/bQv2asCwfA1JSub3HYzZGRSKDye.jpg', '30년 전, 화재로 모든 것이 사라진 전설의 마을 ‘사일런트 힐’. 그곳에서 사라진 딸을 찾기 위해 로즈는 미스터리한 마을로 들어서게 된다. 저 멀리 사라져가는 딸의 뒷모습을 따라 안개 속에서 헤매던 로즈. 그때 마을을 뒤덮은 안개와 잿빛 속에서 갑자기 사이렌이 울리자 거대한 어둠이 밀려오고 ‘사일런트 힐’은 전혀 다른 공간으로 바뀌어 버린다! 그리고 어둠 속에서 서서히 다가오는 무시무시한 크리쳐들! 이제 그녀는 거대한 비밀을 숨기고 있는 그곳으로부터 딸을 되찾아야만 한다. 사일런트 힐을 움직이는 거대한 저주와 미스터리는 딸과 어떤 관계가 있는 것인가?', '2006-11-09', 6.609, 22.3786, 132, 'Christophe Gans', 4669, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1300116, '폴 포 미', 'Fall for Me', 'movie', 'https://image.tmdb.org/t/p/w500/nxW1kVYMps37Yys3azPo9KXsWNT.jpg', 'https://image.tmdb.org/t/p/original/xd7YqovQSLBY7dbptsz2bPgL0ym.jpg', '여동생의 새 약혼자를 미심쩍게 여기던 릴리. 그런데 본인의 삶에 매력적인 낯선 남자가 등장하면서, 순식간에 욕망의 소용돌이에 휘말리게 된다.', '2025-08-21', 6.121, 22.1022, 103, 'Sherry Hormann', 195, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (912649, '베놈: 라스트 댄스', 'Venom: The Last Dance', 'movie', 'https://image.tmdb.org/t/p/w500/ptfoRD0MmL8Ry0iBVccYbqoN9Xc.jpg', 'https://image.tmdb.org/t/p/original/3V4kLQg0kSqPLctI5ziYWabAZYF.jpg', '환상의 케미스트리의 에디 브록과 그의 심비오트 베놈은 그들을 노리는 정체불명 존재의 추격을 피해 같이 도망을 다니게 된다. 한편 베놈의 창조자 널은 고향 행성에서부터 그들을 찾아내기 위해 지구를 침략하고 에디와 베놈은 그동안 겪어보지 못한 최악의 위기를 맞이하게 되는데…', '2024-10-23', 6.667, 22.0734, 109, '켈리 마르셸', 3973, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (872585, '오펜하이머', 'Oppenheimer', 'movie', 'https://image.tmdb.org/t/p/w500/jpD6z9fgNe7OqsHoDeAWQWoULde.jpg', 'https://image.tmdb.org/t/p/original/ycnO0cjsAROSGJKuMODgRtWsHQw.jpg', '세상을 구하기 위해 세상을 파괴할 지도 모르는 선택을 해야 하는 천재 과학자의 핵개발 프로젝트.', '2023-08-15', 8.036, 22.0541, 181, '크리스토퍼 놀란', 11242, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1172265, '마지막 푸른빛', 'O Último Azul', 'movie', 'https://image.tmdb.org/t/p/w500/4LV2kTS54D7v1da2ooQ8knhptLh.jpg', 'https://image.tmdb.org/t/p/original/2UXrkv2G1aXMyn3VY70krD9Anid.jpg', '77세의 테레사는 ‘은퇴 구역’으로 이송되기 직전 자유를 찾아 탈출을 감행한다.', '2025-09-18', 7.26, 22.0012, 86, 'Gabriel Mascaro', 52, 0);
