INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1033148, '다이, 마이 러브', 'Die My Love', 'movie', 'https://image.tmdb.org/t/p/w500/kajpShbFhOdpl6yCrLezMrr9tB4.jpg', 'https://image.tmdb.org/t/p/original/dEkFlZzj2cb5F7SShvqkL54E4lr.jpg', '외딴 시골에 사는 한 여성이 결혼과 육아로 인해 정신적으로 극한에 이르게 된다.', '2025-10-06', 6.221, 20.8413, 119, '린 램지', 321, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1175942, '배드 가이즈 2', 'The Bad Guys 2', 'movie', 'https://image.tmdb.org/t/p/w500/1oG69MtmZGovhho0pPgRY9d1qrU.jpg', 'https://image.tmdb.org/t/p/original/8FWLJHuWB72UXBmiMtxwTvQVumN.jpg', '착하게 살기 위해 무지하게 애쓰는 자타공인 최고의 나쁜 녀석들이 새롭게 등장한 ''배드 걸즈''로 인해 일생일대의 글로벌 범죄 작전에 휘말리며 벌어지는 범죄오락액션 블록버스터', '2025-07-30', 7.696, 20.8039, 104, 'Pierre Perifel', 631, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (109445, '겨울왕국', 'Frozen', 'movie', 'https://image.tmdb.org/t/p/w500/lYceQKe3EsYn7VdDXGTy7dSwBLp.jpg', 'https://image.tmdb.org/t/p/original/9WHM084AoskcHCObAy4QnJg01eM.jpg', '서로가 최고의 친구였던 자매 엘사와 안나. 하지만 언니 엘사에게는 하나뿐인 동생에게조차 말 못할 비밀이 있다. 모든 것을 얼려버리는 신비로운 힘이 바로 그 것. 엘사는 통제할 수 없는 자신의 힘이 두려워 왕국을 떠나 북쪽 산으로 도망치고, 홀로 그곳에서 얼음 궁전을 지어 지내게 된다. 한편 얼어버린 왕국의 저주를 풀기 위해 안나는 언니를 찾아 나서고, 그 과정에서 안나는 까칠한 매력의 얼음장수 크리스토프와 만나 영원히 얼어붙은 왕국을 구해내기 위해 함께 고군분투한다.', '2014-01-16', 7.248, 20.7533, 108, 'Chris Buck', 17298, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (321612, '미녀와 야수', 'Beauty and the Beast', 'movie', 'https://image.tmdb.org/t/p/w500/tzYsKo6wGoBrP51eL9wDzfDP6Vx.jpg', 'https://image.tmdb.org/t/p/original/uU1Mt4JWhDvl4vKb3AfxNsorkoM.jpg', '프랑스의 작은 마을에 아버지와 살고 있는 벨은 책을 통해 넓은 세계를 꿈꾼다. 전쟁 영웅 개스톤의 저돌적인 구애와 마을 사람들의 핀잔에도 결혼 따위엔 관심이 없다. 어느 날 행방불명된 아버지를 찾아 폐허가 된 성에 도착한 벨은 저주에 걸린 야수를 만나 아버지 대신 성에 갇히고, 야수 뿐 아니라 성 안의 모든 이들이 신비로운 장미의 마지막 꽃잎이 떨어지기 전에 저주를 풀지 못하면 영원히 인간으로 돌아올 수 없는 운명임을 알게 된다. 성에서 도망치려던 벨은 자신을 보호해 준 야수의 진심을 알게 되면서 차츰 마음을 열어가기 시작하는데...', '2017-03-16', 6.968, 20.7052, 129, '빌 콘돈', 15885, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1096642, 'L''Attachement', 'L''Attachement', 'movie', 'https://image.tmdb.org/t/p/w500/dn3GIoD2Bjzm6ej0yt3kMtGo7ss.jpg', 'https://image.tmdb.org/t/p/original/z5HJG3hq26dgTRUwCgNneq7RATm.jpg', '', '2025-02-19', 7.196, 20.6847, 106, 'Carine Tardieu', 189, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (948184, '누군가 지켜보고 있다', '默視錄', 'movie', 'https://image.tmdb.org/t/p/w500/6ohJCscMK2GWyR03eg1pccqrxBp.jpg', 'https://image.tmdb.org/t/p/original/1beVQxKqtRkEwl3gY9TVXwnCrdp.jpg', '어린 딸이 불가사의하게 실종된 후, 젊은 부부는 이상한 동영상을 받고 누군가 그들의 일상을, 심지어 가장 사적인 순간까지 촬영해 왔다는 것을 깨닫는다. 경찰은 훔쳐보는 사람을 잡으려 집 주변을 감시하지만, 사방에서 지켜보는 감시의 시선 속에서 가족의 비밀이 드러나며 가족은 무너지기 시작한다.', '2025-05-03', 7, 20.6569, 127, 'Yeo Siew Hua', 21, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (552524, '릴로 & 스티치', 'Lilo & Stitch', 'movie', 'https://image.tmdb.org/t/p/w500/ww7jn7lv1YzTAGd5m0R6CP1VXAs.jpg', 'https://image.tmdb.org/t/p/original/7Zx3wDG5bBtcfk8lcnCWDOLM4Y4.jpg', '보송보송한 파란 솜털, 호기심 가득한 큰 눈, 장난기 가득한 웃음을 가졌지만 가장 위험한 실험체 취급을 받던 스티치는 우주에서 도망쳐 지구의 하와이 섬에 불시착하게 된다. 단짝 친구를 원하던 외톨이 소녀 릴로는 별똥별과 함께 나타난 귀여운 파란색 강아지 스티치와 소중한 친구이자, 하나의 가족이 되어가며 외로웠던 일상이 유쾌하게 변하기 시작한다. 그러던 어느 날, 스티치를 잡아 우주로 되돌아가려는 정체불명의 요원들이 등장하고 릴로와 스티치는 예상치 못한 상황을 마주하게 되는데..!', '2025-05-21', 7.225, 20.6054, 107, '딘 플레이셔 캠프', 1985, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1480382, '힌드의 목소리', 'صوت هند رجب', 'movie', 'https://image.tmdb.org/t/p/w500/cNGEWPfE3vUGPz6yzFHeI2loVm3.jpg', 'https://image.tmdb.org/t/p/original/mQwD7GtPTkv6WF5m8AJWGrO5XOE.jpg', '여섯 살 팔레스타인 소녀 힌드 라잡은 친척과 함께 차로 피신하던 중 이스라엘군의 공격을 받는다. 차 안의 유일한 생존자 힌드는 가까스로 팔레스타인 적신월사(이슬람권의 적십자) 콜센터와 연결이 된다. 이때부터 적신월사의 오마르와 동료들은 소녀를 구하기 위해 헌신적인 노력을 다한다.', '2025-09-18', 8.168, 20.5981, 89, '카우타르 벤 하니야', 134, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (603, '매트릭스', 'The Matrix', 'movie', 'https://image.tmdb.org/t/p/w500/fxBxoXFAYKWde6lKzXxSusn18Av.jpg', 'https://image.tmdb.org/t/p/original/tlm8UkiQsitc8rSuIAscQDCnP8d.jpg', '인간의 기억마저 AI에 의해 입력되고 삭제되는 세상, 진짜보다 더 진짜 같은 가상 현실 매트릭스. 그 속에서 진정한 현실을 인식할 수 없게 재배되는 인간들. 그 매트릭스를 빠져 나오면서 AI에게 가장 위험한 인물이 된 모피어스는 몇 안 되는 동료들과 함께 기계와의 전쟁 전후의의 폐허를 떠돌며 인류를 구할 마지막 영웅을 찾아 헤맨다. 마침내 모피어스는 낮에는 평범한 회사원 앤더슨으로, 밤에는 해커로 활동하는 청년 네오를 그로 지목한다. 모피어스의 지시대로 그를 만나게 된 네오는 두개의 알약 중 하나를 고르는 선택을 하게 되는데...', '1999-05-15', 8.237, 20.5334, 136, '라나 워쇼스키', 27259, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (372058, '너의 이름은.', '君の名は。', 'movie', 'https://image.tmdb.org/t/p/w500/2DJCufz3Oa703PbLjNX1pM6MCG2.jpg', 'https://image.tmdb.org/t/p/original/8x9iKH8kWA0zdkgNdpAew7OstYe.jpg', '시골에 사는 소녀 미츠하(가미시라이시 모네)는 어느 날 잠에서 깬 후 자신의 몸이 남자로 바뀐 걸 알게 된다.  같은 시간, 도쿄에 사는 소년 타키(가미키 류노스케) 역시 이 기이한 상황을 겪고 있다.  낯선 가족, 낯선 친구들, 낯선 풍경들...  서로에게 이어진 끈을 알게 된 둘은 둘만의 규칙을 정하고 점차 상황을 받아들이기 시작한다.  서로에게 남긴 메모를 확인하며  점점 친구가 되어가는 타키와 미츠하.  언제부턴가 더 이상 몸이 바뀌지 않자  자신들이 특별하게 이어져있었음을 깨달은  타키는 미츠하를 만나러 가는데...', '2017-01-04', 8.478, 20.5021, 106, '신카이 마코토', 12240, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (680, '펄프 픽션', 'Pulp Fiction', 'movie', 'https://image.tmdb.org/t/p/w500/6lXRHGoEbnnBUKsuqpL9JxD4DzT.jpg', 'https://image.tmdb.org/t/p/original/96hiUXEuYsu4tcnvlaY8tEMFM0m.jpg', '펌프킨와 허니 버니가 레스토랑에서 강도 행각을 벌이기 시작한다. 빈센트와 그 동료 쥴스는 두목의 금가방을 찾기 위해 다른 건달이 사는 아파트를 찾아간다. 마르셀러스는 부치에게 돈을 주며 상대 선수에게 져 주라고 하지만 부치는 상대 선수를 때려 눕히고 도망치다, 어릴 때 아버지에게 물려받은 시계를 찾기 위해 아파트로 향한다. 아무런 상관 없이 보이는 이 사건들이 서로 얽히고 섥히면서 예상치 못한 인과관계가 만들어지는데...', '1994-09-10', 8.486, 20.4705, 154, '쿠엔틴 타란티노', 29576, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (438631, '듄', 'Dune', 'movie', 'https://image.tmdb.org/t/p/w500/7zV8FTYofAORGm0Umgh1mNNCym8.jpg', 'https://image.tmdb.org/t/p/original/wYMbnrdRCREjNLwFlG5SLWzBjui.jpg', '10191년, 아트레이데스 가문의 후계자인 폴은 시간과 공간을 초월해 과거와 미래를 모두 볼 수 있고, 더 나은 미래를 만들 유일한 구원자인 예지된 자의 운명을 타고났다. 그리고 어떤 계시처럼 매일 꿈에서 아라키스의 행성에 있는 한 여인을 만난다. 귀족들이 지지하는 아트레이데스 가문에 대한 황제의 질투는 폴과 그 일족들을 죽음이 기다리는 아라키스로 이끄는데...', '2021-10-20', 7.776, 20.3587, 155, '드니 빌뇌브', 14344, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (346698, '바비', 'Barbie', 'movie', 'https://image.tmdb.org/t/p/w500/h3mUJ9WEJ8PzA450ad4hrjsaiqG.jpg', 'https://image.tmdb.org/t/p/original/3N5QNUqS76GFYNoEayfkkJyAyTN.jpg', '원하는 무엇이든 될 수 있는 바비랜드에서 살아가던 바비가 현실 세계와 이어진 포털의 균열을 발견하게 되고, 이를 해결하기 위해 켄과 예기치 못한 여정을 떠나면서 펼쳐지는 이야기', '2023-07-19', 6.933, 20.1435, 114, '그레타 거윅', 10692, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1248226, '플레이데이트', 'Playdate', 'movie', 'https://image.tmdb.org/t/p/w500/nzEjHWzNstCy4JeXq6bHkSSnFUB.jpg', 'https://image.tmdb.org/t/p/original/5lQ4euO30sDin5nCifvi0vURFNd.jpg', '"아빠들의 낮, 순식간에 액션으로 뒤집히다" 실직으로 집에 남게 된 한 아빠가 아이의 친구와 마련한 플레이데이트에 나선다. 가볍게 공 던지고 간식 나누면 끝일 줄 알았던 오후, 어딘가 수상한 또 다른 아빠와 얽히며 평범한 만남은 순식간에 추격과 난투, 미니밴 카체이스로 번진다. 아이들을 지키기 위해 어설픈 초보와 과하게 단련된 고수가 한 팀이 되고, 웃지 못할 실수와 의외의 재능이 번갈아 터지며 하루는 점점 통제 불능의 소동으로 치닫게 되는데...', '2025-11-05', 6.031, 20.0539, 93, 'Luke Greenfield', 473, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (23527, '제1부대, 진실의 순간', 'Первый отряд', 'movie', 'https://image.tmdb.org/t/p/w500/mh2DUD5iHNs9VR8kxxJ8yVgZD0N.jpg', 'https://image.tmdb.org/t/p/original/3k1PKmzNEosWFaOR1yC9ZKIYqmm.jpg', '1942년 구소련의 적군(赤軍)이 독일인에 맞서 저항하고 있다. 나디아는 공습으로 인한 탄환 충격에 시달리지만 곧 그녀의 새로운 재능을 발견한다. 그것은 바로 ‘진실의 순간들’을 예견할 수 있는 능력으로, 그녀는 미래의 전투에서 가장 결정적인 순간들과 조우하게 된다.', '2009-05-13', 6.259, 20.0337, 73, '芦野芳晴', 141, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1035259, '총알 탄 사나이', 'The Naked Gun', 'movie', 'https://image.tmdb.org/t/p/w500/rmwQ8GsdQ1M3LtemNWLErle2nBU.jpg', 'https://image.tmdb.org/t/p/original/kzeBfhXMRWiykBsqoL3UbfaM0S.jpg', '단 한 사람만이 경찰 특공대를 이끌고 세상을 구할 특별한 기술을 지녔다… 그는 바로 프랭크 드레빈이다.', '2025-07-30', 6.441, 20.0237, 85, 'Akiva Schaffer', 1341, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1103437, 'Please Don''t Feed the Children', 'Please Don''t Feed the Children', 'movie', 'https://image.tmdb.org/t/p/w500/GoIIdrjmXo587L2s2mqgMFvBIs.jpg', 'https://image.tmdb.org/t/p/original/1J5n9DDQN62pKkyTwzxr3wvZTzU.jpg', '', '2025-07-03', 6.1, 19.9981, 94, '데스트리 스필버그', 65, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1217602, '킬러와 보디가드', 'London Calling', 'movie', 'https://image.tmdb.org/t/p/w500/89NQ6sAp3LwODarSoVDFbmKZhAa.jpg', 'https://image.tmdb.org/t/p/original/1dqFuNiutgBdNF9d5QOQBWHHvft.jpg', '영국에서 임무를 망치고 도망친 킬러, ''토미 워드''. 그가 맡은 새 일은... 보스 아들 ''줄리언''의 보디가드 겸 인생 코치. 첫 수업부터 전설적인 암살자 제거 작전에 뛰어든다. 총을 쏘고, 가르치고, 목숨도 건다! 거래와 추격 사이, 보기 드문 킬러들의 총격전이 펼쳐진다!', '2026-01-15', 6.865, 19.9521, 115, 'Allan Ungar', 74, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (863, '토이 스토리 2', 'Toy Story 2', 'movie', 'https://image.tmdb.org/t/p/w500/gXUNsdIIn6NiEBvh8Mq6gjgVPm0.jpg', 'https://image.tmdb.org/t/p/original/nsfVr4QbbunUrHINN9N7JdVAMTf.jpg', '앤디가 카우보이 캠프에 간 동안 앤디의 어머니는 벼룩 시장을 열고 앤디의 장난감 중 위지가 팔려가게 될 운명이 되자 우디가 위지를 구하러 간다. 그러나 우디는 토이 수집가 알에게 유괴당한다. 우디는 원래 제시와 스팅키와 한 세트로 셋이 모이면 일본의 토이 박물관에 갈 수 있다. 알은 우디를 새 것처럼 고쳐주고 제시와 스팅키는 우디와 함께 박물관으로 갈 것을 우디에게 요청한다. 앤디와 친구들을 생각하며 처음엔 거절했으나 우디는 그들과 함께 박물관으로 가기로 한다. 그러나 이 사실을 모르는 버즈와 토이 친구들은 구조대를 결성해 우디를 구하러 가는데...', '1999-12-18', 7.604, 19.9505, 94, '존 라세터', 14585, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1359607, '영화 코바야시네 메이드래곤 외로움쟁이 용', '小林さんちのメイドラゴン さみしがりやの竜', 'movie', 'https://image.tmdb.org/t/p/w500/qbkDlUJuFzjozUvIFOWA1xz74oO.jpg', 'https://image.tmdb.org/t/p/original/nBKrBDxNx10SuAKPLRtBXoRku5y.jpg', '평범한 회사원 코바야시 씨. 코바야시 씨에게 이끌려 모인 드래곤들. 그중 하나 어린 드래곤 칸나에게 누군가가 찾아온다. 그 정체는 놀랍게도 칸나의 아버지였는데.', '2025-07-10', 7.6, 19.9282, 105, '石原立也', 8, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1156594, '우리의 잘못', 'Culpa nuestra', 'movie', 'https://image.tmdb.org/t/p/w500/yCbT1nKemh1AuQgdbns5Cf1RmRj.jpg', 'https://image.tmdb.org/t/p/original/srk5NlOnpEsd0hxVFiHfhtQtfDe.jpg', '헤어진 후 오랫동안 기다려온 노아와 닉은 예나와 라이온의 결혼식에서 재회한다. 노아를 용서하지 못하는 닉의 마음은 넘을 수 없는 장벽처럼 단단하다. 할아버지의 사업을 물려받은 닉과 사회생활을 시작한 노아는 아직 꺼지지 않은 불꽃에 다시 불붙는 것을 애써 피하려 한다. 하지만 두 사람의 길이 다시 만난 지금, 사랑이 원망보다 더 강해질 수 있을까?', '2025-10-15', 7.404, 19.7187, 112, '도밍고 곤살레스', 592, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1493009, 'Cobre', 'Cobre', 'movie', 'https://image.tmdb.org/t/p/w500/xXuDJUCU8m83OjyqAh79rbHtrAZ.jpg', 'https://image.tmdb.org/t/p/original/way9junUt7Myz0M83swnOoeHazK.jpg', '', '2025-07-09', 0, 19.6966, 79, 'Nicolás Pereda', 0, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (385687, '분노의 질주: 라이드 오어 다이', 'Fast X', 'movie', 'https://image.tmdb.org/t/p/w500/cltj9nKLzl0HXtz2qdu55BoIgOn.jpg', 'https://image.tmdb.org/t/p/original/4XM8DUTQb3lhLemJC51Jx4a2EuA.jpg', '돔과 그의 패밀리 앞에 나타난 운명의 적 단테. 과거의 그림자는 돔의 모든 것을 파괴하기 위해 달려온다. 단테에 의해 산산히 흩어진 패밀리들은 모두 목숨을 걸고 맞서야 하는 함정에 빠지고 마는데...', '2023-05-17', 7.008, 19.5505, 142, '루이스 레테리어', 6166, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (240, '대부 2', 'The Godfather Part II', 'movie', 'https://image.tmdb.org/t/p/w500/35RGDgySfINL9V2e6lkDECQ0hRa.jpg', 'https://image.tmdb.org/t/p/original/kGzFbGhp99zva6oZODW5atUtnqi.jpg', '아버지의 장례식 도중에 맏아들 파올로가 총에 맞아 죽고, 비토(로버트 드니로)는 겨우 도망쳐 미국으로 건너온다. 대부로 성장한 후 비토는 다시 치치오를 찾아 복수를 한다. 새롭게 등장한 젊은 대부 마이클(알 파치노)은 본거지를 라스베가스로 옮기고 가족의 사업을 가능한 합법적인 것으로 바꾸려고 애쓴다. 그런 과중 중에 자신을 제거하려는 음모를 알게되고 그는 냉혹하고 신속하게 반대파들을 제거, 조직을 더욱 확대해 나간다. 이를 위해 마이클은 배신한 형마저 죽이고, 일 때문에 아내와 헤어지는 등 인간적으로는 계속 외로워져 가는데...', '1978-04-20', 8.57, 19.5478, 202, '프랜시스 포드 코폴라', 13512, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (198663, '메이즈 러너', 'The Maze Runner', 'movie', 'https://image.tmdb.org/t/p/w500/bL0bBepUCLFcCj2ATFD40FbyDEl.jpg', 'https://image.tmdb.org/t/p/original/eTlcNXGv32zkVI7ZDHhfeaKHXKQ.jpg', '삭제된 기억, 거대한 미로로 둘러싸인 낯선 공간  모든 기억이 삭제된 채 의문의 장소로 보내진 토마스. 토마스는 미로에 갇힌 그곳에서 자신과 같은 상황의 사람들을 만난다. 그들은 매일 밤 살아 움직이는 미로에서 정체를 알 수 없는 죽음의 존재와 대립하며, 지옥으로부터 빠져나갈 탈출구인 지도를 완성해 나간다. 그러던 어느 날, 미로의 문이 열리고 그들은 마지막 선택의 기로에 놓이게 되는데…', '2014-09-18', 7.19, 19.5122, 113, '웨스 볼', 17811, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (13, '포레스트 검프', 'Forrest Gump', 'movie', 'https://image.tmdb.org/t/p/w500/xdJxoq0dtkchOkUz5UVKuxn7a2V.jpg', 'https://image.tmdb.org/t/p/original/67HggiWaP9ZLv5sPYmyRV37yAJM.jpg', '불편한 다리, 남들보다 조금 떨어지는 지능을 가진 포레스트 검프는 헌신적인 어머니의 보살핌과 첫사랑 제니와의 만남으로 편견과 괴롭힘 속에서도 따뜻한 마음을 지니고 성장한다. 또래들의 괴롭힘을 피해 도망치던 포레스트는 누구보다 빠르게 달릴 수 있는 자신의 재능을 깨닫는다. 그의 재능을 알아 본 대학에서 그를 미식축구 선수로 발탁하고, 졸업 후에도 뛰어난 신체능력으로 군에 들어가 무공훈장을 수여받는 등 탄탄한 인생 가도에 오르게 된 포레스트. 하지만 어머니가 병에 걸려 죽음을 맞이하고, 첫사랑 제니 역시 그의 곁을 떠나가며 다시 한 번 인생의 전환점을 맞이하게 되는데...', '1994-10-15', 8.462, 19.4409, 142, '로버트 저메키스', 29139, 0);
