INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1161617, '코드 3', 'Code 3', 'movie', 'https://image.tmdb.org/t/p/w500/lIxySIaEBsoy8FxeQ4Xk9U8g7Hw.jpg', 'https://image.tmdb.org/t/p/original/vZK3f5N8Fv2LcyFYLwt6dz0HE1H.jpg', '번아웃으로 한계에 다다른 베테랑 구급대원 랜디는 마침내 일을 그만두기로 결심하지만, 사직서를 내려면 먼저 새로 들어온 신참 구급대원 제시카를 하루 동안 교육해야 한다. 그의 마지막 24시간은 평범한 근무로 시작되지만 곧 예상을 벗어나 기이한 신고들, 황당한 환자들, 예산이 바닥난 현실이 한꺼번에 몰아치며 통제 불능의 하루가 펼쳐진다.', '2025-09-12', 6.9, 19.3198, 100, 'Christopher Leone', 181, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1257009, '프리미티브 워', 'Primitive War', 'movie', 'https://image.tmdb.org/t/p/w500/rPFXcEp6UNLJrjktuixG0aesNwe.jpg', 'https://image.tmdb.org/t/p/original/bWF5ImUscXXYia8owpm8coadR4m.jpg', '1968년, 베트남 정글 깊숙이 사라진 특수부대를 찾기 위해 미군 정찰대가 투입된다. 하지만 그들이 마주한 것은 전쟁이 아니라, 정부의 비밀 실험이 낳은 ‘시간의 틈’이었다. 살아있는 공룡들이 지배하는 금단의 구역에서, 인간은 다시 사냥감이 된다.', '2025-08-21', 6.7, 19.3135, 133, 'Luke Sparke', 212, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1295026, '100미터.', 'ひゃくえむ。', 'movie', 'https://image.tmdb.org/t/p/w500/itooVuz3gka7ykr3TpOvwXYqESM.jpg', 'https://image.tmdb.org/t/p/original/hKy4J8jbiOBmSKs0NlcHP1hLWYl.jpg', '선천적으로 발이 빨라 달리기에서 지는 법이 없던 토가시는 현실을 잊기 위해 무작정 달렸던 전학생 코미야를 만나 제대로 달리는 법을 가르쳐 준다. 누구보다 빠르게 달릴 때의 환희를 알게 된 코미야는 토가시에게 100M 경주를 신청하고 그날의 경기 이후 코미야는 토가시의 앞에서 사라진다. 그리고 몇 년 후, 계속 이겨야 한다는 압박감에 시달리고 있던 토가시 앞에 일본 기록 경신을 꿈꾸는 코미야가 나타나는데…', '2025-10-08', 7.652, 19.2004, 106, '岩井澤健治', 56, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (693134, '듄: 파트 2', 'Dune: Part Two', 'movie', 'https://image.tmdb.org/t/p/w500/8AsDR2o5AC3V8Jmj6JH6cpta7dz.jpg', 'https://image.tmdb.org/t/p/original/o869RihWTdTyBcEZBjz0izvEsVf.jpg', '황제의 모략으로 멸문한 가문의 유일한 후계자 폴. 어머니 레이디 제시카와 간신히 목숨만 부지한 채 사막으로 도망친다. 그곳에서 만난 반란군들과 숨어 지내다 그들과 함께 황제의 모든 것을 파괴할 전투를 준비한다. 한편 반란군들의 기세가 높아질수록 불안해진 황제와 귀족 가문은 잔혹한 암살자 페이드 로타를 보내 반란군을 몰살하려 하는데…', '2024-02-28', 8.131, 19.1943, 167, '드니 빌뇌브', 7430, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1022787, '엘리오', 'Elio', 'movie', 'https://image.tmdb.org/t/p/w500/ymd7E8ZRXOfOpJ418rgGtEdVmEN.jpg', 'https://image.tmdb.org/t/p/original/ukPu5xYOBAnh5H46uK4aQOirW2b.jpg', '세상 그 어디에서도 소속감을 느끼지 못한 채, 외계인의 납치를 꿈꾸는 외톨이 소년 엘리오. 그러던 어느 날 작은 오해로 인해 지구 대표로 우주에 소환되고, 그곳에서 자신과는 너무도 다른 특별한 존재 글로든을 만나 처음으로 마음을 나눌 친구를 갖게 된다.  낯설지만 따뜻한 우주에서 꿈같은 나날들을 보내던 엘리오 앞에 온 우주를 위험에 빠뜨릴 크나큰 위기가 닥쳐오는데...', '2025-06-18', 6.954, 19.1789, 98, '마데라인 사라피안', 801, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (949709, '하이포스', '危机航线', 'movie', 'https://image.tmdb.org/t/p/w500/2bP8QgJo5LlK25Fo9hLjRWZRkXq.jpg', 'https://image.tmdb.org/t/p/original/8lqfrOBQ2EcY7znD3LxTYcvlh25.jpg', '10,000피트 상공에서 벌어진 비행기 납치 테러. 특수요원 하오쥔(유덕화)은 가족들과 승객들의 생존을 위해 납치된 항공기 안에서 테러범들과 숨 막히는 결전을 벌인다.', '2025-10-15', 5.952, 19.1654, 115, '彭順', 31, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (10192, '슈렉 포에버', 'Shrek Forever After', 'movie', 'https://image.tmdb.org/t/p/w500/t3FNCqPBgRK9jYTzLGWptIdpD3O.jpg', 'https://image.tmdb.org/t/p/original/uzzTystB8lL0mRDII5Sfs5HxgkI.jpg', '슈렉이 아름다운 공주 피오나와 겁나먼 왕국을 구해낸 이후. 그들도 오래오래 행복하게 살았...더라면 참 좋았을텐데! 과연 슈렉에게도 모두가 바라던 해피엔딩이 올까?  한 가정의 평범한 아빠와 남편으로 반복되는 일상에 따분함을 느끼던 슈렉은 마을 사람들에게 겁을 주고, 진흙 목욕도 실컷 하던 시절의 자유를 꿈꾸게 된다. ‘단 하루라도 자유로워진다면 죽어도 한이 없겠어’라며 일탈을 꿈꾸던 슈렉은 ‘겁나먼 왕국’을 차지하려는 악당 럼펠의 그럴싸한 계략에 속아 넘어가 ‘완전 딴판 겁나먼 세상’에 떨어지고 만다. 완전 딴판으로 바뀌어버린 세상에서 절친 동키는 슈렉을 미친 괴물 취급하며 줄행랑 치고, 단 하나의 사랑 피오나는 하이킥을 날리고, 장화신은 고양이는 더 이상 장화를 신지 않는 D라인의 고양이가 되어 있다. 친구들과 왕국, 그리고 하나뿐인 진실한 사랑을 되찾기 위한 슈렉의 마지막 이야기가 시작된다!', '2010-07-01', 6.394, 19.1573, 93, 'Mike Mitchell', 7789, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1266798, '도그 51', 'Chien 51', 'movie', 'https://image.tmdb.org/t/p/w500/6pSkQRQxxC5AJ82aKbp1lFXQnXo.jpg', 'https://image.tmdb.org/t/p/original/OO75q1cTWWXDmy52bB79yzpxBt.jpg', '', '2025-10-15', 6.421, 19.1335, 100, 'Cédric Jimenez', 164, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (672, '해리 포터와 비밀의 방', 'Harry Potter and the Chamber of Secrets', 'movie', 'https://image.tmdb.org/t/p/w500/bo8FuQPWKLqbg3WgAXYISkwrbZ9.jpg', 'https://image.tmdb.org/t/p/original/1stUIsjawROZxjiCMtqqXqgfZWC.jpg', '해리 포터에겐 이번 여름방학이 별로 즐겁질 못했다. 마법이라면 질색을 하는 페투니아 이모와 버논 이모부의 구박도 그렇지만, 무엇보다 속상한 건 단짝이었던 론 위즐리와 헤르미온느 그레인저가 그 사이 자신을 까맣게 잊었는지 자신의 편지에 답장 한 통 없다는 것.  그러던 어느날 꼬마 집요정 도비가 해리의 침실에 나타나 뜻밖의 얘기를 한다. 호그와트 마법학교로 돌아가면 무서운 일을 당할 거라는 것. 도비는 해리를 학교에 못 가게 하려고 자신이 여태까지 론과 헤르미온느의 답장을 가로채 왔음을 고백한다. 그러나 도비와 더즐리 가족의 방해에도 불구, 해리는 론과 그의 형제들이 타고 온 하늘을 나는 자동차를 타고 이모집을 탈출, 따뜻한 가족애가 넘치는 론의 집으로 가는데...', '2002-12-13', 7.705, 19.0426, 160, '크리스 콜럼버스', 23174, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1086260, '애스트로넛', 'The Astronaut', 'movie', 'https://image.tmdb.org/t/p/w500/souvvkJHYhztC1UqZ8lEVUiJa3J.jpg', 'https://image.tmdb.org/t/p/original/3C01kAcKGR6FwsUUSOvJ8N82pqr.jpg', '"우주에서 돌아온 순간, 진짜 공포는 집 안에서 시작된다" 첫 임무 후 기적적으로 귀환한 NASA 우주비행사 샘 워커는 숲속의 보안 하우스에서 격리 재활을 받게 된다. 양부이자 군 장성의 감시 아래 남편과 재회하지만, 깊어가는 밤마다 설명할 수 없는 흔적과 환청, 피부 아래서 꿈틀대는 감각이 그녀를 잠식한다. 사고의 후유증인지, 함께 내려온 ‘무언가’인지 알 수 없는 공포 속에서 이성으로 무장한 샘의 세계가 균열을 넓혀 가기 시작한다. 결국 사랑하는 이들까지 위험에 휩싸이자 샘은 자신을 따라붙는 진실과 맞설 결단을 내리게 되는데...', '2025-09-26', 5.678, 19.0104, 90, 'Jess Varley', 160, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1238188, 'El cautivo', 'El cautivo', 'movie', 'https://image.tmdb.org/t/p/w500/2vfxMQ3WEA8goCH7LXlAzED9aed.jpg', 'https://image.tmdb.org/t/p/original/sBEM8U5l7jq0BH7XiC7Zzs4d8e2.jpg', '', '2025-09-12', 7.479, 18.9341, 134, '알레한드로 아메나바르', 24, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1242419, '루프맨', 'Roofman', 'movie', 'https://image.tmdb.org/t/p/w500/qUeT9KG99sSyxkGzWJ7pBVoKz5j.jpg', 'https://image.tmdb.org/t/p/original/2YOnE2qmoyyOUqQsFit12gDSauk.jpg', '전직 육군 레인저이자 생활고에 몰려 맥도날드 매장의 지붕을 뚫고 침입하는 방식으로 강도를 벌이며 ‘루프맨’이라는 별명을 얻는다. 체포된 뒤 탈옥에 성공한 그는 한동안 모습을 감춘 채 토이저러스 매장 안에 숨어 6개월 동안 아무에게도 들키지 않고 지내며 다음 범행을 준비한다. 그러던 중, 예기치 않게 한 이혼 여성을 만나 그의 매력에 이끌린 그녀와 관계가 깊어지면서 그의 이중생활은 균열을 맞기 시작한다. 그리고 과거가 서서히 그를 덮쳐오며, 숨기려는 남자와 들춰내려는 세력 사이에 팽팽한 긴장감의 고양이와 쥐의 추격전이 펼쳐진다.', '2025-10-08', 7.201, 18.9148, 126, '데릭 시엔프랜스', 459, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (854, '마스크', 'The Mask', 'movie', 'https://image.tmdb.org/t/p/w500/jPC2eYub74zwf2tPGVtzSlBW6Oy.jpg', 'https://image.tmdb.org/t/p/original/bQlw59HncOXX9alFlOYKHAvSnm.jpg', '에지 시(Edge City). 은행에서 단조로운 일상을 보내고 있던 평범한 은행원 스탠리. 어느날 그는 우연한 기회로 고대 시대의 유물인 마스크를 발견한다. 그런데 이 마스크는 아주 신비로운 힘을 가지고 있다.  스탠리가 마스크를 쓰면 초인적인 힘을 가진 불사신이 된다. 스탠리는 나이트클럽 가수인 티나를 사랑하지만 그녀는 악당 조직 보스의 정부다. 스탠리의 마스크 때문에 여러가지 소동이 일어나고 경찰은 스탠리를 뒤쫓는다. 티나가 보스를 사랑하지도 않으며 빠져나올 기회만을 노리고 있다는 것을 알고 그녀를 돕는다.  스탠리의 마스크 때문에 일어난 여러가지 소동으로 경찰은 그를 추적하고 엎친데 덮친격으로 조직까지 가세, 쫓고 쫓기는 사건이 벌어진다. 조직의 사주를 받은 어느 여기자에 의해 정체가 탄로난 스탠리는 조직에게 마스크를 빼앗기고 조직의 보스는 마스크를 이용하여 도시의 세력을 장악하려하는데…', '1994-08-20', 6.975, 18.8869, 101, 'Chuck Russell', 10962, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1184918, '와일드 로봇', 'The Wild Robot', 'movie', 'https://image.tmdb.org/t/p/w500/8dkuf9IuVh0VZjDTk7kAY67lU0U.jpg', 'https://image.tmdb.org/t/p/original/1pmXyN3sKeYoUhu5VBZiDU4BX21.jpg', '우연한 사고로 거대한 야생에 불시착한 로봇 로즈는 주변 동물들의 행동을 배우며 낯선 환경 속에 적응해 가던 중, 사고로 세상에 홀로 남겨진 아기 기러기 브라이트빌의 보호자가 된다. 로즈는 입력되어 있지 않은 새로운 역할과 관계에 낯선 감정을 마주하고 겨울이 오기 전에 남쪽으로 떠나야 하는 브라이트빌을 위해 동물들의 도움을 받아 이주를 위한 생존 기술을 가르쳐준다. 그러나 선천적으로 몸집이 작은 브라이트빌은 짧은 비행도 힘겨워 하는데...', '2024-10-01', 8.313, 18.8651, 102, '크리스 샌더스', 5667, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (807, '세븐', 'Se7en', 'movie', 'https://image.tmdb.org/t/p/w500/izzk8dbmrLowcoGbFaebqJvzyXg.jpg', 'https://image.tmdb.org/t/p/original/iwgl8zlrrfvfWp9k9Paj8lvFEvS.jpg', '은퇴를 7일 앞둔 관록의 형사 윌리엄 소머셋(모건 프리먼)과 새로 전근 온 신참내기 형사 밀스(브래드 피트)가 팀이 된 바로 다음날, 강압에 의해 위가 찢어질 때까지 먹다가 죽은 초고도 비만 남자와 역시 강압에 의해 식칼로 자기 살을 베어내 죽은 악덕 변호사의 사건과 마주한다. 식탐, 탐욕, 그리고 나태, 분노, 교만, 욕정, 시기. 소머셋은 현장에 남은 흔적들로 단테의 신곡과 쵸서의 캔터베리 서사시를 근거로 한 기나긴 연쇄 살인이 시작되었음을 직감하고 성서의 7가지 죄악을 따라 발생하는 사건들을 추적하기 시작하는데...', '1995-11-11', 8.379, 18.8437, 127, '데이비드 핀처', 22510, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (346364, '그것', 'It', 'movie', 'https://image.tmdb.org/t/p/w500/nlZKIOeoSWwrRcrppoIbkfOGZ6J.jpg', 'https://image.tmdb.org/t/p/original/tcheoA2nPATCm2vvXw2hVQoaEFD.jpg', '살인과 실종사건이 이상하게 많이 생기는 데리라는 마을, 비 오는 어느 날 종이배를 들고 나간 동생이 사라졌다.  형 빌은 ‘루저 클럽’ 친구들과 함께 동생을 찾아 나서고, 27년마다 가장 무서워하는 것의 모습을 한 채 아이들을 잡아먹는다는 ‘그것’이 빨간 풍선을 든 삐에로의 모습으로 그들 앞에 나타나는데…  빌과 친구들은 공포를 이겨내고 ‘그것’에 맞서 동생과 사라진 아이들을 찾을 수 있을까?', '2017-09-06', 7.239, 18.7412, 135, '앤디 무시에티', 20019, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1206083, 'Conjuring Tapes', 'Conjuring Tapes', 'movie', 'https://image.tmdb.org/t/p/w500/puPN6uC5NpbAQW8dDovGkJ79arn.jpg', 'https://image.tmdb.org/t/p/original/w3KuQ1rLd7Ur26WluD0k9oLgYdQ.jpg', '', '2025-04-10', 5.1, 18.697, 79, 'Randy Nundlall Jr.', 13, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (674, '해리 포터와 불의 잔', 'Harry Potter and the Goblet of Fire', 'movie', 'https://image.tmdb.org/t/p/w500/uWPnKtu1eutmgBQ2hoWm0Xe8nfN.jpg', 'https://image.tmdb.org/t/p/original/8f9dnOtpArDrOMEylpSN9Sc6fuz.jpg', '요즘 들어 매일 꾸는 악몽 때문에 이마의 상처에 더욱 통증을 느끼는 해리는 친구 론과 헤르미온느와 함께 퀴디치 월드컵에 참가해 악몽에서 벗어날 수 있게 돼 마냥 기쁘다. 그러나 퀴디치 캠프장 근방 하늘에 불길한 기운이 나타난다. 바로 마왕 볼드모트의 상징인 어둠의 표식이 나타난 것. 볼드모트가 13년 전에 자취를 감춘 뒤, 감히 모습을 드러내지 못했던 그의 추종자 데스 이터들이 그 표식을 불러낸 것이다. 두려움으로 가득 찬 해리는 안전한 호그와트 마법학교로 돌아가고 싶어한다. 덤블도어 교장이라면 자신을 지켜줄 수 있을 것이기에. 그러나 올해는 예년과 상황이 좀 다른데...', '2005-12-01', 7.801, 18.5737, 157, '마이크 뉴웰', 21771, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1616993, 'Safia/Safdar', 'Safia/Safdar', 'movie', 'https://image.tmdb.org/t/p/w500/ggN2WBU8cRMehVdS1nV0VYHACin.jpg', 'https://image.tmdb.org/t/p/original/uSBUMknphVjcnGJk6se3gWe9omG.jpg', '', '2026-01-16', 0, 18.5694, 106, 'Baba Azmi', 0, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (216015, '그레이의 50가지 그림자', 'Fifty Shades of Grey', 'movie', 'https://image.tmdb.org/t/p/w500/iQaLakvYBzpmdHUB2h6h2aVY5nE.jpg', 'https://image.tmdb.org/t/p/original/7IGKrY1f1KfwMipx9wZC4NRgIdF.jpg', '순수한 사회 초년생인 여대생 ‘아나스타샤’는 어느 날, 아픈 친구를 대신해 모든 것을 다 가진 매력적인 CEO ‘크리스찬 그레이’의 인터뷰를 맡게 된다. 단숨에 사람을 매료시키는 ‘크리스찬 그레이’의 마력에 ‘아나스타샤’는 순식간에 빠져들고, 그 역시 순수한 아나스타샤를 점점 더 알고 싶어지게 된다.  내 취향은 아주 분명해.  한편, 원하는 것을 모두 들어줄 만큼 완벽한 ‘그레이’의 숨겨진 비밀을 알게 된 ‘아나스타샤’는 거부할 수 없는 본능에 눈을 뜨게 되는데…', '2015-02-25', 5.874, 18.5168, 125, '샘 테일러존슨', 12231, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (497, '그린 마일', 'The Green Mile', 'movie', 'https://image.tmdb.org/t/p/w500/pk1TPODQVnI8GdLf0DhlJQYxWjd.jpg', 'https://image.tmdb.org/t/p/original/lgJlu0Fp1mdTaFEeaQJ7DskhSOr.jpg', '미국 루이지애나의 콜드 마운틴 교도소. 폴은 사형수 감방의 간수장으로 일하고 있다. 그의 일은 사형수들을 감독하고, 그린 마일이라 불리는 초록색 복도를 거쳐 그들을 사형 집행장까지 안내하는 것. 폴은 그들이 죽음을 맞이하는 순간까지 평화롭게 지낼 수 있도록 최선을 다한다. 어느 날 존 커피라는 사형수가 이송되어 온다. 그는 쌍둥이 여자아이를 살해한 흉악범. 하지만 순진한 눈망울에 겁을 잔뜩 집어먹은 그의 모습에 폴은 당혹감을 느낀다. 게다가 그는 초자연적 능력으로 폴의 지병을 깨끗하게 치료해주기까지 한다. 존을 전기 의자로 데려가야 할 날이 다가오면서 폴은 그가 무죄라는 확신을 갖게 되는데...', '2000-03-04', 8.503, 18.4773, 189, '프랭크 다라본트', 18754, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (939243, '수퍼 소닉 3', 'Sonic the Hedgehog 3', 'movie', 'https://image.tmdb.org/t/p/w500/4784u4fHwcvc4owOGylVpP7JaKQ.jpg', 'https://image.tmdb.org/t/p/original/noPEm6Vu9Lm6QUdTGLOyRgk4M6s.jpg', '너클즈, 테일즈와 함께 평화로운 일상을 보내던 초특급 히어로 소닉. 연구 시설에 50년간 잠들어 있던 사상 최강의 비밀 병기 "섀도우"가 탈주하자, 세계 수호 통합 부대(약칭 세.수.통)에 의해 극비 소집된다. 소중한 것을 잃은 분노와 복수심에 불타는 섀도우는 소닉의 초고속 스피드와 너클즈의 최강 펀치를 단 단숨에 제압해버린다. 세상을 지배하려는 닥터 로보트닉과 그의 할아버지 제럴드 박사는 섀도우의 엄청난 힘 카오스 에너지를 이용해 인류를 정복하려고 하는데…', '2025-01-01', 7.632, 18.4492, 110, 'Jeff Fowler', 3111, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (822119, '캡틴 아메리카: 브레이브 뉴 월드', 'Captain America: Brave New World', 'movie', 'https://image.tmdb.org/t/p/w500/qj1uEI7zrCWbMppjFZmCXVlWlb1.jpg', 'https://image.tmdb.org/t/p/original/8eifdha9GQeZAkexgtD45546XKx.jpg', '대통령이 된 새디우스 로스와 재회 후, 국제적인 사건의 중심에 서게 된 샘이 전 세계를 붉게 장악하려는 사악한 음모 뒤에 숨겨진 존재와 이유를 파헤쳐 나가는 액션 블록버스터', '2025-02-12', 5.99, 18.3412, 119, '줄리어스 오나', 2882, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (986056, '썬더볼츠*', 'Thunderbolts*', 'movie', 'https://image.tmdb.org/t/p/w500/iTX4O9gb8Jn0F5N5WgYnbIopdnP.jpg', 'https://image.tmdb.org/t/p/original/jYCyTdPfgT01IOJWDnnetr9RDX6.jpg', '어벤져스가 사라진 후, 세계 최대의 위협과 마주한 세상을 구하기 위해 전직 스파이, 암살자, 살인 청부 업자 등 마블의 별난 놈들이 펼치는 예측불허 팀플레이를 담은 액션 블록버스터', '2025-04-30', 7.306, 18.3009, 127, '제이크 슈레이어', 3117, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1477388, '은밀한 전화 상담소', 'Sex On Phone', 'movie', 'https://image.tmdb.org/t/p/w500/scE01UqdYdu4BcDk3DDYcemr7vQ.jpg', NULL, '남편한텐 비밀, 내게 딱 맞는 직장을 찾았다!? 생계를 위해 성인 콜센터에 취직한 ‘어맨다’. 그녀의 업무는 전화를 걸어오는 손님들의 성적 판타지를 채워주는 일! 출근 첫날부터 엄청난 실적을 올리며 재능을 발견한다. 일을 하면서 오히려 자신의 환상을 충족하던 어맨다는 급기야 단골 손님 ‘알프레드’와 실제 만남을 가지려고 하는데…', '2025-11-28', 7, 18.2407, 97, 'Bobby Bonifacio', 4, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (673, '해리 포터와 아즈카반의 죄수', 'Harry Potter and the Prisoner of Azkaban', 'movie', 'https://image.tmdb.org/t/p/w500/anwNl1xbzXoj5Ax1nVw3WoDzHlw.jpg', 'https://image.tmdb.org/t/p/original/vbk5CfaAHOjQPSAcYm6AoRRz2Af.jpg', '13세가 된 해리 포터는 또 한번의 여름 방학을 이모 가족인 더즐리 일가와 우울하게 보내야 했다. 물론 마법을 쓰는 건 일체 금지. 하지만, 버논 이모부의 누이인 마지 아줌마가 더즐리 가를 방문하면서 상황은 변한다. 위압적인 마지는 해리에겐 늘 공포의 대상. 마지 아줌마 때문에 스트레스를 받던 해리는 급기야 실수로 그녀를 거대한 괴물 풍선으로 만들어 하늘 높이 띄워 보내버리고 만다. 이모와 이모부에게 벌을 받을 것도 두렵고, 일반 세상에선 마법 사용이 금지돼 있는 것을 어겼기 때문에 호그와트 마법학교와 마법부의 징계가 걱정된 해리는 밤의 어둠 속으로 도망치지만, 순식간에 근사한 보라색 3층 버스에 태워져 한 술집으로 인도되고 마는데...', '2004-07-16', 8.009, 18.2407, 136, '알폰소 쿠아론', 22753, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (122917, '호빗: 다섯 군대 전투', 'The Hobbit: The Battle of the Five Armies', 'movie', 'https://image.tmdb.org/t/p/w500/8SGuYvRd6mGdgL6oOGgwuK0R7Qc.jpg', 'https://image.tmdb.org/t/p/original/3UbaCMmqOd7mca4Y5DOzY2ZVTyX.jpg', '빌보 배긴스와 참나무 방패 소린, 난쟁이 족이 떠난 거대한 여정의 끝에 난쟁이 족은 원래 자신들의 터전이던 에레보르에 있는 엄청난 보물을 되찾지만 이는 무시무시한 용 스마우그가 호수마을의 무기력한 주민들을 공격하게 되는 결과를 낳는다. 소린은 탐욕에 서서히 눈이 멀어 우정과 명예를 저버린 채 왕의 보물 아르켄스톤을 찾는다. 암흑의 군주 사우론은 오크 군대를 보내 외로운 산에 기습 공격을 감행한다. 마침내 다섯 군대의 전투가 시작되고 빌보는 본인과 친구들의 목숨을 걸고 싸워야만 하는데...', '2014-12-17', 7.331, 18.219, 144, '피터 잭슨', 15042, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1259102, '영원', 'Eternity', 'movie', 'https://image.tmdb.org/t/p/w500/d18gChFbkzbXQNY3owiVbqmHB7K.jpg', 'https://image.tmdb.org/t/p/original/fuacZLpnohQtLD0AhtCErcPVL98.jpg', '죽음 이후 가장 행복했던 시절의 모습으로 사후세계 환승역에 도착한 조앤.  그곳에서 65년 평생을 함께했던 남편 래리와 67년 전 사별한 첫사랑이자 전남편 루크를 동시에 만나게 된다. 살아생전 추구했던 원하던 세상에서 사랑하는 사람과 영원을 보낼 수 있는 환상적인 사후세계를 앞에 두고 조앤은 마지막 환승(!)을 고민하게 되는데! 래리VS루크, 조앤이 평생을 넘어 영원을 함께 하고 싶은 단 하나의 사랑은?!', '2026-02-04', 7.061, 18.1802, 114, 'David Freyne', 344, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (650524, '尋秦記', '尋秦記', 'movie', 'https://image.tmdb.org/t/p/w500/h3OUaPfCaFmzwB2eMHik50RsXlP.jpg', 'https://image.tmdb.org/t/p/original/gpJr8wRED8BpBVaxM0eODQEBNwC.jpg', '', '2025-12-31', 7, 18.1624, 107, '吳炫輝', 6, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1186350, '마르코', 'മാർക്കോ', 'movie', 'https://image.tmdb.org/t/p/w500/6Nj8Y1A9lcReqZZvRHOSiO3iTl6.jpg', 'https://image.tmdb.org/t/p/original/a6RkQIOZ6wThQOEDv6lHsfH53hD.jpg', '케랄라의 유서 깊은 ''아다투'' 가문 출신이자 시각장애인인 ''빅터''는 친구 ''와심''이 살해당하는 현장을 목격한다. 범인은 금 밀수 조직 ''아이작'' 가문의 ''러셀''. 그는 비밀을 감추기 위해 결국 빅터까지 살해한다. 빅터의 형이자 가문의 가장인 ''조지''는 진실을 파헤치려 하고 해외에 머물던 양자 ''마르코''는 동생의 죽음에 복수를 결심한다. 조지의 만류도 소용없다. 마르코는 빅터의 죽음에 연루된 이들을 향해 피의 심판을 맹세한다.', '2025-07-06', 6.535, 18.1286, 145, 'Haneef Adeni', 101, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1865, '캐리비안의 해적: 낯선 조류', 'Pirates of the Caribbean: On Stranger Tides', 'movie', 'https://image.tmdb.org/t/p/w500/osJVVjkHmoO5WoJfbBsImYrKWIb.jpg', 'https://image.tmdb.org/t/p/original/uzIGtyS6bbnJzGsPL93WCF1FWm8.jpg', '부두교의 주술을 부리던  검은 수염은 다리가 한쪽인 남자에게 죽게 된다는 예언을 듣게 된다. 자신의 수명을 늘리기 위해 검은 수염은 젊음의 샘을 찾으러 떠나고, 바르보사 또한 검은수염에게 복수를 하기 위해 그를 뒤쫒는다. 한편 영국에서 블랙펄의 선장이 선원을 모집한다는 소문을 듣게 된 잭 스패로우는 자신을 사칭하는 사기꾼을 잡으려다 영국 왕실에 체포되고, 영국의 국왕은 잭 스패로우에게 젊음의 샘으로 가는 길을 안내하라고 명령하고, 이에 필요한 선장과 배, 선원을 모두 내 주겠다고 하는데...', '2011-05-19', 6.565, 18.0613, 136, '롭 마셜', 14695, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (315635, '스파이더맨: 홈커밍', 'Spider-Man: Homecoming', 'movie', 'https://image.tmdb.org/t/p/w500/hjki9weYYVABvkpZbX5jBOmKXXv.jpg', 'https://image.tmdb.org/t/p/original/tPpYGm2mVecue7Bk3gNVoSPA5qn.jpg', '토니 스타크의 제안을 받고 시빌 워에 참여한 피터 파커는 다음 임무가 언제일지 설렘을 안고 하루하루를 보낸다. 토니는 MIT 진학 준비에 전념할 것을 권하지만 친절한 이웃에 머무는 것은 피터의 성에 차지 않는다. 한편 어벤져스 군단과 외계 세력의 전투로 생긴 산업폐기물을 처리하던 아드리안 툼즈는 그 일이 토니 스타크와 정부에 넘어가면서 하루아침에 빈털터리가 된다. 이에 앙심을 품은 아드리안은 외계 첨단무기를 훔쳐서 개조하는 빌런이 되고, 그의 존재를 알게 된 피터는 도움을 빌리지 않고 자기가 일을 해결해보려고 한다.', '2017-07-05', 7.3, 18.0377, 133, '존 왓츠', 22772, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (502356, '슈퍼 마리오 브라더스', 'The Super Mario Bros. Movie', 'movie', 'https://image.tmdb.org/t/p/w500/jt1GlLLvkWL2m83VX8I1qsDR187.jpg', 'https://image.tmdb.org/t/p/original/9n2tJBplPbgR2ca05hS5CKXwP2c.jpg', '따단-딴-따단-딴 ♫ 전 세계를 열광시킬 올 타임 슈퍼 어드벤처의 등장! 뉴욕의 평범한 배관공 형제 ''마리오''와 ‘루이지’는 배수관 고장으로 위기에 빠진 도시를 구하려다 미스터리한 초록색 파이프 안으로 빨려 들어가게 된다. 파이프를 통해 새로운 세상으로 차원 이동하게 된 형제. 형 ''마리오''는 뛰어난 리더십을 지닌 ''피치''가 통치하는 버섯왕국에 도착하지만 동생 ''루이지''는 빌런 ''쿠파''가 있는 다크랜드로 떨어지며 납치를 당하고 ‘마리오’는 동생을 구하기 위해 ‘피치’와 ‘키노피오’의 도움을 받아 ''쿠파''에 맞서기로 결심한다. 그러나 슈퍼스타로 세상을 지배하려는 그의 강력한 힘 앞에 이들은 예기치 못한 위험에 빠지게 되는데...!', '2023-04-26', 7.597, 17.9615, 93, 'Michael Jelenic', 10216, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (105, '빽 투 더 퓨쳐', 'Back to the Future', 'movie', 'https://image.tmdb.org/t/p/w500/7gGicAJdHRzaUd6qLjH5bSW4Cgi.jpg', 'https://image.tmdb.org/t/p/original/qskzmLTbarKnXDbo2HRj4NJ3vcW.jpg', '마티 맥플라이(마이클 J. 폭스)는 평범한 고등학생이다. 그런데 평소 친하게 지내던 괴상한 발명가 에메트 브라운 박사(크리스토퍼 로이드)가 스포츠카 드로리안을 개조해 타임머신을 만들고, 뜻밖의 사고로 브라운 박사가 테러범들에게 총을 맞고 위험해진 상황에서 마티는 30년 전으로 가게 된다. 극장 간판에는 2류 배우인 로널드 레이건이 보이고 청년인 아버지와 어머니를 보게 된다. 젊은 아버진 멍청하고, 어머니는 미래의 아들인 마티를 좋아해 야단이다. 마티가 미래로 가는 것을 도와 줄 사람은 30년 전인 젊은 브라운 박사뿐인데...', '1987-07-17', 8.323, 17.9343, 120, '로버트 저메키스', 21305, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (755679, '분노의 질주 10: 파트 2', 'Fast X: Part 2', 'movie', 'https://image.tmdb.org/t/p/w500/lD8V3DBban95Mxz4sjuA81Tw771.jpg', NULL, '', NULL, 0, 17.9169, NULL, '루이스 레테리어', 0, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (49026, '다크 나이트 라이즈', 'The Dark Knight Rises', 'movie', 'https://image.tmdb.org/t/p/w500/stbZZs3WMPr9rvAT92Qd8gXCUfx.jpg', 'https://image.tmdb.org/t/p/original/y2DB71C4nyIdMrANijz8mzvQtk6.jpg', '배트맨이 조커와의 대결을 끝으로 세상에서 모습을 감춘 8년 후, 하비 덴트의 죽음에 대한 책임을 떠안은 배트맨은 모든 것을 희생하며 떠난다. 범죄방지 덴트법으로 인해 한동안 평화가 지속되던 고담시의 파멸을 예고하며 나타난 마스크를 쓴 잔인한 악당, 최강의 적 베인이 등장한다. 베인은 배트맨이 스스로 택한 유배 생활에 종지부를 찍게 하지만, 다시 돌아온 배트맨에게 베인은 만만한 상대가 아니다. 자신을 거부한 사람들의 고통을 지켜볼 것인가, 정의의 수호자로 나설 것인가. 배트맨은 승패를 알 수 없는 마지막 전투를 시작하려 하는데...', '2012-07-19', 7.791, 17.9126, 164, '크리스토퍼 놀란', 23909, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (495764, '버즈 오브 프레이: 할리 퀸의 황홀한 해방', 'Birds of Prey (and the Fantabulous Emancipation of One Harley Quinn)', 'movie', 'https://image.tmdb.org/t/p/w500/1HjYMW5Je0D8JkRl5DEXJSdVtDK.jpg', 'https://image.tmdb.org/t/p/original/uozb2VeD87YmhoUP1RrGWfzuCrr.jpg', '오랜 연인이던 조커와 헤어진 할리 퀸은 처음 맞이한 해방에 황홀함을 느낀다. 하지만 조커라는 방패막이 사라지자 평생 처음 무방비 상태에 놓인 할리 퀸을 고담시에서 가장 비열한 범죄왕 로만 시오니스와 고담의 모든 갱들이 노린다. 통제 불능의 상태에서 카산드라라는 소매치기가 로만의 부하에게서 모든 권력과 고담시 지하 세계 전체의 지배권을 차지할 열쇠인 금융 정보가 암호화되어 있는 다이아몬드를 훔치면서 사건을 걷잡을 수 없이 급변한다. 로만 손에 죽을 위기에 처한 할리 퀸은 헌트리스, 블랙 카나리, 르네 몬토야와 새로운 팀을 결성해 로만에 맞서는데...', '2020-02-05', 6.886, 17.9124, 109, 'Cathy Yan', 10656, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (519182, '슈퍼배드 4', 'Despicable Me 4', 'movie', 'https://image.tmdb.org/t/p/w500/vZmCFVff9JySHTUp9zbYUIAcxzc.jpg', 'https://image.tmdb.org/t/p/original/twsxsfao6ZOVvT8LfudH603MMi6.jpg', '슈트-업 하고 악당 전담 처리반 AVL이 된 에이전트 미니언즈와 미니언즈 만큼 귀여운 그루 주니어가 태어나면서 더욱 완벽해진 그루 패밀리. 이들 앞에 과거 그루의 고등학교 동창이자 그에게 체포당했던 빌런 맥심이 등장하고, 오직 그루를 향한 복수심에 불타올라 탈옥까지 감행한 맥심은 그루 패밀리의 뒤를 바짝 추격하며 위협을 가하기 시작하는데... 과연 에이전트 미니언즈와 그루 패밀리는 맥심을 막아낼 수 있을까?', '2024-07-24', 6.995, 17.9066, 94, 'Chris Renaud', 3040, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1469354, 'Border Hunters', 'Border Hunters', 'movie', 'https://image.tmdb.org/t/p/w500/6TNFZnJ5CU0uFQxGaO9dbqriiI7.jpg', 'https://image.tmdb.org/t/p/original/rBygkL0nL18t0zd5bNJECET64kV.jpg', '', '2025-10-20', 6.421, 17.8647, 82, 'Ruben Islas', 38, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (324857, '스파이더맨: 뉴 유니버스', 'Spider-Man: Into the Spider-Verse', 'movie', 'https://image.tmdb.org/t/p/w500/d9V6Q9vpVpmaca7vwSUbCajtDb3.jpg', 'https://image.tmdb.org/t/p/original/8mnXR9rey5uQ08rZAvzojKWbDQS.jpg', '평범한 10대 마일스 모랄레스는 우연히 방사능 거미에 물려 스파이더맨 능력을 가지게 된다. 혼란스러워하던 마일스는 악당과 싸우고 있는 피터 파커를 마주치게 되고 피터 파커는 마일스가 자신과 같은 능력을 가지고 있음을 직감한다. 여러 개의 평행세계가 존재한다는 것을 알게 된 마일스와 피터 파커는 이후 스파이더우먼 스파이더 그웬, 스파이더맨 누아르, 스파이더햄 등 평행세계 속 공존하는 모든 스파이더맨들을 만나게 되는데... 하나의 유니버스에서 만나 팀을 결성한 스파이더맨들은 과연 세계를 구할 수 있을까?', '2018-12-12', 8.394, 17.8468, 117, '밥 퍼시케티', 16786, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (938008, '더 킬러: 죽어도 되는 아이', '더 킬러: 죽어도 되는 아이', 'movie', 'https://image.tmdb.org/t/p/w500/qPXGKOEQ1NSrmH6s7qFFF3qC9O6.jpg', 'https://image.tmdb.org/t/p/original/8gBYmKvo230576bXmW8UZR8zGbB.jpg', '은퇴 후 성공적인 재테크로 호화롭게 생활하는 전설의 킬러 ‘의강’이  제멋대로 행동하는 여고생 ‘윤지’를 떠맡게 된다.  단기간 보호자 역할만 하면 될 거라고 가볍게 여긴 순간  ‘윤지’가 납치되는 사건이 일어나는데…  “걔는 다치면 안 되는 아이야”  애써 잠재운 ‘의강’의 본능이 깨어난다!', '2022-07-13', 7.672, 17.7648, 95, 'Choi Jae-hoon', 406, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1007734, '노바디 2', 'Nobody 2', 'movie', 'https://image.tmdb.org/t/p/w500/vBKQuGX0nrx9p8H3j3GGojDYoKH.jpg', 'https://image.tmdb.org/t/p/original/82C04rTiXYZ7c8XZv91Nu53w82Y.jpg', '가족과 소홀해지는 걸 느낀 허치. 오랜만에 가족들과 떠나는 여름 휴가지는 유년 시절의 추억이 깃든 플러머빌. 꿀 같은 휴식을 꿈꿨지만 평온은 온데간데없고… 사건만 터지는데. 일도 가족도 고단한 아저씨의 휴가를 쟁탈하기 위한 싸움이 시작된다.', '2025-08-27', 7.015, 17.7397, 90, '티모 차얀토', 1205, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1147266, '6시간 후 너는 죽는다', '6시간 후 너는 죽는다', 'movie', 'https://image.tmdb.org/t/p/w500/asdw71nkWcyvwfuPlpgohavTuXL.jpg', 'https://image.tmdb.org/t/p/original/yPf0rHXOiudd95otYcAiQUWHY5w.jpg', '서른 살 생일을 하루 앞둔 정윤은 길에서 만난 낯선 남자 준우에게 죽음 예고를 듣는다. 믿을 수 없는 예언이 거짓말처럼 현실이 되어가면서 정윤은 자신을 죽이려는 범인을 찾기 위해 준우와 여정을 시작하게 되는데...', '2024-10-16', 6.318, 17.7002, 91, '이윤석', 22, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (429617, '스파이더맨: 파 프롬 홈', 'Spider-Man: Far From Home', 'movie', 'https://image.tmdb.org/t/p/w500/3YewJtji80oIroeXUavNRZkeXfQ.jpg', 'https://image.tmdb.org/t/p/original/34jW8LvjRplM8Pv06cBFDpLlenR.jpg', '어벤져스 멤버들과 타노스와의 대접전을 마친 뒤, 지난 5년 동안 사라졌던 사람들이 동시에 돌아왔다. 아이언맨이 떠난 채 한동안 지구를 구할 히어로가 공석인 상황을 수습할 히어로는 현재 스파이더맨 피터 파커뿐이다. 친구들과의 유럽 현장학습 도중 닉 퓨리의 부름을 받게 된 피터는 미스테리오라는 정체 모를 히어로와 힘을 합쳐 엘리멘탈이라는 괴생명체를 무찔러야 하는 상황에 처한다. 그런데 피터는 지구를 구하는 일보다 MJ에게 멋지게 고백할 계획이 우선인데...', '2019-07-02', 7.397, 17.6781, 129, '존 왓츠', 16615, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (297762, '원더 우먼', 'Wonder Woman', 'movie', 'https://image.tmdb.org/t/p/w500/oZGYR75RaSLQ8XdJIVerYnOdhFx.jpg', 'https://image.tmdb.org/t/p/original/AaABt75ZzfMGrscUR2seabz4PEX.jpg', '수천년 간 존재를 숨긴 채 지구를 수호하던 데미스키라의 공주 다이애나는 어느 날 하늘에서 이상한 움직임을 포착한다. 1차 세계대전에 참전해 스파이 활동을 벌이다가 격추된 미국인 조종사 스티브가 해변에 불시착한 것. 태어나 처음으로 남성을 보게 된 다이애나는 호기심을 감추지 못하고, 데미스키라의 일원들은 그가 파멸을 가져올 수도 있음을 경고한다. 다이애나는 엄마이자 여왕인 히폴리타의 반대에도 불구하고 나치군의 추격을 따돌리면서 그들의 생화학무기 공격을 비밀리에 막아야 하는 스티브를 따라나선다.', '2017-05-31', 7.211, 17.5973, 141, '패티 젠킨스', 20655, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (411, '나니아 연대기: 사자, 마녀 그리고 옷장', 'The Chronicles of Narnia: The Lion, the Witch and the Wardrobe', 'movie', 'https://image.tmdb.org/t/p/w500/vSY6MgDWD5Ch5I87X8BaxZyydCI.jpg', 'https://image.tmdb.org/t/p/original/tuDhEdza074bA497bO9WFEPs6O6.jpg', '제2차 세계대전 중의 영국. 공습을 피해 디고리 교수의 시골 별장으로 간 페번시가의 네 남매인 피터, 수잔, 에드먼드, 루시는 마법의 옷장을 통해 신비로운 나라 나니아로 들어선다. 말하는 동물들과 켄타우로스, 거인들이 평화롭게 어울려 사는 땅이었던 나니아는 사악한 하얀 마녀 제이디스에 의해 긴 겨울에 감금되어 있다. 게다가 이 겨울에는 크리스마스도 없다. 호기심 많은 루시, 퉁명스러운 에드먼드, 신중한 수잔, 분별 있는 맏이 피터는 고귀한 사자 아슬란의 인도로 제이디스의 싸늘한 주문을 깨는 싸움에 가담한다.', '2005-12-29', 7.137, 17.5828, 143, '앤드류 애덤슨', 11269, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (585, '몬스터 주식회사', 'Monsters, Inc.', 'movie', 'https://image.tmdb.org/t/p/w500/fnDLrtEoIrxTCWUvuurMzOzQGpQ.jpg', 'https://image.tmdb.org/t/p/original/sDTnMOJ3H5wI38OxObmCtK7wfd5.jpg', '호탕한 설리와 재치만점 마이크는 몬스터 주식회사 겁주기 팀의 최우수 콤비다. 매일 밤 투철한 직업정신으로 인간 세계로 통하는 벽장 문을 열던 설리와 마이크 콤비는 어느 날 일생일대의 실수를 저지른다. 덜 닫힌 벽장 문 사이로 인간아이 부가 몬스터 세계에 침입한 것. 설리와 마이크는 부를 인간세계로 돌려보내고 사건을 조용히 수습하려 하지만 부는 설리를 무서워하기는커녕 애완 야옹이쯤으로  생각하고 쫄래쫄래 따라다닌다. 부의 침입이 발각되자 몬스터 주식회사는 발칵 뒤집히고 마는데...', '2001-12-21', 7.847, 17.5285, 92, '피트 닥터', 19407, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (129, '센과 치히로의 행방불명', '千と千尋の神隠し', 'movie', 'https://image.tmdb.org/t/p/w500/aZuBfbR0PnCb2up7lqHDsgJlLjs.jpg', 'https://image.tmdb.org/t/p/original/ukfI9QkU1aIhOhKXYWE9n3z1mFR.jpg', '평범한 열 살 짜리 소녀 치히로 식구는 이사 가던 중 길을 잘못 들어 낡은 터널을 지나가게 된다. 터널 저편엔 폐허가 된 놀이공원이 있었고 그곳엔 이상한 기운이 흘렀다. 인기척 하나 없는 이 마을의 낯선 분위기에 불길한 기운을 느낀 치히로는 부모님에게 돌아가자고 조르지만 부모님은 호기심에 들떠 마을 곳곳을 돌아다니기 시작한다. 어느 음식점에 도착한 치히로의 부모님은 그 곳에 차려진 음식들을 보고 즐거워하며 허겁지겁 먹어대다가 돼지로 변해버린다. 겁에 질려 당황하는 치히로에게 낯선 소년 하쿠가 나타나 빨리 이곳을 나가라고 소리치는데...', '2002-06-28', 8.533, 17.5022, 124, '미야자키 하야오', 17864, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1595481, '납치된 아이: 엘리자베스 스마트', 'Kidnapped: Elizabeth Smart', 'movie', 'https://image.tmdb.org/t/p/w500/lFSaWH6IYjSOtSF3CCoUuRNC3Av.jpg', 'https://image.tmdb.org/t/p/original/n2WschLfgBrF2Dj0SkdCL94q2jC.jpg', '14세의 나이에 유타주 자택에서 납치되었던 엘리자베스 스마트의 이야기를 조명한 다큐멘터리. 피해자 본인의 증언과 미공개 자료를 통해 당시 사건의 충격적인 전말이 공개된다. 2002년 6월 5일 이른 새벽, 14세 소녀 엘리자베스 스마트가 유타주 솔트레이크시티의 자택 침실에서 납치당했다. 미국 역사상 손꼽히게 큰 파장을 일으키며 집중 보도된 실종 사건의 시작이었다. 《납치된 아이: 엘리자베스 스마트》는 엘리자베스 본인의 증언과 가족, 수사 담당자, 사건 관계자들의 단독 인터뷰를 통해 그날의 이야기를 생생하게 들여다보는 강렬한 다큐멘터리 영화다. 이 작품은 생생한 기록 영상과 미공개 자료를 엮어, 브라이언 데이비드 미첼과 완다 바지의 손아귀에 붙잡혀 있었던 엘리자베스의 악몽 같은 9개월을 따라간다. 또한, 그 과정에서 엘리자베스와 가족들이 겪었던 심리적·정서적 고통, 끊임없이 이어진 언론의 관심, 끈기 있게 해답을 찾으려 한 지역 사회의 노력을 조명하는 동시에, 그 당시 엘리자베스를 살아남게 했고 20년이 지난 지금까지도 그녀를 단단히 지탱해 온 불굴의 생존 의지를 되새긴다. 이 다큐멘터리는 미국 전역을 충격에 빠뜨렸던 사건을 단순히 되짚는 데서 그치지 않고, 그 후 엘리자베스가 걸어온 치유의 여정과 다른 이들에게도 희망을 전하고 울타리가 되어주고자 하는 그녀의 장기적인 목표까지 함께 조명한다.', '2026-01-21', 7.2, 17.5012, 91, 'Benedict Sanderson', 18, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (12445, '해리 포터와 죽음의 성물 2', 'Harry Potter and the Deathly Hallows: Part 2', 'movie', 'https://image.tmdb.org/t/p/w500/ehUeFvQeo8Vr2aDIKLsLbC8okcw.jpg', 'https://image.tmdb.org/t/p/original/cbcpDn6XJaIGoOil1bKuskU8ds4.jpg', '덤블도어 교장이 남긴 죽음의 성물의 단서를 쫓던 해리 포터는 볼드모트가 그토록 찾아 다닌 절대적인 힘을 가진 지팡이의 비밀을 통해 드디어 마지막 퍼즐을 완성한다. 볼드모트의 영혼이 담긴 다섯 번째 호크룩스를 찾기 위해 마법학교 호그와트로 돌아온 해리와 친구들은 그들을 잡으려는 보안마법에 걸려 위기를 맞지만 덤블도어의 동생인 에버포스의 도움으로 벗어난다. 그리고 그에게서 덤블도어와 어둠의 마법사 그린델왈드에 관한 놀라운 과거에 대해 알게 된다. 한편 볼드모트는 해리에 의해 호크룩스들이 파괴되었음을 느끼고 호그와트로 향한다. 해리를 주축으로 한 불사조 기사단과 죽음을 먹는 자들 간의 전투가 벌어지며 호그와트는 거대한 전쟁터로 변하게 되는데...', '2011-07-13', 8.082, 17.4821, 130, '데이빗 예이츠', 21602, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (16869, '바스터즈: 거친 녀석들', 'Inglourious Basterds', 'movie', 'https://image.tmdb.org/t/p/w500/4eQ2DQi2Vb8oYN9IRAca8vaALNl.jpg', 'https://image.tmdb.org/t/p/original/hwNtEmmugU5Yd7hpfprNWI0DGIn.jpg', '2차 세계 대전, 나치의 잔인하고 폭력적인 행태에 분개한 미군 알도 레인 중위는 당한 만큼 돌려준다는 강렬한 신념으로 최고의 재능을 가진 8명의 대원을 모아 바스터즈란 군단을 만들어 나치가 점령한 프랑스에 잠입해 복수를 시작한다. 어느 날 알도 레인 중위는 독일의 여배우이자 영국의 더블 스파이인 브리짓에게 뜻밖의 소식을 듣는다. 나치 수뇌부가 모두 참석하는 독일 전쟁 영화의 프리미어에 히틀러도 참석을 한다는 것. 한 번에 나치를 모두 쓸어버릴 계획으로 바스터즈는 이탈리아 영화 관계자로 분장해 극장으로 향하는데...', '2009-10-28', 8.215, 17.4172, 152, '쿠엔틴 타란티노', 23630, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (436270, '블랙 아담', 'Black Adam', 'movie', 'https://image.tmdb.org/t/p/w500/mEdMHGy1FfCUc7PskFO0tibm8jp.jpg', 'https://image.tmdb.org/t/p/original/bQXAqRx2Fgc46uCVWgoPz5L5Dtr.jpg', '기원전 가장 번성하고 위대한 고대 국가였지만 현재는 국제 군사 조직 인터갱의 독재 국가로 전락한 칸다크. 인터갱의 눈을 피해 고대 유물을 찾던 아드리아나는 우연히 5000년 동안 잠들어 있던 블랙 아담을 깨우게 된다.  엄청난 괴력과 스피드, 방탄 능력과 자유자재의 고공비행, 번개를 쏘는 능력까지. 온몸이 무기인 블랙 아담은 자신의 앞을 막아서는 인터갱들을 모조리 쓸어버리고 칸다크 국민들은 이에 열광한다. 한편, 그의 폭주를 막기 위해 호크맨, 닥터 페이트, 아톰 스매셔, 사이클론으로 구성된 히어로 군단 저스티스 소사이어티가 칸다크에 나타나는데...', '2022-10-19', 6.827, 17.4134, 125, 'Jaume Collet-Serra', 6841, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (615453, '나타지마동강세', '哪吒之魔童降世', 'movie', 'https://image.tmdb.org/t/p/w500/zb8xejiaNR0snSJgDepwFQUIi2e.jpg', 'https://image.tmdb.org/t/p/original/k1pJslKr4aDayw9kWwWnlC3MIP3.jpg', '태을진인의 실수로 영주(선) 대신 마환(악)은 이정의 아들 나타로 환생한다. 3년 후, 천겁을 맞고 사라져야 할 운명을 타고난 나타는 마을을 혼란에 빠트려 사람들의 미움을 사게 된다. 세상에 파멸을 가져올 운명을 짊어진 나타의 마지막은 과연…', '2019-07-26', 7.887, 17.3784, 110, '饺子', 780, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (22, '캐리비안의 해적: 블랙펄의 저주', 'Pirates of the Caribbean: The Curse of the Black Pearl', 'movie', 'https://image.tmdb.org/t/p/w500/3ovejwQO4fKOWx4VgGBJeT8CKCn.jpg', 'https://image.tmdb.org/t/p/original/uRNgkJSkNBFbbn9fPsEjDIy8Sh3.jpg', '잭 스패로우는 10년 전의 반란 사건으로 자신의 배 블랙펄을 빼앗긴 해적 선장이다. 혼자 대양을 떠돌던 그는 자메이카의 로열포트에 이르러 유령선처럼 변해버린 블랙펄과 재회하게 된다. 아즈텍의 황금을 훔친 블랙펄의 선원들은 영원히 죽지 못하는 저주에 걸린 처지. 보물을 모두 제자리에 돌려놓고 피의 제물을 바쳐야만 고대 신들이 내린 저주를 풀 수 있다. 그들은 로열포트를 습격해 아즈텍의 마지막 목걸이를 가진 총독의 딸 엘리자베스를 납치하고, 엘리자베스를 사랑하는 어린 시절 친구 윌과 스패로우는 그 뒤를 쫓는데...', '2003-09-10', 7.818, 17.3304, 143, '고어 버빈스키', 21790, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (296096, '미 비포 유', 'Me Before You', 'movie', 'https://image.tmdb.org/t/p/w500/aCnkVi4QTuc7E0d0qp0SAnRA3M0.jpg', 'https://image.tmdb.org/t/p/original/3WK7p9EdZmmvB1IbB2Vw9Rf4lXH.jpg', '6년간 일하던 카페가 폐업하면서 하루아침에 일자리를 잃은 루이자(에밀리아 클라크). 그녀는 새 직장을 찾던 중 집에서 가깝고 보수도 좋은 간병인 일을 찾게 되고, 면접을 본 그날 바로 채용이 결정된다. 하지만 루이자가 간병해야 할 윌(샘 클라플린)은 2년 전 사고로 전신마비 환자가 된 자신을 받아들이지 못하고 남에게 쌀쌀맞기 일쑤다. 어느 날 윌이 루이자에게 유독 심한 독설을 퍼붓자 루이자는 참지 못해 그의 태도를 따끔하게 지적하고, 그때부터 윌은 그녀에게 호감을 느끼기 시작한다. 두 사람이 점점 가까워지던 사이, 루이자는 윌이 존엄사를 계획하고 있음을 알게 되는데...', '2016-06-01', 7.922, 17.3234, 110, 'Thea Sharrock', 13010, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1726, '아이언맨', 'Iron Man', 'movie', 'https://image.tmdb.org/t/p/w500/ziReGUV3xURsWmcmsn2GOunPc0L.jpg', 'https://image.tmdb.org/t/p/original/cKvDv2LpwVEqbdXWoQl4XgGN6le.jpg', '천재적인 두뇌와 재능으로 세계 최강의 무기업체를 이끄는 CEO이자, 타고난 매력으로 셀러브리티 못지않은 화려한 삶을 살아가던 억만장자 토니 스타크. 아프가니스탄에서 자신이 개발한 신무기 발표를 성공리에 마치고 돌아가던 그는 게릴라군의 갑작스런 공격에 의해 가슴에 치명적인 부상을 입고 게릴라군에게 납치된다. 가까스로 목숨을 건진 그에게 게릴라군은 자신들을 위한 강력한 무기를 개발하라며 그를 위협한다. 그러나 그는 게릴라군을 위한 무기 대신, 탈출을 위한 무기가 장착된 철갑수트를 몰래 만드는 데 성공하고, 그의 첫 수트인 ‘Mark1’를 입고 탈출에 성공한다. 미국으로 돌아온 토니 스타크는 자신이 만든 무기가 많은 사람들의 생명을 위협하고, 세상을 엄청난 위험에 몰아넣고 있다는 사실을 깨닫고 무기사업에서 손 뗄 것을 선언한다. 그리고, Mark1을 토대로 최강의 하이테크 수트를 개발하는 데 자신의 천재적인 재능과 노력을 쏟아 붓기 시작한다. 탈출하는 당시 부서져버린 Mark1을 바탕으로 보다 업그레이드 된 수트 Mark2를 만들어낸 토니 스타크. 거기에 만족하지 않고, 숱한 시행착오와 실패 끝에 자신의 모든 능력과 현실에서 가능한 최강의 최첨단 과학 기술이 집적된 하이테크 수트 Mark3를 마침내 완성, 최강의 슈퍼히어로 ‘아이언맨’으로 거듭난다. 토니 스타크가 탈출하는 과정을 통해 Mark1의 가공할 위력을 확인한 게릴라 군은 토니 스타크가 미처 회수하지 못한 Mark1의 잔해와 설계도를 찾아낸다. Mark1을 재조립하여 그들의 목적을 이루기 위한 거대하고 강력한 철갑수트를 제작하려는 음모를 꾸미는 게릴라군. 토니 스타크가 갖고 있던 에너지원을 훔쳐 ‘아이언맨’을 능가하는 거대하고 강력한 ‘아이언 몽거’를 완성한 그들은 세계 평화를 위협하고, 토니 스타크는 그들의 음모과 배후세력이 누구인지를 알게 되는데...!', '2008-04-30', 7.7, 17.3137, 125, '존 파브로', 27662, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (299534, '어벤져스: 엔드게임', 'Avengers: Endgame', 'movie', 'https://image.tmdb.org/t/p/w500/z7ilT5rNN9kDo8JZmgyhM6ej2xv.jpg', 'https://image.tmdb.org/t/p/original/7RyHsO4yDXtBv1zUU3mTpHeQ0d5.jpg', '어벤져스의 패배 이후 지구는 초토화됐고 남은 절반의 사람들은 정신적 고통을 호소하며 하루하루를 근근이 버텨나간다. 와칸다에서 싸우다 생존한 히어로들과 우주의 타이탄 행성에서 싸우다 생존한 히어로들이 뿔뿔이 흩어졌는데, 아이언맨과 네뷸라는 우주를 떠돌고 있고 지구에 남아 있는 어벤져스 멤버들은 닉 퓨리가 마지막에 신호를 보내다 만 송신기만 들여다보며 혹시 모를 우주의 응답을 기다리는 중이다. 애초 히어로의 삶을 잠시 내려놓고 가족과 시간을 보내던 호크아이 역시 헤아릴 수 없는 마음의 상처를 입은 채 사라지고 마는데...', '2019-04-24', 8.237, 17.3034, 181, '안소니 루소', 27163, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (11, '스타워즈 에피소드 4: 새로운 희망', 'Star Wars', 'movie', 'https://image.tmdb.org/t/p/w500/7XFfURIFCJxN1mfBg0SAjk5yGzg.jpg', 'https://image.tmdb.org/t/p/original/2w4xG178RpB4MDAIfTkqAuSJzec.jpg', '공화국이 붕괴하고 제국이 수립된 뒤 20년, 제다이 기사단은 전멸하고 강력한 제국군의 횡포에 은하계는 공포에 휩싸여 있다. 그러던 중 공화국 재건을 노리는 반란군이 제국군의 비밀병기 데스스타 설계도를 훔쳐 달아나고 제국군은 이를 쫓는다. 하지만 결국 제국의 손에 붙잡히게 된 그들은 드로이드 R2-D2에 설계도를 넣어서 R2의 친구 C-3PO와 탈출시키는 데 성공하고, 두 드로이드 콤비는 타투인의 시골 마을에서 숙부와 함께 살고 있던 청년 루크 스카이워커에게 오게 되는데...', '1978-06-01', 8.202, 17.298, 121, '조지 루카스', 21851, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1242011, '투게더', 'Together', 'movie', 'https://image.tmdb.org/t/p/w500/ivWOD2MiC1HywIPBF2Ei2CN3ywY.jpg', 'https://image.tmdb.org/t/p/original/x5Mli7QJAGIhpMib3IHwpEZRFfg.jpg', '관계의 한계에 부딪힌 오래된 커플 팀과 밀리. 어느 날 서로의 몸이 점점 붙어버리기 시작하는데…', '2025-09-03', 7.1, 17.2798, 102, 'Michael Shanks', 851, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (61012, '사일런트 힐: 레버레이션', 'Silent Hill: Revelation 3D', 'movie', 'https://image.tmdb.org/t/p/w500/nAzKHrpscT8KXaKkpimi5OHAce8.jpg', 'https://image.tmdb.org/t/p/original/9puin7KvQBHKUEKLRuPsh6X9lC.jpg', '헤더는 항상 무언가로부터 쫓기는 꿈을 꾼다. 그리고 무언가를 숨기는 듯한 아빠까지 그녀를 불안하게 한다. 18살 생일날, 헤더는 아버지가 사라지는 악몽에 시달린다. 새로운 학교로 가는 그녀는 한 남자로부터 위험에 빠질 것이라는 소리를 듣는다. 그리고 전학간 첫날부터 주변이 다른 공간으로 바뀌며 이상한 환영에 사로잡히게  되는데…', '2012-10-10', 5.542, 17.2643, 94, 'MJ Bassett', 1784, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1309129, 'Diabolisch', 'Diabolisch', 'movie', 'https://image.tmdb.org/t/p/w500/gm0e0W7QRTpima3aIGz2ZLU9pgm.jpg', 'https://image.tmdb.org/t/p/original/dbUUasPx24MR0JHWbREwKy0CgvU.jpg', '', '2025-09-29', 7, 17.1838, 95, 'Tristan van Doorn', 3, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1456349, '그저 사고였을 뿐', 'یک تصادف ساده', 'movie', 'https://image.tmdb.org/t/p/w500/zQFzmYKZKrB0IU9sik25LdSjO6E.jpg', 'https://image.tmdb.org/t/p/original/zhoMwQofjgVec5Sin05hWECJtVQ.jpg', '어느 날, 나를 지옥으로 이끌던 삐걱 소리가 다시 들렸다. 나는 안다. 그가 맞다. “그저 사고였을 뿐? 누군가는 그걸 평생 기억해”', '2025-10-01', 7.215, 17.1764, 104, '자파르 파나히', 296, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1284120, '어글리 시스터', 'Den stygge stesøsteren', 'movie', 'https://image.tmdb.org/t/p/w500/sgstfJwOCiCEMusDGatnm1qegSW.jpg', 'https://image.tmdb.org/t/p/original/ev9kxdoJ5IYVprt1OvH2SMWJdU1.jpg', '아름다움이 곧 권력이 되는 잔혹한 경쟁의 왕국. 언제나 외모로 조롱받던 ‘엘비라’는 ‘왕자’와의 달콤한 사랑을 꿈꾼다.  그러던 어느 날, 그녀에게 찾아온 단 한 번의 기회— 의붓언니인 ‘아그네스’와 함께 왕자가 개최하는 무도회에 초대된다. 그녀는 왕자의 마음을 사로잡기 위해 아름다움에 집착하며, 그 어떤 고통도 마다하지 않는다.  아름다움을 향한 그 갈망의 끝에 끔찍한 대가가 따른다는 사실을 모른 채…', '2025-08-20', 7.3, 17.1577, 110, 'Emilie Blichfeldt', 844, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1420733, '귀시', '귀시', 'movie', 'https://image.tmdb.org/t/p/w500/prXqVtz3NOGGh52y9VZK5ja4efh.jpg', 'https://image.tmdb.org/t/p/original/tYJMvtbjtYexeYB5CjnjezwnWEq.jpg', '매일 밤, 아무도 모르게 열리는 귀신을 사고 파는 시장 ‘귀시’. 양손의 검지와 새끼손가락을 맞대 여우 모양의 창을 그리면, 그 문이 열린다. 돈, 외모, 성적, 스펙, 인기.. 갖지 못한 것을 탐하는 사람들이 모이는 곳, 그곳에서는 매일 밤 상상조차 할 수 없는 섬뜩한 거래가 벌어지는데…', '2025-09-17', 6.5, 17.1222, 97, '홍원기', 6, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (793387, '거룩한 밤: 데몬 헌터스', '거룩한 밤: 데몬 헌터스', 'movie', 'https://image.tmdb.org/t/p/w500/7MGnHpfhF8savUsrUJoI8Q7dTk9.jpg', 'https://image.tmdb.org/t/p/original/5A01YSCPYoCOZOhh9tU7F3Htxkf.jpg', '악마와 그를 쫓는 어둠의 숭배자들로 인해 혼란에 빠지게 된 도시. 공권력조차 이들 앞에서 무력해지자 특별한 능력을 가진 어둠의 해결사 거룩한 밤 팀 바우, 샤론, 김군이 직접 악의 무리를 처단하고자 한다. 그러던 중 갑자기 동생 은서가 이상증세를 보인다는 의뢰인 정원이 찾아오고 그 안에서 지금껏 본 적 없던 강력한 존재의 기운을 느끼는데… 과연 거룩한 밤 팀은 악의 무리에 맞서 세상을 구원해 낼 수 있을까?', '2025-04-30', 6.857, 17.0794, 92, 'Lim Dae-hee', 84, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (462183, '와일드 어웨이크닝', 'Salvaje despertar', 'movie', 'https://image.tmdb.org/t/p/w500/qWkWESVyw1nsX89AXshyRa31Bk6.jpg', 'https://image.tmdb.org/t/p/original/lJJUpqjlZYKxIO1YdlmA15pa1Bf.jpg', '토니와 엠마는 안정된 농장을 소유한 남매다. 라몬과 그의 아들 아론은 그들을 위해 일한다. 토니는 공공연히 알려진 게이고 파티를 좋아하고, 엠마는 아론을 좋아하는데 아론은 게이지만 아빠한테 비밀을 숨기고 있다. 하지만 아론의 아빠 또한 비밀을 갖고 있는데...', '2016-10-23', 5.1, 16.9958, 105, 'Joan Fermí Martí', 21, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (8587, '라이온 킹', 'The Lion King', 'movie', 'https://image.tmdb.org/t/p/w500/9Y048zYw66TWvpUtsiNK0uReiVX.jpg', 'https://image.tmdb.org/t/p/original/q00H8EqULYSK74lgevMkhmGGLHn.jpg', '아프리카의 평화로운 왕국 프라이드랜드. 이곳을 다스리는 사자 무파사의 아들 심바가 태어난다. 왕의 동생 스카는 자신이 왕위를 차지하기 위해 하이에나들과 결탁하여 무파사를 죽이고 심바에게 죄를 뒤집어 씌워 멀리 내쫓는다. 간신히 목숨을 건진 심바는 유쾌한 미어캣 티몬과 멧돼지 품바와 함께 생활하며 어른이 된다. 어느 날 심바는 옛 친구 날라를 만나 프라이드랜드가 파괴되고 있다는 소식을 듣게 된다. 하지만 자신이 저지른 실수 때문에 고향으로 돌아가기를 거부하는 심바. 결국 아버지의 가르침과 자신의 운명을 깨달은 심바는 스카와 하이에나들을 물리치고 평화를 되찾기 위해 왕국으로 돌아가는데...', '1994-07-02', 8.255, 16.9842, 89, 'Roger Allers', 19311, 0);
