INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (12444, '해리 포터와 죽음의 성물 1', 'Harry Potter and the Deathly Hallows: Part 1', 'movie', 'https://image.tmdb.org/t/p/w500/lOXvz8HrgOkp7AXGQp1APKeZqag.jpg', 'https://image.tmdb.org/t/p/original/slW0M2G9txC0aUbftCTm1nYX1K8.jpg', '덤블도어 교장의 죽음 이후, 마법부는 죽음을 먹는 자들에게 점령당하고 호그와트는 위기에 빠진다. 성년이 되며 해리를 지켜주던 수호 마법은 사라지고 해리와 론, 헤르미온느는 볼드모트 영혼의 조각이 보관된 호크룩스를 찾아 파괴하기 위한 모험을 떠난다. 그러나 이미 볼드모트에 의해 장악된 마법세계에서 죽음을 먹는 자들을 피해 숨어다니는 것만으로도 쉽지 않다. 세 사람에게 남겨진 덤블도어의 유품은 수수께끼처럼 그저 막막하고, 아무런 단서도 없이 떠난 그들의 모험은 불안과 초조함으로 가득하다. 계속되는 시련의 나날 속에 세 친구는 끊임없이 서로에 대한 믿음과 숙명에 대한 의지를 시험받는다.', '2010-12-15', 7.736, 16.4289, 146, '데이빗 예이츠', 20025, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (414906, '더 배트맨', 'The Batman', 'movie', 'https://image.tmdb.org/t/p/w500/jicHGaOX5pHs7RKjfexMxvLkwjf.jpg', 'https://image.tmdb.org/t/p/original/b0PlSFdDwbyK0cf5RxwDpaOJQvQ.jpg', '지난 2년 간 고담시의 어둠 속에서 범법자들을 응징하며 배트맨으로 살아온 브루스 웨인. 알프레드와 제임스 고든 경위의 도움 아래 그는 도시의 부패한 공직자들과 고위 관료들 사이에서 복수의 화신으로 활약한다. 고담의 시장 선거를 앞두고 고담의 엘리트 집단을 목표로 잔악한 연쇄살인을 저지르는 수수께끼 킬러 리들러가 나타나자, 최고의 탐정 브루스 웨인이 수사에 나서고 남겨진 단서를 풀어가며 캣우먼, 펭귄, 카마인 팔코네, 리들러를 차례대로 만난다. 사이코 범인의 미스터리를 수사하면서 그 모든 증거가 자신을 향한 의도적인 메시지였음을 깨닫고,  리들러에게 농락 당한 배트맨은 광기에 사로잡힌다. 범인의 무자비한 계획을 막고 오랫동안 고담시를 썩게 만든 권력 부패의 고리를 끊어야 하지만, 부모님의 죽음에 얽힌 진실이 밝혀지자 복수와 정의 사이에서 갈등하는데...', '2022-03-01', 7.656, 16.4027, 176, '맷 리브스', 11538, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (210577, '나를 찾아줘', 'Gone Girl', 'movie', 'https://image.tmdb.org/t/p/w500/m2Lw04GIjiTjylqPiccoo3WFMVb.jpg', 'https://image.tmdb.org/t/p/original/iWak7wT0j6ycCc8lKr4NBz9c7n5.jpg', '모두가 부러워하는 삶을 살아가는 완벽한 커플인 닉과 에이미. 결혼 5주년 기념일 아침, 에이미가 흔적도 없이 실종된다. 유년시절 어린이 동화 시리즈 어메이징 에이미의 실제 여주인공이었던  유명인사 아내가 사라지자, 세상은 그녀의 실종사건으로 떠들썩해진다. 한편 경찰은 에이미가 결혼기념일 선물로 숨겨뒀던 편지와 함께  곳곳에서 드러나는 단서들로 남편 닉을 유력한 용의자로 지목한다. 미디어들이 살인 용의자 닉의 일거수일투족을 보도하기 시작하고, 시간이 갈수록 세상의 관심이 그에게 더욱 집중되는데...', '2014-10-23', 7.889, 16.3896, 149, '데이비드 핀처', 19572, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (106646, '더 울프 오브 월 스트리트', 'The Wolf of Wall Street', 'movie', 'https://image.tmdb.org/t/p/w500/rdBYtoxLvd8J9PsVYVGd7FGzQux.jpg', 'https://image.tmdb.org/t/p/original/7Nwnmyzrtd0FkcRyPqmdzTPppQa.jpg', '부자가 되는 게 꿈인 22살의 조던 벨포트는 꿈을 실현코자 월스트리트에 발을 들인다. 고객의 돈을 내 주머니로 끌어들이는 비법은 코카인과 마스터베이션에 있다고 말하는 괴짜들이 하루 종일 전화기를 붙들고 사기치는 곳, 조던에게 월스트리트의 첫인상은 그랬다. 첫 직장에 몸담은 지 1년 만에 블랙 먼데이를 경험하고 실직자가 된 조던은 현란한 언변을 무기로 위기를 기회로 만들어버린다. 친구들을 불러모아 스트래튼 오크몬트사를 세운 그는 수수료가 비싼 투기적 저가주을 팔아 돈을 긁어모으고, 주가 조작으로 억만장자가 된 후 술과 마약, 여자를 탐닉한다. 그사이 FBI는 그의 뒤를 캐기 시작하는데...', '2014-01-09', 8.026, 16.3863, 180, '마틴 스콜세지', 25405, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (604079, '롱 워크', 'The Long Walk', 'movie', 'https://image.tmdb.org/t/p/w500/pcao4x0sOh7xapvUYXBnNvxrERN.jpg', 'https://image.tmdb.org/t/p/original/zf7BQY4k5RNFI1sD4n9EVLnEG8m.jpg', '"살아남고 싶다면, 멈추지 마라" 권력이 지배하는 근미래, 국가가 주관하는 치명적인 ‘롱 워크’가 시작된다. 정해진 속도 아래로 떨어질 때마다 경고가 쌓이고, 세 번째엔 냉혹한 처벌이 따른다. 같은 길을 걷는 소년들은 서로를 경계하면서도, 끝을 알 수 없는 도로 위에서 가족의 사연과 두려움을 나누며 미묘한 연대를 만들어 간다. 점점 무거워지는 발걸음과 높아지는 긴장 속에서, 한 소년은 살아남기 위해 무엇을 버리고 무엇을 붙잡아야 하는지, 그리고 왜 끝까지 걸어야 하는지를 스스로에게 묻게 되는데...', '2025-09-10', 6.94, 16.3584, 108, '프랜시스 로렌스', 1075, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (788396, '리얼 찰리 채플린', 'The Real Charlie Chaplin', 'movie', 'https://image.tmdb.org/t/p/w500/zajwv6MwIweYlyhu1ibMojr65wB.jpg', 'https://image.tmdb.org/t/p/original/qvBSf6qjaMSf0FukAo6aQCuxE3g.jpg', '', '2021-11-19', 7.5, 16.3407, 114, 'Pete Middleton', 25, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1252309, '나의 S 파트너', 'Pídeme lo que quieras', 'movie', 'https://image.tmdb.org/t/p/w500/5rtaLwyKAjbceww4J1ro8aA8BNB.jpg', 'https://image.tmdb.org/t/p/original/8Rseq6hAhAItnTrbECEFt35VoSJ.jpg', '주디는 어느 날, 회사의 인수합병을 위해 방문한 억만장자 CEO 에릭과 엘리베이터에 갇히게 된다. 우연히 시작된 치명적인 끌림. 주디는 에릭의 유혹 앞에 흔들리고 만다. 그의 따뜻한 진심에 마음을 연 주디는 결국, 위험하고 달콤한 제안을 받아들인다. 에릭이 이끄는 금기의 세계에 발을 들인 주디. 비밀스러운 만남이 이어질수록, 그녀는 에릭의 숨겨진 진짜 얼굴을 알고 싶어지고, 동시에 자신 안에 잠든 본능까지 깨워가는데…', '2025-10-02', 6.141, 16.3331, 114, 'Lucía Alemany', 262, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1198994, '직장상사 길들이기', 'Send Help', 'movie', 'https://image.tmdb.org/t/p/w500/c4df7ExGyVUWAWOwNB5jy4EFHsx.jpg', 'https://image.tmdb.org/t/p/original/493MuzSs6iLyKM7aqsA30eODfsV.jpg', '직장에서 인정받지 못해 괴로워하는 린다는 죽일 만큼 미운 상사 브래들리와 출장 도중 비행기 추락 사고로 인해 무인도에 단둘이 고립된다. 와이파이도, 인사팀도, 직급도 없는 야생의 섬에서 이들의 권력관계는 완전히 뒤집히게 되는데…!', '2026-01-28', 6.1, 16.2691, 113, '샘 레이미', 4, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (557, '스파이더맨', 'Spider-Man', 'movie', 'https://image.tmdb.org/t/p/w500/4xOhtzXGt0if74dTmS4qtizFelX.jpg', 'https://image.tmdb.org/t/p/original/zQ8AxTPiCiS5nnwXpwTBPBHSaa5.jpg', '평범하고 내성적인 고등학생 피터 파커는 우연히 방사능에 감염된 거미에 물린다.그 후, 피터는 손에서 거미줄이 튀어 나오고 벽을 기어 오를 수 있는 거미와 같은 능력을 갖게 된다. 다가오는 위험을 본능적으로 감지하는 초감각과 엄청난 파워를 소유하게 된 것이다. 피터는 짝사랑하던 메리 제인의 관심을 끌기 위해 멋진 스포츠카를 구입하는데 초능력을 처음 사용한다. 그러다 사랑하는 벤 아저씨의 죽음을 계기로 그 힘을 악의 세력에 대항하는데 쓰기로 결심한다. 한편 피터의 절친 해리 오스본의 아버지인 노만은 실험 도중 가스에 중독되어 악의 화신 그린 고블린으로 변하는데...', '2002-05-03', 7.319, 16.2614, 121, '샘 레이미', 20216, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1288072, '키퍼', 'Keeper', 'movie', 'https://image.tmdb.org/t/p/w500/mbGHijUc0C3fcM12l6ro6FgxIvg.jpg', 'https://image.tmdb.org/t/p/original/kUuWEOgqlVqcXsXujJPK8C6kjum.jpg', '남편을 따라 오랜만에 떠난 휴가, 도착한 산장에선 누군가 지켜보는 느낌이 자꾸 들고 이상한 이들이 찾아와 불안하게 한다. 그리고 곧 남편의 오래된 과거를 발견하게 되는데...', '2025-11-12', 5.514, 16.2516, 99, '오즈 퍼킨스', 109, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1584215, '인턴십', 'The Internship', 'movie', 'https://image.tmdb.org/t/p/w500/fYqSOkix4rbDiZW0ACNnvZCpT6X.jpg', 'https://image.tmdb.org/t/p/original/eUERZRVjCTNdgnESlQxyaOJ2d4K.jpg', '“배신당한 킬러들의 반란, CIA 내부를 격돌하다”  어린 시절부터 비밀 CIA ‘인턴십’으로 혹독한 훈련을 받아온 여성이 이제 그 프로그램이 자신의 삶을 빼앗아간 진짜 이유를 밝히기 위해 나선다. 그녀는 자신처럼 길러진 동료 인턴들을 모아 조직을 무너뜨리려 하고, 점점 더 치명적인 임무 속에서 배신과 살아남기 위한 본능이 충돌하게 된다. CIA는 이를 막기 위해 더욱 강력한 대응에 나서고, 인턴들과 기관 모두가 최후의 결전을 벌이게 되는데…', '2026-01-13', 6.4, 16.2484, 91, 'James Bamford', 29, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1128650, '열혈검사', '誤判', 'movie', 'https://image.tmdb.org/t/p/w500/lWItoP2bXrV1yJYOqJjEVei8Zdj.jpg', 'https://image.tmdb.org/t/p/original/4frrYwamVG0eXhdMTy3cpNNcCBp.jpg', '마약 밀매 혐의로 기소된 청년의 사건을 맡게 된 형사 출신 검사 ‘곽자호’(견자단). 곽자호는 사건을 담당한 구백문 변호사의 부당한 변호로 청년이 억울하게 기소되었다는 사실을 알게 된다. 수사를 진행할수록 홍콩에 마약을 유통하는 거대 조직의 뒤를 구백문 변호사가 봐주고 있다는게 밝혀지고, 곽자호는 정의를 위해 목숨과 경력을 걸고 수사에 나서는데….', '2025-04-16', 6.871, 16.228, 117, '견자단', 174, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1071585, '메간 2.0', 'M3GAN 2.0', 'movie', 'https://image.tmdb.org/t/p/w500/5dDIFCUsDD5rFvBmT8Hl3bwXAm0.jpg', 'https://image.tmdb.org/t/p/original/cT9ZfwoPDk8JbgkessmQgxAWiaM.jpg', '강제 종료 후 다시 돌아온 돌AI ‘메간’. 쌍돌AI ‘아멜리아’의 위협으로 ‘메간’의 유일한 친구 ‘케이디’ 목숨이 위태로워지자 ‘젬마’의 기술로 완전히 새롭게 진화한 메간이 다시 태어난다.', '2025-07-16', 7.296, 16.1423, 120, 'Gerard Johnstone', 1104, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (786892, '퓨리오사: 매드맥스 사가', 'Furiosa: A Mad Max Saga', 'movie', 'https://image.tmdb.org/t/p/w500/zaUFDdJidS4Nyyd6jb2Ok3Kq4Vo.jpg', 'https://image.tmdb.org/t/p/original/wNAhuOZ3Zf84jCIlrcI6JhgmY5q.jpg', '문명 붕괴 45년 후, 황폐해진 세상 속 누구에게도 알려지지 않은 풍요가 가득한 녹색의 땅에서 자란 퓨리오사는 바이커 군단의 폭군 디멘투스의 손에 모든 것을 잃고 만다. 가족도 행복도 모두 빼앗기고 세상에 홀로 내던져진 퓨리오사는 반드시 고향으로 돌아가겠다는 어머니와의 약속을 지키기 위해 인생 전부를 건 복수를 시작하는데...', '2024-05-22', 7.456, 16.1193, 149, '조지 밀러', 4612, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (177572, '빅 히어로', 'Big Hero 6', 'movie', 'https://image.tmdb.org/t/p/w500/gLabmTVZpNOGa8LEiMvTi9hJPDe.jpg', 'https://image.tmdb.org/t/p/original/4s2d3xdyqotiVNHTlTlJjrr3q0H.jpg', '천재 공학도 ‘테디’가 개발한 힐링로봇 ‘베이맥스’! ‘테디’의 동생이자 로봇 전문가인 ‘히로’는 도시가 파괴될 위기에 처하자 ‘베이맥스’를 슈퍼히어로로 업그레이드 하는데... 과연 이들은 도시의 위험을 막아낼 수 있을까?', '2015-01-21', 7.725, 16.112, 102, 'Chris Williams', 16299, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (335984, '블레이드 러너 2049', 'Blade Runner 2049', 'movie', 'https://image.tmdb.org/t/p/w500/fJZmCJpLeBFKktLFEIKPEhllWlU.jpg', 'https://image.tmdb.org/t/p/original/mVr0UiqyltcfqxbAUcLl9zWL8ah.jpg', '인간과 리플리컨트가 혼재된 2049년. 인간의 통제를 벗어난 리플리컨트를 쫓는 블레이드 러너 K는 임무 수행 도중 약 30년 전 여자 리플리컨트의 유골을 발견하고 충격적으로 출산의 흔적까지 찾아낸다. 리플리컨트가 출산까지 가능하다는 사실이 알려지면사회에 큰 혼란이 야기되므로 이를 덮으려는 경찰 조직과, 그 비밀의 단서를 찾아내 더욱 완벽한 리플리컨트를 거느리고 세상을 장악하기 위해 K를 쫓는 니안더 월레스. 리플리컨트의 숨겨진 진실에 접근할수록 점차 정체성의 혼란을 겪게 되는 K는 과거 블레이드 러너였던 릭 데커드를 만나 전혀 상상치 못한 진실을 마주하게 되는데...', '2017-10-12', 7.589, 16.1083, 164, '드니 빌뇌브', 14709, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (507089, '프레디의 피자가게', 'Five Nights at Freddy''s', 'movie', 'https://image.tmdb.org/t/p/w500/6rUZcazlkYILiNPKFgCGkzTn0BN.jpg', 'https://image.tmdb.org/t/p/original/7NRGAtu8E4343NSKwhkgmVRDINw.jpg', '80년대에 아이들이 실종되고 폐업한지 오래된 프레디의 피자가게 그곳의 야간 경비 알바를 하게 된 ‘마이크''는 캄캄한 어둠만이 존재하는 줄 알았던 피자가게에서 살아 움직이는 피자가게 마스코트 ''프레디와 친구들’을 목격한다. 어딘가 기괴하고 섬뜩한 프레디와 친구들이 실체를 드러내기 시작하는데...', '2023-11-15', 7.353, 16.1012, 110, 'Emma Tammi', 4846, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1327862, '리그레팅 유', 'Regretting You', 'movie', 'https://image.tmdb.org/t/p/w500/jJinKJWCTAwMPTcvTq5eH2yBc8w.jpg', 'https://image.tmdb.org/t/p/original/m3WlBJJRbFPaut1QS0PbOG8Wezy.jpg', '여자친구가 있는 학교 인기남 ‘밀러’를 좋아하는 고등학생 ‘클라라’는 자신을 과잉보호하는 엄마 ‘모건’ 대신 이모 ‘제니’에게 의지하며 연애 상담을 이어간다. 그러던 어느날, ‘클라라’가 가장 좋아하는 제니와 아빠 ‘크리스’가 같은 날 사고로 세상을 떠나게 되고 모건과 제니의 약혼자 ‘조나’는 둘 사이의 충격적 비밀을 알게되어 분개한다. ‘모건’과 ‘조나’는 충격받을 ‘클라라’를 위해 이 사실을 숨기면서도 분노를 참을 수 없어 떠난 두 사람의 흔적을 지우려고만 하고 그로 인해 상심한 ‘클라라’를 ‘밀러’가 위로하면서 둘은 서로 가까워지게 되는데…', '2025-11-05', 7, 16.0867, 116, '조쉬 분', 258, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1119878, '아이스 로드: 복수', 'Ice Road: Vengeance', 'movie', 'https://image.tmdb.org/t/p/w500/cQN9rZj06rXMVkk76UF1DfBAico.jpg', 'https://image.tmdb.org/t/p/original/2nwhxEyefcIFKwOrSigiamoIzu2.jpg', '“빙하 위에 펼쳐진 새롭고 위험한 여정”  얼어붙은 도로 대신, 네팔의 설산 ‘하늘로 가는 길’이 배경이다. 첫 번째 영화에서의 비극 이후, 마이크 맥캔(리암 니슨 분)은 형의 유언을 따라 그의 유골을 히말라야 만년설에 뿌리기로 결심한다. 그곳에서 만난 산악 가이드 다니(판 빙빙 분)와 함께, 그는 설산을 횡단하는 관광 버스를 운전하며 설원을 가로지른다. 그런데 뜻하지 않게 만나게 된 용병 집단의 계략은 평화를 위협하고, 마이크는 탑승객과 마을 사람들을 위해 다시 한 번 몸을 던지게 된다. 거친 산길 위에서 벌어지는 긴장감 넘치는 추적과 대결, 그리고 인간애가 교차하며 숨 막히는 순간들을 이어가는데… 그리고 마침내 그가 마주하게 될 진실은…?', '2025-06-27', 6.253, 16.0815, 113, '조너선 헨즐리', 564, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (675, '해리 포터와 불사조 기사단', 'Harry Potter and the Order of the Phoenix', 'movie', 'https://image.tmdb.org/t/p/w500/1ItejykqHTbFWbZXdzqlvqriv7K.jpg', 'https://image.tmdb.org/t/p/original/pkxPkHOPJjOvzfQOclANEBT8OfK.jpg', '길고도 지루한 여름 날 호그와트 마법학교 다섯 번째 해를 기다리고 있는 해리포터. 이모부 더즐리 식구들과 참고 사는 것도 지겨운데다 친구 론과 헤르미온느에게서는 편지 한 통 오지 않는다. 그러던 중 예상치 못했던 편지 한 장이 도착한다. 그것은 해리가 학교 밖인 리틀 위닝에서 얄미운 사촌 두들리, 즉 머글 앞에서 디멘터들의 공격을 막는 마법을 사용했기 때문에 호그와트 마법학교에서 퇴학 당하게 되었다는 소식이었다. 앞이 캄캄한 해리. 갑자기 어둠의 마법사 오러들이 나타나 해리를 불사조 기사단의 비밀 장소로 데리고 가는데...', '2007-07-11', 7.673, 16.0354, 137, '데이빗 예이츠', 20451, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1382406, '토니 자의 리벤지', '惊天大营救', 'movie', 'https://image.tmdb.org/t/p/w500/dMpzNcO97VLXIZklPYAvEiqQvmp.jpg', 'https://image.tmdb.org/t/p/original/yth78N88nwokepnOe5atwPGfTL1.jpg', '바이안은 눈앞에서 아내와 어린 딸이 잔혹하게 살해당하는 것을 목격한다. 그렇게 모든 걸 잃은 바이안. 이제 그의 유일한 목표는 가족을 죽인 자들을 찾아 응징하는 것이다. 아내가 가지고 있던 마약 밀반출 정보가 살해의 원인임을 알게 되고, 거대 마약 조직과 연계된 무역 회사의 잉하오허 회장을 주범으로 확신한다. 복수를 위해 그를 쫓던 중, 마약 조직이 허 회장의 가족을 습격한다. 회장의 딸 팅팅이 자신의 딸처럼 무고하게 죽게 둘 수는 없던 바이안은 그녀를 구해주고 그렇게 살인자의 딸과 동행하게 되는데…', '2024-12-05', 7.39, 16.0314, 111, '成思毅', 146, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1470086, '욕망의 계절', 'Ligaw', 'movie', 'https://image.tmdb.org/t/p/w500/1gPJZZzvcTTHMP4MhqSFpQwFmw2.jpg', 'https://image.tmdb.org/t/p/original/heMsXGykub43tU79I9hv6T1vHRc.jpg', '외딴 시골 마을, 남자들의 마음을 홀리는 요염한 여인! ‘돌로레스’는 하반신이 마비된 남편을 헌신적으로 돌보던 중 한 젊은 등산객 ‘제이론’을 만난다. 제이론이 마을에 오래 묵게 되면서 그녀는 무료한 일상 속 새로운 자극을 느끼는데... 둘의 불륜을 목격한 ‘올란’이 돌로레스를 협박하면서 돌로레스의 일상은 더 깊은 수렁으로 빠져들게 된다.', '2025-09-19', 6, 16.0264, 85, 'Omar Deroca', 5, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (121, '반지의 제왕: 두 개의 탑', 'The Lord of the Rings: The Two Towers', 'movie', 'https://image.tmdb.org/t/p/w500/zxZdTi3fA7aDxEOivmzZAY2bmTu.jpg', 'https://image.tmdb.org/t/p/original/kWYfW2Re0rUDE6IHhy4CRuKWeFr.jpg', '9명의 반지원정대는 사우론의 세력에 맞서 반지를 지켜냈지만 반지 원정대는 뿔뿔이 흩어지게 된다. 메리와 피핀을 구하기 위해 우르크하이 군대를 추격하던 아라곤과 레골라스, 김리는 유령 숲에서 백색의 마법사로 부활한 마법사 간달프를 만나게 되고 사우론이 암흑세계의 두 개의 탑을 통합하여 점점 그 세력을 넓혀가고 있다는 사실을 듣게 된다. 이에 아라곤과 원정대는 중간계의 선한 무리의 통합을 이뤄 사우론의 세력을 견제해야 하는 큰 임무를 맡게 된다. 하지만 원수지간인 곤도르와 로한으로 나뉜 인간 종족의 통합은 쉽지 않고 게다가 로한의 왕마저 사루만에게 동화되는데...', '2002-12-19', 8.412, 16.0216, 177, '피터 잭슨', 23320, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (111, '스카페이스', 'Scarface', 'movie', 'https://image.tmdb.org/t/p/w500/zx7sXrMISbs8RI4URbjPyKocRgP.jpg', 'https://image.tmdb.org/t/p/original/sctvs9cUwJD15qlTlrsh2BXsK75.jpg', '1980년 5월 쿠바가 마리엘 항을 개항하여 반카스트로 지지자들이 미국 플로리다에 입항한다. 토니 몬타나와 마니리베라도 이민 수용소로 보내진다. 3개월 후 마니가 수용소에 있는 레벤가라는 자를 살해해 주면 신분증을 입수해 주겠다는 일을 받아 수용소에 폭동을 일으켜 레벤가를 암살한다. 접시닦이로 근근히 살아가던 토니는 프랭크의 부하로부터 콜롬비아 마약상과의 거래일을 맡았다가 위험천만한 위기를 넘긴다. 그 사건을 계기로, 토니는 프랭크의 신임을 얻고 그의 부하가 되지만, 수 개월 후 결국 자신을 없애려는 프랭크를 죽이고 조직을 장악, 보스 자리에 오르는데...', '1984-12-08', 8.156, 16.0136, 170, '브라이언 드 팔마', 12676, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (475557, '조커', 'Joker', 'movie', 'https://image.tmdb.org/t/p/w500/6OnFzi7nU6t4j1rmX9QI8EYDWb4.jpg', 'https://image.tmdb.org/t/p/original/hO7KbdvGOtDdeg0W4Y5nKEHeDDh.jpg', '홀어머니와 사는 아서 플렉은 코미디언을 꿈꾸지만 그의 삶은 좌절과 절망으로 가득 차 있다. 광대 아르바이트는 그에게 모욕을 가져다주기 일쑤고, 긴장하면 웃음을 통제할 수 없는 신경병 증세는 그를 더욱 고립시킨다. 정부 예산 긴축으로 인해 정신과 약물을 지원하던 공공의료 서비스마저 없어져 버린 어느 날, 아서는 지하철에서 시비를 걸어온 증권사 직원들에게 얻어맞던 와중에 동료가 건네준 권총으로 그들을 쏴 버리고 만다. 군중들은 지배계급에 대한 저항의 아이콘이 된 그를 추종하기 시작하며 광대 마스크로 얼굴을 가리고 거리로 쏟아져 나오기 시작하는데...', '2019-10-02', 8.129, 16.0032, 122, '토드 필립스', 27205, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (829557, '365일: 오늘', '365 dni: Ten dzień', 'movie', 'https://image.tmdb.org/t/p/w500/nzrh7HhednL8gp08zR1rY3OAImC.jpg', 'https://image.tmdb.org/t/p/original/zBG5Mg29NH9xxpWMMG7BIvKwYhL.jpg', '재결합하여 그 어느 때보다도 열렬한 관계를 이어가는 라우라와 마시모. 하지만 마시모의 가족 관계, 그리고 라우라의 마음을 얻으려는 수수께끼의 남자로 인해 삶이 복잡해진다.', '2022-04-27', 5.933, 15.9018, 111, '토마시 만데스', 1809, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (98, '글래디에이터', 'Gladiator', 'movie', 'https://image.tmdb.org/t/p/w500/yemF0xxGU56Pf3JXxVr4C6kuKng.jpg', 'https://image.tmdb.org/t/p/original/jhk6D8pim3yaByu1801kMoxXFaX.jpg', '죽을 날이 머지않은 황제 마르쿠스 아우렐리우스는 막시무스를 총애하여 아들이 아닌 그에게 권력을 넘겨주기로 한다. 황제의 아들 코모두스는 이에 질투와 분노를 느껴 황제를 살해한다. 왕좌를 이어받은 코모두스는 막시무스와 그의 가족을 죽이라고 명령한다. 가족을 모두 잃고 겨우 살아남은 막시무스는 노예로 전락하고, 투기장의 검투사가 된다. 그에게 남은 건 오직 황제 코모두스에 대한 복수 뿐. 검투사로서 매 경기마다 승리로 이끌면서 살아남자 그의 명성은 날로 높아 간다. 그러던 어느 날 오래 전 사랑했던 황제의 누이 루실라를 다시 만나게 되는데...', '2000-06-03', 8.221, 15.8862, 154, '리들리 스콧', 20431, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (106, '프레데터', 'Predator', 'movie', 'https://image.tmdb.org/t/p/w500/AjYcJsuiqW4sHFEmh5SVSy5PswH.jpg', 'https://image.tmdb.org/t/p/original/70cezTFUmtijJLqnZw02gQlKVKJ.jpg', '더치와 특수부대 동료들은 CIA와 계약을 맺어 중앙 아메리카 정글에서 게릴라들에게 붙잡힌 조종사를 구하러 간다. 임무는 순조롭게 진행되었으나 그들은 귀환 도중 무언가로 부터 공격을 받는다. 보이지 않는 적은 정글 속에 숨어서 그들의 사체를 전리품으로 수집해간다.  이 외계 괴물은 더치의 동료들을 하나씩 죽이면서 유희를 벌이는데...', '1987-07-17', 7.544, 15.8298, 107, '존 맥티어난', 8787, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (348, '에이리언', 'Alien', 'movie', 'https://image.tmdb.org/t/p/w500/k3m1RdlYUlCx51PxxNMlmbm7QSk.jpg', 'https://image.tmdb.org/t/p/original/cEobq5QrnOJjO6giDs8q4RxmMKh.jpg', '2122년, 2천만톤의 광물과 7명의 승무원을 태우고 지구로 귀환중인 화물선 노스트로모호의 메인 컴퓨터 마더는 어떤 위성에서 나오는 알 수 없는 신호를 포착하게 된다. 마더에 의해 동면중 깨어난 승무원들은 이 신호를 조사하기 위해 혹성 LA-426에 착륙한다. 이들 중엔 2등 항해사인 엘렌 리플리도 있다. 혹성에서 정체 불명의 우주선을 발견한 그들은 탐사에 나서지만, 우주선은 이미 오래전에 파괴되어 썩고 있었으며 승무원들은 모두 미이라로 변해 있다. 사고 원인을 찾기 위해 좀 더 안으로 들어간 조사반은 여기저기 계란 모양의 물체가 있는 산란실을 발견하는데...', '1987-10-01', 8.166, 15.7698, 117, '리들리 스콧', 15933, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1468417, 'First Moon', 'First Moon', 'movie', 'https://image.tmdb.org/t/p/w500/hcjYvv4k9qs0lDG1Q3GIglT30IW.jpg', 'https://image.tmdb.org/t/p/original/7h0qCqkuQzmG5vXN3lGBc06reLd.jpg', '', '2025-05-06', 4.448, 15.7121, 97, 'Peter McLeod', 58, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (564, '미이라', 'The Mummy', 'movie', 'https://image.tmdb.org/t/p/w500/31lxBgDl51HYnAnIV41aPyK4em7.jpg', 'https://image.tmdb.org/t/p/original/8zLS8p1tRyWFLRFfmgQq0j5WE6z.jpg', '고대 이집트의 파라오 중 가장 영화를 누렸던 세티 1세의 시대. 세티 1세의 정부인 앙크수나문과 세티 1세의 총애을 한몸에 받던 승정원 이모탭은 금지된 사랑에 빠진다. 그러나 그들의 운명적인 사랑은 얼마되지 않아 파라오에게 발각되고 이에 앙크수나문은 자결하게 된다. 이모텝은 흑마서의 주문으로 그녀를 부활시키려 하지만, 파라오의 근위대에 붙잡히게 되고, ''홈다이''라는 형벌에 처해진다. 홈다이란 산 채로 석관에 갇혀 영원히 생시체가 되는 끔찍한 극형. 결국 금지된 사랑은 파라오의 저주로 비극적인 끝을 맺고 왕족들이 잠든 하무납트라는 죽음의 도시가 되어 역사 속에 묻힌다.  황금의 유물을 찾아 여러 탐험가들이 하무납트라를 찾아오지만 하나 같이 의문의 죽음을 당하고, 전투 중에 피신했던 외인부대 장교 오커넬만이 유일하게 살아남는다. 그 소식을 들은 이집트 박물관 사서 이비와 그녀의 오빠 조나단이 오커넬을 찾아오고 죽음의 도시 하무납트라에 관한 단서를 듣게 된다. 용기와 모험심으로 뭉친 세 사람은 의기 투합하여 하무납트라의 황금유물을 찾아 떠나기로 한다.  한편 파라오의 저주를 푸는 열쇠를 손에 넣은 조나단은 실수로 이모텝을 부활시키고, 마침내 3천년을 기다려온 엄청난 분노가 온 이집트를 뒤덮는데. 아무것도 모르는 세 사람은 죽음과 저주의 왕국 한 가운데에서 살아난 미이라와의 사투를 벌인다.', '1999-07-10', 6.957, 15.6897, 124, 'Stephen Sommers', 9695, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (205596, '이미테이션 게임', 'The Imitation Game', 'movie', 'https://image.tmdb.org/t/p/w500/wT4cHJMqWqWxY4GXDXgD10lMQWy.jpg', 'https://image.tmdb.org/t/p/original/gLQoJ9P79g501oEEtrN8zMlCPpx.jpg', '매 순간 3명이 죽는 사상 최악의 위기에 처한 제 2차 세계대전. 절대 해독이 불가능한 암호 에니그마로 인해 연합군은 속수무책으로 당하게 된다. 결국 각 분야의 수재들을 모아 기밀 프로젝트 암호 해독팀을 가동한다. 천재 수학자 앨런 튜링은 암호 해독을 위한 특별한 기계를 발명하지만  24시간 마다 바뀌는 완벽한 암호 체계 때문에 번번히 좌절하고 마는데... 과연, 앨런 튜링과 암호 해독팀은 암호를 풀고 전쟁의 승리를 끌어낼 수 있을까…?', '2015-02-17', 7.988, 15.6714, 114, '모튼 틸덤', 17759, 0);
