INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (68721, '아이언맨 3', 'Iron Man 3', 'movie', 'https://image.tmdb.org/t/p/w500/5aHoACZhLJR95uQN4Hd2k6swUZq.jpg', 'https://image.tmdb.org/t/p/original/iVped1djsF0tvGkvnHbzsE3ZPTF.jpg', '어벤저스의 일원으로 활약한 뉴욕 사건 이후, 트라우마로 인해 영웅으로서의 삶에 회의를 느끼는 토니 스타크. 그가 혼란을 겪는 사이 최악의 테러리스트 만다린을 내세운 익스트리미스 집단 AIM이 스타크 저택에 공격을 퍼붓는다. 이 공격으로 그에게 남은 건 망가진 수트 한 벌 뿐. 모든 것을 잃어버린 그는 다시 테러의 위험으로부터 세계와 사랑하는 여인을 지켜내야 하는 동시에 머릿속을 떠나지 않던 한가지 물음의 해답도 찾아야만 한다. 과연 그가 아이언맨인가? 수트가 아이언맨인가?', '2013-04-25', 6.9, 15.5915, 129, '셰인 블랙', 23074, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (150540, '인사이드 아웃', 'Inside Out', 'movie', 'https://image.tmdb.org/t/p/w500/rMXHvHzpuYZXrJUhRVJ3TvDSwe5.jpg', 'https://image.tmdb.org/t/p/original/jJKZaTBNenlFclQyjrnvzkRmvWE.jpg', '모든 사람의 머릿속에 존재하는 감정 컨트롤 본부. 그곳에서 불철주야 열심히 일하는 기쁨, 슬픔, 버럭, 까칠, 소심 다섯 감정들. 정든 옛 동네를 떠나 도시로 이사하는 라일리 가족. 이사 후 새로운 환경에 적응해야 하는 라일리를 위해 그 어느 때 보다 바쁘게 감정의 신호를 보내지만 우연한 실수로 기쁨과 슬픔이 본부를 이탈하게 되자 라일리의 마음 속에 큰 변화가 찾아온다. 라일리가 예전의 모습을 되찾기 위해서는 기쁨과 슬픔이 본부로 돌아가야만 한다. 그러나 엄청난 기억들이 저장되어 있는 머릿속 세계에서 본부까지 가는 길은 험난하기만 한데...', '2015-07-09', 7.909, 15.5849, 102, '피트 닥터', 23094, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (8966, '트와일라잇', 'Twilight', 'movie', 'https://image.tmdb.org/t/p/w500/ryvt6cLTjHHH7Nnce3Xi5S3I533.jpg', 'https://image.tmdb.org/t/p/original/weAYfu6FfrNxEDJ3xH1XpgQcqUv.jpg', '17세의 평범한 고등학생 소녀 ‘벨라’는 집안 사정으로 워싱턴 주 포크스에 있는 아빠의 집으로 이사를 온다. 전학 첫날, ‘벨라’는 냉담하지만 자신을 무장 해제시킬 정도로 잘생긴 ‘에드워드’와 마주치고, 전율과 두려움 넘치는 인생의 전환을 맞이한다. ‘에드워드’와 돌이킬 수 없는 사랑에 빠져든 ‘벨라’. 하지만 ‘에드워드’와 그의 가족이 뱀파이어 일족이라는 사실을 알게 되고, 예기치 못한 운명에 빠져든다.', '2008-12-10', 6.3, 15.5802, 122, '캐서린 하드윅', 14181, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1433719, 'High Ground', 'High Ground', 'movie', 'https://image.tmdb.org/t/p/w500/cqF7xuZWbBYXWHsp1I1H5PwujPs.jpg', 'https://image.tmdb.org/t/p/original/kyp7PSCKPZKGosthRbjfXPm8gJg.jpg', '', '2025-03-17', 5.825, 15.5574, 92, 'James Bamford', 40, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (14160, '업', 'Up', 'movie', 'https://image.tmdb.org/t/p/w500/lL2WzkjLZP0RkPgUhybBjb9x9SL.jpg', 'https://image.tmdb.org/t/p/original/hGGC9gKo7CFE3fW07RA587e5kol.jpg', '평생 모험을 꿈꿔 왔던 칼 할아버지는 재개발 공사 현장의 인부를 실수로 다치게 하고 집을 빼앗길 위기에 처한다. 그 동안 미뤄 왔던, 먼저 세상을 떠난 아내와의 약속을 지키기 위해 그는 수천 개의 풍선을 매달아 집을 통째로 남아메리카로 날려 버린다. 하지만 이 위대한 모험에 초대 받지 않은 불청객이 있었으니, 바로 황야의 어린이 탐험가 러셀. 우여곡절 끝에 도착한 남미에서 칼은 어린 시절의 우상이었던 위대한 모험가 찰스 먼츠를 만나게 되는데... 그들은 과연 남미의 잃어버린 세계에서 사라져 버린 꿈과 희망, 행복을 다시 찾을 수 있을까?', '2009-07-29', 7.96, 15.5325, 96, '피트 닥터', 21260, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (2062, '라따뚜이', 'Ratatouille', 'movie', 'https://image.tmdb.org/t/p/w500/zFah4LNeWw68y7RRGi20CQlGByY.jpg', 'https://image.tmdb.org/t/p/original/xgDj56UWyeWQcxQ44f5A3RTWuSs.jpg', '절대미각, 빠른 손놀림, 끓어 넘치는 열정의 소유자 레미. 프랑스 최고의 요리사를 꿈꾸는 그에게 단 한가지 약점이 있었으니, 바로 주방 퇴치대상 1호인 생쥐라는 것. 어느 날 하수구에서 길을 잃은 레미는 파리의 별 다섯개짜리 최고급 레스토랑에 떨어진다. 보글거리는 수프, 둑닥둑닥 도마소리, 향긋한 허브 내음에 식욕이 아닌 요리욕이 북받친 레미의 작은 심장은 콩닥콩닥 뛰기 시작한다. 끝내 주방으로 들어가는 레미는 요리에 열중하다 견습생 링귀니에게 딱 걸리고 만다. 해고위기에 처해있던 링귀니는 레미의 재능을 한눈에 알아보고 의기투합을 제안하는데...', '2007-07-25', 7.835, 15.5118, 115, '브래드 버드', 18107, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (269955, '인간중독', '인간중독', 'movie', 'https://image.tmdb.org/t/p/w500/fYrFH2WlCEUNuR85JturV77uOBU.jpg', 'https://image.tmdb.org/t/p/original/iGBbWXmAIgpiWg9Mx2D2gLzbg4n.jpg', '베트남전이 막바지로 치달아가던 1969년, 엄격한 위계질서와 상하관계로 지배되는 군관사. 모두의 신임을 받으며 승승장구 중인 교육대장 김진평과 남편을 장군으로 만들려는 야망을 가진 진평의 아내 이숙진. 어느 날, 김진평의 부하로 충성을 맹세하는 경우진과 그의 아내 종가흔이 이사를 온다. 진평은 우진의 아내 가흔에게 첫 만남부터 강렬한 떨림을 느끼는데…', '2014-05-14', 6.7, 15.4662, 132, '김대우', 77, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1562, '28주 후', '28 Weeks Later', 'movie', 'https://image.tmdb.org/t/p/w500/2BflgoKrzMMoVgn9md0uSPJ0GTU.jpg', 'https://image.tmdb.org/t/p/original/83ownpZPvBHJD5UVNShzQfa3LaW.jpg', '인간을 좀비로 만드는 분노 바이러스가 영국을 휩쓸고 지나간 후 6개월이 지난 시점. 미국 군대가 바이러스와의 전쟁을 선언한 뒤 마치 그들이 승리를 거둔 듯해 보인다. 그리고 점차 도시는 질서를 되찾는다. 런던을 떠났던 시민들은 점차 도시로 돌아오고, 헤어졌던 가족은 재회의 기쁨을 나눈다. 하지만, 사실 바이러스는 죽지 않았고, 사람들이 모르는 사이 다시금 도시를 초토화 시키려고 하는데..', '2019-07-11', 6.608, 15.4507, 100, 'Juan Carlos Fresnadillo', 5302, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1009640, '38선: DMZ 탈출 작전', 'Valiant One', 'movie', 'https://image.tmdb.org/t/p/w500/eRo3mdp4Sc6G6sXUPZNBerPKZSu.jpg', 'https://image.tmdb.org/t/p/original/wPSZXVqe84X8SINvJGiKYZhkSG1.jpg', '헬기 추락으로 북한 지역에 고립된 미군 특수 대원들. 탄약은 바닥나고, 적의 포위망은 점점 좁혀온다. 구조의 희망은 사라졌지만, 그들에게 남은 선택지는 단 하나... 비무장지대, DMZ를 향한 죽음의 행군.  끝없는 총격전과 곳곳에 도사린 매복, 매 순간이 함정이고, 한 걸음 한 걸음이 죽음과 맞닿아 있다.  그러나 반드시 살아 돌아가야 한다는 의지로, 그들은 목숨을 건 탈출 전투를 시작한다.', '2025-10-28', 6.733, 15.4279, 87, 'Steve Barnett', 101, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (14836, '코렐라인: 비밀의 문', 'Coraline', 'movie', 'https://image.tmdb.org/t/p/w500/iGp4wBc0ZBVFd2HPicyDgl6Pn1r.jpg', 'https://image.tmdb.org/t/p/original/hofnlIyF6bePkgQOpcuRWLvzf15.jpg', '새로운 집으로 이사 온 열한 살 소녀 코렐라인은 모든 것이 낯설기만 하고, 늘 바쁜 부모님 때문에 외로운 날들을 보낸다. 호기심 많은 코렐라인은 홀로 집과 동네를 탐험하다 동네 소년 와이비와 개성 넘치는 이웃들을 만나게 된다. 그러던 어느 날, 집 안에 숨겨진 작은 비밀 문을 발견한 코렐라인은 문을 열고 어두운 통로를 지나 들어간다. 그곳은 현실과 꼭 닮았지만, 훨씬 더 완벽해 보이는 또 다른 세계였다. ‘다른 엄마’와 ‘다른 아빠’는 언제나 그녀를 따뜻하게 맞이하고, 신비로운 검은 고양이는 그림자처럼 곁을 맴돌며 호기심을 자극한다. 처음엔 꿈만 같은 낯선 세계였지만, 점점 그곳의 숨겨진 진실이 드러나기 시작하는데...', '2009-05-21', 7.899, 15.4093, 101, '헨리 셀릭', 8752, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (767, '해리 포터와 혼혈왕자', 'Harry Potter and the Half-Blood Prince', 'movie', 'https://image.tmdb.org/t/p/w500/yrGlb3HLtjGp39mv4MJ5UuIHcj4.jpg', 'https://image.tmdb.org/t/p/original/ze6Mx4QE5mQVXRYmG2flncqqle4.jpg', '어둠의 세력이 더욱 강력해져 머글 세계와 호그와트까지 위협해온다. 위험한 기운을 감지한 덤블도어 교수는 다가올 전투에 대비하기 위해 해리 포터와 함께 대장정의 길을 나선다. 볼드모트를 물리칠 수 있는 유일한 단서이자 그의 영혼을 나누어 놓은 7개의 호크룩스를 파괴하는 미션을 수행해야만 하는 것! 또한 덤블도어 교수는 호크룩스를 찾는 기억여행에 결정적 도움을 줄 슬러그혼 교수를 호그와트로 초청한다. 한편 학교에서는 계속된 수업과 함께 로맨스의 기운도 무르익는다. 해리는 자신도 모르게 지니에게 점점 끌리게 되고, 새로운 여자 친구가 생긴 론에게 헤르미온느는 묘한 질투심을 느끼는데...', '2009-07-15', 7.682, 15.3923, 153, '데이빗 예이츠', 20423, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (889737, '조커: 폴리 아 되', 'Joker: Folie à Deux', 'movie', 'https://image.tmdb.org/t/p/w500/bIwIzpgrPddNk4xrhdd3xyM8C20.jpg', 'https://image.tmdb.org/t/p/original/AVWlQpVhpudyFsSh3OQIieHHYf.jpg', '2년 전, 세상을 뒤흔들며 고담시 아이콘으로 자리한 아서 플렉은 아캄 수용소에 갇혀 최종 재판을 앞둔 무기력한 삶을 살아간다. 그러던 어느 날, 수용소에서 운명적으로 만난 리 퀸젤은 아서의 삶을 다시 뒤바꾸며 그의 마음 속에 잠들어 있던 조커를 깨우고 리 역시 각성하며 자신을 할리 퀸이라 지칭하며 서로에게 깊이 빠져든다. 무고한 시민을 죽인 죄로 재판에 오르게 된 아서. 그는 최후의 심판대에서 할리 퀸과 함께 자신, 조커의 이야기를 시작하는데…', '2024-10-01', 5.405, 15.35, 138, '토드 필립스', 2757, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1578018, 'Bendito corazón', 'Bendito corazón', 'movie', 'https://image.tmdb.org/t/p/w500/bfburbW7SnLBscRe2hWneN6z9vB.jpg', 'https://image.tmdb.org/t/p/original/xh2IXxK62vZeLAn0VQmJLRH3ObU.jpg', '', '2026-01-22', 0, 15.3322, 159, 'Miguel Ángel Pérez', 0, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1119090, '프랑켈다', 'Soy Frankelda', 'movie', 'https://image.tmdb.org/t/p/w500/rh3HNzV7o8ouH4NnCuL76OFPFBF.jpg', 'https://image.tmdb.org/t/p/original/pZr3484MENVj3m7toTUk7Cw4bnW.jpg', '어릴 적부터 어둡고 공포스러운 이야기만 써온 프란치스카 앞에 어느 날 헤르네발 왕자가 나타난다. 그의 설명에 따르면 두려움이라는 감정으로 유지되는 왕국이 존폐 위기에 처했다고 한다. 이어 호러 작가로서 프란치스카의 힘이 절실하다는 말과 함께 그를 무의식 세계로 초대한다.', '2025-10-25', 8.381, 15.2876, 113, 'Roy Ambriz', 59, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (156022, '더 이퀄라이저', 'The Equalizer', 'movie', 'https://image.tmdb.org/t/p/w500/hqes9NQtVIULs8VKu0WqY6RdXGU.jpg', 'https://image.tmdb.org/t/p/original/wNAfVj1ObGNye5fQM4tJXJGtU0.jpg', '새벽 2시만 되면 어김없이 잠에서 깨는 로버트 맥콜. 불면증으로 잠 못 드는 이 시간이면 그는 늘 책 한 권을 들고 카페로 향한다. 가족도 친구도 없는 그는 아내가 남기고 간 ‘죽기 전에 읽어야 할 소설 100권’을 모두 읽는 것이 유일한 삶의 목표다. 그런 그에게 어느 날, 어린 콜걸 테리가 말을 건넨다. 무료하게 전화를 기다리다 벨이 울리면 대기하고 있던 리무진에 오르는 테리와 매일 같은 공간에서 같은 시간을 공유하던 로버트는 묘한 동질감을 느끼며 가까워진다. 그러던 어느 날, 테리가 포주인 러시아 마피아에게 무자비하게 폭행을 당한 채로 발견되자 세상을 향한 분노가 폭발하고만 로버트는 마침내, 강자에겐 약하고 약자에겐 한없이 강한 이 세상을 향해 스스로 심판자가 되기로 결심하는데...', '2015-01-28', 7.282, 15.1908, 132, '안톤 후쿠아', 9691, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (507244, '애프터번', 'Afterburn', 'movie', 'https://image.tmdb.org/t/p/w500/hrze9JXp2QJpc2WjLfSUtRxyYSb.jpg', 'https://image.tmdb.org/t/p/original/kHOfxq7cMTXyLbj0UmdoGhT540O.jpg', '“인류가 사라진 땅, 보물 사냥꾼의 마지막 의뢰” 태양폭풍으로 전 세계의 기술과 문명이 붕괴된 지 10년. 생존자들은 폐허 속에서 잔존한 유물과 자원을 두고 치열한 경쟁을 벌인다. 전직 군인이었던 제이크는 ‘보물 사냥꾼’으로 전락해 문명의 파편이 된 유물들을 회수해 생계와 희망을 이어 간다. 그는 위험한 의뢰를 받고 프랑스로 향하게 되고, 그곳에서 프랑스 저항군 전사 드레아와 손을 맞잡는다. 그러나 이번 목표는 단순한 보물이 아니다. 인류의 마지막 상징이자 권력의 열쇠인 모나리자를 되찾는 그들의 여정은, 전장 속에서 새로운 운명을 마주하게 되는데…', '2025-08-20', 6.5, 15.1903, 105, 'J. J. 페리', 175, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1302017, '거부할 수 없는 유혹', 'Uhaw', 'movie', 'https://image.tmdb.org/t/p/w500/xsUjSNFXyEWe3zkcHOWm7Hw7dR6.jpg', 'https://image.tmdb.org/t/p/original/1bRxlfuI7woxnxM8Z8LIgaKpffH.jpg', '', '2025-03-27', 4.4, 15.1804, 94, 'Bobby Bonifacio', 5, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1376434, '프레데터: 킬러 오브 킬러스', 'Predator: Killer of Killers', 'movie', 'https://image.tmdb.org/t/p/w500/d0xpDahU5hTyHoL9wyM6jVg1tFP.jpg', 'https://image.tmdb.org/t/p/original/3AGZKVr2DPT9H53gYtkSEC1tK1E.jpg', '이 작품은 인류 역사상 가장 잔인한 세 전사의 운명을 따라가는 오리지널 애니메이션이다. 이들은 어린 아들을 이끌고 핏빛 복수의 여정을 떠나는 바이킹 약탈자, 일본 봉건시대 때 치열한 승계 다툼 후 사무라이인 형제에게 등을 돌리게 된 닌자, 그리고 연합군을 위협하는 초자연적 위험을 조사하러 하늘로 향하는 제2차 세계대전 조종사이다.', '2025-06-06', 7.852, 15.1734, 85, '댄 트랙턴버그', 1051, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (290098, '아가씨', '아가씨', 'movie', 'https://image.tmdb.org/t/p/w500/62l7g8lUJufEcd1Qz9TbAL5HR9t.jpg', 'https://image.tmdb.org/t/p/original/3upEZ0ltY7WwOSFVXrtiP34D48p.jpg', '어릴 적 부모를 잃고 후견인 이모부의 보호 아래 살아가는 귀족 아가씨에게 백작이 추천한 새로운 하녀가 찾아온다. 이모부의 서재에서 책을 읽는 것이 일상의 전부인 아가씨는  순박해 보이는 하녀에게 조금씩 의지하기 시작한다. 하지만 하녀의 정체는 유명한 여도둑의 딸인 소매치기 고아 소녀 숙희. 막대한 재산을 상속받게 될 아가씨를 유혹하여 돈을 가로채겠다는 사기꾼 백작의 제안을 받고  아가씨가 백작을 사랑하게 만들기 위해 하녀가 된 것. 드디어 백작이 등장하고, 백작과 숙희는 자신만의 방식으로 아가씨의 마음을 흔들기 시작하는데...', '2016-06-01', 8.191, 14.461, 144, '박찬욱', 4164, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (58, '캐리비안의 해적: 망자의 함', 'Pirates of the Caribbean: Dead Man''s Chest', 'movie', 'https://image.tmdb.org/t/p/w500/6tD4oT7C01aZLVfoZDz5VFVbJCi.jpg', 'https://image.tmdb.org/t/p/original/vr6n6ZFUZvedvIlhfYcbCWcaKyW.jpg', '잭 스패로우는 블랙펄을 되찾아 포트 로열을 떠났지만 그를 기다리는 것은 수평선만이 아니었다. 유령선 플라잉 더치맨의 선장 데이비 존스는 잭이 자신에게 피로 진 빚이 있다면서 빚을 갚거나 영혼을 내놓으라고 요구한다. 불행 중 다행한 것은 잭에게 피의 빚 외에도 중매의 은총이 있었다는 것. 결혼을 앞둔 윌 터너와 엘리자베스 스완은 만사를 제쳐두고 옛 친구를 도우러 온다. 잭을 구할 수 있는 단 한 가지 방법은 세상 끝에 있다는 망자의 함을 찾는 것 뿐인데...', '2006-07-06', 7.374, 16.098, 151, '고어 버빈스키', 16829, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1426776, '벼랑 끝에 서서', 'STRAW', 'movie', 'https://image.tmdb.org/t/p/w500/puj4agwRL5TsT7e0TYDqEXBZqyN.jpg', 'https://image.tmdb.org/t/p/original/fnbWrDx8w8Reau4F1tFqoGuGmDZ.jpg', '열심히 일하며 간신히 버텨온 싱글맘. 하지만 인내심을 무너뜨릴 최후의 타격을 맞게 된다면? 끔찍한 하루를 보내고 한계에 다다른 그녀는 절망에 빠져 충격적인 행동을 하기에 이른다.', '2025-06-06', 7.766, 16.1043, 105, '타일러 페리', 899, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1286185, '목수의 아들', 'The Carpenter''s Son', 'movie', 'https://image.tmdb.org/t/p/w500/tXEtdZjoaHqjDjSxZJWwDVjIfx9.jpg', 'https://image.tmdb.org/t/p/original/aP7w2JPEDyIukrYxIGHmTrmYOWJ.jpg', '', '2025-11-13', 5.337, 15.5597, 94, 'Lotfy Nathan', 43, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (823464, '고질라 X 콩: 뉴 엠파이어', 'Godzilla x Kong: The New Empire', 'movie', 'https://image.tmdb.org/t/p/w500/4z1VMmlxHrziG45901esjB4dpIa.jpg', 'https://image.tmdb.org/t/p/original/gvLG3Fnznkxl4SmYfcK8gUuqxM8.jpg', '두 타이탄의 전설적인 대결 이후 할로우 어스에 남은 콩은 드디어 애타게 찾던 동족을 발견하지만 그 뒤에 도사리고 있는 예상치 못한 위협에 맞닥뜨린다. 한편, 깊은 동면에 빠진 고질라는 알 수 없는 신호로 인해 깨어나고 푸른 눈의 폭군 스카 킹의 지배 아래 위기에 처한 할로우 어스를 마주하게 된다. 할로우 어스는 물론, 지구상에도 출몰해 전세계를 초토화시키는 타이탄들의 도발 속에서 고질라와 콩은 사상 처음으로 한 팀을 이뤄 반격에 나서기로 하는데…', '2024-03-27', 7.06, 15.942, 115, '애덤 윈가드', 4476, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (9654, '이탈리안 잡', 'The Italian Job', 'movie', 'https://image.tmdb.org/t/p/w500/sAyAtBkqD5yirImZQKfvLzlH1EZ.jpg', 'https://image.tmdb.org/t/p/original/jPH8ROhZMLvP0owQCE1J6it7fN0.jpg', '금고털이 전문범인 존 브릿저는 외동딸 스텔라의 만류로 은퇴를 결심하지만, 동료인 찰리의 권유를 뿌리치지 못 하고 마지막으로 한탕만 더하기로 한다. 이탈리아의 베니스에서 3천 5백만 달러어치의 금괴가 든 금고를 그들 각각의 두뇌 플레이와 각자의 전문 실력을 발휘하여 쥐도 새도 모르게 탈취한다. 그러나 수익금을 배분하기도 전에 같은 동료인 스티브가 이들을 배반하여 모두를 호수에 수장 시키고 금고를 빼앗아 달아나버린다. 그 와중에 멤버의 대부 격인 존은 죽고, 살아남은 찰리와 나머지 동료들은 스티브에 대한 복수를 준비 한다.  스티브가 헐리웃에 숨어산다는 정보를 입수한 이들은 스티브의 금고를 탈취할 계획을 세운다. 무슨 금고든지 열수 있는 금고 열이 최고 전문가인 존의 딸 스텔라도 아버지의 원수를 갚기 위하여 이들에게 합류한다. 한편, 죽은줄 알았던 옛 동료들이 나타나자 긴장한 스티브는 금괴가 든 금고를 멕시코로 옮길 결심을 한다.그러나 이들이 누구인가! 그들은 피라미드 저 밑에 숨겨도 찾아낼 수 있는 최고의 폭약 전문가, 컴퓨터 전문가,자동차 전문가로 구성된 실력 군단 인 것이다! 그들은 이탈리아에서 보여 주었던 그들의 실력을 다시 보여 주기 위하여 치밀한 계획 하에 스티브의 금고를 다시 나꿔챌 작전을 세우는데.', '2003-10-03', 6.784, 12.6867, 110, 'F. 게리 게리', 5856, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1241752, '홀로 남은 아내: 리타', 'Rita', 'movie', 'https://image.tmdb.org/t/p/w500/grIFQLXXwQmjvYYfXVXCgGTMUWw.jpg', 'https://image.tmdb.org/t/p/original/5AsIFZ2AJC7JcGpq40aRPuRuaRc.jpg', '해외로 떠난 남편을 기다리며 홀로 남겨진 리타. 끝없는 외로움은 그녀를 서서히 다른 사람의 품으로 이끌고, 남편 역시 타국에서 비밀스러운 위안을 찾는다. 재회한 두 사람은 아무 일도 없었던 듯 일상을 이어가려 하는데, 둘의 결혼은 결국 파국을 맞는다.', '2026-01-28', 6, 15.027, 113, 'Jerry Lopez Sineneng', 20, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (218, '터미네이터', 'The Terminator', 'movie', 'https://image.tmdb.org/t/p/w500/y6FmrimVoBBKsERc08VyVP1NyNs.jpg', 'https://image.tmdb.org/t/p/original/ffdqHMWkh1h9MABwIfbfRJhgFW6.jpg', '1997년, 인간이 만든 인공지능 컴퓨터 전략 방어 네트워크가 스스로의 지능을 갖추고는 인류를 핵전쟁의 참화을 일으켜 30억이라는 인류를 잿더미 속에 묻어버린다. 그리고 남은 인간들은 기계의 지배를 받아 시체를 처리하는 일 등에 동원된다. 이때 비상한 지휘력과 작전으로 인간들을 이끌던 사령관 존 코너는 반기계 연합을 구성, 기계와의 전쟁을 시작하면서 상황은 반전된다. 이에 기계는 존 코너의 탄생 자체를 막기 위해 2029년의 어느 날 타임머신에 터미네이터를 태워서 1984년의 L.A로 보내게 된다.', '1984-12-22', 7.674, 15.8066, 108, '제임스 카메론', 14213, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1588846, 'Ekis', 'Ekis', 'movie', 'https://image.tmdb.org/t/p/w500/vuUvGqqGabV422qzjGWPlhRuvN0.jpg', 'https://image.tmdb.org/t/p/original/3pJx6MzdvdWQACLTYQtDW3IgzV0.jpg', '', '2025-12-19', 6.25, 15.1246, 107, 'Christian Paolo Lat', 4, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (46853, '유년의 사랑', 'Maladolescenza', 'movie', 'https://image.tmdb.org/t/p/w500/nu5uj47KSF73VPEiIRYdPLJ96j7.jpg', 'https://image.tmdb.org/t/p/original/2AI3pSt5sbAEav6isVDIeCuiZql.jpg', '《유년의 사랑》은 이탈리아에서 제작된 피에르 쥬세페 무르기아 감독의 1977년 드라마, 멜로/로맨스 영화이다. 라라 웬델 등이 주연으로 출연하였다.', '1977-05-17', 5.12, 14.7908, 94, 'Pier Giuseppe Murgia', 83, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (679, '에이리언 2', 'Aliens', 'movie', 'https://image.tmdb.org/t/p/w500/8J1SwqmsHRzZ5k8QVRibkzyc9jc.jpg', 'https://image.tmdb.org/t/p/original/4kix6fAblJIH6eMs0Ku2loyZJXK.jpg', '에일리언과의 싸움에서 간신히 살아남은 리플리는 잠든 채로 57년을 떠돌다 구조선에 의해 구출된다. 회사는 리플리를 비롯한 당시 승무원들이 노스트로모호를 잃어버린 것을 추궁하지만 에이리언 얘기는 믿지 않는다. 이때 지구와 한 혹성 거주민들의 통신이 두절되는 사건이 벌어지자 리플리는 고문 자격으로 해병대와 동행하게 된다. 혹성에 도착한 해병대원들은 곧 혹성 거주민들이 에일리언 유충의 산 먹이로 된 것을 목격하고, 곧이어 벌어진 교전에서 여러 대원들을 잃는다. 그들은 혹성 거주민들의 실험실로 대피하고, 리플리는 이곳에서 마지막 생존자인 뉴트를 발견하게 된다.', '1986-12-24', 7.957, 13.7924, 137, '제임스 카메론', 10543, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1084199, '컴패니언', 'Companion', 'movie', 'https://image.tmdb.org/t/p/w500/dq7CEYFCvQPfYIpAXOvJr3w6VLY.jpg', 'https://image.tmdb.org/t/p/original/cZnJ3ABPvsWGqwPcu06Eda493F9.jpg', '서로에게 딱 맞는 커플 ‘아이리스’와 ‘조시’는 친구들과 함께 호숫가의 별장으로 호화로운 휴가를 떠난다. 하지만 그곳에는 충격적인 사건이 기다리고 있는데…', '2025-03-19', 7.025, 17.1356, 97, 'Drew Hancock', 2023, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (228150, '퓨리', 'Fury', 'movie', 'https://image.tmdb.org/t/p/w500/dYwwlFLd8WNrfa3s6HBzAbH3QXG.jpg', 'https://image.tmdb.org/t/p/original/95ckrV6wQgbffurAVmETQ5YKASL.jpg', '2차 세계대전, 전차부대를 이끄는 대장 워대디에게 적으로 둘러싸인 최전선에서의 마지막 전투 명령이 떨어진다. 하지만 수 차례의 전투로 대부분의 동료를 잃은 그에겐 단 한 대의 탱크 퓨리와 지칠 대로 지쳐버린 부대원들만이 남아있을 뿐. 게다가 지원군으로 경력이 전무한 신병 노먼이 배치되고, 워대디는 신참을 포함한 단 4명의 부대원만으로 적진에 나서야 하는 상황에 처한다. 수백 명의 적들과 맞서야 하는 단 5인의 병사. 최소의 인원과 최악의 조건 속, 사상 최대 위기에 처한 워대디와 그의 부대는 생존 가능성 제로인 최후의 전쟁터로 향하는데...', '2014-11-20', 7.54, 15.5567, 134, '데이비드 에이어', 12673, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1252428, '아나콘다: 저주받은 정글', '狂蟒之灾', 'movie', 'https://image.tmdb.org/t/p/w500/9a7URTaq1Eimlg2ZujPX9FdOeGK.jpg', 'https://image.tmdb.org/t/p/original/gSVk4r8Q4R8aeGY0hhEG3bE0QzL.jpg', '태국 순회 공연을 시작한 한 서커스 팀이 전 동료에게 속아넘어간다. 동남아시아 열대우림을 가로지르는 여정 중, 그들은 거대한 비단뱀의 공격을 받는다. 도움을 제안하는 제프라는 신비한 남자를 만나지만, 그가 밀렵꾼임을 곧 깨닫게 된다. 제프의 배를 찾아 나선 그들은 비단뱀과 제프 자신과의 생사를 건 싸움에 직면한다.', '2024-03-01', 7, 18.4265, 84, 'Xiang Qiuliang', 125, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (447365, '가디언즈 오브 갤럭시 Vol. 3', 'Guardians of the Galaxy Vol. 3', 'movie', 'https://image.tmdb.org/t/p/w500/zK0FTsXvkWVS3yubZkbenbAFcnY.jpg', 'https://image.tmdb.org/t/p/original/hoVj2lYW3i7oMd1o7bPQRZd1lk1.jpg', '가모라를 잃고 슬픔에 빠져 있던 피터 퀼이 위기에 처한 은하계와 동료를 지키기 위해 다시 한 번 가디언즈 팀과 힘을 모으고, 성공하지 못할 경우 그들의 마지막이 될지도 모르는 미션에 나서는 이야기.', '2023-05-03', 7.929, 14.9144, 150, '제임스 건', 7936, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (615777, '바빌론', 'Babylon', 'movie', 'https://image.tmdb.org/t/p/w500/6JQtIajMe70HWtBf7uZ1ZyWiW1F.jpg', 'https://image.tmdb.org/t/p/original/5fxTB08O7CW1hAcN2MWOKodp1h1.jpg', '황홀하면서도 위태로운 고대 도시 바빌론에 비유되는 할리우드에서 전성기를 누리고 있는 당대 최고의 스타 잭 콘래드.  누구나 잭과 같은 성공을 꿈꾸지만 아무나 이룰 수 없던 그 때, 화려한 데뷔를 위해 당차게 야망을 좇는 넬리 라로이와 열정적인 청년 매니 토레스가 영화 같은 삶을 꿈꾸며 할리우드에 입성한다. 하지만 할리우드에서는 기존 영화 산업의 틀을 깬 새로운 변화가 시작되고 그 격변의 한가운데에서 잭과 넬리, 그리고 매니는 살아남아 각자의 꿈을 이루기 위해 고군분투하는데...', '2023-02-01', 7.366, 14.3479, 189, '데이미언 셔젤', 3613, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1495694, '뷰티 프롬 페인', 'Beauty from Pain', 'movie', 'https://image.tmdb.org/t/p/w500/mJtBKvHQaFzgp0N6JFskSvjbTar.jpg', 'https://image.tmdb.org/t/p/original/yCg9mQpR3nVmX9ku3ObCAIISb5g.jpg', '참담한 이별을 겪은 후, 한 음악 지망생이 호주로 도피한다. 그녀는 억만장자 와인 제조업자와 조건 없는 연애를 하기로 동의하지만, 사랑에 빠지게 되자 떠나야 할지, 사랑을 두려워하는 남자에게 마음을 걸어야 할지 선택해야 한다.', '2025-12-18', 7.313, 14.5216, 116, 'Christine Luby', 8, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (12, '니모를 찾아서', 'Finding Nemo', 'movie', 'https://image.tmdb.org/t/p/w500/9ViCYfZ0whpwtKbM2WJP5PfsG2x.jpg', 'https://image.tmdb.org/t/p/original/eCynaAOgYYiw5yN5lBwz3IxqvaW.jpg', '광대어 말린은 아내 코랄과 2세들의 부화를 기다리던 중 상어의 습격을 받는다. 알을 보호하려던 아내는 행방불명되고, 유일하게 살아남은 아기에게 말린은 니모라는 이름을 붙인다. 사건 이후 큰 바다를 무조건 겁내게 된 말린은 니모를 과보호한다. 하지만 니모는 등교 첫날 잠수부에게 납치돼 시드니에 있는 치과의사의 수족관에 끌려가고, 슬픔으로 혼비백산한 아빠 말린은 평소의 심약함을 잊고니모를 찾아나선다. 단기기억상실증을 지닌 명랑한 물고기 도리의 도움으로 상어, 심해어, 해파리의 위협을 뚫고 동호주 해류로 향하는 동안, 니모는 수족관의 새 친구들과 탈출을 모의한다.', '2003-06-06', 7.817, 16.9534, 100, '앤드류 스탠튼', 20197, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1379963, '상냥하게 말해줘', 'Dímelo bajito', 'movie', 'https://image.tmdb.org/t/p/w500/nQmpQaCLwxUGeYkTGo5U8aCY91U.jpg', 'https://image.tmdb.org/t/p/original/rtv6da2U8poERiAZSAbCOePXzql.jpg', '카밀라의 인생은 완벽하다. 공부, 친구 관계, 평판까지... 하지만 7년 동안 사라졌던 이웃 디 비앙코 형제가 갑자기 돌아왔다. 첫 키스 상대 티아고와 절친이었던 테일러. 둘의 귀환으로 카미의 세계는 완전히 흔들린다. 세 사람은 과거의 상처를 극복할 수 있을까? 아니면 또다시 모든 게 엉망이 돼 버릴까?', '2025-12-11', 6.222, 14.7709, 119, 'Denis Rovira van Boekholt', 117, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1322752, '극장판 프로젝트 세카이 부서진 세카이와 전해지지 않는 미쿠의 노래', '劇場版プロジェクトセカイ 壊れたセカイと歌えないミク', 'movie', 'https://image.tmdb.org/t/p/w500/ssWJFcux3TIf9LMsUBXccplvRnp.jpg', 'https://image.tmdb.org/t/p/original/kLpIAD9WWku0VhGNWJ7bjUilPjK.jpg', '「너에 대해서, 알려 줘. 그러면 노래를 알 수 있을지도 몰라」 음반 가게에서 처음 듣는 미쿠의 노래를 듣게 된 호시노 이치카. 그녀는 모니터에서 처음 보는 모습의 "하츠네 미쿠"를 보고 「미쿠?!」라고 소리를 낸다. 그 목소리에 놀란 미쿠는 이치카와 눈이 마주쳤지만 금방 사라지고 말았다.  며칠 뒤, 거리 공연을 마친 이치카의 스마트폰에 저번에 봤던 미쿠의 모습이 나타난다. 쓸쓸한 듯 고개를 떨구고 있는 미쿠에게 이치카가 조심스레 물어보니, 노래를 전하고 싶은 사람들이 있는데 아무리 노래해도 그 노래가 전해지지 않는다고 말한다. 미쿠는 공연으로 많은 사람들의 마음에 노래를 전하는 이치카의 모습을 보고 이치카에 대해서 알면 자신도 이치카처럼 할 수 있을 거라고 생각해서 이치카를 찾아온 것이었다.  미쿠의 부탁에 이치카는 「나라도 괜찮다면」이라고 미소 지으며 대답하고, 하츠네 미쿠와 소년소녀들의 새로운 이야기가 시작된다.', '2025-05-29', 7.6, 15.0098, 105, '하타 히로유키', 31, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1015539, 'Santastein', 'Santastein', 'movie', 'https://image.tmdb.org/t/p/w500/ipkIS0Tm4mBvj9iOHHYzzB49JHP.jpg', 'https://image.tmdb.org/t/p/original/atwY0qa1ZK5ZmDR7E943xiYG9a4.jpg', '', '2024-11-25', 6.3, 15.1423, 88, 'Benjamin Edelman', 15, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1138194, '헤레틱', 'Heretic', 'movie', 'https://image.tmdb.org/t/p/w500/z2ALWuQ2WwjzuJJiAfNsF8A7T2b.jpg', 'https://image.tmdb.org/t/p/original/ag66gJCiZ06q1GSJuQlhGLi3Udx.jpg', '외딴 집을 찾은 신앙심 깊은 두 소녀에게 집주인은 믿음을 뒤흔드는 이야기를 꺼낸다. 무언가 의심스럽다고 느끼는 순간, 두 소녀는 꼼짝없이 집안에 갇히게 된다. 친절했던 남자는 돌변하고, 그녀들은 살기 위해 위험한 선택을 하는데…', '2025-04-02', 6.975, 15.0388, 111, '스콧 벡', 2403, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (11036, '노트북', 'The Notebook', 'movie', 'https://image.tmdb.org/t/p/w500/ntdgcdsmMuHd9s4oEKTvWDiUyU7.jpg', 'https://image.tmdb.org/t/p/original/zdXnJqBaGFVtLoPNuMeKfEYUViZ.jpg', '17살, 노아는 밝고 순수한 앨리를 보고 첫눈에 반한다. 빠른 속도로 서로에게 빠져드는 둘. 그러나 이들 앞에 놓인 장벽에 막혀 이별하게 된다. 24살, 앨리는 우연히 신문에서 노아의 소식을 접하고 잊을 수 없는 첫사랑 앞에서 다시 한 번 선택의 기로에 서게 되는데…', '2004-11-26', 7.89, 15.4819, 123, '닉 카사베츠', 12277, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (209112, '배트맨 대 슈퍼맨: 저스티스의 시작', 'Batman v Superman: Dawn of Justice', 'movie', 'https://image.tmdb.org/t/p/w500/nfdgwCossZkIEEaQ4iR80mX2iR3.jpg', 'https://image.tmdb.org/t/p/original/5fX1oSGuYdKgwWmUTAN5MNSQGzr.jpg', '슈퍼맨과 조드 장군의 격렬한 전투 이후 메트로폴리스는 파괴되었고 슈퍼맨은 세계 최고 논쟁의 인물이 되어 버린다. 검증되지 않은 신과 같은 능력을 지닌 슈퍼맨의 등장에 사람들은 두려움에 빠지게 된다. 한편 배트맨은 그 동안 타락했던 많은 자들처럼 슈퍼맨 역시 언젠가 타락을 할 것이라 생각하며 사회에서 가장 위험한 존재로 여긴다. 세계의 미래를 위해 무모하고 제어할 수 없는 힘을 가진 슈퍼맨으로 인해 벌어졌던 일들을 바로 잡으려 한다. 배트맨과 슈퍼맨이 격돌하는 사이 인류를 위협할 새로운 위기가 빠르게 부상하기 시작하는데...', '2016-03-24', 6, 15.1338, 151, '잭 스나이더', 18700, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (425, '아이스 에이지', 'Ice Age', 'movie', 'https://image.tmdb.org/t/p/w500/biwqSbuyxjrZMvVcb8Lsv3GyQbw.jpg', 'https://image.tmdb.org/t/p/original/8pwIhymsxfAVjrAE7syDjQULn37.jpg', '거대한 빙하가 온 지구의 표면을 뒤덮기 시작하던 때, 모든 동물들은 따뜻한 남쪽나라로 이동을 시작하지만, 염세적인 털북숭이 맘모스 만프레드만은 유별나게 북쪽으로 향한다. 만프레드는 우연히 떠버리 나무늘보 시드를 만나고, 인간의 아이 로샨을 발견한 뒤 가족을 찾아주기로 한다. 이들은 여행길에 검치 호랑이 디에고와 동행하게 되지만, 디에고는 비밀스런 임무를 맡고 있는 처지다. 바로 호랑이 무리의 두목으로부터 끼니를 때울 만한 인간의 아이를 납치해오라는 명령을 받은 것이다. 과연 로샨은 무사히 가족의 품으로 돌아갈 수 있을까?', '2002-08-09', 7.366, 16.0542, 81, 'Chris Wedge', 14015, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (285, '캐리비안의 해적: 세상의 끝에서', 'Pirates of the Caribbean: At World''s End', 'movie', 'https://image.tmdb.org/t/p/w500/bTotG6tZERQqfKr2TDjwdjW8It4.jpg', 'https://image.tmdb.org/t/p/original/1jHxkVXMI5s3vRiyiZooUy1shB5.jpg', '윌 터너와 엘리자베스 스완, 바르보사 선장은 바다괴물 크라켄에 잡아먹힌 잭 스패로우를 구하는 데 도움을 얻기 위해 싱가포르의 해적 사오펭을 찾아간다. 이들은 잭 스패로우가 있어야만 해적연맹의 아홉 영주를 모아 연합함대를 구성할 수 있고, 해적 소탕에 쌍심지를 켠 동인도회사에 맞설 수 있다. 동인도회사의 커틀러 베켓 경은 유령선 플라잉 더치맨과 그 선장 데비 존스를 수하에 거느리게 된 터. 이 힘이 막강해서, 해적 연합함대는 다시 바다의 여신 칼립소에게 도움을 요청하기로 한다.', '2007-05-23', 7.267, 15.1149, 169, '고어 버빈스키', 15157, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (769, '좋은 친구들', 'GoodFellas', 'movie', 'https://image.tmdb.org/t/p/w500/zF9hSBS1t7PVFLo01GrJ3OjGi67.jpg', 'https://image.tmdb.org/t/p/original/gILte6Zd7m1YneIr6MVhh30S9pr.jpg', '아일랜드계 이탈리아인 헨리 힐와 토미는 13살에 마피아에 입문해 지미와 함께 트럭이나 공항 화물을 훔치는 일을 한다. 결혼 후에도 마피아 생활을 계속하는 헨리는 이제 조직에서도 안정된 위치와 경제적 여유를 갖는다.  어느 날 헨리와 지미는 공항터미널 사건을 모의해 현금 6백만 달러라는 엄청한 돈을 훔친다. 이 사건을 은폐하기 위해 혈안이 된 지미는 모의에 참여했던 사람들을 죽이고, 토미는 마피아 조직에 가담했다가 살해당한다. 엎친데 덮친격으로 헨리마저 마약거래로 경찰서에 잡혀 들어가는데...', '1991-02-14', 8.452, 16.792, 146, '마틴 스콜세지', 13940, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (10681, '월•E', 'WALL·E', 'movie', 'https://image.tmdb.org/t/p/w500/skTzymk67FfQSfGvwp4JSAqje4Z.jpg', 'https://image.tmdb.org/t/p/original/fK5ssgvtI43z19FoWigdlqgpLRE.jpg', '텅 빈 지구에 홀로 남아 수백 년이란 시간을 외롭게 일만 하며 보내던 월-E (WALL-E: Waste Allocation Load Lifter Earth-Class, 지구 폐기물 수거-처리용 로봇). 그런 그가 매력적인 탐사 로봇 ‘이브’와 마주친 순간, 잡동사니 수집만이 낙이던 인생에도 소중한 목표가 생긴다. 이브는 지구의 미래를 결정할 열쇠가 우연히 월-E의 손에 들어간 사실을 알게 되고, 고향별로 돌아갈 날만 애타게 기다리는 인간들에게 이를 보고하기 위해 서둘러 우주로 향한다. 한편 월-E는 이브를 뒤쫓아 은하를 가로지르며, 스크린 사상 가장 짜릿한 상상이 넘치는 어드벤처를 선사한다. 이제껏 꿈에서도 볼 수 없었던 미래 세계를 배경으로 우주에서 펼쳐지는 월-E의 환상적인 모험! 애완용 바퀴벌레, 용맹스럽지만 어딘가 나사가 빠진 듯한 사회 부적응 로봇 군단 등 일련의 유쾌한 캐릭터들이 여기에 동참한다.', '2008-08-06', 8.107, 16.4867, 98, '앤드류 스탠튼', 19841, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1167307, 'David', 'David', 'movie', 'https://image.tmdb.org/t/p/w500/7lFG1WrCwAxBfyGK8ahlBVzXno7.jpg', 'https://image.tmdb.org/t/p/original/d10VuEOMroY7ngQi2FUhJH72k0e.jpg', '', '2025-12-14', 7.7, 14.3966, 109, 'Phil Cunningham', 20, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (949, '히트', 'Heat', 'movie', 'https://image.tmdb.org/t/p/w500/p0uAcyDgBXtCSXZdnacwr9OGcIH.jpg', 'https://image.tmdb.org/t/p/original/uI22JkEMediWyiRqhllNqeeGtW0.jpg', '닐 맥컬리(로버트 드 니로)는 빈틈없고 치밀하게 일을 처리하는 프로 범죄자지만 따뜻한 가정의 온기를 동경한다. 반면 LA 경찰국 강력계 수사반장인 빈센트 한나(알 파치노)는 두 번의 이혼 경력에 이어 세 번째 결혼마저 위기를 맞은 불안정한 사생활의 소유자지만, 일에 있어서는 굶주린 짐승처럼 집요하게 쫓아가 결국에는 해결을 보고 만다. 닐과 그의 동료들이 특급우편 발송 차량을 습격하는 대규모 도난 사건을 일으켜 증권 투자사 간부의 고액 채권을 강탈한다. 사건 발생 직후부터 빈센트는 예리한 추리력으로 한걸음씩 닐에게 접근해간다. 닐 역시 빈센트의 추격을 눈치채는데...', '1996-08-10', 7.926, 15.1946, 170, '마이클 만', 8028, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (244786, '위플래쉬', 'Whiplash', 'movie', 'https://image.tmdb.org/t/p/w500/sNoZ3DAjOtCtpGvaEubMELDNtaS.jpg', 'https://image.tmdb.org/t/p/original/1kuYEvLkX2nTkbfzN6X0w0xQFQU.jpg', '최고의 드러머가 되기 위해서라면 무엇이든 할 각오가 되어있는 음악대학 신입생 앤드류는 아무도 없는 지하실에서 혼자 드럼을 연습하던 중 우연한 기회로 누구든지 성공으로 이끄는 최고의 실력자이지만, 또한 동시에 최악의 폭군인 플렛처 교수에게 발탁되어 그의 밴드에 들어가게 된다. 설레는 마음으로 참가한 첫 연습에서, 그는 플렛처 교수의 진짜 얼굴을 마주치게 된다. 폭언과 학대 속에 좌절과 성취를 동시에 안겨주는 플렛처의 지독한 교육방식은 천재가 되길 갈망하는 앤드류의 집착을 끌어내며 그를 점점 광기로 몰아넣는데...', '2015-03-12', 8.375, 15.3116, 106, '데이미언 셔젤', 16234, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (99861, '어벤져스: 에이지 오브 울트론', 'Avengers: Age of Ultron', 'movie', 'https://image.tmdb.org/t/p/w500/y8pY5MIzpPAnF5vYUNm1tw1AzL3.jpg', 'https://image.tmdb.org/t/p/original/kIBK5SKwgqIIuRKhhWrJn3XkbPq.jpg', '토니 스타크는 뉴욕전쟁 때와 같은 사태가 벌어지지 않도록 한때 가동하려다 중단된 휴면 상태의 평화 유지 프로그램을 작동 시키려 한다. 배너 박사와 함께 지구를 지킬 최강의 인공지능 울트론을 탄생시키게 되지만, 울트론은 예상과 다르게 지배를 벗어나 폭주하기 시작하고 어벤져스는 지구의 운명이 걸린 거대한 시험대에 오르게 된다. 울트론이 자신을 복제해 위협을 가하자 이를 저지하기 위해 아이언맨, 캡틴 아메리카, 토르, 헐크, 블랙위도우, 호크아이 등으로 구성된 어벤져스와 새로 합류하게 되는 퀵 실버, 스칼렛 위치 남매와 불안한 동맹을 맺는다.', '2015-04-23', 7.3, 16.2681, 141, '조스 웨던', 24042, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1610413, '기묘한 이야기 5 메이킹: 마지막 모험', 'One Last Adventure: The Making of Stranger Things 5', 'movie', 'https://image.tmdb.org/t/p/w500/sUkdh0YmY7GLJg7LcM2SGUAqrlo.jpg', 'https://image.tmdb.org/t/p/original/edGuDPKY6qHBg9hYvmnvLjcFoy4.jpg', '더퍼 형제의 기획으로 한 세대를 대표하는 아이콘이 된 시리즈. 그 마지막 시즌이 완성되기까지 투입된 수년간의 노력과 제작 과정을 비하인드 스토리로 만나 본다.', '2026-01-12', 7.745, 13.2351, 123, 'Martina Radwan', 53, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (324544, '인 더 로스트 랜드', 'In the Lost Lands', 'movie', 'https://image.tmdb.org/t/p/w500/e6gZUW5IJrtKxmzSrL1oHFpMcjI.jpg', 'https://image.tmdb.org/t/p/original/jb7yM17VZvDqUJVS4JR77EOfgEM.jpg', '원하는 모든 걸 이루어 줄 수 있는 거대한 힘을 가졌으나 어떤 거절도 할 수 없는 운명을 지닌 마녀 앨리스는, 도시의 지배자 여왕에게 불가능한 요청을 받게 된다. 바로 인간 이상의 힘을 얻게 해달라는 것! 앨리스는 여왕의 요청을 들어주기 위해, 살아 돌아올 수 없는 로스트 랜드의 길을 아는 사냥꾼 보이스와 어둠의 힘을 찾아 짐승과 악마의 땅으로 나선다. 한편, 마녀의 존재를 부정하는 종교 집단은 앨리스를 처치하기 위해 그들을 추적하기 시작하는데…', '2025-11-19', 6.423, 13.5787, 101, '폴 W. S. 앤더슨', 697, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (966, '황야의 7인', 'The Magnificent Seven', 'movie', 'https://image.tmdb.org/t/p/w500/e5ToxOyJwuZD4VOfI0qEn5uIjeJ.jpg', 'https://image.tmdb.org/t/p/original/2aC3284N1p86o6S4Uyj9AaryYeR.jpg', '미국과 멕시코의 국경 지대에 있는 가난한 마을에 매년 칼베라(Calvera: 엘리 월라치 분)란 도적떼가 나타나 수확한 양식을 빼앗아 가자 마침내 마을 사람들은 도적떼와 싸우기로 결심하고 총잡이를 구하러 도시로 온다. 대가도 너무 싸고 싸움에 승산이 없다는 걸 알면서도 그들을 딱하게 여긴 크리스(Chris Adams: 율 브리너 분)라는 총잡이가 다섯 명의 일류 총잡이들을 설득한다. 드디어 여섯 명의 총잡이가 마을로 향해가고 있는데 젊은 청년 치코가 그들을 쫓아오며 자신도 끼워달라고 떼를 쓴다. 결국 그의 끈질김에 감탄하여 그들은 치코를 끼워주기로 한다.  마을에 도착한 7인의 총잡이들은 마을 사람들에게 총 쏘는 법을 훈련시키고 함정을 만들며 칼베라와 싸울 준비 태세를 갖춘다. 처음엔 총잡이들이 무서워 피하기만 하던 마을 사람들도 그들을 믿고 따르게 된다. 드디어 칼베라 일당이 후퇴를 한다. 그러나 칼베라가 완전히 도망간 게 아니고 끝까지 싸울 계획임을 알게 되자 마을 사람들은 지금이라도 항복하자는 패와 끝까지 싸우자는 패로 나뉜다.  결국 항복을 주장하던 마을 사람 하나가 칼베라를 마을에 몰래 끌어들여 7인의 총잡이들을 잡게 한다. 목숨만 구한 채 마을에서 쫓겨난 그들은 죽을 걸 알면서도 마을로 되돌아가 싸우기로 한다. 목숨을 걸고 싸우고 있는 그들의 모습에 마을 사람들도 두려움을 떨치고 합세하여 칼베라 일당을 모조리 죽인다. 그러나 7인의 총잡이 중 셋만이 살아남는다. 그 중 치코는 사랑하는 마을 처녀 옆에 남기로 하고 두 명만이 마을을 떠나 다시 황야로 향한다.', '1960-10-12', 7.508, 18.699, 127, '존 스터지스', 1920, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (615677, '오늘부터 히어로', 'We Can Be Heroes', 'movie', 'https://image.tmdb.org/t/p/w500/kEsaGfkZeoBbiEXlm6pMk4zEkI1.jpg', 'https://image.tmdb.org/t/p/original/y6FYAhaeFMj9Lsk8OdF2NeWQkbd.jpg', '지구의 슈퍼히어로들이 외계인에게 납치된다. 부모님도 구하고 이 세상도 구해야 하는 그 2세들. 하지만 이대로는 안 되겠어. 힘을 모아 함께 싸우는 법부터 배워야지.', '2020-12-25', 5.972, 14.5201, 96, '로버트 로드리게즈', 797, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (396535, '부산행', '부산행', 'movie', 'https://image.tmdb.org/t/p/w500/6XvEZVBFFjybvb1yQd1qfOC6F2S.jpg', 'https://image.tmdb.org/t/p/original/fVpFOcQyHJM2di9upgSIwWD5wac.jpg', '별거 중인 펀드 매니저 석우는 소원해진 딸 수안의 생일 소원을 들어주기 위해 아내가 있는 부산행 KTX에 오른다. 이내 열차는 좀비의 침투와 감염으로 아수라장으로 변하고, 전국적 재난 뉴스를 차내에서 접한 승객들의 생존가능성은 유일하게 초기 대응에 성공한 도시 부산까지 살아남은 채 도착할 수 있느냐에 달리게 된다. 열차에 몸을 실은 석우와 딸 수안, 상화와 성경 커플, 고등학생 영국, 진희, 그리고 노숙자와 중년의 비즈니스맨 용석은 감염된 사람들의 공격을 피해 열차 안에서 사투를 벌인다.', '2016-07-20', 7.748, 14.2848, 118, '연상호', 8128, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1102493, '이처럼 사소한 것들', 'Small Things Like These', 'movie', 'https://image.tmdb.org/t/p/w500/ug1ES4MZBo3bveE9T45B1bIjG5w.jpg', 'https://image.tmdb.org/t/p/original/rtpFIgy1YYw3kx7PCyNhi6xmEFb.jpg', '1985년 아일랜드의 소도시, 빌 펄롱은 석탄을 팔며 아내, 다섯 딸과 함께 소박하게 살아가고 있다. 크리스마스를 앞둔 어느 날, 빌 펄롱은 지역 수녀원에 석탄을 배달하러 가고 숨겨져 있던 어떤 진실을 마주하게 된다.', '2024-12-11', 6.65, 14.8631, 98, 'Tim Mielants', 469, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1196573, '쉬 라이즈 샷건', 'She Rides Shotgun', 'movie', 'https://image.tmdb.org/t/p/w500/nvqW8mOm818QDio3GKKmPLK8kXj.jpg', 'https://image.tmdb.org/t/p/original/ytCi1wg6YHpYcFRWCO2jpzN31Kf.jpg', '출소한 전과자 네이트는 자신이 보호해야 할 존재가 열한 살 딸 폴리라는 사실에 당혹감을 느낀다. 낯선 딸과 함께 갱단의 위협을 피해 도주를 시작한 그는, 거칠고 냉혹한 세상 속에서 생존을 위한 법칙들을 하나씩 가르쳐 나간다. 처음엔 서로를 잘 알지 못했던 두 사람은 도망이라는 극한 상황 속에서 조금씩 마음을 열게 되고, 진정한 가족의 의미를 찾아가기 시작하는데…', '2025-07-31', 7.021, 14.3309, 120, 'Nick Rowland', 216, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (546554, '나이브스 아웃', 'Knives Out', 'movie', 'https://image.tmdb.org/t/p/w500/7brBiaaH1sToGV1YBi5EIUnyjo0.jpg', 'https://image.tmdb.org/t/p/original/4HWAQu28e2yaWrtupFPGFkdNU7V.jpg', '미스터리 소설의 대가인 작가 할란이 자신의 85살 생일에 자신의 방에서 날카로운 단검으로 목이 그인 채 발견된다. 외딴 저택에 모인 할란의 간병인과 자식 내외, 그리고 3세들은 유산 상속을 놓고 대거 혼란에 빠진다. 파견된 형사들은 가족과의 면담을 할 수록 자살로 의견이 모이지만, 면담 중 멀찍이 떨어져 상황을 전망하는 푸른 눈의 사내는 형사들마저 압도하며 심문을 주도해나간다. 남자의 이름은 바로 브누아 블랑. 챔피언 사건을 해결해서 이름이 높아진 유명한 사립탐정이다.', '2019-12-04', 7.844, 15.2138, 131, '라이언 존슨', 13575, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (559, '스파이더맨 3', 'Spider-Man 3', 'movie', 'https://image.tmdb.org/t/p/w500/9atb6Nn8TRGxfwROJGuzOD24GNl.jpg', 'https://image.tmdb.org/t/p/original/w1oD1MzHjnBJc5snKupIQaSBLIh.jpg', '대중의 사랑을 듬뿍 받으며 진정한 영웅으로 거듭난 스파이더맨, 피터 파커는 어느 날, 외계에서 온 수수께끼의 유기체인 심비오트에 감염되고 스파이더맨은 오리지날 스파이더맨에서 블랙 슈트 스파이더맨으로 변화한다. 한층 업그레이드 되고 강력해진 파워를 얻게 된 스파이더맨은 자신의 힘에 도취되어 마음껏 세상을 즐긴다. 그러나 아버지의 복수를 위해 뉴 고블린이 된 해리와 물리 실험에 노출되어 능력을 얻게 된 피터의 삼촌을 죽인 진범 샌드맨은 호시탐탐 스파이더맨을 노리는데...', '2007-05-01', 6.448, 15.7011, 139, '샘 레이미', 14901, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (237439, '스펙: 제로', 'SPEC〜零〜', 'movie', 'https://image.tmdb.org/t/p/w500/jHSBVaU2K0tPLYtTMg07nGTHGOW.jpg', 'https://image.tmdb.org/t/p/original/7WL9YUEnzk7AbXyN0S4IJdl7Vgo.jpg', '일본 드라마 스펙2의 확장된 버전의 단편 드라마. 스펙 드라마 전체를 이해하는 데 도움을 주는 길라잡이 단편작.', '2013-10-23', 7.905, 48.3431, 138, '堤幸彦', 21, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (762509, '무파사: 라이온 킹', 'Mufasa: The Lion King', 'movie', 'https://image.tmdb.org/t/p/w500/1VUExee8iFohFTwYVi4IOArYyaM.jpg', 'https://image.tmdb.org/t/p/original/1w8kutrRucTd3wlYyu5QlUDMiG1.jpg', '길을 잃고 혼자가 된 새끼 사자 무파사는 광활한 야생을 떠돌던 중 왕의 혈통이자 예정된 후계자 타카와 우연히 만나게 된다. 마치 친형제처럼 끈끈한 우애를 나누며 함께 자란 무파사와 타카는 운명을 개척하기 위해 거대한 여정을 함께 떠난다. 한 치 앞을 알 수 없는 적들의 위협 속에서 두 형제의 끈끈했던 유대에 금이 가기 시작하고 예상치 못한 위기까지 맞닥뜨리게 되는데…', '2024-12-18', 7.321, 14.5988, 118, '배리 젠킨스', 2506, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1495, '킹덤 오브 헤븐', 'Kingdom of Heaven', 'movie', 'https://image.tmdb.org/t/p/w500/sxuzh94v3POpVzaE3FTm0fbCO6i.jpg', 'https://image.tmdb.org/t/p/original/kP8rK9dGS1pr0HrnmXfIi2heWjo.jpg', '전쟁으로 가족을 잃고 깊은 슬픔에 잠겨있는 프랑스의 젊은 대장장이 발리안에게 부상당한 십자군 기사 고프리가 찾아온다. 무언가 비밀을 품고 있는 듯한 그의 정체는 바로 발리안의 아버지. 발리안에게 숨겨진 전사의 자질을 꿰뚫어본 고프리는 자신과 함께 떠날 것을 제안하고, 발리안은 성스러운 도시를 지키기 위한 영예로운 여정을 시작한다. 발리안은 고프리로부터 여러 가지 검술과 전술 등을 배우며 용맹한 전사로 거듭난다. 그리고 고프리가 죽기 직전 수여한 작위를 받아 정식기사가 되어 성스러운 도시 예루살렘의 국왕 볼드윈 4세에 대한 충성을 서약하는데...', '2005-05-05', 7.013, 14.5591, 137, '리들리 스콧', 4752, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1155281, '봉신연의 II: 서기전란', '封神第二部：战火西岐', 'movie', 'https://image.tmdb.org/t/p/w500/5bBgvH3hTxlANUsLP1ov0lEKmJp.jpg', 'https://image.tmdb.org/t/p/original/yujcZMkNKtNXPvRGyTA3e3VCrbx.jpg', '주왕조와 은나라의 패권 다툼이 본격화되는 가운데, 주나라의 근거지인 서기(西岐)는 거센 전쟁의 불길에 휩싸인다.  무너져가는 질서 속에서 인간과 신, 요괴가 얽힌 복잡한 음모가 펼쳐지고, 봉신대전은 더욱 격렬해진다.  강력한 마력을 지닌 이들 ‘마족(魔族)’의 군세가 서기를 위협하며, 전설의 영웅들은 각자의 운명을 걸고 싸움에 뛰어든다.  신과 인간, 왕권과 정의가 충돌하는 전장 한복판에서, 젊은 영웅들은 진정한 ‘봉신(封神)’의 의미를 깨닫게 된다.  서기의 운명과 봉신의 미래를 결정지을, 피할 수 없는 신들의 전쟁이 시작된다.', '2025-01-29', 6.343, 12.5049, 145, '乌尔善', 127, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (410119, '육보단', '足本玉蒲團', 'movie', 'https://image.tmdb.org/t/p/w500/3NwBn6zPY6yXCqfxEHmEgGh8Jgc.jpg', 'https://image.tmdb.org/t/p/original/lhHxiwtHq1GG5MhPyWaETvKjoGg.jpg', '청년시절 여인을 탐하는 꿈을 자주 꾸던 이운생은 소향과 결혼한 후, 과거보러 떠난 길에 명주실 짜는 옥분을 알게 되어 사랑에 빠진다. 옥분의 남편 관녹지는 위자료를 받아낸 뒤, 운생의 집에 머슴으로 들어가 소향과 밀애후 도피행각을 하기에 이른다. 복수가 목적이었던 곽녹지는 소향을 홍루에 팔아버린 후, 절에 들어간다. 한편, 집에 돌아와 장인으로부터 아내가 상사병에 걸려 죽었다는 말을 듣고 다시 길을 떠나다 홍루에서 기생이 된 아내를 만나게 된 운생은 모든 사실을 알게된다. 소향이 고심 씉에 목을 매어 자살하자, 이운생은 삭발 후 절에 들어가 판녹지와 함께 큰스님을 모신다.', '1987-10-15', 5.2, 15.1717, 90, 'Ho Fan', 27, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1166133, '브라마유감', 'ഭ്രമയുഗം', 'movie', 'https://image.tmdb.org/t/p/w500/x4geWE7mQwGyzNGLw1MKoDf8Fs7.jpg', 'https://image.tmdb.org/t/p/original/3Y5pOfxMrG8SqbIcGhYy497eOXc.jpg', '"광기의 시대" 17세기 케랄라의 한 민속 가수가 한 저택을 발견한다. 그 안에서 그는 수수께끼 같은 요리사와 강력한 주인을 만나게 되며, 이는 그의 삶을 바꾸는 일련의 사건들을 촉발시킨다.', '2024-02-15', 7.632, 15.5573, 139, 'Rahul Sadasivan', 76, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (945961, '에이리언: 로물루스', 'Alien: Romulus', 'movie', 'https://image.tmdb.org/t/p/w500/AmWTYg3RCMv7fbQxwCqrxiaUhkc.jpg', 'https://image.tmdb.org/t/p/original/9SSEUrSqhljBMzRe4aBTh17rUaC.jpg', '2142년, 부모 세대가 맞닥뜨렸던 암울한 미래를 피하려는 청년들이 더 나은 삶을 찾기 위해 식민지를 떠날 계획을 세운다. 하지만 버려진 우주 기지 로물루스에 도착한 이들은 악몽과도 같은 에이리언의 무자비한 공격에 쫓기기 시작한다. 그 누구도 그들의 절규를 들을 수 없는 우주 한가운데, 생존을 위한 치열한 사투를 벌여야 하는데...', '2024-08-14', 7.2, 15.0114, 119, '페데 알바레즈', 4232, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (283995, '가디언즈 오브 갤럭시 Vol. 2', 'Guardians of the Galaxy Vol. 2', 'movie', 'https://image.tmdb.org/t/p/w500/uDuwGhQgffd5GQ695oUfy5oZGqP.jpg', 'https://image.tmdb.org/t/p/original/aJn9XeesqsrSLKcHfHP4u5985hn.jpg', '타노스에 맞서 은하계를 구하고 최고의 해결사로 등극한 스타로드 일행. 하지만 소버린 행성의 여사제 아이샤를 돕던 중 옛버릇을 고치지 못하고 행성의 배터리를 훔쳤다가 소버린 종족에 쫓기는 신세가 된다. 그 과정에서 피터의 아버지 에고가 그들을 돕는다. 아픈 엄마와 어린 자신을 버리고 떠난 아버지에 대한 원망이 컸던 피터는 에고의 행성에서 아버지의 능력을 확인하곤 그 힘에 이끌린다. 하지만 가모라는 에고의 행성에서 이상한 기운을 감지한다. 한편 반란군에 의해 위기에 처한 욘두는 로켓과 그루트의 도움으로 목숨을 구한다.', '2017-05-02', 7.611, 14.6496, 136, '제임스 건', 22560, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (4935, '하울의 움직이는 성', 'ハウルの動く城', 'movie', 'https://image.tmdb.org/t/p/w500/3sVFlmzBCZpwlsosKHxyK4d9oDw.jpg', 'https://image.tmdb.org/t/p/original/pjy0T63vIFYvxRSJ3ZtjB4tmWV4.jpg', '19세기 말 마법과 과학이 공존하고 있는 세계 앵거리. 소피는 돌아가신 아버지의 모자상점에서 쉴틈없이 일하는 18살 소녀이다. 어느 날 오랫만에 마을로 나간 소피는 우연히 하울을 만나게 된다. 하울은 왕실 마법사로서 핸섬하지만 조금 겁이 많은 청년이다. 황무지 마녀는 두 사람의 사이를 오해, 주문을 걸어 소피를 90살의 늙은 할머니로 만들어 버린다. 가족을 걱정한 소피는 집을 나오게 되고 황무지를 헤매다가 하울이 사는 성에서 가정부로 낯선 생활을 시작한다. 4개의 다리로 걷는 기괴한 움직이는 성 안에서 하울과 소피의 기묘한 사랑과 모험이 시작되는데...', '2004-12-24', 8.388, 15.9172, 119, '미야자키 하야오', 10766, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (603692, '존 윅 4', 'John Wick: Chapter 4', 'movie', 'https://image.tmdb.org/t/p/w500/h3LsdSBzhRnBebz4BTpAhh63PD3.jpg', 'https://image.tmdb.org/t/p/original/7I6VUdPj6tQECNHdviJkUHD2u89.jpg', '죽을 위기에서 살아난 존 윅은 최고 회의를 쓰러트릴 방법을 찾아낸다. 비로소 완전한 자유의 희망을 보지만, 빌런 그라몽 후작과 전 세계의 최강 연합은 존 윅의 오랜 친구까지 적으로 만들어 버리고, 새로운 위기에 놓인 존 윅은 최후의 반격을 준비하는데...', '2023-04-12', 7.712, 15.6734, 170, '채드 스타헬스키', 7623, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (37165, '트루먼 쇼', 'The Truman Show', 'movie', 'https://image.tmdb.org/t/p/w500/AsUv4pFf1UQuOLKf7nYUXgmgCNf.jpg', 'https://image.tmdb.org/t/p/original/aCHn2TXYJfzPXQKA6r9mKPbMlUB.jpg', '트루먼 버뱅크는 작고 조용한 섬마을에 사는 평범한 세일즈맨이다. 그런 그가 자신의 삶에 대해 의문을 갖기 시작한 것은 평소와 다름없이 평범한 어느 날, 갑자기 하늘에서 촬영용 조명등이 떨어지고, 어렸을 적 자신이 익사를 직접 목격했던 아버지가 살아오고, 또 누군가에 의해 끌려가는 등 상식 밖의 일들이 벌어지고 나서부터였다. 평생을 그다지 신경쓰지 않고 지냈던 일상이었지만 주변을 보니 이상한 일이 너무 많았다. 결국 자신이 특별한 상황에 놓여있다는 확신을 하게된 트루먼은 첫사랑 실비아의 모든 것이 다 거짓라는 말을 되새기며 일상으로부터 탈출을 결심하게 되는데...', '1998-10-24', 8.15, 13.651, 103, '피터 위어', 19701, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (68718, '장고: 분노의 추적자', 'Django Unchained', 'movie', 'https://image.tmdb.org/t/p/w500/AoH4YLDdxAHraeT336sc9nOIaX0.jpg', 'https://image.tmdb.org/t/p/original/5Lbm0gpFDRAPIV1Cth6ln9iL1ou.jpg', '흑인 노예 장고는 착한 사마리아인 같은 독일인 현금사냥꾼 닥터 킹의 도움을 받아 멋진 말을 타고 미국 평원을 달리며 헤어진 아내 브룸힐다를 찾아다니는 총잡이 낭만주의자로 변신한다. 그는 브룸힐다가 미시시피에서 가장 악독한 농장 캔디랜드의 노예로 일하고 있다는 소식을 듣고 농장주 캔디를 찾아간다. 아내를 구해야 하는 분노의 로맨티스트 장고, 그를 돕는 정의의 바운티 헌터 닥터 킹, 그리고 그들의 표적이 된 욕망의 마스터 캔디. 복수의 사슬이 풀리면, 세 남자의 피도 눈물도 없는 대결이 시작된다.', '2013-03-21', 8.186, 15.005, 165, '쿠엔틴 타란티노', 27469, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (758009, '샷건 웨딩', 'Shotgun Wedding', 'movie', 'https://image.tmdb.org/t/p/w500/aGhII6CTTvpZwnElzAUB7ZbgjTN.jpg', 'https://image.tmdb.org/t/p/original/zGoZB4CboMzY1z4G3nU6BWnMDB2.jpg', '‘다아시’(제니퍼 로페즈)와 ‘톰’(조쉬 더하멜)의 결혼식 당일, 우여곡절 끝에 결혼식에 참석할 모두가 섬에 모인다. 모든 게 순조로워 보이던 그때!  갑자기 들이닥친 해적으로 인해 결혼식장의 모두가 인질이 되고… ‘다아시’와 ‘톰’은 무사히 혼인서약을 마치기 위해 목숨을 건 버진 로드를 걷게 되는데…  죽이든가, 죽든가! 2023년 3월, 가장 화X한 웨딩이 온다!', '2023-03-29', 6.251, 8.8873, 101, 'Jason Moore', 1272, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1280450, '스톨른 걸', 'Stolen Girl', 'movie', 'https://image.tmdb.org/t/p/w500/fZlNXEHZsBp7unqw009MeBbMv87.jpg', 'https://image.tmdb.org/t/p/original/qcDDn7WeKBenM4nLlOPXAeJ4hpg.jpg', '1993년 오하이오, 이혼한 싱글맘 마라(케이트 베킨세일 분)의 삶은 네 살배기 딸 아미나(Amina)가 전 남편에게 납치되면서 산산조각 난다. 전 남편은 아미나를 데리고 중동으로 도주하고, 경찰의 도움은 기대할 수 없는 상황. 절망에 빠진 마라는 딸을 찾기 위해 모든 것을 바치기로 결심한다. 10년이 넘는 기나긴 시간 동안 홀로 고군분투하던 그녀는 결국 국제 아동 납치 전문가인 전직 해병대원 로브슨(스콧 이스트우드 분)과 손을 잡게 된다. 두 사람은 레바논 베이루트로 향하고, 그곳에서 국제 첩보전, 배신, 부패가 얽힌 위험한 음모에 휘말리게 된다. 시간이 촉박한 상황에서 마라는 딸을 구하기 위해 목숨을 건 위험한 작전을 감행하며, 인생에서 가장 어려운 선택의 순간에 직면한다. 실화를 바탕으로 한, 딸을 향한 어머니의 포기하지 않는 사랑과 치열한 추적극!', '2025-09-04', 6.196, 13.9848, 110, 'James Kent', 125, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1156593, '네 잘못이야', 'Culpa tuya', 'movie', 'https://image.tmdb.org/t/p/w500/zuctS3p8Bs9IeYv5ScKeOKp5Na5.jpg', 'https://image.tmdb.org/t/p/original/k24eZq5I3jyz4htPkZCRpnUmBzE.jpg', '전 세계적인 히트작 ''나의 잘못''의 속편. 노아와 닉의 사랑은 둘을 떼어놓으려는 부모님의 노력에도 불구하고 흔들림이 없어 보인다. 하지만 닉의 직업과 노아의 대학 진학은 두 사람의 관계와 레이스테르 가족의 근간을 흔들 새로운 관계로 그들의 삶을 안내한다. 많은 사람이 두 사람 사이를 파괴하려는 가운데 이 둘은 결국 행복을 맞이할 수 있을까?', '2024-12-27', 7.119, 13.8662, 118, '도밍고 곤살레스', 1493, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1025527, 'Six jours', 'Six jours', 'movie', 'https://image.tmdb.org/t/p/w500/foyiQu23zq4WhmffnQkFiNAvqcJ.jpg', 'https://image.tmdb.org/t/p/original/tLf5hjuO4gx62lVojPiHsIzCroh.jpg', '', '2024-12-11', 5.918, 15.0315, 95, 'Juan Carlos Medina', 91, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1409235, '위로가 필요한 날', 'Las Ilusyunadas', 'movie', 'https://image.tmdb.org/t/p/w500/bi48c9bBtzqVPohUd47viv3xQRc.jpg', 'https://image.tmdb.org/t/p/original/wFbBkNnwdvvF8RhGgaNKzA5CazQ.jpg', '유혹은 뜻밖의 장소에서 찾아온다! 내전으로 각각 남편을 잃은 엠마와 산드라. 사랑하던 남편을 잃고 하루아침에 젊은 미망인이 된 이들은 슬픔에 매일 같이 남편이 묻힌 묘지를 찾는다. 그러다 묘지에서 자주 마주치게 된 두 여인. 이내 같은 아픔을 가졌다는 것을 알게 되고 이들은 가까워 지는데... 하지만 이내 우정을 넘어선 끌림을 느끼고, 엠마와 산드라는 각각 혼란에 빠지지만 서로를 원하는 마음은 더욱 깊어만 간다.', '2025-04-25', 5.4, 14.1053, 90, 'Roman Perez Jr.', 7, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (424, '쉰들러 리스트', 'Schindler''s List', 'movie', 'https://image.tmdb.org/t/p/w500/oyyUcGwLX7LTFS1pQbLrQpyzIyt.jpg', 'https://image.tmdb.org/t/p/original/zb6fM1CX41D9rF9hdgclu0peUmy.jpg', '2차 세계대전 당시 독일군이 점령한 폴란드. 시류에 맞춰 자신의 성공을 추구하는 기회주의자 쉰들러는 유태인이 경영하는 그릇 공장을 인수한다. 그는 공장을 인수하기 위해 나찌 당원이 되고 독일군에게 뇌물을 바치는 등 갖은 방법을 동원한다. 그러나 냉혹한 기회주의자였던 쉰들러는 유태인 회계사인 스턴과 친분을 맺으면서 냉혹한 유태인 학살에 대한 양심의 소리를 듣기 시작한다. 마침내 그는 강제 수용소로 끌려가 죽음을 맞게될 유태인들을 구해내기로 결심하고, 독일군 장교에게 빼내는 사람 숫자대로 뇌물을 주는 방법으로 유태인들을 구해내려는 계획을 세우는데...', '1994-03-05', 8.565, 15.2894, 195, '스티븐 스필버그', 17024, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (573435, '나쁜 녀석들: 라이드 오어 다이', 'Bad Boys: Ride or Die', 'movie', 'https://image.tmdb.org/t/p/w500/wIrhEUBWjRmZuL1Ix41cF2LhJrW.jpg', 'https://image.tmdb.org/t/p/original/3q01ACG0MWm0DekhvkPFCXyPZSu.jpg', '마이애미 강력반 최고의 콤비 마이크와 마커스. 가족 같은 하워드 반장이 사망 전 마약 카르텔 조직의 비리에 연루되었다는 뉴스 속보를 접하게 된다. 하지만 아무도 믿지 말라는 하워드 반장의 비밀 메시지를 받은 마이크와 마커스 형사는 사건의 진실을 밝히기 위해 위험한 수사를 시작한다. 서서히 드러나는 거대한 음모와 마주하게 된 나쁜 녀석들. 그러나 이들 역시 함정에 빠져 사건의 용의자로 지목되며 동료 경찰들은 물론 마약 카르텔 조직에게도 쫓기는 신세가 되고 마는데…', '2024-06-06', 7.342, 14.6937, 115, '아딜 엘 아르비', 3187, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1385536, 'Sore: Istri Dari Masa Depan', 'Sore: Istri Dari Masa Depan', 'movie', 'https://image.tmdb.org/t/p/w500/u4pNXPmBuYeTtksakUCZgJ1zpSB.jpg', 'https://image.tmdb.org/t/p/original/sTNzZZdIm7csFdgnvP20XmSJRTx.jpg', '', '2025-07-10', 7.661, 15.4465, 119, 'Yandy Laurens', 31, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (466272, '원스 어폰 어 타임 인… 할리우드', 'Once Upon a Time... in Hollywood', 'movie', 'https://image.tmdb.org/t/p/w500/1F2rDT1oNdvMyXF7gxbGxaXCzrz.jpg', 'https://image.tmdb.org/t/p/original/aQLygZOIKai6aaiBAeeKpIWO5nc.jpg', '자유의 바람이 불던 1969년 할리우드, 잊혀져 가는 액션스타 릭 달튼과 그의 스턴트 배우 겸 매니저인 클리프 부스는 과거의 영광을 되찾기 위해 고군분투하지만 새로운 스타들에 밀려 큰 성과를 거두진 못한다. 어느 날 릭의 옆집에 할리우드에서 가장 핫한 로만 폴란스키 감독과 배우 샤론 테이트 부부가 이사 오자 릭은 새로운 기회가 생길 수도 있다고 기뻐하지만 인사조차 나누지 못한다. 형편상 더 이상 함께 일할 수 없게 된 릭과 클리프는 각자의 길을 가기로 하고 릭의 집에서 술을 거나하게 마시던 중 뜻하지 않은 낯선 방문객을 맞이하게 되는데…', '2019-09-25', 7.425, 13.66, 162, '쿠엔틴 타란티노', 14464, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (558449, '글래디에이터 II', 'Gladiator II', 'movie', 'https://image.tmdb.org/t/p/w500/b5UXjzW5cLZhprMnlAmsVAA3G4t.jpg', 'https://image.tmdb.org/t/p/original/bHeUgZKqduubnNl8GshjrpHS9lF.jpg', '로마의 영웅이자 최고의 검투사였던 막시무스가 콜로세움에서 죽음을 맞이한 뒤 20여 년이 흐른 후. 쌍둥이 황제 게타와 카라칼라의 폭압 아래 시민을 위한 자유로운 나라 로마의 꿈은 잊힌 지 오래다. 한편 아카시우스 장군이 이끄는 로마군에 대패한 후 모든 것을 잃고 노예로 전락한 루시우스는 강한 권력욕을 지닌 마크리누스의 눈에 띄어 검투사로 발탁된다. 로마를 향한 걷잡을 수 없는 분노, 타고난 투사의 기질로 콜로세움에 입성하게 된 루시우스는 결투를 거듭하며 자신이 진짜 누구인지 알게 되고 마침내 로마의 운명을 건 결전을 준비하게 되는데...!', '2024-11-13', 6.639, 15.5687, 148, '리들리 스콧', 4137, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (12153, '화이트 칙스', 'White Chicks', 'movie', 'https://image.tmdb.org/t/p/w500/4caC5bNljJiakF2r18Bb3j4URAe.jpg', 'https://image.tmdb.org/t/p/original/85k0kaoRgGmF6ACq0M61AFxhjLN.jpg', '위장술 하나는 끝내주지만 정작 사건 해결은 못해본 FBI 명물 콤비 마커스(말론 웨이언스)와 케빈(숀 웨이언스)은 순간의 착각으로 거물급 마약상을 놓치는 일대 실수를 저지르고 만다. FBI에서 퇴출 위기에 몰린 둘은 얼떨결에 자선파티 참석을 위해 LA에 오는 호텔재벌 윌슨가 자매의 모두가 꺼려하는 경호를 떠맡게 된다. 하지만 첫날부터 호틀갑 자매의 귀하신 얼굴에 상처를 내는 대형사고(?)를 치고 마는데…  FBI고 뭐고 발각되면 인생 끝장이다! 힙 올리고 가슴 더 키워!!!  길길이 날뛰는 자매 앞에 이들이 살아남는 방법은 딱 하나! ‘뽕 넣고 찍어 발라서라도’ 그녀들로 변신, 그녀들 대신 사교계를 휘어잡는 것! 이제 풍만한 가슴에 쭉빠진 바디라인의 금발미녀가 된 그들, 아니 그녀들은 알고보면 첩보전을 능가하는 칵테일 파티와 총격전보다 살벌한 패션쇼 등 재벌계의 엄청난 사생활에 말려들기 시작하는데…?!', '2004-11-17', 6.934, 15.19, 109, 'Keenen Ivory Wayans', 4372, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1011985, '쿵푸팬더 4', 'Kung Fu Panda 4', 'movie', 'https://image.tmdb.org/t/p/w500/fvtswV04JfLGxxrjxW4t4j8bPhx.jpg', 'https://image.tmdb.org/t/p/original/3ffPx9jqg0yj9y1KWeagT7D20CB.jpg', '마침내 내면의 평화… 냉면의 평화…가 찾아왔다고 믿는 용의 전사 ‘포’ 이젠 평화의 계곡의 영적 지도자가 되고, 자신을 대신할 후계자를 찾아야만 한다. “이제 용의 전사는 그만둬야 해요?” 용의 전사로의 모습이 익숙해지고 새로운 성장을 하기보다 지금 이대로가 좋은 ‘포’ 하지만 모든 쿵푸 마스터들의 능력을 그대로 복제하는 강력한 빌런 ‘카멜레온’이 나타나고 그녀를 막기 위해 정체를 알 수 없는 쿵푸 고수 ‘젠’과 함께 모험을 떠나게 되는데… 포는 가장 강력한 빌런과 자기 자신마저 뛰어넘고 진정한 변화를 할 수 있을까?', '2024-04-10', 7.012, 15.8231, 94, 'Mike Mitchell', 3348, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (66245, 'அருணாச்சலம்', 'அருணாச்சலம்', 'movie', 'https://image.tmdb.org/t/p/w500/vplqDhbUk5GMPUosMuQy91NePxv.jpg', 'https://image.tmdb.org/t/p/original/z2WjRzdsP5pChOjFADIXXfd5XpZ.jpg', '', '1997-04-10', 7.3, 12.593, 165, 'Sundar C', 28, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (9502, '쿵푸팬더', 'Kung Fu Panda', 'movie', 'https://image.tmdb.org/t/p/w500/c3Dzd3A3QE0LkKb5HMOHTzs2Fyg.jpg', 'https://image.tmdb.org/t/p/original/qdthf9WrRDSaIkGVQGhhJ9pz1hn.jpg', '평화의 계곡에서 아버지의 국수 가게를 돕고 있는 팬더 포. 아버지는 국수의 비법을 알려주어 가업을 잇게 하고 싶지만, 포의 관심사는 오로지 쿵푸 마스터. 가게 일은 뒷전으로 하고 쿵푸의 비법이 적힌 용문서의 전수자를 정하는 무적의 5인방 대결을 보러 시합장을 찾은 포. 그런데 마을의 현인 우그웨이 대사부가 포를 용문서의 전수자로 점지하는 이변이 일어난다. 무적의 5인방은 물론 시푸 사부 역시 이 사태를 받아들이지 못하는 가운데, 용문서를 노리고 어둠의 감옥에서 탈출한 타이 렁이 마을을 습격해오자 그를 막아야 하는 미션이 포에게 떨어지는데...', '2008-06-05', 7.312, 14.7401, 90, '마크 오스본', 12331, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (76341, '매드맥스: 분노의 도로', 'Mad Max: Fury Road', 'movie', 'https://image.tmdb.org/t/p/w500/cadVm6gKYYukmPysHGCwrawUHHa.jpg', 'https://image.tmdb.org/t/p/original/uT895WNwm0aIJRtGizcQhrejWUo.jpg', '핵전쟁으로 멸망한 22세기. 얼마 남지 않은 물과 기름을 차지한 독재자 임모탄 조가 살아남은 인류를 지배한다. 한편 아내와 딸을 잃고 살아남기 위해 사막을 떠돌던 맥스는 임모탄의 부하들에게 납치되어 노예로 끌려가고, 폭정에 반발한 외팔의 사령관 퓨리오사는 인류 생존의 열쇠를 쥔 임모탄의 여인들을 탈취해 분노의 도로로 폭주한다. 이에 임모탄의 전사인 워보이들과 신인류 눅스는 피주머니 신세로 전락한 맥스를 이끌고 퓨리오사의 뒤를 쫓는데...', '2015-05-14', 7.629, 15.3538, 120, '조지 밀러', 23686, 0);
