INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1273948, '아버지의 이름으로', '以父亲之名', 'movie', 'https://image.tmdb.org/t/p/w500/fV9TkOqFCZHPUG9OWx419dw0Iew.jpg', 'https://image.tmdb.org/t/p/original/nrWn0blVlcdsbSrYPgCyQpTE5hn.jpg', '동급생에 의해 살해된 딸의 시신을 수습하기 위해 슬픔에 잠긴 아버지는 미국으로 향한다. 폭력으로 아버지를 잃은 중국계 미국인 학생의 도움을 받아, 그는 경찰이 남긴 단서를 추적하며 딸의 살인자를 찾고 아버지로서 자신의 자리와 정의를 되찾으려 한다.', '2024-07-07', 0, 16.9085, 121, 'Daming Chen', 0, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (670, '올드보이', '올드보이', 'movie', 'https://image.tmdb.org/t/p/w500/xpa9ybm6tYGna5LseqSXvKpSSJn.jpg', 'https://image.tmdb.org/t/p/original/sdwjQEM869JFwMytTmvr6ggvaUl.jpg', '오대수는 어느 날 술이 거나하게 취해 집에 돌아가는 길에 누군가에게 납치, 사설 감금방에 갇히게 된다. 중국집 군만두만을 먹으며 8평이라는 제한된 공간에서 그가 할 수 있는 일이라곤 텔레비전 보는 게 전부. 1년이 지났을 무렵, 뉴스를 통해 나오는 아내의 살해소식. 게다가 아내의 살인범으로 자신이 지목되고 있음을 알게 된 오대수는 복수와 탈출을 위해 감금방 한쪽 구석을 쇠젓가락으로 파기 시작한다. 감금 15년을 맞이하는 해, 마침내 사람 몸 하나 빠져나갈 만큼의 탈출구가 생겼을 때, 어이없게도 15년 전 납치됐던 바로 그 장소로 풀려나 있는 자신을 발견하게 된다.', '2003-11-21', 8.243, 15.4737, 120, '박찬욱', 9501, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (10195, '토르: 천둥의 신', 'Thor', 'movie', 'https://image.tmdb.org/t/p/w500/7hThYJ0yBzclKviPxBt5UB94zNT.jpg', 'https://image.tmdb.org/t/p/original/cDJ61O1STtbWNBwefuqVrRe3d7l.jpg', '파괴를 일삼는 요툰하임을 제압한 왕 오딘의 통치로 평화로운 나날을 보내고 있는 신의 세계 아스가르드. 오딘의 아들인 토르의 왕위 계승식이 있던 날, 요툰하임의 지배자인 라우페이는 평화 협정을 위반하고 아스가르드를 침입한다. 이 사건으로 왕위에 오르지 못한 토르는 분노와 모욕감에 요툰하임을 공격하지만 막강한 군대에 포위되어 위기에 몰리게 되고, 오딘은 토르의 오만하고 경솔한 행동에 분노해 토르의 신으로서의 능력을 박탈한 채 인간 세계 미스가르드로 추방한다. 한편 천체의 이상현상을 연구하던 과학자 제인 일행은 거대한 섬광의 흔적을 쫓던 중, 그 현장 한가운데서 지구에 떨어진 토르와 맞닥뜨린다.', '2011-04-28', 6.768, 13.4052, 115, '케네스 브래너', 22011, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (11324, '셔터 아일랜드', 'Shutter Island', 'movie', 'https://image.tmdb.org/t/p/w500/5gEu0DqMtRj6IB98BGlb8FyyUtZ.jpg', 'https://image.tmdb.org/t/p/original/rbZvGN1A1QyZuoKzhCw8QPmf2q0.jpg', '보스턴 셔터아일랜드의 정신병원은 중범죄를 저지른 정신병자를 격리하는 병동으로 탈출 자체가 불가능하다. 하지만 자식 셋을 죽인 혐의를 받고 있는 여인이 이상한 쪽지만을 남긴 채 감쪽같이 사라지는 사건이 발생한다. 연방보안관 테디 다니엘스(레오나르도 디카프리오)는 수사를 위해 동료 척(마크 러팔로)과 함께 셔터아일랜드로 향한다. 테디는 수사를 위해 의사, 간호사, 병원관계자 등을 심문하지만 수사는 전혀 진척되지 않는다. 설상가상 폭풍이 불어 닥쳐 테디와 척은 섬에 고립되게 되고, 그들에게 점점 괴이한 일들이 일어나기 시작하는데...', '2010-03-18', 8.2, 14.625, 138, '마틴 스콜세지', 25290, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1114967, '굿 포츈', 'Good Fortune', 'movie', 'https://image.tmdb.org/t/p/w500/mlpVu3aq1cOjlHOxd70NILlj1fc.jpg', 'https://image.tmdb.org/t/p/original/nkxtuK4alXlGC87FRNDfAZJIFiB.jpg', '길 잃은 영혼의 수호천사가 되고 싶지만, 현실은 운전 중 문자하는 인간들을 보호하는 작은 날개의 초짜 천사 가브리엘. 열심히 살아도 차에서 노숙하는 삶을 못 벗어나며 절망에 빠진 N잡러 아지를 구원하기 위해 금수저인 벤처 투자자 제프와 삶을 바꿔준다. 하루아침에 극과 극으로 변한 아지와 제프의 삶은 가브리엘의 의도와 다르게 흘러가고, 이에 대한 책임으로 가브리엘은 날개를 반납하고 인간으로 강등당하는데… 인생이 뒤바뀐 아지와 제프, 인간이 된 가브리엘 이 세 남자의 유쾌한 좌충우돌 운명 재도전기가 펼쳐진다!', '2026-01-07', 7.011, 13.7956, 98, '아지즈 안사리', 419, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (387848, '친구엄마', '친구엄마', 'movie', 'https://image.tmdb.org/t/p/w500/5JDVEZN0v3e9xMzZbZ92fC7HaQi.jpg', 'https://image.tmdb.org/t/p/original/78frwN1N9PeHQB0iXxlxbnAFL1L.jpg', '이론만 강한 남자, 스무살 경수!  섹스를 인터넷 야동으로만 보고 배운 경수. 그는 이론에만 강할뿐 실전은 전무하다. 짝사랑만 했을 뿐 키스한번 못 해 봤다. 짝사랑하던 선배 지연에게 고백했다가 개쪽만 당하고 방구석에서 일본 언니들을 벗삼아 오른손 긴긴 밤을 보내던 어느 날. 홀아버지와 대판 싸운 경수는 방학이 되면 자신의 집에 놀러오라는 친구 백현의 얘기를 떠 올리고 무작정 강원도 삼척으로 향하는 버스에 오른다.  뱀파이어인가! 늙지않는 친구 엄마, 현옥!  20대 뺨을 후려치는 완벽한 바디 라인과 이승환과 친구 먹는 동안의 전복 아가씨 출신 현옥. 긴긴밤 외로이 바닷가를 바라보며 소주잔을 기울이던 그녀에게 무려 20살이나 어린 아들 친구가 작업을 걸어온다. 이 어린 놈의 새끼를 받아줘도 문제. 안 받아줘도 문제?  사랑일까? 엔조이일까?  하루 수십번도 가능한 경수. 집에서도 하고, 해변에서도 하고, 물에서도 하고, 하고 하고 또 해도 경수는 끊임없이 일어선다. 그런 경수가 싫지 않은 현옥. 자신을 시도때도 없이 덮치는 경수가 귀엽고 사랑스럽다. 하지만 경수의 짝사랑 지연이 삼척에 내려오자 지랄 맞은 날씨처럼 경수의 마음이 오락가락 하기 시작한다. 지연에게 한번. 현옥에게 한번. 경수는 현옥을 사랑하는 것일까? 아니면 그냥 엔조이일까?', '2015-11-12', 5.7, 12.6173, 101, 'Kong Ja-kwan', 14, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (333339, '레디 플레이어 원', 'Ready Player One', 'movie', 'https://image.tmdb.org/t/p/w500/j4TIfwFrm8WnckByTnMFEAuIVju.jpg', 'https://image.tmdb.org/t/p/original/5a7lMDn3nAj2ByO0X1fg6BhUphR.jpg', '2045년, 암울한 현실과 달리 가상현실 오아시스에서는 누구든 원하는 캐릭터로 상상하는 모든 걸 할 수 있다. 웨이드 와츠의 유일한 낙은 오아시스에 접속하는 것. 어느 날 오아시스의 창시자인 괴짜 천재 제임스 할리데이는 자신이 가상현실 속에 숨겨둔 3개의 미션에서 우승하는 사람에게 오아시스의 소유권과 막대한 유산을 상속한다는 유언을 남기고, 그가 사랑했던 80년대 대중문화 속에 힌트가 있음을 알린다. 와츠가 첫 번째 수수께끼를 푸는 데 성공하자 이를 저지하기 위해 현실에서 살인도 마다하지 않는 IOI라는 거대 기업이 뛰어드는데...', '2018-03-28', 7.585, 13.8745, 140, '스티븐 스필버그', 16525, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1357633, '나 혼자만 레벨업 -리어웨이크닝-', '俺だけレベルアップな件 -ReAwakening-', 'movie', 'https://image.tmdb.org/t/p/w500/vOONcAbFSVCOgct9k4JJPLbPvOi.jpg', 'https://image.tmdb.org/t/p/original/hlfu6g0h0D65SjkVhQBU20zePTl.jpg', '다른 차원과 이쪽 세계를 이어 주는 통로인 ''게이트가'' 갑자기 발생한 지 10여 년. 세계에는 ''헌터''라고 불리는 초인적인 힘에 각성한 사람들이 출현했다. 헌터는 그 힘을 사용해 게이트 안의 던전을 공략하고 대가를 받는 것을 생업으로 하고 있는데 강자들만 모인 헌터들 중 ''성진우''는 인류 최약병기라 불리는 저랭크 헌터로서 생활하고 있었다. 어느 날, 저랭크 던전에 숨겨진 고랭크 이중 던전에서 빈사의 중상을 입은 성진우의 눈앞에 수수께끼의 퀘스트창이 나타났다. 죽음의 순간, 퀘스트를 수락하기로 결심한 성진우는 자신만 ''레벨업''할 수 있게 되는데── 전직 퀘스트를 클리어하고 그림자 병사를 부릴 수 있는 ''그림자 군주''가 된 성진우의 앞에 다음 시련으로서 나타난 것은 상급 던전으로 이어지는 레드 게이트였다──', '2024-11-28', 7.1, 13.2196, 116, '中重俊祐', 252, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (66732, '기묘한 이야기', 'Stranger Things', 'drama', 'https://image.tmdb.org/t/p/w500/mpOQpOKdo2XJnTqRzo1lTmDNsc1.jpg', 'https://image.tmdb.org/t/p/original/8zbAoryWbtH0DKdev8abFAjdufy.jpg', '인디애나주의 작은 마을에서 행방불명된 소년. 이와 함께 미스터리한 힘을 가진 소녀가 나타나고, 마을에는 기묘한 현상들이 일어나기 시작한다. 아들을 찾으려는 엄마와 마을 사람들은 이제 정부의 일급비밀 실험의 실체와 무시무시한 기묘한 현상들에 맞서야 한다.', '2016-07-15', 8.581, 443.8127, NULL, '로스 더퍼', 20401, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (224372, '세븐킹덤의 기사', 'A Knight of the Seven Kingdoms', 'drama', 'https://image.tmdb.org/t/p/w500/6igvNs5VJB4ryBLgjjXksDVs0Fm.jpg', 'https://image.tmdb.org/t/p/original/7mkUu1F2hVUNgz24xO8HPx0D6mK.jpg', '왕좌의 게임이 일어나기 백여 년 전, 타르가르옌 가문이 철왕좌를 지키고, 최후의 드래곤에 대한 기억이 살아 있던 시절. 웨스테로스를 떠돌던 영웅이 있었다. 젊고 순진하지만 용맹한 기사 던칸 경과 그의 작은 종자 에그. 이 둘의 앞엔 운명과 강적, 그리고 모험이 기다리고 있는데.', '2026-01-18', 8.1, 320.1837, NULL, '조지 R. R. 마틴', 94, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (79744, '더 루키', 'The Rookie', 'drama', 'https://image.tmdb.org/t/p/w500/7LUiqnZFX9JXYZtRpzv8n7taKV.jpg', 'https://image.tmdb.org/t/p/original/6iNWfGVCEfASDdlNb05TP5nG0ll.jpg', '이혼 후 은행 강도를 당한 일을 계기로 LAPD에 지원한 40세의 최고령 신입을 중심으로 펼쳐지는 이야기', '2018-10-16', 8.533, 246.7796, NULL, '알렉시 홀리', 2908, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (2734, '로 앤 오더: 성범죄전담반', 'Law & Order: Special Victims Unit', 'drama', 'https://image.tmdb.org/t/p/w500/iofokHZoUB4Qhik4PflvJl8TT6a.jpg', 'https://image.tmdb.org/t/p/original/obtdxPgmfykYwVnvuYXC5f2xKlQ.jpg', '추악한 성범죄를 수사하는 뉴욕 경찰 성범죄전담수사반의 활약을 그린 드라마.', '1999-09-20', 7.936, 244.8255, NULL, '딕 울프', 4104, 0);
