INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (2661, '가면라이더', '仮面ライダー', 'drama', 'https://image.tmdb.org/t/p/w500/fIJNVBa6MJStPiOvhLV69nAdu0e.jpg', 'https://image.tmdb.org/t/p/original/usLRh1bcbL0Q9X8zf6rL4OV1qrA.jpg', '우수한 과학자로 오토바이 레이서이기도 한 혼고 타케시는, 그 능력에 주목한 악의 비밀 결사 쇼커에 납치되어 메뚜기의 능력을 가진 개조 인간(사이보그의 일종)이 되어 버렸다. 그러나, 뇌수술에 의해 그 의사를 빼앗기기 직전, 쇼커의 협력자로 되고 있었던 은사인 미도리카와 박사의 안내로 탈출에 성공했다. 미도리카와 박사는 탈출의 도중에 쇼커의 괴인·거미남자에게 암살되지만, 그 유지를 이어받은 다케시는 허리에 찬 벨트 풍차 발전기에 바람의 에너지를 받아 변신, 쇼커에 직면한다.', '1971-04-03', 6.5, 90.7837, 24, NULL, 94, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1433, '아메리칸 대드!', 'American Dad!', 'drama', 'https://image.tmdb.org/t/p/w500/aC1q422YhQR7k82GB8gW4KoD91p.jpg', 'https://image.tmdb.org/t/p/original/skBNukpZWvr5AhqPDEaO262Rjkr.jpg', '랭글리 폴즈라는 도시에서 사는 CIA에서 근무하는 수꼴에 과대망상이 매우 심한 아버지(스탠 스미스)와 전형적인 금발백치 어머니(프랜신 스미스), 반항아에 좌빨인 장녀(헤일리 스미스)에 Nerd 아들(스티브 스미스), 변장을 좋아하는 양성애자자웅동체[1] 외계인(로저), 그리고 동독 스키점퍼의 기억을 가지고 있는 금붕어(클라우스 하이슬러)로 이루어진 스미스 가족과 그 주변인물들을 다루고 있다', '2005-02-06', 7, 85.5258, 22, '세스 맥팔레인', 2290, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (250307, '더 피트', 'The Pitt', 'drama', 'https://image.tmdb.org/t/p/w500/kvFSpESyBZMjaeOJDx7RS3P1jey.jpg', 'https://image.tmdb.org/t/p/original/6uPBHw488MUW6x51zZ2OCJo6Dgp.jpg', '피츠버그 외상 센터의 의사 로비는 새 인턴과 의대생을 맞이한다. 인턴들은 레지던트와 간호사들 틈에서 응급실의 현실에 눈을 뜬다. 한편, 로비는 비용 삭감에 눈먼 경영진과 대립하는데...', '2025-01-09', 8.723, 85.9123, NULL, 'R. Scott Gemmill', 403, 0);
