INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (4087, '엑스 파일', 'The X-Files', 'drama', 'https://image.tmdb.org/t/p/w500/6BVL2a1fuRAj7rEflQ5HcrM2dRS.jpg', 'https://image.tmdb.org/t/p/original/w00lfexrsOeR25dO4hsWhbcUnmD.jpg', '과소 평가되어 무시되거나 미해결 상태로 남겨진 사건들(X 파일)을 조사하는 FBI 특수요원 폭스 멀더와 데이나 스컬리의 활약상을 그린 SF 스릴러 TV 드라마 시리즈.

멀더는 외계인의 존재나 과학으로 설명할 수 없는 초자연적인 현상을 믿는 반면, 회의적인 성격의 스컬리는 멀더가 발견한 것들에 대하여 과학적인 분석으로 비합리적인 부분들을 지적하며 멀더를 좀더 정상적으로 보이는 사건으로 끌어들이려 노력한다.', '1993-09-10', 8.373, 90.1232, NULL, '크리스 카터', 3419, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (60574, '피키 블라인더스', 'Peaky Blinders', 'drama', 'https://image.tmdb.org/t/p/w500/tNywkichh1mbS8BZA6CUPB8Zqgd.jpg', 'https://image.tmdb.org/t/p/original/l8v3gJDlASN0lNn51gR8zQJsu5O.jpg', '1919년 영국 버밍엄. 토마스 셸비를 주축으로 한 셸비 가문은 악명 높은 범죄 조직 "피키 블라인더스"를 이끌고 암흑가의 정상을 차지하기 위해 수단과 방법을 가리지 않는다.', '2013-09-12', 8.526, 84.0183, NULL, '스티븐 나이트', 10750, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (2190, '사우스 파크', 'South Park', 'drama', 'https://image.tmdb.org/t/p/w500/1CGwZCFX2qerXaXQJJUB3qUvxq7.jpg', 'https://image.tmdb.org/t/p/original/3UviYOlhn8EgXMBuiT6MnUuo1w9.jpg', '사우스 파크 마을에 사는 꼬맹이 4인방. 생김새는 평범하지만 입은 거칠고 생각은 험하다. 정치, 연예, 문화, 시사까지 성역 없이 던져지는 녀석들의 돌직구. 사우스 파크만의 사이다 멘트와 블랙 유머가 살아있는 어른용 애니메이션.', '1997-08-13', 8.3, 90.7646, NULL, '트레이 파커', 4817, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (16656, 'Фитиль', 'Фитиль', 'drama', 'https://image.tmdb.org/t/p/w500/9hdEulzIzfj0M2JBKRRIxWOBXUY.jpg', 'https://image.tmdb.org/t/p/original/hdlpSh7NstYZSVmuoeVENJdNaLR.jpg', '', '1962-06-04', 7.6, 82.6313, NULL, '세르게이 미할코프', 8, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (18165, '뱀파이어 다이어리', 'The Vampire Diaries', 'drama', 'https://image.tmdb.org/t/p/w500/b3vl6wV1W8PBezFfntKTrhrehCY.jpg', 'https://image.tmdb.org/t/p/original/cJYLon9ejKJV7ua03ab8Tj9u067.jpg', 'L. J. 스미스의 뱀파이어 다이어리 소설 시리즈 원작. 뉴욕 외곽도시, 미스틱 폴즈의 한 고등학교를 배경으로 두 뱀파이어 형제 스테판과 데미언, 그리고 인간 소녀 엘레나의 로맨스를 그린다.', '2009-09-10', 8.306, 82.5592, 43, '케빈 윌리엄슨', 9449, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (63174, '루시퍼', 'Lucifer', 'drama', 'https://image.tmdb.org/t/p/w500/ekZobS8isE6mA53RAiGDG93hBxL.jpg', 'https://image.tmdb.org/t/p/original/ncftkNAjIz2PBbUMY7T0CHVJP8d.jpg', '지긋지긋한 지옥 생활을 청산하고 은퇴를 선언한 악마. LA로 와 나이트클럽을 열고 인생을 즐기던 어느 날 강력계 형사를 만나면서 새로운 삶을 살기 시작한다.', '2016-01-25', 8.436, 81.1332, 45, 'Tom Kapinos', 15268, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1398, '소프라노스', 'The Sopranos', 'drama', 'https://image.tmdb.org/t/p/w500/lXaipuB4DrTfbyGT2xN9IpDtNH.jpg', 'https://image.tmdb.org/t/p/original/lNpkvX2s8LGB0mjGODMT4o6Up7j.jpg', '1999년 1월 HBO에서 방영을 시작한 마피아 범죄물. 뉴저지 마피아의 중간 보스인 토니 소프라노는 이유를 알 수 없는 공황발작으로 정신과 의사를 찾게 된다. 토니는 아내 카멜라와 두 자녀를 부양하는 평범한 아버지로서의 생활과 마피아로서의 생활을 동시에 진행하면서 정신적 공황을 겪게 되고 이에 대한 상담은 필연적으로 마피아 내부의 범죄행위를 노출하는 결과를 가져온다. 마피아 조직의 중간 보스에 걸맞지 않은 정신적 나약함으로 비추어 질 수 있다는 점과 누군가에게 조직의 비밀을 발설하고 있다는 사실이 지닌 위험 때문에 상담은 비밀리에 진행되는데...', '1999-01-10', 8.651, 80.2917, NULL, '데이비드 체이스', 3248, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (2288, '프리즌 브레이크', 'Prison Break', 'drama', 'https://image.tmdb.org/t/p/w500/25CanTqZbSxroa2dqcbtRi7jaQ5.jpg', 'https://image.tmdb.org/t/p/original/n3Brk7roueE9HOwVmYlJx5j462g.jpg', '2005년 8월 FOX에서 방영을 시작한 스릴러. 로욜라 대학에서 건축학을 전공한 후 미들턴 재판소 건축 설계 엔지니어로 근무하던 마이클 스코필드(웬트워스 밀러)는 그의 형인 링컨(도미닉 퍼셀)이 부통령 동생의 살인 누명을 쓰고 수감되어 사형을 선고받자, 형을 탈옥시키고 누명을 벗기기 위해 몸 전체에 교도소의 지도를 문신으로 세기고 의도적으로 은행강도를 저질러 형이 있는 감옥에 수감된다. 하지만 그가 들어가기 전에 세워둔 완벽하다고 생각했던 계획들은 인간이라는 장애물 앞에 조금씩 어긋나기 시작한다.', '2005-08-29', 8.075, 79.1507, NULL, 'Paul T. Scheuring', 5746, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (124364, '프롬', 'FROM', 'drama', 'https://image.tmdb.org/t/p/w500/wjaz71csFQWCvXkXDuIptfqwY7R.jpg', 'https://image.tmdb.org/t/p/original/6gN8DYnIEln8v7OhRy61c57w0Xy.jpg', '미국 중부에 있는 악몽 같은 도시가 들어오는 모든 사람들을 함정에 빠뜨리고 있다. 주민들은 정상의식을 유지하고 탈출구를 찾기 위해 고군분투하고 있지만, 특히 해가 질 때 나오는 무서운 생물들을 포함한 주변 숲의 위협에서도 살아남아야 한다.', '2022-02-20', 8.153, 79.1203, NULL, 'John Griffin', 2334, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (2691, '두 남자와 1/2', 'Two and a Half Men', 'drama', 'https://image.tmdb.org/t/p/w500/xgfjxyV3g1S68opzuvG6G87muDp.jpg', 'https://image.tmdb.org/t/p/original/2pOmuq4nkWZzwZbOfZq7CyyQAsM.jpg', '자유로운 영혼이었던 찰리가 떠나간 이후, 앨런과 그의 아들 제이크에게 찾아온 앨런의 친구 월든이 다시금 새로운 가족으로 생활하게 되면서 벌어지는 코믹한 일상을 담은 시트콤', '2003-09-22', 7.4, 78.7045, NULL, 'Lee Aronsohn', 3544, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (308482, '타스카리: 밀수와의 전쟁', 'तस्करी: द स्मगलर्स वेब', 'drama', 'https://image.tmdb.org/t/p/w500/k5vEx3490N7p4qwXhEOxXZGMIwg.jpg', 'https://image.tmdb.org/t/p/original/5WOikKpCZ5H0zEzVDeE6eJwA8BH.jpg', '헌신적인 세관원과 그가 이끄는 팀이 강력한 조직 두목인 악명 높은 밀수업자에 맞선다. 하지만 예상치 못한 장애물이 등장하면서 이들의 임무는 위기에 놓인다.', '2026-01-14', 7.1, 78.5972, NULL, 'Neeraj Pandey', 7, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (73586, '옐로우스톤', 'Yellowstone', 'drama', 'https://image.tmdb.org/t/p/w500/nmHvUWkUovDEJwZPlyPOktEzHf.jpg', 'https://image.tmdb.org/t/p/original/ynSOcgDLZfdLCZfRSYZGiTgYJVo.jpg', '미국 최초의 국립 공원과 국경을 접하는 사람들의 지속적인 공격을 받으면서 미국에서 가장 큰 목장을 관리하는 존 던트의 이야기', '2018-06-20', 8.259, 78.5557, NULL, '테일러 쉐리던', 2975, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (57532, '퍼피 구조대', 'PAW Patrol', 'drama', 'https://image.tmdb.org/t/p/w500/juAmsE4GC6gql0L1HsDmABkLWuX.jpg', 'https://image.tmdb.org/t/p/original/7OrV2aAH5Yp7hA9zCCvUloLvZtl.jpg', '퍼피구조대 대장 라이더와 용감한 여섯마리의 강아지 구조대의 이야기. 안전한 어드벤쳐 베이를 만들기 위한 라이더 대장과 여섯마리 귀여운 강아지 구조대의 끊임없는 연습과 도전! 경찰견 체이스와 소방견 마샬, 공사견 러블, 미화견 로키에 해양구조견 주마와 하늘을 나는 스카이까지! 여섯마리 강아지의 엉뚱발랄 신나는 구조활동을 지켜봐주세요!', '2013-08-12', 7, 78.2163, NULL, 'Keith Chapman', 796, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (259731, '그의 이야기 & 그녀의 이야기', 'HIS & HERS', 'drama', 'https://image.tmdb.org/t/p/w500/jDXqbmGao99W6Out4AK7gSiD7so.jpg', 'https://image.tmdb.org/t/p/original/n4hJLZmBG8kZccNn7bNgBDsVQ6a.jpg', '한 사람은 형사, 다른 한 사람은 뉴스 기자. 서로에게 등을 돌린 부부가 살인 사건의 진실을 두고 맞붙는다. 서로를 유력한 용의자로 의심하면서.', '2026-01-08', 7.084, 78.0787, NULL, '윌리엄 올드로이드', 179, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (46296, '스파르타쿠스', 'Spartacus', 'drama', 'https://image.tmdb.org/t/p/w500/9aehAV4zGOWad1Gz31gibjfIEnx.jpg', 'https://image.tmdb.org/t/p/original/1vhKauCQAq32u53X8n9qI896e6.jpg', '2010년 1월 Starz에서 방영을 시작한 드라마. 기원전 73년부터 2년 뒤인 기원전 71년까지 노예들을 이끌고 반(反)로마 공화정 항쟁을 지도한 노예 검투사 스파르타쿠스의 이야기를 바탕으로 각색했다. 로마의 접경시대에 살던 소수민족 트라키아의 전사였던 스파르타쿠스가 로마군에 사로잡힌 후 투기장의 노예로 팔려가지만, 극적으로 목숨을 부지하고 카푸아의 검투사 양성소에서 글래디에이터로 명성을 떨치는 이야기를 중심으로 당시 로마 귀족들의 사치와 부패, 사회상, 그리고 자유를 향한 노예 출신 등장 인물들의 갈망을 적나라하게 보여준다.', '2010-01-22', 8.029, 77.0647, 53, 'Steven S. DeKnight', 2811, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (44006, '시카고 파이어', 'Chicago Fire', 'drama', 'https://image.tmdb.org/t/p/w500/r915sk2JpthZSjHEgZKifWxgo6L.jpg', 'https://image.tmdb.org/t/p/original/14LzHqJrFcHk7ruMNCXpEkB0Thg.jpg', '시카고의 한 소방서를 배경으로 각자의 사연을 지닌 소방관들의 숭고한 직업정신을 그린 드라마.', '2012-10-10', 8.403, 76.0593, 42, 'Derek Haas', 2336, 0);
