INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (200875, '그것: 웰컴 투 데리', 'IT: Welcome to Derry', 'drama', 'https://image.tmdb.org/t/p/w500/3xwtiAKI97GYjcEFlr2YfkUYvml.jpg', 'https://image.tmdb.org/t/p/original/2fOKVDoc2O3eZmBZesWPuE5kgPN.jpg', '"그곳은 항상 사라짐으로 시작된다"

1962년, 한 가족이 메인 주의 작은 마을 데리에 이사 오면서 연쇄적인 실종과 설명할 수 없는 불길한 징조가 퍼져나간다. 비밀을 감춘 하수도와 오래된 서커스의 그림자, 어른들은 외면하고 아이들은 속삭인다. 무언가가 깨어났다고. 점점 커지는 공포 속에서 마을의 과거와 연결된 금기된 진실이 모습을 드러내기 시작하고, 누구도 안전하지 않다는 사실이 선명해진다. 그 미소의 주인이 다시 환영을 건네올 때, 이들은 과연 무엇을 마주하게 될 것인가', '2025-10-26', 8.226, 67.3101, NULL, '앤디 무시에티', 1218, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (108978, '리처', 'Reacher', 'drama', 'https://image.tmdb.org/t/p/w500/diZdQHPy4cQmpowkGKmQ9anEWqn.jpg', 'https://image.tmdb.org/t/p/original/JYgqp8g2kI3SEus9XBDSHukfBN.jpg', '은퇴한 헌병 대원 잭 리처는 자신이 저지르지 않은 살인으로 체포되고, 이내 자신이 부패한 경찰, 수상쩍은 사업가, 교활한 정치가들이 판치는 음모의 한 가운데 있음을 알게 된다. 리처는 오직 자신의 지혜만을 가지고 조지아주 마그레이브에서 무슨 일이 일어나고 있는지 알아내야 한다.', '2022-02-03', 8.085, 64.4093, NULL, '닉 샌토라', 2618, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (873, '형사 콜롬보', 'Columbo', 'drama', 'https://image.tmdb.org/t/p/w500/2JCD8vab3fircOU8cM2HJCxfv4I.jpg', 'https://image.tmdb.org/t/p/original/2emkZBBiZG7pE7RBuIWtbKZ2a33.jpg', '후줄근한 옷차림에 의미 없는 잡담을 늘어 놓다가, 날카로운 질문으로 간담을 서늘하게 만드는 LA 경찰청의 형사 콜롬보. 드라마 도입부에 살인범이 먼저 밝혀지고, 범인의 완벽한 계획 범죄가 콜롬보에 의해 밝혀지며 사건이 해결되는 형식의 형사 추리물', '1971-09-15', 8.089, 67.0398, NULL, 'William Link', 789, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (80748, 'FBI', 'FBI', 'drama', 'https://image.tmdb.org/t/p/w500/zfKS4WL0OZ9udpNoSYZw91VB3aH.jpg', 'https://image.tmdb.org/t/p/original/5DFvscYGpcFaQMJljCic5gbzVe6.jpg', 'FBI 뉴욕 지부는 모든 전문성을 활용해 뉴욕과 미국을 안전하게 지킨다. 특수 요원 매기, 파트너 OA, 그들을 감독하는 특수요원 데이나, 분석가 크리스틴까지. 테러, 조직 범죄, 첩보 등 엄청난 규모의 사건들을 끈질기게 파고들어 해결해나가는 일류 요원들의 역대급 수사드라마가 시작된다.', '2018-09-25', 7.901, 63.8873, NULL, '딕 울프', 876, 0);
