INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (34524, '틴 울프', 'Teen Wolf', 'drama', 'https://image.tmdb.org/t/p/w500/8Ij1O2nU8exLgwPXU8Eo6PZdCDC.jpg', 'https://image.tmdb.org/t/p/original/1F2RnXLc0fmRt7iWfBK4mNVsjno.jpg', '어느 날 갑자기 늑대인간이 되어버린 후, 우정과 사랑을 지키며 스스로 살아남기 위해서 싸우는 고등학생 스캇의 이야기. 1985년 제작된 동명 영화를 리메이크한 작품.', '2011-06-05', 8.459, 61.8889, NULL, 'Jeff Davis', 4604, 0);
