INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1403, '에이전트 오브 쉴드', 'Marvel''s Agents of S.H.I.E.L.D.', 'drama', 'https://image.tmdb.org/t/p/w500/86BdTM6j3aEizD0OKt09OUmrInB.jpg', 'https://image.tmdb.org/t/p/original/iWopHyAvuIDjGX10Yc3nn6UEebW.jpg', '마블 어벤져스의 필 콜슨 요원이 돌아왔다! 뉴욕 사건 이후 콜슨 요원을 중심으로 탄생한 지구 최강의 평화 유지 조직. 인류를 위협하는 이상한 사건들, 우리가 접수한다. 마블 어벤져스의 뉴욕 사건으로 지구에 유입된 외계 생명체들을 수사하고자, 각 분야 최고의 요원들이 한자리에 모였다.', '2013-09-24', 7.473, 57.7922, NULL, '조스 웨던', 3703, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (502, '세서미 스트리트', 'Sesame Street', 'drama', 'https://image.tmdb.org/t/p/w500/wZC3fXTxR00YCjgqkc1N20seZJb.jpg', 'https://image.tmdb.org/t/p/original/tNi2aJPdCKfielGYzIi3IKxStz9.jpg', '새서미 스트리트는 미국 어린 아이들을 위한 장수 TV 시리즈였습니다. 이 프로그램은 교육적인 목적으로 만들어졌지만 짐 핸슨의 인형극, 애니메이션, 짧은 영화, 유머와 문화에 대한 내용들로 매우 창의적인 내용들을 다루고 있습니다. 첫 시리즈는 1969년 11월 10일 방영되었으며 당시 긍정적인 리뷰가 있었고 논란이 되기도 하였고 높은 평가를 받았습니다.', '1969-11-10', 7.087, 56.9897, 54, 'Lloyd Morrisett', 275, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (693, '위기의 주부들', 'Desperate Housewives', 'drama', 'https://image.tmdb.org/t/p/w500/3TMNdFDDo5O61Zh288vie8o1MvW.jpg', 'https://image.tmdb.org/t/p/original/kub3bZS2sOGviEjo4p1ohREboVb.jpg', '이곳은 위스테리아가. 전형적인 미국의 완벽한 교외 거리처럼 보이지만 근사한 집과 울타리 너머를 보면 균열이 눈에 띄기 시작한다. 최근까지 이 동네에 살던 메리 앨리스는 자신의 목숨을 끊었다. 고인이 된 그녀는 위스테리아가의 이웃과 친구들이었던 브리, 이디, 가브리엘, 르넷과 수잔의 비밀을 벗겨낸다.', '2004-10-03', 7.905, 58.7813, NULL, 'Marc Cherry', 2015, 0);
