INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1695, '몽크', 'Monk', 'drama', 'https://image.tmdb.org/t/p/w500/ytOIRpgJL9cp679u19FcjjkajYj.jpg', 'https://image.tmdb.org/t/p/original/dMY7XUfEAK0Rl8hsgc8ufEOaiZ2.jpg', '현대 샌프란시스코를 배경으로 하는 코미디 수사물 미드. 3년 전 자동차 폭발 사건으로 아내를 잃은이후 큰 충격에서 빠져나오지 못한 채, 독특한 강박관념에 사로잡혀 많은 사람들이 모인 군중과 높은 곳, 그리고 어둠을 두려워하는 증세를 보이는 전직 경찰 에이드리언 몽크가 샌프란시스코 경찰을 도와 복잡한 사건들을 해결한다.', '2002-07-12', 7.948, 57.3945, NULL, '앤디 브렉먼', 1197, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (229891, '이 사랑 통역 되나요?', '이 사랑 통역 되나요?', 'drama', 'https://image.tmdb.org/t/p/w500/ePz0D6B6wbxoLHsUtcaqfGx7E41.jpg', 'https://image.tmdb.org/t/p/original/60Hm8JC1Ps8DsrstAt4PTQuBdIB.jpg', '촬영차 전 세계를 오가는 스타 배우와 그녀의 통역사. 서로를 향한 마음이 깊어지는 것과 달리 설렘의 감정은 자꾸만 오역이 되는데. 과연 둘만의 사랑의 언어를 찾을 수 있을까?', '2026-01-16', 9.037, 59.5123, NULL, '홍미란', 27, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (85552, '유포리아', 'Euphoria', 'drama', 'https://image.tmdb.org/t/p/w500/lRsDSuj98WQfXBCV44xMoG0G29M.jpg', 'https://image.tmdb.org/t/p/original/9KnIzPCv9XpWA0MqmwiKBZvV1Sj.jpg', '약물과 성, 트라우마, 범죄 그리고 소셜 미디어가 가득한 세상 속에서 사랑과 우정 사이에서 갈등하는 10대 청소년들의 이야기.', '2019-06-16', 8.286, 59.2893, NULL, '샘 레빈슨', 10268, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (95603, '쿠룰루스 오스만', 'Kuruluş Osman', 'drama', 'https://image.tmdb.org/t/p/w500/ykZFJ0kqL57SyogceHCwU17RgKc.jpg', 'https://image.tmdb.org/t/p/original/ndLd4IIc90ajv5VpCaLfqmmEYOb.jpg', '3세기 말 아시아와 유럽을 연결하는 땅, ''아나톨리아'' 그 땅에서 살던 유목부족을 통일하여 세 대륙에 걸친 대제국을 건설한 오스만. 오스만 제국의 창시자인 오스만 1세의 삶과 제국을 건설하는 과정을 그린 드라마', '2019-11-20', 7.866, 58.8392, 120, 'Mehmet Bozdağ', 291, 0);
