INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1620, 'CSI: 마이애미', 'CSI: Miami', 'drama', 'https://image.tmdb.org/t/p/w500/pNW64pjaHvf6purNaFhq4SHYRfl.jpg', 'https://image.tmdb.org/t/p/original/bhG1XJ1fubbZkLnoBAxNrzzGXOg.jpg', '플로리다 주의 마이애미 데이드 경찰청. 호레이쇼 반장과 CSI 과학 수사 대원들은 논리적인 증거 분석과 본능적인 수사로 마이애미에서 일어나는 위험한 범죄들을 해결해나간다.', '2002-09-23', 7.711, 57.8081, 42, 'Ann Donahue', 1668, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (41956, '데스 인 파라다이스', 'Death in Paradise', 'drama', 'https://image.tmdb.org/t/p/w500/u7t6vCyqAdD5hE4eEfTrZmVljDi.jpg', 'https://image.tmdb.org/t/p/original/8dbKQrdVR5HD7PVWjTPawnTYCPT.jpg', '세인트 마리섬의 치안을 담당하는 오노레 경찰서에 영국 런던경찰청에서 새 경위가 파견된다. 융통성이라고는 전혀 없는 폴 경위, 세인트 마리의 동료들과 부대끼며 사건을 해결하기 시작한다. 작은 단서도 놓치지 않는 리처드와 개성 뚜렷한 동료들이 모여 세인트 마리의 살인 사건을 해결한다.', '2011-10-25', 7.477, 57.6476, 60, 'Robert Thorogood', 304, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (120089, '스파이 패밀리', 'SPY×FAMILY', 'drama', 'https://image.tmdb.org/t/p/w500/rikBBQHmCTOiZ7YoJVkYcKdXgNx.jpg', 'https://image.tmdb.org/t/p/original/lysUnU6V0VfcthDbviuVlIqgHOR.jpg', '사람은 누구나 아무에게도 보여줄 수 없는 자신을 갖고 있다. 세계 각국이 물밑에서 치열하게 정보전을 펼치는 시대. 오스타니아와 웨스탈리스는 십수 년간에 걸쳐 냉전 상태에 있었다. 웨스탈리스의 정보국 대동과 ''WISE'' 소속의 수완가 스파이인 ''황혼'' 은 동서 평화를 위협하는 위험인물, 오스타니아의 국가통일당 총재 도노반 데스몬드의 동향을 살피기 위해 어떤 극비 임무를 수행하게 된다. 그 이름은 오퍼레이션 ''올빼미''. 임무 내용은 "일주일 이내에 가족을 만들어, 데스몬드의 아들이 다니는 명문 학교의 친목회에 잠입하라". ''황혼'' 은 정신과 의사 로이드 포저로 위장하고 가족을 만들게 된다. 하지만, 그가 만난 딸 아냐는 마음을 읽을 수 있는 초능력자, 아내 요르는 암살자였다! 3명의 이해가 일치하여 서로 정체를 숨기면서 함께 생활하게 되는데. 해프닝 연속인 임시 가족에게, 세계의 평화는 맡겨졌다.', '2022-04-09', 8.523, 57.5733, 24, NULL, 2172, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (307534, '버트에게 자유를', 'Free Bert', 'drama', 'https://image.tmdb.org/t/p/w500/bQ0nPGGESLVKejaAwbgb7noQhzQ.jpg', 'https://image.tmdb.org/t/p/original/utwGNSLV2mjicTPmYPwOCFfdxs1.jpg', '엉뚱하고 막무가내인 아빠와, 그 못지않게 필터 없는 가족. 명문 사립 학교의 잘난 척하는 엘리트 가족들 틈에 끼어 보려다, 그야말로 난장판이 벌어진다.', '2026-01-22', 9, 57.2645, NULL, 'Jarrad Paul', 2, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (113962, '라이어니스: 특수 작전팀', 'Lioness', 'drama', 'https://image.tmdb.org/t/p/w500/ajaXSmdAlYYhnvx1EIsvpfN949y.jpg', 'https://image.tmdb.org/t/p/original/r0Zg70jpcDAD7IMDhVqajSnG9vb.jpg', '테러리스트를 제거하기 위해 조직 내부에 침투해야하는 실존하는 CIA 팀, ‘라이어니스''의 이야기를 다룬다. 팀의 수장이자 두 딸의 엄마인 ‘조’. 그녀는 국가의 명령을 수행하면서도 테러 조직에 잠입한 팀원 ‘크루즈’의 생명까지 지켜야 한다. 동시에 엄마로서의 책임까지 지켜내야 하는데. 과연 그녀는 무엇을 위해 싸울 것인가.', '2023-07-23', 8.002, 56.9932, NULL, '테일러 쉐리던', 1112, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (45094, '팔로잉', 'The Following', 'drama', 'https://image.tmdb.org/t/p/w500/xkyQduQCbHFkXCThIQEnqsgl2CP.jpg', 'https://image.tmdb.org/t/p/original/2HpYUipbaIgYhcO3PkllGF9xy5D.jpg', '자신이 가르치던 캠퍼스에서 14명의 여대생을 살해한 연쇄살인범 ''조 캐롤''과 그를 쫓는 전직 FBI 요원 ''라이언 하디''의 목숨을 건 대결을 그린 스릴러 드라마.', '2013-01-21', 6.892, 56.9657, 43, '케빈 윌리엄슨', 560, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1412, '애로우', 'Arrow', 'drama', 'https://image.tmdb.org/t/p/w500/u8ZHFj1jC384JEkTt3vNg1DfWEb.jpg', 'https://image.tmdb.org/t/p/original/wAFuDJfZJrnh6a1wf1Vt7PqYBvR.jpg', '스탈링 시티의 잘나가는 재벌 2세 올리버 퀸은 아버지와 보트 여행에 나섰다가 태풍을 만나 난파를 당한다. 그는 5년 동안 외딴 섬에 표류되어 생존을 위한 처절한 사투를 벌이고 마침내 고향으로 돌아온다. 아버지의 유언에 따라 스탈링 시티의 엘리트 범죄자들을 사냥하기위해 스스로 자경단원을 자처하는 올리버퀸. 그러나 그의 앞날에는 그의 상상보다 더 큰 진실과 음모가 기다리고 있는데...', '2012-10-10', 6.831, 56.2053, NULL, 'Andrew Kreisberg', 6213, 0);
