INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (790, '아가사 크리스티: 명탐정 포와로', 'Agatha Christie''s Poirot', 'drama', 'https://image.tmdb.org/t/p/w500/pWVZ6WUSZfqxTOllyiV9mM3jQ4g.jpg', 'https://image.tmdb.org/t/p/original/rwxxDbG9Kijki7CkmB4k64MSbte.jpg', '미스터리 추리 소설의 여왕, 아가사 크리스티의 작품을 영상화한 시리즈. 멋진 콧수염이 트레이드 마크인 벨기에 출신의 명탐정 에르큘 포와로가 미궁에 빠진 사건들을 해결한다.', '1989-01-08', 8.2, 55.8541, 50, NULL, 523, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (42009, '블랙 미러', 'Black Mirror', 'drama', 'https://image.tmdb.org/t/p/w500/ej7Br2B8dkZZBGa6vDE8HqATgU7.jpg', 'https://image.tmdb.org/t/p/original/dg3OindVAGZBjlT3xYKqIAdukPL.jpg', '인간이 지닌 최악의 본성, 최고의 혁신 등을 드러내는 연작 시리즈. 틀을 깨는 기이하고 과감한 이야기들이 펼쳐진다.', '2011-12-04', 8.285, 55.7012, NULL, 'Charlie Brooker', 5929, 0);
