INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (30983, '명탐정 코난', '名探偵コナン', 'drama', 'https://image.tmdb.org/t/p/w500/tg5Gya0yv7mScUMIX8CSXZzLCVd.jpg', 'https://image.tmdb.org/t/p/original/5546GF3zT3yA25ydCz0KlujjRA3.jpg', '검은 조직의 약물에 당해서 초등학생의 몸이 된 고등학생 쿠도 신이치가 에도가와 코난이라는 가명을 사용하여 소꿉친구인 란의 아버지가 운영하는 탐정사무소에서 얹혀 살며 사건을 해결하는 이야기를 다루고 있다.', '1996-01-08', 7.995, 52.9948, 25, NULL, 730, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (5092, '무한도전', '무한도전', 'drama', 'https://image.tmdb.org/t/p/w500/fpXfEfcZu5uDTOKqjwXSGgrL4iY.jpg', 'https://image.tmdb.org/t/p/original/s2qJb1FLwp1Mse9lY08JqgMp0kw.jpg', '대한민국 평균 이하임을 자처하는 남자들이 매주 새로운 상황 속에서 펼치는 좌충우돌 도전기', '2005-04-23', 7.7, 52.9351, 90, '김태호', 20, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (30984, '블리치', 'BLEACH', 'drama', 'https://image.tmdb.org/t/p/w500/2cT8jkEVsAL86CVKALR4pnaVLDb.jpg', 'https://image.tmdb.org/t/p/original/o0NsbcIvsllg6CJX0FBFY8wWbsn.jpg', '''쿠로사키 이치고''는 유령을 볼 수 있는 15세의 남자다. 특수한 체질을 가지고도 평범한 생활을 하던 이치고에게 갑자기 스스로를 사신이라고 소개하는 소녀 ''쿠치키 루키아''가 나타난다. 유아울러 산 사람, 죽은 사람 안 가리고 공격해서 영혼을 먹어치우는 나쁜 혼령 ''호로''도 모습을 드러낸다. 그런데 호로로 인해 이치고의 가족이 쓰러져가는데...', '2004-10-05', 8.4, 52.86, 24, NULL, 2047, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1100, '내가 그녀를 만났을 때', 'How I Met Your Mother', 'drama', 'https://image.tmdb.org/t/p/w500/b34jPzmB0wZy7EjUZoleXOl2RRI.jpg', 'https://image.tmdb.org/t/p/original/gvEisYtZ0iBMjnO3zqFU2oM26oM.jpg', '《내가 그녀를 만났을 때》는 미국 CBS에서 방영되었던 시트콤이다. 소울메이트를 찾기 위한 테드의 기나긴 여정. 어른이 된 테드가 아이들에게 아빠와 엄마가 만난 이야기를 들려주며 회상하는 장면들로 이뤄진다.', '2005-09-19', 8.143, 52.3714, 22, 'Carter Bays', 5528, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (48866, '원헌드레드', 'The 100', 'drama', 'https://image.tmdb.org/t/p/w500/wcaDIAG1QdXQLRaj4vC1EFdBT2.jpg', 'https://image.tmdb.org/t/p/original/8ZerYKvIaNUJZvAHXYTQu4qTwFw.jpg', '지구가 핵전쟁으로 황폐해지고 한 세기의 시간이 흐른 뒤, 우주 정거장에 살던 사람들 100명이 인류의 생존 가능성을 알아내기 위해 지구로 보내진다.', '2014-03-19', 7.885, 52.0768, 42, 'Jason Rothenberg', 8472, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1450, '클로저', 'The Closer', 'drama', 'https://image.tmdb.org/t/p/w500/q6FhABXGf3TaYKoKNwzGAEzW7bt.jpg', 'https://image.tmdb.org/t/p/original/oenEPUQI0ZgeaBWB5dYGrzrA9gN.jpg', '증거가 없는 범죄의 자백을 받아내기로 유명한 LAPD 국장 브렌다가 능력을 발휘해 어려운 사건들을 해결해 나가는 과정을 그린 드라마', '2005-06-13', 7.875, 51.973, 46, 'James Duff', 324, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (70672, '아는 형님', '아는 형님', 'drama', 'https://image.tmdb.org/t/p/w500/zak7mqMxJGnnWplSdbjDtV7bg2Y.jpg', 'https://image.tmdb.org/t/p/original/a8a8z4aJr40zYgRMfmSESppX2eO.jpg', '2015년 12월 JTBC에서 방영을 시작한 버라이어티 쇼. 세상의 모든 질문을 그들만의 방식으로 풀어주는 아는 형님. 인생을 살다 보면 마주치게 되는 사소하지만 궁금해 견딜 수 없는 질문들. 그럴 땐 질문하라. 아는 형님이 답할 것이다. 나이도, 출신도, 성격도, 외모도 전혀 다르지만 인생 좀 살아 본, 그래서 인생을 좀 아는 형님들이 모여 그들만의 방식으로 추측하고 실험하고 전해주는 아는 형님만의 인생 해답. 지금부터 우리에게 속 시원한 답을 주기 위해 벌이는 형님들의 고군분투가 시작된다.', '2015-12-05', 7.512, 51.7478, 90, NULL, 41, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1409, '썬즈 오브 아나키', 'Sons of Anarchy', 'drama', 'https://image.tmdb.org/t/p/w500/jzsCDbn0UCod1SjtUaPNeBblved.jpg', 'https://image.tmdb.org/t/p/original/dk2AwvW3VyKHCWAdED0sJzD0NYQ.jpg', '2008년 9월 FX Networks에서 방영을 시작한 범죄 드라마. 캘리포니아 북부의 마을인 차밍은 SOA라는 바이크 클럽이 실권을 잡아 살아가고 있는 곳이다. SOA의 부보스인 잭스 텔러는 조직의 보스이자 양아버지인 클레이와 함께 조직을 꾸려나가고 있다. 잭스는 아이를 거의 죽일 뻔 한 마약 중독자 부인인 웬디를 재활시설로 보내버리고, 어린 시절 연인이었던 타라와 재회한다. 어느 날 우연히 사망한 아버지인 존 텔러의 일기장을 발견하게 되고, 아버지가 꿈꾸었던 조직의 발전 방향과 조직의 현실 사이에서 갈등하게 된다.', '2008-09-03', 8.416, 51.2586, NULL, '커트 서터', 3151, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (94997, '하우스 오브 드래곤', 'House of the Dragon', 'drama', 'https://image.tmdb.org/t/p/w500/e58T9kPvtBjO7L8DjpyBGrMR6al.jpg', 'https://image.tmdb.org/t/p/original/2xGcSLyTAzConiHAByWqhfLiatT.jpg', '대륙을 지배하는 타르가르옌 가문의 왕 비세리스 1세의 어린 딸 라에니라와, 왕의 난폭한 동생 다에몬이 왕위 계승을 노리면서 음모와 배신, 피와 죽음으로 얼룩지는 길고 긴 싸움이 시작된다. 아무도 넘볼 수 없는 절대 권력, 왕위 계승을 둘러싼 가문의 내전이 벌어진다.', '2022-08-21', 8.299, 51.1714, NULL, '조지 R. R. 마틴', 5676, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (246386, '올 허 폴트: 그날의 책임', 'All Her Fault', 'drama', 'https://image.tmdb.org/t/p/w500/o8vZKZlc8H4OcgpbJuqP0iK4B2.jpg', 'https://image.tmdb.org/t/p/original/uv0LVwNM8mZcwhCa5pd6FJxvKDz.jpg', '머리사 어바인은 같은 유치원에 다니는 친구 집에 처음 놀러 간 아들 마일로를 데려오기 위해 문자에 적힌 주소를 찾아간다. 하지만 집에서 나온 여성이 마일로라는 아이를 본 적이 없다고 하자, 머리사는 크게 당황한다.', '2025-11-07', 8.186, 51.0709, NULL, 'Megan Gallagher', 129, 0);
