INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (119051, '웬즈데이', 'Wednesday', 'drama', 'https://image.tmdb.org/t/p/w500/oCpvKD0yuRV9OAZ8xklRy9HWc6l.jpg', 'https://image.tmdb.org/t/p/original/iHSwvRVsRyxpX7FE7GbviaDvgGZ.jpg', '똑똑함은 기본, 비꼬는 것에도 도가 튼 웬즈데이 아담스. 암울함을 풍기는 그녀가 네버모어 아카데미에서 얽히고설킨 미스터리를 파헤치기 시작한다. 새 친구도 사귀고, 앙숙도 만들며.', '2022-11-23', 8.361, 50.688, NULL, '마일스 밀러', 10235, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (62650, '시카고 메드', 'Chicago Med', 'drama', 'https://image.tmdb.org/t/p/w500/9eym662FRJJb9wdgCiDKPDciZzf.jpg', 'https://image.tmdb.org/t/p/original/x2jNLrYw1s9i6kihEJqsBQgs9nR.jpg', '대도시 시카고에 위치한 병원을 배경으로, 매일 반복되는 아수라장 속에서 다양한 사건 사고와 마주하며 함께 난관을 헤쳐나가는 의료진들의 이야기를 그리는 메디컬 드라마', '2015-11-17', 8.282, 50.6776, NULL, '딕 울프', 1219, 0);
