INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (90, '항공사고 수사대', 'Mayday', 'drama', 'https://image.tmdb.org/t/p/w500/lkU3OafPOiaPSyUuDilJ2FM9O1b.jpg', 'https://image.tmdb.org/t/p/original/zocVz88wzfCd2y3RPKxI8qjhRKc.jpg', '세계 각지에서 일어난 항공 사고를 검증하는 프로그램이다.  조종석 음성 기록 장치(CVR)와 비행 데이터 레코더(FDR), 목격자/사고기 탑승객/수사관의 인터뷰와 실제 교신 기록을 바탕으로 재현된 CG영상, 그리고 그 외의 다양한 영상 자료로 구성되어 있다.', '2003-09-03', 8.2, 48.7542, 46, 'André Barro', 272, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (17610, 'NCIS: 로스앤젤레스', 'NCIS: Los Angeles', 'drama', 'https://image.tmdb.org/t/p/w500/h0yKOgUrFKSv9U3J0ZAUFhCq5x8.jpg', 'https://image.tmdb.org/t/p/original/dAepkmD4vdfhS82r2OIqF1nwGR5.jpg', 'LA 지역에서 활동하는 NCIS 특수작전부 소속 위장잡입수사 전문요원들의 활약을 그린다. NCIS의 첫번째 스핀오프 시리즈.', '2009-09-22', 7.532, 49.7678, 45, 'Shane Brennan', 1219, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1920, '트윈 픽스', 'Twin Peaks', 'drama', 'https://image.tmdb.org/t/p/w500/lA9CNSdo50iQPZ8A2fyVpMvJZAf.jpg', 'https://image.tmdb.org/t/p/original/dZklTql88IDOmkC3JAYQSTgyK6f.jpg', '데이비드 린치와 마크 프로스트가 만든 미국 TV 시리즈로, 1990년 4월 8일에 ABC에서 첫 에피소드를 방영했다. 워싱턴주의 작은 마을에서 여학생 로라 팔머의 시체가 발견되고, FBI 요원 데일 쿠퍼가 수사를 시작하며 사건은 시작된다. 트윈 픽스는 1990년대 가장 인기있는 드라마 중 하나로 컬트 팬들을 사로잡았을 뿐만 아니라, 영화, 음악, 게임, 만화, 광고, 드라마 등에 다양한 대중 문화에 수많은 영향을 끼쳤다. 린치의 다른 작품, <블루 벨벳> 처럼 트윈 픽스는 작은 마을의 평화롭고 완벽한 모습과 그 밑에 숨어있는 지저분한 삶을 들추어낸다. 이야기가 계속될 수록 처음엔 순수하게 보였던 캐릭터들의 어두운 내면이 드러난다. 불안정한 톤과 초자연적인 특징들은 호러에 가깝지만, 비현실적으로 과장된 캐릭터들이 사랑, 복수, 질투, 돈 등의 사건에 휩싸인 다는 점은 평범한 연속극의 형식을 취하고 있기도 하다. 실외 촬영은 노스벤드, 스노퀄미등 워싱턴주의 도시와 캘리포니아주에서 진행되었고, 실내장면은 샌 퍼르난도 밸리의 창고의 세트장에서 촬영되었다. 이야기는 범죄 드라마의 형식으로 그려지지만, 묘한 분위기와 초자연적인 요소, 그리고 과장되고 유별난 인물들이 등장한다. 린치의 다른 작품과 유사하게 탁월한 촬영, 초현실적이고 색다른 유머 코드가 있다. 린치의 협력자인 안젤로 바달라멘티가 작곡한 오리지널 스코어 역시 찬사를 받았다.', '1990-04-08', 8.3, 49.2472, NULL, 'Mark Frost', 2432, 0);
