INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (12971, '드래곤볼 Z', 'ドラゴンボールゼット', 'drama', 'https://image.tmdb.org/t/p/w500/70gAmYUfEVOFMuC3gJBIo0MSfbh.jpg', 'https://image.tmdb.org/t/p/original/ydf1CeiBLfdxiyNTpskM0802TKl.jpg', '흥미진진한 드래곤 볼! 계속되는 이야기! 성장한 손오공이 치치와 결혼하여 손오반이라는 아들까지 둔 모습을 보여주고 있다. 어느 날 우주로부터 형 라데츠가 찾아와 지구를 멸망시키려고 하며 손오공에게 동참할 것을 설득한다. 하지만, 자신의 설득이 먹혀들지 않자 조카인 오반을 납치한다. 오공과 피콜로가 합심하여 라데츠를 물리치지만, 오공도 죽어버리는 사태가 발생한다. 지구를 위해, 그리고 우주를 위해 싸우는 Z 용사들!', '1989-04-26', 8.355, 50.8454, 26, NULL, 4727, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (153312, '털사 킹', 'Tulsa King', 'drama', 'https://image.tmdb.org/t/p/w500/2FsXAf6QHkieAM4as5Xxe9W0D1P.jpg', 'https://image.tmdb.org/t/p/original/mNHRGO1gFpR2CYZdANe72kcKq7G.jpg', '오클라호마주 털사에서 이탈리아 마피아 가족을 재건해야 하는  놀라운 과제에 직면한 이탈리아 폭력배의 이야기.', '2022-11-13', 8.288, 52.9698, NULL, '테일러 쉐리던', 2484, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (655, '스타 트렉: 넥스트 제너레이션', 'Star Trek: The Next Generation', 'drama', 'https://image.tmdb.org/t/p/w500/vkLzXddgUKH5VcpnYiRzpJFrZhz.jpg', 'https://image.tmdb.org/t/p/original/qmliLoo6GVheM2FihatlAXxCKyF.jpg', '배경은 "오리지널 시리즈"로부터 대략 100년 후로 설정되어 있으며, 2363년 10월 4일 새롭게 취역한 엔터프라이즈-D와 장 뤽 피카드 함장이 출연한다. 본 시리즈에서는 또한 베타조이드 혼혈인 디애나 트로이와 스타플릿 최초의 클링온 장교인 워프 등과 같은 외계 종족의 승무원이 등장하였다. 1987년 9월 28에 시작하여 1994년 5월 23일을 끝으로 7 시즌간 방영되었다. 이전 시리즈와는 달리, 네트워크 방송사에 공중파로 방송되지 않고 프로그램이 배급되었다. 《스타 트렉》의 다른 어떤 시리즈보다 호평을 받았으며, 방송 후반부에는 배급률 1위를 차지하였다. 최종 시즌은 에미상 최고 드라마 시리즈 부분의 수상 후보로 거명되었다. “The Big Good-bye”화는 우수 TV 프로그램 부분 피보디상을 수여받았다.', '1987-09-28', 8.365, 49.8223, 45, '진 로덴베리', 1678, 0);
