INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (103540, '퍼시 잭슨과 올림포스의 신들', 'Percy Jackson and the Olympians', 'drama', 'https://image.tmdb.org/t/p/w500/3lCExsvn5CKzfRXFUIp7LIoUgfd.jpg', 'https://image.tmdb.org/t/p/original/sAxx25ijwYQ8xsT56wu2IzvIRss.jpg', '괴물들과 상대하고 신들을 따돌리며 미국 곳곳을 탐험하는 것도 모자라 제우스의 번개 화살을 되찾고 전쟁을 저지해야하는 위험천만한 모험이 퍼시를 기다린다. 그는 모험을 함께하는 동료 아나베스, 그로버의 도움으로 평생을 짓누르던 의문, 이 세상에 어떻게 적응할 것이고, 그의 운명은 무엇인지에 대한 답을 찾아간다.', '2023-12-19', 7.295, 46.6457, NULL, '릭 라이어던', 689, 0);
