INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (250505, '애거사 크리스티의 세븐 다이얼스', 'Agatha Christie''s Seven Dials', 'drama', 'https://image.tmdb.org/t/p/w500/6GEotZmZyk4FzXtaq4G8dPln4kR.jpg', 'https://image.tmdb.org/t/p/original/eVEbRtSOrczWlYnVmwM195AnX86.jpg', '1925년 잉글랜드. 한 시골 저택의 호화 파티에서 장난으로 시작된 일이 뜻하지 않은 방향으로 흘러 급기야 살인으로 이어진다. 곧이어 진상 조사가 시작되고, 비상한 탐구심의 레이디 아일린 ''번들'' 브렌트는 자신의 인생을 송두리째 바꾸게 될 간담 서늘한 음모를 밝히는 일에 착수한다. 그리고 그렇게 시골 저택 미스터리의 진실이 온 세상에 드러난다.', '2026-01-15', 6.211, 42.3594, NULL, 'Chris Chibnall', 90, 0);
