INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (127532, '나 혼자만 레벨업', '俺だけレベルアップな件', 'drama', 'https://image.tmdb.org/t/p/w500/5gR5oCQufzZ6tPcFoHb61ckiwiP.jpg', 'https://image.tmdb.org/t/p/original/xMNH87maNLt9n2bMDYeI6db5VFm.jpg', '다른 차원과 이쪽 세계를 이어주는 통로인 ''게이트''가 갑자기 발생한 뒤 10년 세계에는 ''헌터''라고 불리는 초인적인 힘에 각성한 사람들이 출현했다. 헌터는 게이트 안의 던전을 공략하고 대가를 받는 것을 생업으로 하고 있는데 그런 강자들만 가득한 헌터들 중 ''성진우''는 인류 최약병기라고 불리는 저랭크 헌터로서 생활하고 있었다. 어느 날, 저랭크 던전에 숨겨진 고랭크 이중 던전을 발견했지만 빈사의 중상을 입은 성진우의 눈앞에 의문의 퀘스트창이 나타났는데. 죽음의 순간, 퀘스트를 수락하기로 결심한 성진우는 자신만 ''레벨업''할 수 있게 되었는데.', '2024-01-07', 8.607, 46.2926, 24, NULL, 1523, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (269, '원 트리 힐', 'One Tree Hill', 'drama', 'https://image.tmdb.org/t/p/w500/sOrelBaAhp7DZbPTivDwKEyPslC.jpg', 'https://image.tmdb.org/t/p/original/eDNSgT1xPMKYcEzJ5GG0PCE3NcN.jpg', '', '2003-09-23', 7.758, 37.4672, 42, 'Mark Schwahn', 559, 0);
