INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (12225, '페파 피그', 'Peppa Pig', 'drama', 'https://image.tmdb.org/t/p/w500/aTaGTqkbMWoy0ef0M48qJkMltxE.jpg', 'https://image.tmdb.org/t/p/original/ooIYvpusdiXzULeUlL1Ul7XljQK.jpg', '페파 피그는 엄마, 아빠, 그리고 남동생 조지와 함께 사는 활기찬 돼지입니다. 그녀는 진흙 웅덩이에 뛰어드는 것과 큰 코웃음 소리를 내는 것을 좋아합니다.', '2004-05-31', 6.576, 50.9956, NULL, 'Neville Astley', 727, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (46648, '트루 디텍티브', 'True Detective', 'drama', 'https://image.tmdb.org/t/p/w500/7olVsWP4qnBI4cyVeMp2KUKOEnM.jpg', 'https://image.tmdb.org/t/p/original/bPLRjO2pcBx0WL73WUPzuNzQ3YN.jpg', '2014년 1월 HBO에서 방영을 시작한 형사물. 1995년과 2012년이라는 17년의 간극을 두고 연쇄살인마를 쫓는, 루이지애나 경찰국 소속 형사인 러스틴 콜과 마틴 하트의 이야기를 그린다.', '2014-01-12', 8.3, 44.7738, NULL, 'Nic Pizzolatto', 3910, 0);
