INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (2004, '말콤네 좀 말려줘', 'Malcolm in the Middle', 'drama', 'https://image.tmdb.org/t/p/w500/ck4iRhTXFD7CsEBi2iOdOXL7QhE.jpg', 'https://image.tmdb.org/t/p/original/ysaA0BInz4071p3LKqAQnWKZCsK.jpg', '늘 사건사고가 일어나는 말콤네 가족 특히 사고 뭉친 4형제로 인하여 말콤네 가족은 늘 시끌벅적합니다. 후에 말코의 4형제는 5형제가 됩니다.', '2000-01-09', 8.463, 44.343, NULL, 'Linwood Boomer', 4695, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (48891, '브루클린 나인-나인', 'Brooklyn Nine-Nine', 'drama', 'https://image.tmdb.org/t/p/w500/A3SymGlOHefSKbz1bCOz56moupS.jpg', 'https://image.tmdb.org/t/p/original/wyspZaGs7CXceV3Ct7NJhcKNDkn.jpg', '경찰의 명예를 중시하는 원칙주의자 홀트 서장. 그 아래 재능은 물론 꼼수, 공갈, 운까지 총동원해서 어떻게든 사건을 해결해내는 듬직한(?) 형사들이 있는 곳. 브루클린 99 관할 경찰서에 오신 것을 환영합니다!', '2013-09-17', 8.218, 44.1046, NULL, 'Daniel J. Goor', 3800, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1447, '싸이크', 'Psych', 'drama', 'https://image.tmdb.org/t/p/w500/fDI15gTVbtW5Sbv5QenqecRxWKJ.jpg', 'https://image.tmdb.org/t/p/original/sh7GRlX4d7j3XSTeyGZnlKqkHGk.jpg', '숀은 자신의 아버지가 경찰이어서 매일 집중력 훈련을 받게 된다. 그 결과 엄청난 관찰력을 가지게 됬지만 경찰을 싫어한다. 우연히 자신의 능력으로 경찰에게 범인을 알려주지만 공범으로 몰릴뻔 하자 자신이 심령술사라고 말하며 경찰서에 들어오자마자 봤던 자료를 이용해 신뢰를 얻는다.  이로 인해 심령술사 사립탐정으로 일하게 되면서 벌어지는 일을 다룬 드라마.', '2006-07-07', 7.901, 45.6328, 43, 'Steve Franks', 923, 0);
