INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1435, '굿 와이프', 'The Good Wife', 'drama', 'https://image.tmdb.org/t/p/w500/lasNCd45fpPLirlA7QxkuopWro.jpg', 'https://image.tmdb.org/t/p/original/uinrziSwEmS6s8VvGBad5sed7bF.jpg', '스캔들로 철창신세가 된 정치인 남편 때문에 다시 변호사로 일하게 된 얼리샤 플로릭의 이야기를 담은 법정 드라마.', '2009-09-22', 7.581, 45.2395, 43, 'Michelle King', 651, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (61859, '나이트 매니저', 'The Night Manager', 'drama', 'https://image.tmdb.org/t/p/w500/1MccRnw41qQjREuZkovqP2UX1i3.jpg', 'https://image.tmdb.org/t/p/original/lJoaiZcYMc8RkmPLROcdS2WQxn9.jpg', '전직 군인 출신으로 호텔에서 일하고 있는 조나단 파인이 우연히 얻게 된 비밀문서의 내용을 알게 되면서 일어나는 일들을 다룬 첩보 드라마. 동명의 스파이 소설이 원작이다.', '2016-02-21', 7.752, 42.4874, NULL, 'David Farr', 1181, 0);
