INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (4586, '길모어 걸스', 'Gilmore Girls', 'drama', 'https://image.tmdb.org/t/p/w500/gwtzCwU2wdLLf8oejQu2TINiWfQ.jpg', 'https://image.tmdb.org/t/p/original/8U2ndZrneigI2zkvGuTJtt1ZsxK.jpg', '독립심이 강한 싱글맘 로렐라이는 아이비리그 진학은 문제없을 정도로 명석한 두뇌를 가진 딸 로리를 키운다. 이 모녀 사이에는 항상 재치 넘치는 대화가 끊이지 않는다.', '2000-10-05', 7.9, 44.2337, 44, 'Amy Sherman-Palladino', 1198, 0);
