INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (615, '퓨쳐라마', 'Futurama', 'drama', 'https://image.tmdb.org/t/p/w500/tJsAIv9xdefUUieS46zeFAlwU8O.jpg', 'https://image.tmdb.org/t/p/original/4xKG4S1IyLIglHbCYGJDsptgQNh.jpg', '피자 배달부 프라이는 1999년에 우연히 극저온에 냉동되었다가 천 년 후 멋진 신세계에서 깨어난다. 하지만 어떤 면에서는 20세기보다 딱히 나아진 것은 없다.', '1999-03-28', 8.367, 38.7215, NULL, '맷 그레이닝', 3602, 0);
