INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (56570, '아웃랜더', 'Outlander', 'drama', 'https://image.tmdb.org/t/p/w500/6u1IGxKAzaxnGg9M1I6p1bcuHxG.jpg', 'https://image.tmdb.org/t/p/original/nf3Vlxm3C9U1aKUUQHmKFZmxPSc.jpg', '제2차 세계대전, 평범한 간호사가 알 수 없는 힘으로 18세기 스코틀랜드 중세시대로 타임슬립하면서 겪는 이야기.

다이애나 개벌든(Diana Gabaldon)의 인기 판타지 로맨스 소설 시리즈를 각색한 서사시적 드라마로, 시간을 초월하여 만난 두 연인의 사랑 이야기를 다룬다. 어느 날 1743년으로 시간 여행을 하게 된 20세기 종군 간호사 클레어(Claire)는 자신이 심각한 위험에 처했음을 알게 된다.', '2014-08-09', 8.181, 36.9682, NULL, '로널드 D. 무어', 2757, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (4546, '커브 유어 엔수지애즘', 'Curb Your Enthusiasm', 'drama', 'https://image.tmdb.org/t/p/w500/mZqWmSq1M61Jlre3furVDSXvdrN.jpg', 'https://image.tmdb.org/t/p/original/t97VtC5qvra5GThnNBCXHJFnmXg.jpg', '래리는 새 파일럿 쇼 제작에 돌입한다. 그의 쇼는 아이템 제안 때부터 넷플릭스의 좋은 반응을 끌어내며 순조롭게 출발하지만, 전혀 예기치 않은 사고와 사건들 때문에 번번이 위기를 맞는다.', '2000-10-15', 8.036, 34.873, NULL, '래리 데이비드', 878, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (81044, '천장에서 떨어진 그녀 ~2층에서 여자가 떨어졌다!?~', 'じょしおちっ！～2階から女の子が・・・降ってきた！？～', 'drama', 'https://image.tmdb.org/t/p/w500/7x8x6dl4leOSw6KGUcOrQew7Eua.jpg', 'https://image.tmdb.org/t/p/original/AgTy5IsOv1FAx02gunir8ZSiUxG.jpg', '고물 아파트에 사는 나의 유일한 위안은 미인 집주인과 귀여운 2층 아이. 그러던 어느날, 천장이 삐걱거리는 소리가 나고… 뚝! 하고 밑바닥이 빠져 내 바로 위에 2층의 그 아이가 내려온다…!? 기적의 에로 해프닝으로, 우연히 연결되는 마음과 몸. 그리고, 왠지 시작되는 미녀 2명과의 공동생활!? 그리고 한지붕아래, 너무 농밀한 삼각관계의 앞날은...!?', '2018-07-02', 7.2, 37.7502, 7, NULL, 24, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (200709, '약한영웅', '약한영웅', 'drama', 'https://image.tmdb.org/t/p/w500/jXd83QZhBDAFno4OGqHcMMDs56i.jpg', 'https://image.tmdb.org/t/p/original/cLTAda6fMRirkCY1xfO4pmcHVkk.jpg', '연시은은 공부 외엔 관심이 없지만 걸어온 싸움을 피하지도 않는다. 타고난 두뇌로 유리한 상황을 만들고 주변 도구를 활용하여 자신을 보호하던 시은이지만 혼자이기에 결국 위기가 닥치고, 그 순간 또 다른 아웃사이더 안수호와 전학생 오범석의 도움을 받는다. 그렇게 정글 같은 학교에서 살아남기 위해 따로 또 같이 싸우던 이들 사이에 묘한 우정이 싹튼다.', '2022-11-18', 8.603, 39.0526, 41, '유수민', 341, 0);
