INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (74016, '더 레지던트', 'The Resident', 'drama', 'https://image.tmdb.org/t/p/w500/2IkYQJlT26yXef2iot7dhRtavSC.jpg', 'https://image.tmdb.org/t/p/original/9oVp0xfKW2igxDEo5wr3JTMQBub.jpg', '노련한 고참 레지던트가 이상으로 가득 찬 신참들의 교육을 맡는다. 레지던트와 신참 의사와 환자들의 이야기 중심으로 현대 의학과 병원의 진짜 모습을 드러내는 메디컬 드라마.', '2018-01-21', 8.4, 39.3616, 42, 'Roshan Sethi', 1284, 0);
