INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (2098, '배트맨: 애니메이션 시리즈', 'Batman: The Animated Series', 'drama', 'https://image.tmdb.org/t/p/w500/lBomQFW1vlm1yUYMNSbFZ45R4Ox.jpg', 'https://image.tmdb.org/t/p/original/jszr5nLTaK946h85MBl1K2dkvKN.jpg', '기존 아이들을 겨냥했던 슈퍼히어로물과의 차이를 두고 좀 더 시청연령을 높게 잡았던 이 작품은 슈퍼히어로물 애니메이션 역사상 처음으로 화약 총기류가 나온다. 적들에게 직접적으로 발차기와 주먹을 날렸고 유혈묘사도 처음으로 나오게 된 애니메이션이다. 어른이 보기에도 전혀 유치하지 않은 내용이다.

미국 TV 애니메이션 중 가장 많은 스핀오프를 가지고 있는 애니메이션이고 총 13개의 스핀오프가 있으며 지금도 잊을 만하면 한 번씩 나오고 있다.

이 작품에서 최초로 모습을 등장한 조커의 사이드킥이자 애인인 할리 퀸과 여형사 르네 몬토야는 이 작품을 통해 인기를 얻고 지금도 DC 코믹스에서 활약 중이다.', '1992-09-05', 8.557, 31.8801, NULL, '브루스 팀', 1759, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (3570, '달의 요정 세일러문', '美少女戦士セーラームーン', 'drama', 'https://image.tmdb.org/t/p/w500/oCgEdfayxG8GoPydrlF2ZjcJyCL.jpg', 'https://image.tmdb.org/t/p/original/sNCpbcCcRadDBMTh6An1dBMakqr.jpg', '지구의 평화를 지키기 위해 적과 싸우는 소녀들의 이야기를 그린 애니메이션', '1992-03-07', 8.4, 35.8182, 24, NULL, 998, 0);
