INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (8514, '루폴의 드래그 레이스', 'RuPaul''s Drag Race', 'drama', 'https://image.tmdb.org/t/p/w500/ySs9xkTfPgQCUNB2ctOzcMWP14n.jpg', 'https://image.tmdb.org/t/p/original/hEtBwhqAzHKihQ1H9QD2kj8bJ5.jpg', '독보적인 무대 장악력을 뽐내는 퀸들이 무한 경쟁에 나섰다. 이들의 목표는 10만 달러 상금과 ''미국의 차세대 드래그 슈퍼스타''라는 명예. 드래그 퀸의 대모 격인 루폴이 이들의 화려한 무대를 이끈다. 에미상 수상에 빛나는 리얼리티 쇼.', '2009-02-02', 7.5, 29.304, NULL, '루폴', 266, 0);
