INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (40075, '괴짜가족 괴담일기', 'Gravity Falls', 'drama', 'https://image.tmdb.org/t/p/w500/dROdoUSfh819CpeV8AqvQCulMEj.jpg', 'https://image.tmdb.org/t/p/original/l0XvAI856XdyDYEfr1njztjH7u0.jpg', '2012년 여름, 디퍼와 메이블의 부모님은 여름방학동안 쌍둥이 남매를 오리건 주의 ''그래비티 폴즈''라는 시골의 삼촌 할아버지 댁으로 보낸다. 그곳에서 남매는 그들의 삼촌 할아버지인 스탠의 집 겸 관광지인 수수께끼 가게의 다락방에서 여름을 보내게 된다.

스탠과 달리 평소 그래비티 폴즈에 대해 이상하게 생각했던 디퍼는 숲에서 표지에 황금색 육손 모양에 ''3''이라고 적혀진 책을 발견하였는데, 거기엔 그래비티 폴즈의 온갖 미스터리에 대해 적혀 있었다. 남매는 새로 사귄 친구들과 그래비티 폴즈에서 괴상한 일을 겪으면서 의문점을 하나하나 풀어가게 되는 이야기이다.', '2012-06-15', 8.608, 31.2347, 22, 'Alex Hirsch', 3348, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (21510, '화이트 칼라', 'White Collar', 'drama', 'https://image.tmdb.org/t/p/w500/4cSByoCuIztFmzKX4U6NlDQDL5p.jpg', 'https://image.tmdb.org/t/p/original/aUyweq31etaay92oF4crwdDcnoT.jpg', '매력적인 사기꾼 닐 카프리는 감옥에서 용케 도망치지만 숙적인 FBI 요원 피터 버크에게 다시 붙잡힌다. 별다른 선택지가 없자 그는 미래의 자유를 얻는 조건으로 FBI가 신출귀몰한 범죄자들을 체포하는 일에 협력한다. 하지만 그는 곧 자신을 감옥으로 돌려보내거나 죽길 바라는 자들의 손아귀에서 놀아나고 있을 뿐이라는 걸 깨닫는다.', '2009-10-23', 8.2, 30.1389, NULL, 'Jeff Eastin', 1499, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (2290, '스타게이트 아틀란티스', 'Stargate Atlantis', 'drama', 'https://image.tmdb.org/t/p/w500/l0JYr2iqwId6VOmCV8dHzlIM6Wd.jpg', 'https://image.tmdb.org/t/p/original/SLAPI1h9SWBMLTCO8ULvTGiP9G.jpg', '스타게이트 아틀란티스는 스타게이트 SG-1에 이어 제작된 드라마이다. 영화 스타게이트의 스토리를 이어 제작된 스타게이트 SG-1이 종영되기 전에 방영되기 시작했다. 페가수스 은하계를 무대로 스타게이트를 건설한 고대인들의 자취를 찾아 아틀란티스로 떠난 일행의 이야기이다.', '2004-07-15', 8.026, 29.0632, 45, 'Robert C. Cooper', 1118, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (94954, '해즈빈 호텔', 'Hazbin Hotel', 'drama', 'https://image.tmdb.org/t/p/w500/c9epbOyQ5E0jc6uC10D21MsKYuF.jpg', 'https://image.tmdb.org/t/p/original/tuCU2yVRM2iZxFkpqlPUyvd6tSu.jpg', '성인용 애니메이션 뮤지컬 시리즈 ''해즈빈 호텔''은 지옥의 공주 찰리가 넘쳐나는 지옥 왕국의 인구를 평화적으로 줄이기 위해 악령들을 재활한다는 불가능해 보이는 임무를 실행하는 모습을 보여준다. 천국에서 실시하는 연례행사인 ''전멸의 날''이 끝나자 찰리는 호텔을 연다. 손님들이 자신들도 구원받을 수 있다는 사실을 증명한 후 호텔을 떠나는 것이 찰리의 목표다.', '2024-01-18', 8.613, 30.6167, NULL, '비비안 메드라노', 1505, 0);
