INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (63351, '나르코스', 'Narcos', 'drama', 'https://image.tmdb.org/t/p/w500/uAofYGxO3pPWpwhUfRzkXGuMjvj.jpg', 'https://image.tmdb.org/t/p/original/qx8XQund44cecIJiX2Yb4SUeiT.jpg', '2015년 8월 Netflix에서 방영을 시작한 범죄수사물.  콜롬비아의 에스코바르와 로스 페페스는 세계 최대의 마약 제국을 건설하고 미국의 공공의 적이 된다. 그리고 이들을 잡기 위해 미국 마약단속국 DEA 요원 스티븐 머피와 하비에르 페냐가 작전에 투입된다. 카르텔과 양국 정부의 피비린내 나는 전쟁, 이것은 실화다.', '2015-08-28', 8.061, 29.0292, NULL, 'Chris Brancato', 3144, 0);
