INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (387824, '엄마친구', '엄마친구', 'movie', 'https://image.tmdb.org/t/p/w500/eLEqhVjleFUgxYWtgIgZ0gHdi3o.jpg', 'https://image.tmdb.org/t/p/original/4jnDdvXt9GAzePbUBMpGQ3gQtAg.jpg', '“엄마한테 이런 친구도 있었어?!”  파란만장하고 판타스틱한 대학생활을 꿈꾸던 스무살 성수. 하지만 상경하자마자 부동산 사기를 당하고 만다. 얼떨결에 엄마 손에 이끌려 엄마친구 자영의 집에 얹혀 살게 된 성수는 자영을 보는 순간 믿을 수 없는 초절정 동안과 섹시한 바디 라인에 빠져 들고 만다. 매일 마주치는 자영을 보며 그녀를 향한 은밀한 상상이 점점 도를 넘는 수준에 이르던 성수는 어느 날, 그녀가 은밀하게 숨겨온 놀랍고도 화끈한 비밀을 알게 되는데...', '2015-08-20', 7, 13.75, 82, 'Myeong Seok Hwan', 24, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1290182, '그 시절, 우리가 좋아했던 소녀', '그 시절, 우리가 좋아했던 소녀', 'movie', 'https://image.tmdb.org/t/p/w500/1aSRSDDHQX2egc1az05qQ5tz6zS.jpg', 'https://image.tmdb.org/t/p/original/rVhoq70ZDDVfeoEPS312PcR5yLE.jpg', '선아에게 고백하기까지 수많은 날을 보낸 철없던 진우의 열여덟 첫사랑 스토리. 각양각색 사춘기 소년들의 유일한 공통점은 같은 반 반장 선아를 좋아한다는 것! 어느 날, 고등학생 진우는 학교에서 작은 사고를 치게 되고, 이를 계기로 선아에게 특별 감시를 받게 된다. 문제아 진우를 비롯한 친구들은 모범생 선아의 사랑을 얻기 위해 고군분투하며 즐거운 학창 시절을 보내는데, 15년 뒤, 진우는 선아로부터 뜻밖의 고백을 듣게 된다.', '2025-02-21', 8.531, 12.5622, 102, '조영명', 49, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (287649, '마담 뺑덕', '마담 뺑덕', 'movie', 'https://image.tmdb.org/t/p/w500/trvtnsNZjHwvB97RLQ3Nc5oncti.jpg', 'https://image.tmdb.org/t/p/original/4GgiMYynlzp5RmaYNzPHkhW12j7.jpg', '불미스러운 오해에 휘말려, 지방 소도시 문화센터의 문학 강사로 내려온 교수 학규는 퇴락한 놀이공원의 매표소 직원으로, 고여있는 일상에 신물 난 처녀 덕이와 걷잡을 수 없는 사랑에 빠진다. 그러나 학규는 복직이 되자마자 서울로 돌아가고 덕이는 버림 받는다. 8년 후, 학규는 작가로 명성을 얻지만 딸 청이는 엄마의 자살이 아버지 탓이라 여기며 반항하고, 학규는 눈이 멀어져 가는 병까지 걸린다. 모든 것을 잃을 위기에 처한 학규의 앞 집으로 이사 온 여자 세정. 눈이 거의 보이지 않는 학규가 세정이 8년 전 덕이라는 걸 모른 채 그녀에게 의지하는 사이, 청이 또한 그녀에게 집착하게 된다. 덕이 없이 아무것도 못하게 된 학규, 그리고 두 사람 사이를 눈치채고 위험한 질투를 시작하는 청이. 세 사람의 위태로운 관계의 한 가운데, 마침내 주도권을 쥔 덕이는 학규의 모든 것을 망가뜨리려고 하는데…', '2014-10-02', 6.1, 12.8186, 111, '임필성', 67, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (897160, '용감한 시민', '용감한 시민', 'movie', 'https://image.tmdb.org/t/p/w500/oVJDtwC41sGx5zmWiEkhqwBlopD.jpg', 'https://image.tmdb.org/t/p/original/5d1sQtAKsbVjdUuzXWoh2vKtyy7.jpg', '불의는 못 본 척, 성질은 없는 척, 주먹은 약한 척 먹고 살기 위해 조용히 살아 온 기간제 교사 소시민. 법도 경찰도 무서울 것 하나 없는 안하무인 절대권력 한수강의 선을 넘는 행동을 목격하게 된다. 그의 계속되는 악행을 도저히 참을 수 없었던 그녀, 정체를 숨긴 채 통쾌한 한 방을 날리기로 마음 먹는데…', '2023-10-25', 7.531, 11.3493, 112, '박진표', 112, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1267319, '사마귀', '사마귀', 'movie', 'https://image.tmdb.org/t/p/w500/gRPSu4sG5iVnWyLv9um7t3L0yhH.jpg', 'https://image.tmdb.org/t/p/original/yOFqBpJ0PEkBdQqalDEaeOiaKbz.jpg', '하룻밤 사이 몰락한 청부살인 업계의 거물들. 그들이 세운 질서가 무너지고, 어둠의 세계가 흔들린다. 혼돈 속에서 기회를 노리는 실력자 ''사마귀''. 그의 손끝에서 새로운 킬러들의 시대가 열린다.', '2025-09-25', 6.28, 11.3467, 113, '이태성', 134, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1290183, '퍼스트 라이드', '퍼스트 라이드', 'movie', 'https://image.tmdb.org/t/p/w500/ulJqKW1VEDBiUaa781VHX7GkM1C.jpg', 'https://image.tmdb.org/t/p/original/7P5QkzsMJf6ssyzQomLgaJWmQvC.jpg', '어린 시절부터 한 몸처럼 붙어 다닌 24년 지기 사총사, 태정, 도진, 연민, 금복의 꿈은 바로 함께 하는 여행! 학창 시절에 이루지 못했던 꿈을 위해 생애 첫 해외여행을 떠나는 날, 계획에 없던 옥심까지 합류하며 이들의 여행은 점점 환장의 세계로 흘러가는데…!', '2025-10-29', 6.6, 11.2565, 117, '남대중', 5, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (508642, '곤지암', '곤지암', 'movie', 'https://image.tmdb.org/t/p/w500/llj8dIkLSHOG1X7aFXims2IaCU5.jpg', 'https://image.tmdb.org/t/p/original/x1j5VVU4ypEx1hM0PDYGwCJvwtS.jpg', '1979년 환자 42명의 집단 자살과 병원장의 실종 이후, 섬뜩한 괴담으로 둘러싸인 곤지암 정신병원으로 공포체험을 떠난 7명의 멤버들. 원장실, 집단 치료실, 실험실, 열리지 않는 402호. 괴담의 실체를 담아내기 위해 병원 내부를 촬영하기 시작하던 멤버들에게 상상도 못한 기이하고 공포스러운 일들이 실제로 벌어지기 시작 하는데…', '2018-03-28', 7.286, 10.882, 94, '정범식', 872, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (49797, '악마를 보았다', '악마를 보았다', 'movie', 'https://image.tmdb.org/t/p/w500/xAhsrqrsMIO7YwKbLAlWatzFbgX.jpg', 'https://image.tmdb.org/t/p/original/ylqOWMU3nyZqg8hjJBG4EPdsGSk.jpg', '국정원 경호요원 수현은 약혼녀 주연이 잔인하게 살해당하자 자신에게 가장 소중한 사람을 지켜내지 못했다는 자괴감과 분노로 가장 고통스러운 복수를 다짐한다. 수현은 연쇄살인마 장경철이 범인임을 알아내고 죽을 만큼의 고통만 가하고 놓아주기를 반복하며 처절한 응징을 시작한다. 그러나, 악마보다 더 악랄한 살인마 장경철은 난생 처음 만난 대등한 적수의 출현을 즐기며 반격에 나서기 시작하는데…', '2010-08-12', 7.788, 11.8805, 144, '김지운', 2880, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (308624, '옹녀뎐', '옹녀뎐', 'movie', 'https://image.tmdb.org/t/p/w500/rtl4hW2KJHInieeCiGgrDJmMG7s.jpg', 'https://image.tmdb.org/t/p/original/w4X3j3ECvmEJMLabhbLB94iGcMV.jpg', '변강쇠를 능가하는 음녀 ‘옹녀’의 귀환!  조선 최고의 색남색녀의 이야기가 지금 시작된다!  한 손으론 감당할 수 없는 풍만한 가슴과 한 줌에 잡힐 듯한 잘록한 허리, 그리고 완벽한 곡선을 그리는 엉덩이까지! 그야말로 신이 내린 섹시한 몸매를 타고난 원조 ''베이글녀''가 있었으니 이름하야 바로 옹녀! 평범하게 살기엔 심하게 새끈하고 과하게 섹시한 옹녀와 그녀의 절친 을령은 온 동네 남자들의 음흉한 시선을 즐기며 화려한 밤생활을 즐기고 있다. 그러나 모든 남자를 자신의 치마폭으로 끌어들일 수 있는 무적의 옹녀에게도 단 한 가지 말 못할 비밀이 있었으니, 바로 그녀의 진정한 욕구를 감당할 남자가 이 세상에 없다는 것이다.', '2014-08-21', 5, 9.1495, 94, 'Gyeong Seok-Ho', 5, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (286687, '화려한 외출', '화려한 외출', 'movie', 'https://image.tmdb.org/t/p/w500/1bMvC9fOTQSfwIGwXBJNcy2cV9N.jpg', 'https://image.tmdb.org/t/p/original/4fza1QWpGAoxReiEsnvdFBeMyfX.jpg', '화려한 겉과 달리 외로움에 빠져 있던 한 여인이  우연히 마주친 소년에게 사랑을 가르쳐주면서 진정한 사랑을 다시 느끼는  19금 힐링 로맨스  완성한 곡마다 히트를 기록하는 잘 나가는 작곡가, 희수!  그러나 새로운 곡을 써야 하는 상황에 직면했으나 아무래도 영감이 떠오르지 않는다.  외로움에 익숙해지다 못해 연애세포가 죽어가는 것 같은 이 기분을 어쩌지?  감정을 다 소모해버린 것 같은 허탈감에 젖어있던 희수는 아파트 엘리베이터에서 우연히 소년과 마주치고,  자신의 육감적 몸매에 흔들리는 소년의 눈빛에서 새로운 노래의 영감을 발견한다.  소년에게 음악을 가르쳐주는 것을 핑계로, 러브 레슨을 시작한 희수!  시간이 흐를수록 소년은 희수에게 빠져들고 희수는 소년을 보며 새로운 곡을 완성해나간다.  그런데, 희수에게 음악과 사랑을 가르쳐 주었던 인생의 스승 준호가 돌아왔다?  외로움에 무감각해져 가던 희수에게 가슴 떨리는 사랑을 다시 불러일으킬 남자는 과연 누구?!  작곡가 희수, 그녀의 짜릿한 음악이 지금 시작된다!', '2013-12-05', 6.8, 10.5647, 80, 'Ko Kyeong-Ah', 42, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1017163, '범죄도시 4', '범죄도시 4', 'movie', 'https://image.tmdb.org/t/p/w500/jucHQwnRSma1O9V2bM007e4eSd7.jpg', 'https://image.tmdb.org/t/p/original/mO9oOVXM8tTlC11VFM4FBBNnL3f.jpg', '신종 마약 사건 3년 뒤, 괴물형사 마석도와 서울 광수대는 배달앱을 이용한 마약 판매 사건을 수사하던 중 수배 중인 앱 개발자가 필리핀에서 사망한 사건이 대규모 온라인 불법 도박 조직과 연관되어 있음을 알아낸다. 필리핀에 거점을 두고 납치, 감금, 폭행, 살인 등으로 대한민국 온라인 불법 도박 시장을 장악한 특수부대 용병 출신의 빌런 백창기와 한국에서 더 큰 판을 짜고 있는 IT업계 천재 CEO 장동철. 마석도는 더 커진 판을 잡기 위해 장이수에게 뜻밖의 협력을 제안하고 광역수사대는 물론, 사이버수사대까지 합류해 범죄를 소탕하기 시작하는데…', '2024-04-24', 7.12, 10.6359, 109, '허명행', 220, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (698818, '음란 주택: 노예가 된 아내', '음란 주택: 노예가 된 아내', 'movie', 'https://image.tmdb.org/t/p/w500/1VfuzK2Qx1tIGE1nhn2G2ilF7RN.jpg', 'https://image.tmdb.org/t/p/original/77xFxLtD2jGpOrcjJbCez2wZWX1.jpg', '지방의 한 맨션으로 이사를 오게 된 현정은 뜻밖의 행운에 쾌재를 부르고 있었다. 층간 소음문제로 한바탕 홍역을 치렀던 탓에, 방음시설이 재대로 되어있는 조용한 집을 소망했던 그녀. 입주자 대부분이 맞벌이 부부인 때문인지, 한 낱의 맨션은 유령의 도시처럼 조용하다.  "사람이 살기는 하는 건가?" 의아한 생각에 이웃들을 살펴보니, 방음이 잘 되는 게 아니라 숨을 죽이고 살았던 것. 잠시 집을 비우고 돌아와 보니 누군가 집에 들어와 뒤진 흔적이 생생하게 남겨져 있다. 득달같이 관리실로 달려가 따져보니 외부인의 침입은 없었다는 대답과 함께 현관엔 주민들의 경고장이 붙어있다. ※ 경고 - 신혼인건 알겠는데 조용히 좀 삽시다! 누군가 자신의 일거수일투족을 감시하고 있다는 생각에 숨이 막혀오는 현정. 아파트 여자들의 비밀과 약점을 움켜쥐고 제왕처럼 군림하는 ''관리인''의 존재가 서서히 그 실체를 드러내는데…', '2020-02-06', 7, 11.4815, 72, 'Han Dong-Ho', 3, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1264805, '만약에 우리', '만약에 우리', 'movie', 'https://image.tmdb.org/t/p/w500/qUY4Q99ZO5MtsMdLiwjIExMO5uT.jpg', 'https://image.tmdb.org/t/p/original/5ziZTaQ7zb3IUMkw6IEimFktNMS.jpg', '고향 가는 고속버스에 올라탄 은호와 휴학 후 어디론가 떠날 결심을 한 정원, 나란히 앉게 된 두 사람은 뜻밖의 인연을 맺는다. 서로의 꿈을 응원하며 의지하던 두 사람은 어느새 일상 깊숙이 스며들어 연인으로 발전한다. 웃고, 싸우고, 화해하며 세상을 다 가진 듯 뜨겁게 사랑하지만, 현실의 벽 앞에 두 사람은 결국 다른 길을 선택하게 된다. 그렇게 10년이 지난 후, 다시 마주한 순간 은호는 정원에게 오랫동안 묻어두었던 한마디를 꺼낸다.', '2025-12-31', 8, 11.5834, 115, '김도영', 1, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (911835, '숙모', '숙모', 'movie', 'https://image.tmdb.org/t/p/w500/zTZqwdxVPs0Qmx4gVejnWWdmudD.jpg', 'https://image.tmdb.org/t/p/original/ogaulvh5g9Z7PxLBybF7qOxuHs9.jpg', '첫 휴가를 나온 영철은 자대 복귀 전, 숙모 집에 며칠 간 신세를 지게 된다.  미망인으로 살아가는 숙모는 성적인 외로움을 달래기 위해, 조카지만 훌쩍 커서 남성미를 물씬 뿜기는 군인으로 나타난 영철에게 점점 성적인 매력을 느끼게 된다.  스물한 살이 되도록 동정을 떼지 못한 영철도 숙모의 성숙한 여성미에 매력을 느끼게 되고, 숙모의 유혹에 빠져 영철은', '2021-07-28', 7.5, 10.8482, 96, 'Lee Sang-soo', 2, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (799379, '늑대사냥', '늑대사냥', 'movie', 'https://image.tmdb.org/t/p/w500/op2y1gvqKhAh4yAPLwc4PlX3XRv.jpg', 'https://image.tmdb.org/t/p/original/mIW7eFxHnNqlwKwKWb6dpVjmHao.jpg', '동남아시아로 도피한 인터폴 수배자들을 이송할 움직이는 교도소 프론티어 타이탄. 극악무도한 이들과 베테랑 형사들이 필리핀 마닐라 항구에 모이고 탈출을 꿈꾸는 종두, 한국으로 돌아가야만 하는 도일을 비롯해 이들은 각자의 목적과 경계심을 품고 탑승한다. 한국으로 향하던 중, 태평양 한 가운데에서 이들에게는 지금까지 보지 못한 극한의 상황과 마주하게 되는데…', '2022-09-21', 6.415, 9.9651, 122, '김홍선', 420, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (110415, '설국열차', '설국열차', 'movie', 'https://image.tmdb.org/t/p/w500/jw66dQvYyXkZNA0bJ7nKvua9jDr.jpg', 'https://image.tmdb.org/t/p/original/33dV6HAnXBmwKl640gO3U4auqUN.jpg', '기상 이변으로 모든 것이 꽁꽁 얼어붙은 지구, 살아남은 사람들을 태운 기차 한 대가 끝없이 궤도를 달리고 있다. 춥고 배고픈 사람들이 바글대는 빈민굴 같은 꼬리칸, 그리고 선택된 사람들이 술과 마약까지 즐기며 호화로운 객실을 뒹굴고 있는 앞쪽칸. 열차 안의 세상은 결코 평등하지 않다. 기차가 달리기 시작한 17년째, 꼬리칸의 젊은 지도자 커티스는 긴 세월 준비해 온 폭동을 일으킨다. 기차의 심장인 엔진을 장악하고 기차 전체를 해방시키기 위해 절대권력자 윌포드가 도사리고 있는 엔진 칸을 향해 질주하는 커티스와 꼬리칸 사람들. 그들 앞에 예기치 못한 상황들이 기다리고 있는데...', '2013-08-01', 6.9, 9.9903, 127, '봉준호', 10183, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (122126, '후궁: 제왕의 첩', '후궁: 제왕의 첩', 'movie', 'https://image.tmdb.org/t/p/w500/tkkUBkGMnoaxwzClDMFZ0HKlXG8.jpg', 'https://image.tmdb.org/t/p/original/zgx6bBaVLAsFO5ip7gwndOjhE7U.jpg', '부모의 강요로 후궁이 되어야 하는 화연(조여정)은 오랜 연인인 권유(김민준)와 헤어져 궁으로 들어간다. 왕의 이복동생인 성원대군(김동욱)은 화연을 사랑하지만, 형수가 된 그녀를 어쩔 수는 없다. 5년 뒤, 선왕의 승하와 함께 성원대군은 왕위에 오른다. 섭정의 명목으로 왕의 머리 위에 오른 대비(박지영)와 그녀의 간신들이 선왕의 세력들을 처단하는 가운데, 화연 또한 위기에 놓인다. 하지만 여전히 그녀를 사랑하는 성원대군은 무능한 왕이고, 내시가 되어 궁에 들어온 옛 연인 권유는 화연과 화연의 부모를 향해 이를 갈고 있는데...', '2012-06-06', 5.877, 11.1649, 122, '김대승', 106, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (615173, '마녀(魔女) Part2. The Other One', '마녀(魔女) Part2. The Other One', 'movie', 'https://image.tmdb.org/t/p/w500/cah6iIYQBctvCmBjsKGb1NCiygr.jpg', 'https://image.tmdb.org/t/p/original/iryef4LKiPQkvhNJS1EtLlay3br.jpg', '자윤이 사라진 뒤, 정체불명의 집단의 무차별 습격으로 마녀 프로젝트가 진행되고 있는 아크가 초토화된다. 그곳에서 홀로 살아남은 소녀는 생애 처음 세상 밖으로 발을 내딛고 우연히 만난 경희의 도움으로 농장에서 지내며 따뜻한 일상에 적응해간다. 한편, 소녀가 망실되자 행방을 쫓는 책임자 장과 마녀 프로젝트의 창시자 백총괄의 지령을 받고 제거에 나선 본사 요원 조현, 경희의 농장 소유권을 노리는 조직의 보스 용두와 상해에서 온 의문의 4인방까지 각기 다른 목적을 지닌 세력이 하나 둘 모여들기 시작하면서 소녀 안에 숨겨진 본성이 깨어나는데…', '2022-06-15', 7.347, 9.9152, 137, '박훈정', 412, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (491584, '버닝', '버닝', 'movie', 'https://image.tmdb.org/t/p/w500/AlKlezuaJkP2lDEWbJxYv47GeDf.jpg', 'https://image.tmdb.org/t/p/original/rENYZSx6HFME7YLbbY0qGYayL7F.jpg', '유통회사 알바생 종수는 배달을 갔다가 어릴 적 같은 동네에서 살았던 친구 해미를 만난다. 종수는 해미에게서 아프리카 여행을 간 동안 자기가 키우는 고양이를 돌봐 달라는 부탁을 받는다. 여행에서 돌아온 해미는 아프리카에서 만난 벤이라는 정체불명의 남자를 종수에게 소개한다. 어느 날 벤은 해미와 함께 종수의 집으로 찾아와 자신의 비밀스러운 취미에 대해 고백한다. 그때부터 종수는 무서운 예감에 사로잡히게 되는데...', '2018-05-17', 7.372, 9.5735, 148, '이창동', 1755, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (335117, '맛있는 택배', '맛있는 택배', 'movie', 'https://image.tmdb.org/t/p/w500/pbU2UBygdGERFZkGLRXXYlj4aVz.jpg', 'https://image.tmdb.org/t/p/original/narlvb3rgIPkTjK5yCJRqcHlFnS.jpg', '물건 배달해 주다가 몸까지 줘버린 택배 청년! 섹(!)기발랄 택배 라이프 속에서 진짜 사랑을 찾을 수 있을까?  아버지의 사업 부도로 여친에게도 차이고 학교도 휴학하게 된 ‘절대 훈남’ 임혁. 부모님을 돕고자 택배 아르바이트를 시작하면서 그의 인생이 180도 바뀐다. 택배 받는 걸 유일한 낙으로 여기며 살던 무료한 여인들에게 물건 배송 외의 특별한 서.비.스.까지 제공하게 된 것! 혁을 공유하며 ‘고추자매’가 된 아파트 큰언니들, 섹시한 옛 여친 희선, 그리고 비밀을 간직한 청순녀 태희까지! 5명의 그녀들과 함께 하는 혁의 5감만족 택배 라이프가 지금 시작된다.', '2015-04-02', 4.143, 10.1085, 84, 'Gi Dae-ho', 7, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (851644, '20세기 소녀', '20세기 소녀', 'movie', 'https://image.tmdb.org/t/p/w500/rSNtRQpCsDckczokmynAcVAt4Fm.jpg', 'https://image.tmdb.org/t/p/original/37y53Jt8K6MvN6s4zJVFa61luO2.jpg', '보라의 둘도 없는 친구 연두는 심장 수술을 위해 미국에 가면서 자신이 좋아하는 남자 백현진에 대한 모든 정보를 수집해 달라고 보라에게 부탁한다. 보라는 백현진의 가장 친한 친구 풍운호와 먼저 친해지기로 한다. 하지만 보라의 서투른 계획은 예상치 못한 방향으로 전개된다. 새로운 세기가 오기 1년 전인 1999년, 17세가 된 보라는 첫사랑의 열병에 빠진다.', '2022-10-06', 8.139, 9.5571, 119, 'Bang Woo-ri', 784, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (479718, '범죄도시', '범죄도시', 'movie', 'https://image.tmdb.org/t/p/w500/sVwbHA4nhw389PwpDzkJam4WMoB.jpg', 'https://image.tmdb.org/t/p/original/xord8lZ7mK8ctki6FBgNYrbpWCO.jpg', '2004년 서울. 중국 하얼빈에서 활동하다 피신한 신흥 범죄조직의 악랄한 보스 장첸. 가리봉동 일대로 넘어온 장첸과 그의 일당들은 단숨에 기존 조직들을 장악하고 가장 강력한 세력인 춘식이파 보스 황사장까지 위협하며 도시 일대의 최강자로 급부상한다. 한편 대한민국을 뒤흔든 장첸 일당을 잡기 위해 오직 주먹 한방으로 도시의 평화를 유지해 온 괴물형사 마석도와  인간미 넘치는 든든한 리더 전일만 반장이 이끄는 강력반은 눈에는 눈 방식의  소탕 작전을 기획하는데...', '2017-10-03', 7.677, 9.8471, 121, '강윤성', 503, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (726139, '탈출: 프로젝트 사일런스', '탈출: 프로젝트 사일런스', 'movie', 'https://image.tmdb.org/t/p/w500/rXuSca6qEb4xPrSRT7XRzYCFbZB.jpg', 'https://image.tmdb.org/t/p/original/39CRS71VP0d9VOsJ5TVgD8IaQnT.jpg', '한치 앞도 구분할 수 없는 짙은 안개 속 붕괴 직전의 공항대교에 고립된 사람들이 그 안에 도사리고 있는 예기치 못한 위협으로부터 살아남기 위해 고군분투하는 이야기.', '2024-07-11', 6.934, 9.7267, 96, '김태곤', 377, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (646315, '전설의 라이타', '전설의 라이타', 'movie', 'https://image.tmdb.org/t/p/w500/h5fCwKCnKAKxdX6onTnrU6MeYe8.jpg', 'https://image.tmdb.org/t/p/original/pe3cTrUeAHHLycZVEmFjT9kEV7a.jpg', '맨주먹계의 전설적인 인물 채성빈(라이타). 아버지 같은 남자 마석준의 충고를 받아들여 이제는 평범한 삶을 살기로 결심한다. 그러던 중 우연히 골목에서 일진들에게 괴롭힘을 당하는 박주민을 구해주게 되고, 그를 계기로 박주민의 누나 박진아와 가까운 사이가 된다. 한편 박진아는 지역개발 이권 다툼에 휘말려 고통 받고 있었고 그 강도가 심해져 목숨까지 위협받는 처지가 된다. 끊임없는 조폭들의 위협으로 하루하루가 지옥 같던 박진아의 곁에 전설의 주먹 채성빈이 등장하게 되고, 채성빈은 사랑하는 박진아를 위해 마지막으로 다시 한번 라이타를 손에 쥐게 된다.', '2019-10-29', 6, 8.5482, 109, 'Chae Ki-jun', 3, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (554776, '정사 : 처제의 사랑', '정사 : 처제의 사랑', 'movie', 'https://image.tmdb.org/t/p/w500/4roDAaF9Kpvd9ob6XLkoCRoDLkn.jpg', 'https://image.tmdb.org/t/p/original/i5xLukHWqHbJaFO1T4yIZb34uOf.jpg', '', '2018-07-26', 4.9, 9.3382, 73, 'Choi Min', 9, 0);
