INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (481871, '엄마의 직업', '엄마의 직업', 'movie', 'https://image.tmdb.org/t/p/w500/oIoJrYsyg34fe66BWndCit1ekUD.jpg', 'https://image.tmdb.org/t/p/original/gLwJ5SsmTqqUVn3lahlBacYSrGH.jpg', '"누나를 가지고 싶어요" "나 의지가 약해, 유혹하지 말아줘" 막 군대를 전역하고 학교로 복학한 대학생 현우. 어려운 가정 형편으로 인해 술집 아르바이트를 시작하게 되고 그 곳에서 운명의 여인 마담 유선을 만난다. 현우는 그녀의 거부할 수 없는 치명적인 매력에 점점 빠져들게 되지만 술집에 놀러온 친구 민석과 그를 접대하기 위해 온 유선의 충격적인 관계를 알게 된다. 유선이 얼마 전 미국에서 돌아온 민석의 엄마였던 것. 얼마 뒤 두 사람의 사이를 전혀 모르는 민석은 현우에게 자신의 집에서 함께 살자는 제안을 하게 되고, 이를 받아들인 현우는 유선과 위험하고도 아찔한 동거를 시작하게 되는데...', '2017-07-27', 5.8, 9.4148, 79, 'Do Bong-san', 15, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1151766, '살인자 리포트', '살인자 리포트', 'movie', 'https://image.tmdb.org/t/p/w500/rcmJRflS4aFJg8Ockk7YePQWlzc.jpg', 'https://image.tmdb.org/t/p/original/xIoUKseV9rnhDmWP9udh5IhtjiH.jpg', '특종에 목마른 위기에 기자 백선주에게 자신이 연쇄살인범이라고 주장하는 정신과 의사 이영훈이 새로운 살인 예고와 함께 인터뷰 요청을 한다. 고민 끝에 선주는 호텔 스위트 룸에서 살인자와의 인터뷰를 시작하고, 그의 살인 동기가 환자의 치료 목적으로 시작되었다는 믿기지 않는 고백을 듣게 된다. 인터뷰가 진행될수록 무언가 잘못됨을 느끼고 도망가려던 선주는 지금 인터뷰를 멈추면 또 한 명이 살해될 것이라는 영훈의 충격적인 얘기를 듣게 되는데…', '2025-09-05', 6.881, 10.4789, 108, 'Cho Young-jun', 21, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (715253, '유령', '유령', 'movie', 'https://image.tmdb.org/t/p/w500/yIwKMwAA3XESJSvnVnhlchVTWC9.jpg', 'https://image.tmdb.org/t/p/original/wFzI8o0jEMYfNugglP4wjFIr647.jpg', '1933년, 일제강점기 경성. 항일조직 흑색단의 스파이인 유령이 비밀리에 활약하고 있다. 새로 부임한 경호대장 카이토는 흑색단의 총독 암살 시도를 막기 위해 조선총독부 내의 유령을 잡으려는 덫을 친다. 영문도 모른 채, 유령으로 의심받고 벼랑 끝 외딴 호텔에 갇힌 용의자들. 총독부 통신과 감독관 쥰지, 암호문 기록 담당 차경, 정무총감 비서 유리코, 암호 해독 담당 천계장, 통신과 직원 백호. 이들에게 주어진 시간은 단 하루 뿐. 기필코 살아나가 동지들을 구하고 총독 암살 작전을 성공시켜야 하는 유령과 무사히 집으로 돌아가고 싶은 이들 사이, 의심과 경계는 점점 짙어지는데…', '2023-01-18', 6.875, 9.3708, 132, '이해영', 64, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (471413, '선 섹스 후 사랑', '선 섹스 후 사랑', 'movie', 'https://image.tmdb.org/t/p/w500/lLMUPdwwyDaBlsuFL44e530cQmN.jpg', 'https://image.tmdb.org/t/p/original/qRfoBlSvthAVYnV9bVLPaKrbZvV.jpg', '사람은 쉽게 사랑에 빠져도  진짜 사랑을 만나기는 어렵다!  언더웨어 디자인회사에서 근무하고 있는 공수는 같은 회사 동료인 신입 디자이너 수연을 짝사랑한다. 대기업 디자인PT를 준비하던 공수는 수연에게 자신의 마음을 고백하기로 결심하고 호시탐탐 고백할 기회를 노리지만 그 기회는 잘생기고 능력까지 갖춘 직장 상사인 이과장에 의해 매번 무산되고 만다. 어느날 실의에 빠져 살던 공수에게 운명처럼 마법팔찌가 나타나고 마법팔찌가 가진 놀랍고 신비로운 힘을 이용해 자신의 욕망을 조금씩 채워나가는 공수는 팔찌의 힘을 빌어 수연에게 다가가게 되는데...', '2017-08-03', 5.2, 9.4209, 97, 'Kim Hyeon-cheol', 10, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (919207, '서울의 봄', '서울의 봄', 'movie', 'https://image.tmdb.org/t/p/w500/ukVVnY9ovwl78WE5KndcpA6SnAm.jpg', 'https://image.tmdb.org/t/p/original/yOn8w3aGd6Rf9JYki7XaC9ZiyDg.jpg', '박 대통령의 암살 이후, 계엄령이 선포된다. 국군보안사령관 전두광과 그를 따르는 장교들에 의해 쿠데타가 일어나고 군대가 정치적 행동을 해선 안된다고 믿는 완고한 군인인, 수도방위사령관 이태신은 전두광을 막기 위해 그와 맞서기로 한다. 그들의 갈등이 점차 심화되고, 대혼란 속에서 모두가 갈망하던 서울의 봄은 예상치 못한 방향으로 흘러간다.', '2023-11-22', 7.485, 9.1287, 141, '김성수', 137, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (27027, '미인', '미인', 'movie', 'https://image.tmdb.org/t/p/w500/eX7ivkIqIDCZzW2yYlD6vf7T9Oq.jpg', 'https://image.tmdb.org/t/p/original/pIBWtyqCFY3YvOA0smV0URuTJvI.jpg', '작가인 남자(오지호)는 글을 쓰기 위해 누드 모델인 여자(이지현)를 인터뷰하면서 그녀가 실연당한 여자라는 것을 알게 된다. 남자는 그녀를 사랑하게 되고 어느 날 그녀는 남자의 집에 들어와 동거를 시작한다. 하지만 그녀는 여전히 옛남자를 잊지 못하고 두 사람은 서로의 육체를 탐닉한다. 어느 날 여자는 옛남자에게 구타를 당하고 남자는 그를 죽인다. 오랫만에 해변에서 행복한 시간을 보낸 후 남자는 여자의 목을 졸라 죽이고 그녀를 영원히 소유하려 한다.', '2000-08-12', 5.6, 8.0262, 91, '여균동', 19, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (936245, '히든페이스', '히든페이스', 'movie', 'https://image.tmdb.org/t/p/w500/rkuzlpvaAQIbamiRvEFPqzv4zVk.jpg', 'https://image.tmdb.org/t/p/original/jgySLjw9ZDKbnGf0VlhlHT7iHSi.jpg', '지휘자 성진이 이끄는 오케스트라의 첼리스트이자 약혼녀 수연이 어느 날 영상 편지만을 남겨둔 채 자취를 감춘다. 성진은 수연을 잃은 상실감에 고통스러워하지만, 그녀를 대신한 첼리스트 미주에게 강한 끌림을 느낀다. 비 오는 밤, 서로의 욕망에 휩쓸린 성진과 미주는 수연의 집에서 용서받지 못할 짓을 저지른다. 한편 사라진 줄 알았던 수연은 혼자서는 절대 나올 수 없는 집 안 밀실에 갇혀 숨겨진 민낯을 지켜보는데...', '2024-11-20', 4.907, 9.5379, 113, '김대우', 59, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (17903, '쌍화점', '쌍화점', 'movie', 'https://image.tmdb.org/t/p/w500/vu9PrY7MEmDInys0w92cYCDI8XJ.jpg', 'https://image.tmdb.org/t/p/original/9bvn5SWwAK6qB79UevNi0jqhfke.jpg', '격정의 고려말, 왕과 왕의 호위무사 ''홍림''. 원의 억압을 받던 고려 말, 친위부대 건룡위의 수장 ''홍림''은 대내외적 위기에 놓인 왕을 보필하며 경계를 늦추지 않는다. 그러나 후사문제를 빌미로 원의 무리한 요구는 계속되고, 정체불명의 자객들이 왕의 목숨을 위협하자, 왕은 중대한 결정을 내리게 된다.  거부할 수 없는 선택, 엇갈린 운명. 왕의 명령이라면 목숨처럼 따르는 홍림, 왕은 고려의 왕위를 이을 원자를 얻기 위해 홍림에게 왕후와의 대리합궁을 명한다. 충격과 욕망이 엇갈린 그날 밤, 세 사람의 운명은 소용돌이 치기 시작하는데...', '2008-12-30', 6.856, 9.0114, 132, '유하', 153, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (142093, '애인', '애인', 'movie', 'https://image.tmdb.org/t/p/w500/b7SAyFvG1hCnCdA3FbVeJFPlWfQ.jpg', 'https://image.tmdb.org/t/p/original/kScVB7SdGhCk7nOWpCuxKIXFq2u.jpg', '춥지 않은 날씨임에도 단추를 목 끝까지 맨, 한치의 흐트러짐도 없는 여자. 여자는 같은 엘리베이터를 탄 매력적인 남자에게 묘한 기분을 느낀다. 같은날 헤이리에서의 또 한번의 우연, 소심하고 조용한 자신에게 가볍게 작업을 걸어오는 남자가 싫지 않다. 당당하고 유쾌한 남자에게 너무도 쉽게 끌려버린 그녀는 즉흥적으로 섹스를 허락하게 되는데...  7년을 사귄 남자가 있고, 그와의 결혼을 한달 앞두고 있는데 처음본 남자에게 자꾸 끌리는 까닭은 무엇일까? 고민을 하기엔 그와 보낼 수 있는 시간이 너무도 짧다. 첫 눈에 상대를 알아보고, 단숨에 사랑을 느끼고 사랑을 확인하는 여자와 남자…. 하루라는 짧은 시간 동안 서로에게 빠져버린 여자와 남자, 과연 내 남자 모르게 애인을 가슴 깊이 숨겨둘 수 있을까?', '2005-12-08', 6.1, 8.9435, 98, 'Kim Eun-tae', 32, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (486589, '레드슈즈', '레드슈즈', 'movie', 'https://image.tmdb.org/t/p/w500/3yZ54uGQ4HxEbpNVO565mU1xagp.jpg', 'https://image.tmdb.org/t/p/original/nN4Gs3vZAOJ1D6FRtrwbU9VGYwU.jpg', '사건 사고가 끊이지 않는 동화의 섬. 사라진 아빠를 찾던 화이트 왕국의 공주는 우연히 마법구두를 신고 이전과 완벽하게 다른 ‘레드슈즈’로 거듭난다. 한편, 초록색 난쟁이가 된 일곱 왕자들은 우연히 자신들의 집에 머물게 된 ''레드슈즈’가 저주를 풀 유일한 희망이라 생각해 그녀를 돕기 시작하고, 영원한 아름다움을 꿈꾸는 왕비 ‘레지나’는 마법구두를 신고 성을 빠져나간 ‘레드슈즈’를 쫓기 시작하는데…', '2019-07-25', 7.7, 7.111, 92, '홍성호', 1122, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (285213, '해적: 바다로 간 산적', '해적: 바다로 간 산적', 'movie', 'https://image.tmdb.org/t/p/w500/yMydhXOFTKPxxFBJiBMKv2JM7sl.jpg', 'https://image.tmdb.org/t/p/original/8UfYtyCeWGbhfyyq0u0xYwEYaZb.jpg', '전대미문 국새 강탈 사건으로 조정은 혼란에 빠지고, 이를 찾기 위해 조선의 난다긴다 하는 무리들이 바다로 모여든다. 바다를 호령하다 졸지에 국새 도둑으로 몰린 위기의 해적, 고래는커녕 바다도 처음이지만 의기양양 고래사냥에 나선 산적, 건국을 코앞에 두고 발등에 불이 떨어진 개국세력까지! 국새를 차지하는 자, 천하를 얻을 것이다!', '2014-08-06', 6.998, 8.393, 129, '이석훈', 231, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (405817, '젊은엄마: 디 오리지널', '젊은엄마 : 디 오리지널', 'movie', 'https://image.tmdb.org/t/p/w500/rtl0y6akc7dLAR190e0XeyPY8zg.jpg', 'https://image.tmdb.org/t/p/original/4HeIGpl3tE5mfDxY5yt0hDZCMCt.jpg', '행복한 나날을 보내던 진구와 주희. 어느 날 갑자기 행복이 깨진다. 남자에 눈이 멀어 가출했던 딸 화영이 돌아온 것. 과거 화영과 진구는 캠퍼스 커플이었다. 데이트가 잦아지며 갑자기 찾아 든 임신 소식에 부랴부랴 결혼을 준비하며 장모인 주희와 한 집에 같이 살게 된다. 그러나 임신이 아님을 알게 된 화영은 다른 남자에게 빠져 결국 가출해 버리고 만다. 그 사이 사랑에 빠진 진구와 주희.  바람나서 떠났지만 그 남자와 헤어지고 다시 집으로 돌아온 화영. 그런데 진구가 엄마의 집에 여전희 머물고 있음이 의아하다. 그 새 연인이 된 주희와 진구는 화영에게 관계를 들키지 않으려 노력하고 거짓말을 한다.  화영은 다시 진구에게 마음이 끌리는지 진구를 유혹하려 노력하고 주희는 화영에게 진구를 뺏기지 않기 위해 몰래 진구를 만나 마음을 확인한다.  두 모녀의 노골적인 사랑 쟁탈전 앞에 진구의 마음 역시 갈대처럼 흔들리기 시작하는데...', '2016-06-23', 6, 8.409, 84, 'Jeong Do-soo', 10, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (482036, '착한 형수', '착한 형수', 'movie', 'https://image.tmdb.org/t/p/w500/e0BF6bJYWnEqaGucuNilOEHqRwf.jpg', 'https://image.tmdb.org/t/p/original/9GD9e9cJRyLIvyRHcwztdRtHM1w.jpg', '"형수님, 오늘 밤은 저만 믿으세요!" 취업 준비생 민호는 면접을 위해 부모님 집에 신세를 지게 된다. 그러나 오랜만에 찾아간 집엔 정작 부모님은 안 계시고 젊은 형수만 있다. 알고 보니 부모님은 아는 분 장례식장에 참석하러 지방에 가셨고, 사이가 나쁜 형 현수는 형수와 싸우고 가출했던 것. 홀로 남은 젊은 형수의 싱그러운 몸매는 자꾸만 민호의 욕망을 자극하는데...', '2016-10-27', 4.7, 9.2124, 78, 'Gi Dae-ho', 3, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (11423, '살인의 추억', '살인의 추억', 'movie', 'https://image.tmdb.org/t/p/w500/3I1Ng4sxDUyPOdVu3lQ20N14PGE.jpg', 'https://image.tmdb.org/t/p/original/6Kn6qW3an3DkPl3MahWemTzrjCt.jpg', '1986년 경기도. 젊은 여인이 무참히 강간, 살해당한 시체로 발견된다. 2개월 후 비슷한 수법의 강간살인사건이 연이어 발생하면서 사건은 세간의 주목을 받기 시작하고, 일대는 연쇄살인이라는 생소한 범죄의 공포에 휩싸인다. 사건 발생 지역에 특별수사본부가 설치되고, 수사본부는 구희봉 반장을 필두로 지역토박이 형사 박두만과 조용구, 그리고 서울 시경에서 자원해 온 서태윤이 배치된다. 육감과 폭력으로 수사를 진행하는 박형사와 증거와 과학수사를 추구하는 서형사는 수사 내내 마찰을 일으키는데...', '2003-04-25', 8.053, 8.5029, 127, '봉준호', 4372, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (581387, '백두산', '백두산', 'movie', 'https://image.tmdb.org/t/p/w500/1n5q3XpEhCe7TnGHzsHs5pwVT8O.jpg', 'https://image.tmdb.org/t/p/original/2TgMAAstOJjRywwmPeBnpyDiQMw.jpg', '대한민국 관측 역사상 최대 규모의 백두산 폭발 발생. 갑작스러운 재난에 한반도는 순식간에 아비규환이 되고, 남과 북 모두를 집어삼킬 추가 폭발이 예측된다. 사상 초유의 재난을 막기 위해 전유경은 백두산 폭발을 연구해 온 지질학 교수 강봉래의 이론에 따른 작전을 계획하고, 전역을 앞둔 특전사 EOD 대위 조인창이 남과 북의 운명이 걸린 비밀 작전에 투입된다. 작전의 키를 쥔 북한 무력부 소속 일급 자원 리준평과 접선에 성공한 인창. 하지만 준평은 속을 알 수 없는 행동으로 인창을 곤란하게 만든다. 한편, 인창이 북한에서 펼쳐지는 작전에 투입된 사실도 모른 채 서울에 홀로 남은 최지영은 재난에 맞서 살아남기 위해 고군분투하고 그 사이, 백두산 마지막 폭발까지의 시간은 점점 가까워 가는데…', '2019-12-19', 6.8, 9.4397, 128, '김병서', 610, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (235704, '동창생', '동창생', 'movie', 'https://image.tmdb.org/t/p/w500/ToZGJadpR5wQjy1rpuzgNZqYmw.jpg', 'https://image.tmdb.org/t/p/original/alo20exRRwPj1vhqrjbmaee9op9.jpg', '명훈은 남파공작원인 아버지의 누명으로, 여동생 혜인과 단 둘이 살아 남아 요덕 수용소에 감금된다. 그 곳에서 그는 정찰국 소속 장교 문상철에게 동생을 구하려면 남으로 내려가 공작원이 되라는 거절할 수 없는 제안을 받는다. 동생을 지키기 위해, 고등학생 강대호로 위장해 어떤 지령도 마다하지 않던 명훈은 동생과 같은 이름에 늘 혼자인 혜인을 눈 여겨 보게 된다. 그러나 시간이 지날수록 그의 임무는 위험해져 가는데...', '2013-11-05', 7.252, 8.5265, 113, 'Park Hong-soo', 131, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (22536, '박쥐', '박쥐', 'movie', 'https://image.tmdb.org/t/p/w500/2CoIYuNwGmdhsV5CM8jRJ2sAZKe.jpg', 'https://image.tmdb.org/t/p/original/oNdO2VSonWIZFZNC7O4bkuFTNOh.jpg', '정체불명의 피를 수혈 받고 뱀파이어가 된 신부 상현. 피를 원하는 욕구와 신앙심 사이에서 갈등하던 그는 우연히 어린 시절 친구 강우와 그의 아내 태주를 만나면서 인간적 욕망에까지 눈뜨게 된다. 상현은 태주의 묘한 매력에 빠져 쾌락을 갈구하고 태주는 히스테리컬한 시어머니와 무능력한 남편에게 억눌렸던 욕망을 깨워준 상현에게 집착한다. 점점 더 대담해져만 가던 둘의 사랑은 급기야 상현이 뱀파이어라는 사실을 알게 된 태주가 자신의 남편을 죽이자고 제안하고, 상현이 제안을 받아들이면서 새로운 국면에 접어드는데...', '2009-04-30', 7.111, 7.9489, 133, '박찬욱', 1040, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (391423, '입영전야', '입영전야', 'movie', 'https://image.tmdb.org/t/p/w500/sITpyNP0k8GkW9NVAhCgHJnlJPT.jpg', 'https://image.tmdb.org/t/p/original/yEAgsGSYXByiiAsNnoHU5HIm56J.jpg', '입대 3일 전. 군대를 안 갈 수 없다면 “도장”이라도 제대로 찍어야 한다는 일념으로 여기저기 들이대보는 ‘승욱’. 하지만 섹시한 과 선배 ‘소윤’도, 소개팅으로 만난 청순녀 ‘일홍’도 도무지 쉽게 넘어오지 않는다. 마침내 다가온 입영전야. 초조해진 ‘승욱’은 친구들의 도움을 받아 무슨 수를 써서라도 입대 전에 두 여자와 함께 하는 화끈한 밤을 보내겠다고 결심한다. 피 끓는 청춘들의 ‘도장’ 찍기 프로젝트가 지금 시작한다.', '2016-04-05', 6, 8.3739, 90, 'Yoo Seung-taek', 2, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (346646, '베테랑', '베테랑', 'movie', 'https://image.tmdb.org/t/p/w500/vPFqA1KxYaVJg6foIuRIawGaH5d.jpg', 'https://image.tmdb.org/t/p/original/y9m021FLQARGxoTyQdJk4C27zCS.jpg', '한 번 꽂힌 것은 무조건 끝을 보는 행동파 서도철은 겁 없고, 못 잡는 것 없고, 봐주는 것 없는 특수 강력사건 담당 광역수사대. 오랫동안 쫓던 대형 범죄를 해결한 후 숨을 돌리려는 찰나, 서도철은 재벌 3세 조태오를 만나게 된다. 세상 무서울 것 없는 안하무인의 조태오와 언제나 그의 곁을 지키는 오른팔 최상무. 서도철은 의문의 사건을 쫓던 중 그들이 사건의 배후에 있음을 직감한다. 건들면 다친다는 충고에도 불구하고 포기하지 않는 서도철의 집념에 판은 걷잡을 수 없이 커져가고, 조태오는 이를 비웃기라도 하듯 유유히 포위망을 빠져 나가는데...', '2015-08-05', 6.913, 7.7285, 123, '류승완', 235, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (481836, '두 엄마', '두 엄마', 'movie', 'https://image.tmdb.org/t/p/w500/hG3LsgFbnAX7j0i798z6NCJO8Qp.jpg', 'https://image.tmdb.org/t/p/original/qcHRHwbnTN4cPLNBQSkaMzMTe3J.jpg', '절친한 두 친구, 서로의 엄마를 탐하다! 동정이란 이유로 짝사랑하는 여자와 어긋나 상심해 있던 준형에게 친 형제 같은 친구 대진의 엄마 서영이 다가온다.  남자로 거듭날 수 있도록 섹스를 가르쳐주겠다는 서영의 파격적인 제안을 준형은 차마 거절하지 못한다.  한편, 준형과 달리 여자들에게 인기가 많은 대진. 그러나 그는 오래 전부터 준형의 엄마인 연희를 짝사랑해온 상태.  부모님이 이혼할 것 같다는 준형의 말을 들은 대진은 이제 연희에게 적극적인 애정 공세를 펼치기 시작한다.', '2017-08-01', 7, 8.6497, 80, 'Lee Do-si', 7, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (291549, '암살', '암살', 'movie', 'https://image.tmdb.org/t/p/w500/2gAym5Oig2NM7k6iu0DwXlxYaGY.jpg', 'https://image.tmdb.org/t/p/original/mctcKx0Co9qe821DQuAjhoH33lw.jpg', '1933년 조국이 사라진 일제 강점기, 대한민국 임시정부는 일본 측에 노출되지 않은 세 명을 암살작전에 지목한다. 대한독립군 저격수 안옥윤, 신흥무관학교 출신 속사포, 폭탄 전문가 황덕삼이 바로 그들. 김구의 두터운 신임을 받는 임시정부 경무국 대장 염석진은 이들을 찾아 나서기 시작한다. 암살단의 타깃은 조선주둔군 사령관 카와구치 마모루와 친일파 강인국. 한편 의문의 누군가에게 거액의 의뢰를 받은 청부 살인업자 하와이 피스톨이 암살단의 뒤를 추격하는데...', '2015-07-22', 7.297, 7.8258, 139, '최동훈', 263, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (396158, '나도 때론 포르노그라피의 주인공이고 싶다', '나도 때론 포르노그라피의 주인공이고 싶다', 'movie', 'https://image.tmdb.org/t/p/w500/zMZ4IiKAPEqNwpSw9r4oA6M3f1F.jpg', 'https://image.tmdb.org/t/p/original/jAx8dfUGWSn1BWOsT5EdCU4t33l.jpg', '아버지의 죽음과 이혼, 슬럼프, 오랜 공백기 그리고 지독한 외로움…  숨기고 싶었던 상처까지도 사랑해주었던 그 남자로 인해 그녀는 다시 태어났다  한 남자를 알게 되면서 사랑을 행위가 아닌 떨림만으로도 만족할 수 있다는 것을 깨닫게 된 ‘진희’(한지은)는 그 남자를 통해 그 동안 궁금했던 모든걸 알아가려 한다. 사랑을 하면 왜 집착하게 되는 것일까? 집착하지 않고 소유하려 하지도 않고 또한 사랑이 증오로 변하지 않는 그런 사랑을 확인하고 싶은 ‘진희’. 그런 사랑이 가능한지 그 남자에 대한 자신의 믿음을 확인하고 싶었다. 그 남자를 통해 남녀간의 관계가 일방적인 쟁취가 아닌 섬세함과 배려를 통해 완성되는 것임을 다시 한 번 확인하려 한다. 그리고 그것을 통해 진정 위로 받고 치유되면서, 버림받은 여자가 아닌 사랑 받는 여자로 다시 태어난다.  그리고 그녀는 말한다.  “그와 안고 있으면 세상에서 제일 아름다운 여자가 된 기분”이라고…', '2015-11-12', 4.7, 7.7786, 81, 'Jang Seong-Soo', 3, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (581528, '악인전', '악인전', 'movie', 'https://image.tmdb.org/t/p/w500/az4OVqXbFVaHoZlktcm7oCm0LZo.jpg', 'https://image.tmdb.org/t/p/original/jJJQ1PPXUEchqyZ9YyWzgSNU39Z.jpg', '중부권을 쥐고 흔드는 제우스파 조직의 보스 장동수, 비 내리던 밤 한적한 도로에서 접촉사고를 위장해 접근한 남자에게 불의의 습격을 받는다. 격투 끝에 가까스로 목숨은 건졌지만 조직 보스의 권위와 자존심은 무너지고 만다. 바짝 독이 오른 장동수 앞에 형사 정태석이 나타나 그를 찌른 놈이 연쇄살인범이라며 그날 밤 기억나는 것을 모두 말하라고 한다. 장동수는 얼굴 없는 연쇄살인마와 마주쳐 살아남은 유일한 생존자이자 목격자였다. 자신의 몸에 손 댄 그 놈을 살 떨리게 잡고 싶은 조직의 보스 장동수와 미치도록 범인을 잡고 싶은 강력반 미친개 정태석, 두 사람은 장동수의 조직력과 자본, 정태석의 정보력과 기술력을 이용해 "K"라 불리는 연쇄살인마를 함께 잡기로 하는데...', '2019-05-15', 7.843, 8.1796, 112, 'Lee Won-tae', 1388, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (435366, '조작된 도시', '조작된 도시', 'movie', 'https://image.tmdb.org/t/p/w500/v2TRu7tQ8LKHOwfusckYjHvXiya.jpg', 'https://image.tmdb.org/t/p/original/wvNCnYb2K5lcfRDhtH65OaWHIvp.jpg', '게임 세계 속에서는 완벽한 리더지만 현실에서는 평범한 백수인 권유.  PC방에서 우연히 휴대폰을 찾아 달라는 낯선 여자의 전화를 받게 되고 이후, 영문도 모른 채 그녀를 잔인하게 살해한 범인으로 몰리게 된다. 모든 증거는 짜맞춘 듯 권유를 범인이라 가리키고,  아무도 그의 결백을 믿어주지 않는 가운데 권유의 게임 멤버이자 초보 해커인 여울은 이 모든 것이 단 3분 16초 동안, 누군가에 의해 완벽하게 조작되었음을 알게 된다. 특수효과 전문 데몰리션을 비롯 게임 멤버가 모두 모여 자신들만의 새로운 방식으로 사건의 실체를 추적해나가기 시작하고, 조작된 세상에 맞서기 위한 짜릿한 반격에 나서는데...', '2017-02-09', 7.673, 8.093, 126, '박광현', 338, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (13855, '추격자', '추격자', 'movie', 'https://image.tmdb.org/t/p/w500/u9FtBUJoGm1jhG9QxAanwg6en5G.jpg', 'https://image.tmdb.org/t/p/original/urBBFQrrVxy7T8uytrn7dOoHqZn.jpg', '출장안마소를 운영하는 전직 형사 중호. 최근 데리고 있던 여자들이 잇달아 사라지는 일이 발생하던 중 조금 전 나간 미진을 불러낸 손님의 전화 번호와 사라진 여자들이 마지막으로 통화한 번호가 일치함을 알아낸다. 연락이 두절된 미진을 찾아 헤매던 중 우연히 옷에 피가 묻은 영민과 마주치고, 추격 끝에 그를 붙잡는다. 실종된 여자들을 모두 죽였다는 충격적인 고백을 담담히 털어 놓는 영민에 의해 경찰서는 발칵 뒤집어진다. 공세우기에 혈안이 된 경찰은 미진의 생사보다는 증거를 찾기에만 급급해 하고, 미진이 살아 있다고 믿는 단 한 사람인 중호는 미진을 찾아 나서는데...', '2008-02-14', 7.753, 9.3009, 123, '나홍진', 1456, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (623135, '싱크홀', '싱크홀', 'movie', 'https://image.tmdb.org/t/p/w500/l71a3Mh4PbOZwbIOlcsi3QcezK5.jpg', 'https://image.tmdb.org/t/p/original/69dIMxj3aHtp8ABQsPYz2Ht0F6p.jpg', '서울 입성과 함께 내 집 마련의 꿈을 이룬 가장 동원은 이사 첫날부터 프로 참견러 만수와 사사건건 부딪힌다. 동원은 자가취득을 기념하며 직장 동료들을 집들이에 초대하지만 행복한 단꿈도 잠시, 순식간에 빌라 전체가 땅 속으로 떨어지고 만다. 지하 500m 싱크홀 속으로 떨어진 이들은 과연 무사히 빠져나갈 수 있을까?', '2021-08-11', 6.912, 8.4361, 113, '김지훈', 154, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (532794, '성판17: 남자들의 17가지 성적 판타지', '성판17: 남자들의 17가지 성적 판타지', 'movie', 'https://image.tmdb.org/t/p/w500/86cLgLKNkHUUyHsgvWCpuh10JLZ.jpg', 'https://image.tmdb.org/t/p/original/58qsiLrXYXxSJl5CjeeF7fZbKZH.jpg', '기하가 꿈꾸는 성적 판타지…  난데없이 나타난 조희가 실현시켜 준다. 그녀는 누구인가?  여자친구 영은이 딴 남자와 침대에서 뒹굴고 있는 모습을 본 기하! 오 마이 갓!  격한 배신감에 사무쳐 있을 즈음, 난데없이 기하가 사는 옥탑 옆 건물에 조희라는 여자가 이사를 온다. 예쁘고 다정해 보이는 조희, 기하에게 호감을 보이는 것은 물론 제대로 된 섹스 경험이 없는 기하가 “소원이 섹스…” 라고 하자, 한 술 더 떠서 기하의 판타지 속 섹스를 실현해 주겠다고 한다. 단 3주 후면 조희는 어딘가로 떠나야 한다고 하는데...  인정받는 연기파 배우 “최재환”, 아이돌 출신 배우 “박경희”의 거침없는 노출 연기  당신의 모든 성적 판타지를 이루어줄 이야기!', '2017-11-13', 6.1, 8.2732, 121, 'Song Eun-joo', 12, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (290865, '타짜: 신의 손', '타짜: 신의 손', 'movie', 'https://image.tmdb.org/t/p/w500/pqvIcZWo1syeTXBMVGNqerJ32Co.jpg', 'https://image.tmdb.org/t/p/original/tW8H0Bn1vptVAS2SZASmkkl2K5P.jpg', '삼촌 고니의 승부욕과 손재주를 닮은 대길은 노름판에서 미나를 보고 첫눈에 사랑에 빠지지만 바로 그 다음날 불미스러운 일에 연루되어 동네를 떠나게 된다. 강남의 하우스에 입성하게 된 대길은 타고난 기술과 매력을 활용해 선수로 급성장한다. 배신과 음모가 판을 치는 노름판에서 우 사장을 만나 사랑에 빠지지만 순진했던 그의 마음은 이용만 당한 채 버려진다. 황당한 액수의 채무와 장기 탈취 등으로 노름판 밑바닥까지 내려가게 된 대길은 우연히 고광렬을 만나고 노름판의 패가 아닌 노름꾼의 눈을 읽는 기술을 터득하게 되면서 재기의 발판을 다지게 된다.', '2014-09-03', 6.967, 8.0916, 147, '강형철', 92, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (118451, '은교', '은교', 'movie', 'https://image.tmdb.org/t/p/w500/tyT8i7zOfMvge8cOoYin0wLSHeL.jpg', 'https://image.tmdb.org/t/p/original/f50TAIeR79Yoh1zYb5Tn58zmIxs.jpg', '한적한 산 속, 제자이자 이적요를 아버지처럼 모시는 소설가 서지우만이 드나드는 노시인 이적요의 집에 어느 날 우연히 여고생 은교가 나타난다. 집안일을 돕게 된 은교가 맑은 웃음소리를 내고, 이적요는 그녀의 젊고 순수하면서도 관능미를 갖고 있는 싱그러운 육체에 매료된다. 한편 스승을 존경하는 한편 손에 잡히지 않는 스승의 재능과 소녀 은교를 향한 질투심으로 갈등하는 제자의 열패감도 소리없이 늘어가며, 질투와 매혹으로 뒤얽힌 세 사람의 숨겨진 이야기가 펼쳐지는데...', '2012-04-25', 6.763, 8.0425, 129, '정지우', 97, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (276126, '젊은 엄마 2', '젊은 엄마 2', 'movie', 'https://image.tmdb.org/t/p/w500/4cKnB9YbAKgM028qd5ok5hf9nrF.jpg', 'https://image.tmdb.org/t/p/original/8cgTc0Rw7dHGl1zePZacZ3rYn1m.jpg', '첫 경험에 대한 치명적인 유혹  거부할 수 없는 판도라의 상자가 열린다!  대학 졸업반인 영길은 취업에 대한 스트레스로 연일 힘든 나날을 보내고 있다. 설상가상으로 아직까지 여자 경험이 없는 영길은 첫 경험에 대한 강한 열망으로 매일 밤 꿈 속을 헤매지만 깨어보면 한낮 백일몽에 불과하다. 그러던 어느 날, 영길의 일상에 변화가 생기기 시작한다. 우연히 손에 넣은 판도라의 상자를 열게 된 후, 비정규직이긴 하지만 일거리를 얻었고, 원하는 방식은 아니었지만 면접 자리에서 여자 상사와 첫 경험도 하게 된다. 그리고 오늘의 역할 대행은 까칠하고 싸가지 없는 주연의 남자 친구. 그렇게 찾아 가게 된 주연의 집에서 뜻밖에 젊고 아름다운 그녀의 엄마를 만난다. 영길은 거부 할 수 없는 젊은 엄마의 치명적인 유혹에서 빠져 나올 수 있을까?', '2014-05-29', 6.2, 7.9026, 89, 'Noh Seong-soo', 18, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (200085, '감기', '감기', 'movie', 'https://image.tmdb.org/t/p/w500/7fQlPXebfjEqjysW3rv4RyNplih.jpg', 'https://image.tmdb.org/t/p/original/tLxj077KKhBMjnwJkW322VAIbbk.jpg', '밀입국 노동자들을 분당으로 실어 나른 남자가 원인불명의 바이러스에 감염되어 사망한다. 환자가 사망한지 채 24시간이 되지 않아 분당의 모든 병원에서 동일한 환자들이 속출한다. 사망자들은 기하급수적으로 늘어나지만 분당의 시민들은 무방비상태로 바이러스에 노출된다. 감염의 공포가 대한민국을 엄습하고, 호흡기를 통해 초당 3.4명 감염, 36시간 내 사망에 이르는 사상 최악의 바이러스에 정부는 2차 확산을 방지하기 위해 국가 재난사태를 발령, 급기야 도시 폐쇄라는 초유의 결정을 내린다. 피할 새도 없이 격리된 사람들은 일대혼란에 휩싸이게 되고, 대재난 속 사랑하는 이들을 구하기 위한 사람들과 죽음에서 살아 남기 위한 사람들은 목숨을 건 사투를 시작하는데…', '2013-08-14', 7.516, 8.8236, 121, '김성수', 1253, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (282631, '명량', '명량', 'movie', 'https://image.tmdb.org/t/p/w500/fl3G8TprVzt4icbYyQKqdPmUfIO.jpg', 'https://image.tmdb.org/t/p/original/3KB32UjT3iL6YziK7760YzSiOEI.jpg', '1597년 임진왜란 6년, 오랜 전쟁으로 인해 혼란이 극에 달한 조선. 무서운 속도로 한양으로 북상하는 왜군에 의해 국가존망의 위기에 처하자 누명을 쓰고 파면당했던 이순신 장군이 삼도수군통제사로 재임명된다. 하지만 그에게 남은 건 전의를 상실한 병사와 두려움에 가득 찬 백성, 그리고 12척의 배 뿐. 마지막 희망이었던 거북선마저 불타고 잔혹한 성격과 뛰어난 지략을 지닌 용병 구루지마가 왜군 수장으로 나서자 조선은 더욱 술렁인다. 330척에 달하는 왜군의 배가 속속 집결하고 모두가 패배를 직감하는 순간, 이순신 장군은 단 12척의 배를 이끌고 바다를 향해 나서는데...', '2014-07-30', 7.015, 7.8652, 128, '김한민', 310, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (554972, '성난황소', '성난황소', 'movie', 'https://image.tmdb.org/t/p/w500/xiVHlQ4aUyeQQFngyGEounzcYlX.jpg', 'https://image.tmdb.org/t/p/original/3XPgvbWGlEJfgmEBzQHLtcEZfLt.jpg', '거칠었던 과거를 벗어나 수산시장에서 건어물 유통을 하며 건실하게 살던 동철. 어느 날 아내 지수가 납치되고, 경찰에 신고를 하지만 그녀의 행방은 묘연하기만 하다. 그리고 동철에게 걸려 온 납치범의 전화. 오히려 지수를 납치한 대가로 거액의 돈을 동철에게 주겠다는 파격 제안을 하고, 이에 폭발한 동철은 지수를 구하기 위해 움직이기 시작하는데…', '2018-11-22', 7.423, 8.7972, 116, 'Kim Min-ho', 195, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (729304, '바꿔 할래?', '바꿔 할래?', 'movie', 'https://image.tmdb.org/t/p/w500/showbtVGSiZJmKoVXJk9WfdfInB.jpg', 'https://image.tmdb.org/t/p/original/4DDG15BS0qLtltiM3MLldEr0JHz.jpg', '한집에 사는 동원-민호 형제. 형 동원은 여자 친구도 없이 집에서 야동이나 보는 동생이 안쓰러워 여자를 소개해준다. 그날 밤, 동원의 여자친구 지원과 동생에게 소개해 줄 지수를 집에 초대해 같이 모여 술자리를 한다. 밤은 깊어지고 술은 취하는데.. 갑자기 지수가 민호에게 키스를 하며 유혹하자 둘은 그날 사랑을 나눈다. 다음 날, 다시 놀러 온 지수와 지원. 형은 동생의 연인이 된 지수가 탐이 나 몰래 그녀가 잠든 방으로 들어가는데...', '2020-03-16', 6.2, 7.8899, 60, 'Han Dae-wi', 5, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (535389, '안시성', '안시성', 'movie', 'https://image.tmdb.org/t/p/w500/buZA2PJAIHxDBby6vYGgvcYpaxH.jpg', 'https://image.tmdb.org/t/p/original/oGe84ddxe2R90hFwvCDxOINE8qL.jpg', '천하를 손에 넣으려는 당 태종은 수십만 대군을 동원해 고구려의 변방 안시성을 침공한다. 20만 당나라 최강 대군 VS 5천명의 안시성 군사들. 40배의 전력 차이에도 불구하고, 안시성 성주 양만춘과 전사들은 당나라에 맞서 싸우기로 결심하는데..  동아시아 역사상 가장 위대한 승리를 이끈 안시성 전투가 시작된다!', '2018-09-19', 6.765, 7.9935, 135, 'Kim Kwang-sik', 183, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1280, '빈집', '빈집', 'movie', 'https://image.tmdb.org/t/p/w500/hr8ghKbdo3UGUROYafpN38Sohfe.jpg', 'https://image.tmdb.org/t/p/original/nqY8yuxLU4K9cSCQpsW4PGyotlN.jpg', '빈 집에 갇힌 여자와 빈 집을 여는 남자  태석은 오토바이를 타고 집집을 돌며 열쇠구멍에 전단지를 붙인다. 그리고 오랫동안 전단지가 떨어져 나가지 않은 집을 열고 들어가 얼마간을 살고 나온다. 그렇게 살아가고 있던 태석은 어느 한 빈 집에서 멍 투성이의 한 여자를 만난다. 남편의 집착과 소유욕 때문에 피폐해지고 망가진 채로 유령처럼 살아가는 여자 선화. 하지만 태석은 그녀를 남겨둔 채 서둘러 집을 빠져 나온다.  그러나 자신을 데려가 주길 바라는 것 같던 선화의 공허한 눈빛을 떨쳐버릴 수가 없던 태석은 다시 그녀의 빈 집으로 돌아간다. 그리고 그곳에서 태석은 남편의 강제적인 탐닉에 몸부림치며 괴로워하는 선화를 보고야 만다. 참을 수 없는 광경 앞에 태석은 그만 손에 잡힌 3번 아이언 골프채를 휘둘러 선화를 구해 도망친다.  태석이 그래왔던 것처럼 함께 전단지를 붙이고 빈집을 찾아 들며 지내는 두 사람. 새로 들르는 집마다 마치 늘 살아왔던 것처럼 어질러진 빈집을 치우고 망가진 물건들을 고쳐놓는 태석을 보며 선화는 처음으로 자신이 비어있지 않은 집에 있는 것 같은 따스함을 느낀다. 태석 역시 조금씩 웃음을 찾아가는 선화를 보며 그녀에게 점점 끌리게 된다. 액체가 섞이듯 어느 사이엔가 서로의 아픔과 외로움을 느끼게 된 두 사람은 서로에 대한 사랑을 확인하게 된다.  그런 어느 날, 우연히 찾아 든 빈 집에서 싸늘히 버려진 노인의 시체를 발견하게 된 두 사람은 정성껏 장례를 치러주고 남겨진 빈 집에서 행복한 시간을 꿈꾼다. 그러나 노인의 아들이 들이닥치고 두 사람은 경찰에 연행된다. 선화의 신원을 파악한 경찰은 태석에게 납치와 살인, 무단 가택 침입이라는 혐의를 씌운다. 돈으로 형사와 깡패를 매수한 민규 앞에 처절히 무너지는 태석과 반항도 못하고 집으로 끌려온 선화. 태석은 어떻게든 선화에게 돌아가려 하고 선화 역시 태석을 찾아 지난 날의 빈 집들을 찾아 나서는데…', '2004-10-15', 7.82, 7.1117, 88, '김기덕', 1225, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (363579, '밀정', '밀정', 'movie', 'https://image.tmdb.org/t/p/w500/3OqkOFlXENLeIMLVBclGejpsaWd.jpg', 'https://image.tmdb.org/t/p/original/5IkEziMnignLFxbxuYqrQGBxdWY.jpg', '1920년대 일제강점기. 조선인 출신 일본경찰 이정출은 무장독립운동단체 의열단의 뒤를 캐라는 특명으로 의열단의 리더 김우진에게 접근하고, 두 사람은 서로의 정체와 의도를 알면서도 속내를 감춘 채 가까워진다. 출처를 알 수 없는 정보가 쌍방간에 새어나가고 누가 밀정인지 알 수 없는 가운데, 의열단은 일제의 주요 시설을 파괴할 폭탄을 경성으로 들여오기 위해, 그리고 일본 경찰은 그들을 쫓아 상해에 모인다. 서로를 이용하려는 암투와 회유, 교란 작전이 숨가쁘게 펼쳐지는 긴장감 속에서 폭탄을 실은 열차는 국경을 넘어 경성으로 향하는데...', '2016-09-07', 7.201, 7.7328, 140, '김지운', 358, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (33196, '해운대', '해운대', 'movie', 'https://image.tmdb.org/t/p/w500/AgWRG68qAT63wDybxNAebnbstts.jpg', 'https://image.tmdb.org/t/p/original/uAfPjNvfHjFuvdtSa8J3iuD1CkI.jpg', '해운대 토박이 만식은 연희를 좋아하면서도 자신의 마음을 숨길 수 밖에 없다. 그러던 어느 날, 만식은 오랫동안 가슴 속에 담아두었던 자신의 마음을 전하기로 결심하고 연희를 위해 멋진 프로포즈를 준비한다. 한편 국제해양연구소의 지질학자 김휘 박사는 대마도와 해운대를 둘러싼 동해의 상황이 5년전 발생했던 인도네시아 쓰나미와 흡사하다는 엄청난 사실을 발견하게 된다. 그는 안전하지 않다고 수차례 강조하지만 그의 경고에도 불구하고 재난 방재청은 지질학적 통계적으로 쓰나미가 한반도를 덮칠 확률은 없다고 단언한다. 그 순간에도 바다의 상황은 시시각각 변해가고, 일본 대마도가 내려 앉으면서 초대형 쓰나미가 생성된다. 한여름 더위를 식히고 있는 수백만의 휴가철 인파와 평화로운 일상을 보내고 있는 부산 시민들, 그리고 이제 막 서로의 마음을 확인한 만식과 연희를 향해 초대형 쓰나미가 시속 800km의 빠른 속도로 밀려오는데...', '2009-07-22', 6.918, 7.7591, 129, '윤제균', 478, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (894753, '내로남불', '내로남불', 'movie', 'https://image.tmdb.org/t/p/w500/jdxiDmtuLiiKV3W9nOGTzVwBEWY.jpg', NULL, '부부관계가 소원한 여정과 도진, 알고보니 아내 여정 몰래 다른 여자와 밀애를 즐기던 도진. 한편, 외로움에 몸부림치던 여정은 우연히 영민을 알게 되었고, 이후 자신에게 사랑이라는 감정이 다시 싹트게 됨을 느끼게 된다.', '2020-01-01', 0, 7.5624, NULL, NULL, 0, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (357458, '젊은 엄마: 내 나이가 어때서', '젊은엄마: 내 나이가 어때서', 'movie', 'https://image.tmdb.org/t/p/w500/41vxnFP4zTOOf70V0cPNRFiiYvP.jpg', 'https://image.tmdb.org/t/p/original/eOZplroXXIYcUpFhV4MJ5mbudQA.jpg', '아버지, 아들, 손자까지!  삼대를 사로잡은 29세 존예 섹시맘!  역대  시리즈 사상 최고의 엄마가 나타났다!  아내와 사별하고 동네 약국을 운영하는  말기 암 시한부 아버지, 용태(명계남)  눈치라고는 약에 쓸래도 없는  정리해고 1순위 아들, 성민(홍서준)  밤이면 밤마다 공부보다는 성인영화에 푹 빠져있는  만년 재수생 손자, 영찬(김민상)  한 지붕 세 남자 앞에 역대  시리즈 사상  최고의 엄마가 나타났다!  29세 존예 섹시맘 진희(채민서)의 등장으로  온통 집 안이 양기로 가득 찬 가운데  각자의 사정으로 위기에 몰린 세 남자를 위한  젊은 엄마의 특급 처방이 시작된다.  아버지부터 손자까지! 도대체 누가 엄마랑!', '2015-04-30', 5.4, 5.6665, 94, 'Kim Jong-il', 5, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1184502, '비밀일 수밖에', '비밀일 수밖에', 'movie', 'https://image.tmdb.org/t/p/w500/hE1vdmh2Lw98S5ebgbPQQNhkcSm.jpg', 'https://image.tmdb.org/t/p/original/wdmKHcJQm4nUGXUd7vzQqKjvbCy.jpg', '강원도 춘천, 고등학교 교사 정하의 평온했던 일상에 뜻밖의 손님들이 찾아온다. 캐나다로 유학 중인 아들 진우가 여자친구 제니와 함께 예고도 없이 학교로 나타나고, 곧이어 캐나다에 있어야 할 제니의 부모까지 갑작스럽게 춘천에 도착한다. 숙소 예약 문제로 벌어진 소동 끝에, 서로를 잘 알지 못하는 두 가족은 정하의 집에서 함께 머무르게 된다. 낯설고도 불편한 동거가 시작된 가운데, 서서히 드러나는 각자의 비밀들로 분위기는 점점 미묘해져 가는데…', '2025-09-10', 6.5, 7.7729, 114, '김대환', 2, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (576964, '누나 친구', '누나 친구', 'movie', 'https://image.tmdb.org/t/p/w500/iLoAQ370qAULWsTE8uUQeJgfp8W.jpg', 'https://image.tmdb.org/t/p/original/qTJqF7zWJjYM9ejfwNvPLBKgPTL.jpg', '', '2016-01-21', 6.7, 8.2391, NULL, 'Shin Hyeon-cheol', 3, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (628704, '미드나이트', '미드나이트', 'movie', 'https://image.tmdb.org/t/p/w500/oJoLrbgEqupECFC7TwcmSZY2JSn.jpg', 'https://image.tmdb.org/t/p/original/sOR6e2JhxhHQmcvawhfi6gAntgc.jpg', '청각장애를 가진 경미는 귀가하던 길에 피를 흘리며 쓰러져 있는 소정을 목격하고, 그녀를 도와주려다 연쇄살인마 도식의 새로운 타겟이 된다. 살고 싶다는 의지로 미친듯이 도망치는 경미, 하지만 살인마의 발소리조차 들을 수 없고, 도식은 또 다른 얼굴로 나타나 경미를 위협하는데...', '2021-06-30', 7.177, 7.9155, 103, '권오승', 300, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (60192, '미인도', '미인도', 'movie', 'https://image.tmdb.org/t/p/w500/szqTmxUrdf8WKOxjhoIGv2f2lcI.jpg', 'https://image.tmdb.org/t/p/original/4RGJHOm1inaWDv84q8J5ulOzpXC.jpg', '4대째 이어온 화원 가문의 막내딸이자 신묘한 그림솜씨로 오빠 신윤복에게 남몰래 대신 그림을 그려주던 7살 천재 윤정. 평범하던 그녀의 삶은 어느날 오빠의 자살로 인해 송두리째 뒤바뀐다. 그림을 위해 여자를 버리고 오빠 신윤복의 삶을 살게 된 것.  조선 최고의 화가 김홍도의 마음을 설레이게 할 만큼 빼어난 그림 실력을 가졌던 윤복은 자유롭고 과감한 사랑을 그려 조선 최초의 에로티시즘을 선보인다. 하지만 그의 ''속화''는 음란하고 저급하다는 질타와 시기를 받는다.', '2008-11-13', 6.179, 7.9699, 108, '전윤수', 39, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (467824, '인랑', '인랑', 'movie', 'https://image.tmdb.org/t/p/w500/9kAjGEOLWF1FXZy5DgghdoCD4OO.jpg', 'https://image.tmdb.org/t/p/original/CX9O14p4SsAG8nz0BFhaDTSKH1.jpg', '남북한 정부가 통일준비 5개년 계획을 선포한 후, 강대국의 경제 제재가 이어지고,  민생이 악화되는 등 지옥 같은 시간이 이어지고 있는 혼돈의 2029년. 자원은 고갈되고 빈곤층이 늘어나면서 도시가 황폐해지자, 통일에 반대하는 반정부 무장테러단체 섹트가 등장한다. 섹트를 진압하기 위해 설립된 대통령 직속의 새로운 경찰조직 특기대는 정국의 주도권을 장악하고, 이에 입지가 줄어든 정보기관공안부는 특기대를 말살할 음모를 꾸민다. 절대 권력기관 간의 피비린내 나는 암투 사이, 특기대 내 비밀조직 인랑에 대한 소문이 떠도는데...', '2018-07-25', 6.274, 7.1631, 139, '김지운', 319, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1140233, '마누라 바꿔먹기', '마누라 바꿔먹기', 'movie', 'https://image.tmdb.org/t/p/w500/lmfpb4QHehVAaLm6IEbgM0VhQuD.jpg', 'https://image.tmdb.org/t/p/original/jLeMKUHRYcrrEuvolfzfIxc1mOL.jpg', '', '2022-08-14', 1, 7.7223, NULL, '민정현', 1, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (801604, '샤크: 더 비기닝', '샤크: 더 비기닝', 'movie', 'https://image.tmdb.org/t/p/w500/r3zWv3Ly1Y2NZrGHFaQntCS4MT7.jpg', 'https://image.tmdb.org/t/p/original/qB4ABpiIcSfIvFTWkRMrRiegV2b.jpg', '뜻밖의 사고로 모든 것을 잃은 학교폭력 피해자 차우솔. 소년교도소에 수감된 뒤 우연히 종합격투기 챔피언 정도현을 만나게 되고, 자신 안의 두려움과 마주한 채 육체적, 정신적 한계를 하나씩 극복해 나간다. 교도소에서 출소해도, 자신을 괴롭힐 배석찬을 두려워하던 차우솔은 고된 훈련을 통해 점차 강력한 상어의 공격 본능을 일깨우기 시작하는데…', '2021-11-26', 7.419, 7.6696, 108, '채여준', 74, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (385141, '하숙집', '하숙집', 'movie', 'https://image.tmdb.org/t/p/w500/7Qp0wioq9dMkbKyM3ZQk2TDI8bi.jpg', 'https://image.tmdb.org/t/p/original/od0HCHuahW9mfw4B0UU3pwd3Kdt.jpg', '섹시한 하숙집 아줌마, 더 섹시한 딸, 그리고 청순한 첫사랑까지?! 세 여자와 함께 하는 파란만장 하숙 라이프가 지금 시작된다! 모녀가 단 둘이 운영하는 하숙집에 머물게 된 신입생 은기. 낯선 서울 생활에서 그의 유일한 낙은 섹시한 모녀와의 은근한 밀당이다. 그런데 갑자기 고향에 있던 청순가련 첫사랑 순이가 은기를 보겠다며 무작정 하숙집에 찾아온다. 자신 옆에는 첫사랑 순이가, 문 너머에는 섹시한 글래머 하숙집 딸, 그리고 바로 옆 욕실에선 풍만한 몸매를 자랑하는 하숙집 아줌마까지… 스무살 숫총각 은기의 잠들 수 없는 밤이 시작된다.', '2014-02-25', 4.3, 8.3067, 94, 'Gyeong Seok-Ho', 6, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (215743, '뫼비우스', '뫼비우스', 'movie', 'https://image.tmdb.org/t/p/w500/g5DnSOYbYWaBvrZgelDwp1UraVP.jpg', 'https://image.tmdb.org/t/p/original/mRPNNScRf2bsskN5Q8XvczqfdMS.jpg', '남편의 외도에 증오심에 차 있던 아내는 남편에 대한 복수로 아들에게 치명적인 상처를 주고 집을 나간다. 남편은 자신 때문에 불행해진 아들을 위해 모든 것을 하지만 결코 회복할 수 없음을 알게 되고 모든 원인이 된 자신의 성기를 절단하고 아들을 위해 모든 것을 바친다. 그 결과 잠시 어느 정도 상처가 회복되지만 완벽하지 못하고 아들과 슬프게 살아가는데, 어느 날 집을 나갔던 아내가 돌아오면서 가족은 더 무서운 파멸로 향해 간다.', '2013-09-05', 6.659, 8.7151, 90, '김기덕', 251, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (252067, '피끓는 청춘', '피끓는 청춘', 'movie', 'https://image.tmdb.org/t/p/w500/wy6kUVovsT2fUTHU96iVOF9P8MZ.jpg', 'https://image.tmdb.org/t/p/original/4n6LRU9BfueuhrB9wbtSrItT7hZ.jpg', '영숙은 충청도를 접수한 여자 일진이지만, 홍성농고 전설의 카사노바 중길을 바라보며 애만 태운다. 한편 홍성공고 싸움짱 광식은 좀처럼 마음을 열지 않는 영숙이 야속하기만 한데, 서울 전학생 소희의 등장이 이들 관계에 일대 파란을 일으킨다. 소희 꼬시기에 여념 없는 중길 때문에 속상한 영숙의 마음을 알아챈 광식은 급기야 소희에게 손길을 뻗친다. 이를 저지하기 위해 나선 중길을 지키기 위해 영숙은 눈 하나 꿈쩍 안하고 자신을 던지는 중대한 결심을 하는데…', '2014-01-22', 7.067, 7.3031, 121, 'Lee Yeon-woo', 112, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (619803, '범죄도시 2', '범죄도시 2', 'movie', 'https://image.tmdb.org/t/p/w500/9XkAF2pl2uliiuAORaWTgPmr6zG.jpg', 'https://image.tmdb.org/t/p/original/eGyvNUw7Kess2QfgtqZjAHC7DqW.jpg', '가리봉동 소탕작전으로부터 4년이 지난 2008년, 금천경찰서 강력반은 베트남으로 도주한 용의자를 인도받아 오라는 미션을 받는다. 그렇게 현지를 물색하던 마석도와 전일만은 용의자에게 미심쩍음을 느껴 추궁한 끝에, 악랄한 강해상의 존재를 알게 된다. 두 형사는 수사권이 없는 상황에도 한국과 베트남을 오가며 역대급 범죄를 저지르는 그를 잡겠다는 일념 하나로 호찌민 이곳저곳을 거침없이 누빈다.', '2022-05-18', 7.314, 7.4717, 106, '이상용', 400, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (399905, '여자전쟁: 비열한 거래', '여자전쟁: 비열한 거래', 'movie', 'https://image.tmdb.org/t/p/w500/2xUNRZwprvVwfx12WR1rRXoohSi.jpg', 'https://image.tmdb.org/t/p/original/OuOCZojaMAZOLIT3bkEcfDRmqF.jpg', '불의의 사고로 실명을 하게 된 화가 하림. 남편을 위해 각막 기증자를 찾아 헤매는 아내 선영. 그런 그녀 앞에 각막을 기증하겠다는 말기 암 노인 대근이 나타난다. 남편의 각막기증을 두고 대근과 선영의 아찔하고 위험한 거래가 시작된다.', '2015-09-27', 5.727, 9.0483, 110, 'No Zin-soo', 33, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (409387, '정사: 결혼 말고 연애', '정사: 결혼 말고 연애', 'movie', 'https://image.tmdb.org/t/p/w500/j3gFifMCgyIF63AI69HzDW6Cj9X.jpg', 'https://image.tmdb.org/t/p/original/6zto711okJGIL9a7hZw4efJslZC.jpg', '"결혼 따윈 미친 짓이야! 나는 연애만 즐기고 싶어!" 한 남자에게 정착하고 싶지 않은 발칙한 그녀의 연애 일대기! 결혼하라고 잔소리하는 엄마, 성과 좀 내라고 닥달하는 상사, 유부남인 걸 속였던 내 남자까지! 미칠 것 같은 심정을 입안이 얼얼할 정도로 매운 음식으로 다스리던 수경. 외로운 생일 날, 또 다시 매운 요리를 찾아간 레스토랑에서 쉐프와 요리보다 더 맵고 자극적인 정사를 나누고 만다. 마음도, 몸도 잘 맞는다는 것을 확인한 두 사람의 관계는 점점 더 끈끈해지지만 결혼 말고 연애만 좋은 수경은 쉐프의 청혼을 거절한다. 그러자 유부남이 된 쉐프가 돌아와 수경에게 묻는다. "결혼은 네 말대로 딴 여자랑 했어. 그럼 연애는 네가 해줄래?"', '2016-04-19', 6.6, 8.5545, 109, 'Jo Kyeong-hoon-I', 14, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (833593, '이공삼칠', '이공삼칠', 'movie', 'https://image.tmdb.org/t/p/w500/mahoRwcpJRx8TAuE6lKrYqCv8io.jpg', 'https://image.tmdb.org/t/p/original/r1Lh5aMjPn3CV9EJFRAVuMH4X2A.jpg', '열아홉 윤영은 엄마와 단 둘이 살며 아르바이트를 하면서 검정고시를 준비한다. 친구들처럼 학교에 가고 싶기도 하지만, 얼른 공무원 시험에 합격해 공장에서 일하는 청각 장애가 있는 엄마를 편하게 해드리고 싶은 마음뿐. 착한 마음과 성실한 의지와는 상관없이 뜻밖의 사고는 윤영을 피해자에서 살인자로 돌변시켜 교도소에 몰아넣고 ‘윤영’이라는 이름대신 ‘이.공.삼.칠.’이라는 수감번호로 불리게 만든다. 더 이상 절망적일 수 없는 상황에서 저마다의 사연을 가진 12호실 동료들은 윤영을 지켜주기 위해 희망의 손길을 내미는데… 반드시 돌려줄게 너의 이름을!', '2022-06-08', 7.412, 6.8469, 125, '모홍진', 68, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (581526, '다만 악에서 구하소서', '다만 악에서 구하소서', 'movie', 'https://image.tmdb.org/t/p/w500/xYnL0kA0V7aDvg8wupmWQbdgb9a.jpg', 'https://image.tmdb.org/t/p/original/au6YoYkzbcgZ4CTCwc57UdhD8FC.jpg', '태국에서 충격적인 납치사건이 발생하고 마지막 청부살인 미션을 끝낸 암살자 인남은 그것이 자신과 관계된 것임을 알게 된다. 인남은 곧바로 태국으로 향하고, 조력자 유이를 만나 사건을 쫓기 시작한다. 한편, 자신의 형제가 인남에게 암살당한 것을 알게 된 레이. 무자비한 복수를 계획한 레이는 인남을 추격하기 위해 태국으로 향하는데...', '2020-08-05', 6.888, 8.3078, 108, '홍원찬', 219, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (16318, '색즉시공', '색즉시공', 'movie', 'https://image.tmdb.org/t/p/w500/eRCd4nqD3i4tAzIVeyd1zTNiRPD.jpg', 'https://image.tmdb.org/t/p/original/y7aUGF0d32JcmuWW8TsgnTEZaLF.jpg', '군대 제대 후 늦깎이 대학생이 된 은식. 남보다 늦은 출발 때문에 고시 합격에 인생 목표를 건다. 하지만 대학에 들어가자마자 해병대 고참 성국을 만나게 되고 그의 꾐에 빠져 차력 동아리에 가입하고 만다. 불철주야 공부를 해도 모자랄 판에 웬 차력? 그런데 거기에 또 하나, 그의 꿈을 가로막는 장애가 있었으니.', '2002-12-12', 6.116, 9.2126, 96, '윤제균', 129, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (654739, '발신제한', '발신제한', 'movie', 'https://image.tmdb.org/t/p/w500/uGYnClpynAYQAzy3rQBPWpEkHf1.jpg', 'https://image.tmdb.org/t/p/original/atPlFdUrQl2U9MtUwujrrjnQHBA.jpg', '은행센터장 성규는 아이들을 차에 태우고 출발한 평범한 출근길에 한 통의 발신번호 표시제한 전화를 받는다. 전화기 너머 의문의 목소리는 차에 폭탄이 설치되어 있고, 자리에서 일어날 경우 폭탄이 터진다고 경고한다. 대수롭지 않게 여기던 성규는 곧 동료의 차가 폭파되는 것을 바로 눈앞에서 목격하고, 졸지에 부산 도심 테러의 용의자가 되어 경찰의 추격을 받게 되는데…', '2021-06-23', 7.533, 7.4801, 94, '김창주', 215, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (436019, '착한 여자', '착한 여자', 'movie', 'https://image.tmdb.org/t/p/w500/s4AunUN05AuuYkBjJtxsTDdH9V3.jpg', 'https://image.tmdb.org/t/p/original/cm9whEZczUOYUNoo47pxnF9qiWc.jpg', '"선생님, 저 선생님 생각 보다 더 잘해요..." 순수했던 그녀, 자신도 몰랐던 뜨거운 본능과 마주하다! 도박 빚만 남기고 또 잠수 타버린 아버지를 대신해서 돈을 벌러 다니는 착하고 순한 딸 분녀. 팍팍한 그녀 인생의 유일한 빛은 자신이 가정부로 일하고 있는 집의 지적이고 상냥한 강선생뿐! 그러나 어느 날 밤, 함께 일하는 동료 명준이 갑자기 분녀에게 사랑을 고백하며 그녀의 몸을 탐한다. 그런데 싫어야 할 그 스킨쉽이 어째서 이렇게 좋은 거지?! 분녀는 매일 밤 명준의 뜨거운 손길을 상상하지만 도무지 만족되지 않는다. 결국, 분녀는 본능에 이끌려 시장 제일의 부자 만갑, 그의 밑에서 일하는 천수, 그리고 오랫동안 흠모해온 강선생까지 유혹하기 시작한다.', '2015-03-25', 7.7, 5.2933, 95, 'Gyeong Seok-Ho', 3, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (128246, '늑대소년', '늑대소년', 'movie', 'https://image.tmdb.org/t/p/w500/4aQ3yPJCNILHR9SrtBjMmCvn3nG.jpg', 'https://image.tmdb.org/t/p/original/8wKDBmmSoLRMtf42dhu7uUDKS1c.jpg', '요양 차 가족들과 한적한 마을로 이사 간 소녀는 어둠 속에 몸을 숨긴 의문의 늑대소년을 발견한다. 야생의 눈빛으로 사람 같지 않은 행동을 보이는 소년에게 왠지 마음이 쓰이는 소녀는 먹을 것을 보고 기다리는 법, 옷 입는 법, 글을 읽고 쓰는 법 등 소년에게 세상에서 살아가는 방법들을 하나씩 가르쳐준다. 태어나 처음으로 자신을 향해 손을 내밀어준 소녀에게 애틋한 감정이 싹트는 소년.  그러던 어느 날 예기치 못한 위기 속에 소년의 숨겨져 있던 위험한 본성이 드러나고, 소년은 순식간에 마을 사람들에게 두려움과 공포의 대상이 되어버리는데……', '2012-10-31', 7.63, 7.1476, 125, '조성희', 281, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (482207, '챌린지 게임', '챌린지 게임', 'movie', 'https://image.tmdb.org/t/p/w500/1JFfsGsImc4qXeMdTqXypjs0sPL.jpg', NULL, '"우리 지금... 할래요?"  치명적 게임의 유혹 ''챌린지 게임''  플로리스트인 ‘애란’(비키)과 경찰청 감식반 형사인 ‘민호’(최령)는 남들이 부러워하는 가정을 이루고 있다. 하지만 ‘민호’는 정상적인 부부관계를 가지지 못하고 급기야 ‘애란’이 다른 남자를 유혹해 관계를 가지는 일종의 유혹게임 ''챌린지 게임''을 시작한다. 그러던 ‘애란’과 ‘민호’는 탱고카페에서 ‘알렉스’(최현호)를 만난다. ‘알렉스’는 ‘애란’에게 관심을 가지고 접근하고, 남편인 ‘민호’와 달리 뛰어난 외모에 자신감 넘치는 ‘알렉스’에게 호감을 가진 ‘애란’은 그를 챌린지 게임에 끌어들인다. 이후 ‘민호’는 우연히 두 사람의 뜨거운 관계를 목격하고 ‘애란’이 유혹한 남자가 ‘알렉스’임을 알고 분노한다. 이후 ‘민호’는 ‘알렉스’가 단순히 게임 파트너가 아니라 의도적으로 자신들에게 접근한 사실을 알게되고 불안해한다. ‘민호’는 ‘알렉스’를 떨쳐내려 하지만 승부욕이 넘치는 소시오패스 성향의 ‘알렉스’는 오히려 ‘민호’와 ‘애란’을 더욱 옥죄이며 카타르시스를 느낀다. 스스로가 즐기기 위해 만든 챌린지 게임이지만 이들이 시작한 게임은 점차 파국으로 치닫게 되는데...', '2016-08-04', 6.4, 8.1155, 93, 'Won Seok-ho', 9, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (94047, '마이웨이', '마이웨이', 'movie', 'https://image.tmdb.org/t/p/w500/iMtEu7346RUV26OMwoqOPHrKERe.jpg', 'https://image.tmdb.org/t/p/original/4QHF7kAYjIpZ5U8A0amvhRkHlZ1.jpg', '1938년 경성. 제 2의 손기정을 꿈꾸는 조선청년 준식과 일본 최고의 마라톤 대표선수 타츠오. 어린 시절부터 서로에게 강한 경쟁의식을 가진 두 청년은 각각 조선과 일본을 대표하는 세기의 라이벌로 성장한다. 그러던 어느 날, 준식은 예기치 못한 사건에 휘말려 일본군에 강제 징집되고 그로부터 1년 후, 일본군 대위가 된 타츠오와 운명적인 재회를 하게 된다. 2차 세계대전의 거대한 소용돌이에 던져진 두 청년은 중국과 소련, 독일을 거쳐 노르망디에 이르는 12,000Km의 끝나지 않는 전쟁을 겪으며 점차 서로의 희망이 되어가는데… 적으로 만나 서로의 희망이 된 조선과 일본의 두 청년 국적을 초월한 인간애의 드라마가 시작된다!', '2011-12-21', 7.892, 7.8365, 137, '강제규', 429, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (27154, '해피 엔드', '해피 엔드', 'movie', 'https://image.tmdb.org/t/p/w500/bqnOc1FnaRU9X3whv7gG43zkUrk.jpg', 'https://image.tmdb.org/t/p/original/em8MBMqzJo5uEFLksqAj9LXxZXE.jpg', '6년 동안 은행에서 일하다 실직한 서민기는 실직의 불안정함과 오랜만에 맛보는 일상의 여유 사이를 오간다. 어린이 영어학원 원장인 서민기의 아내 최보라는 대학 시절 연인이었던 김일범과 은밀한 만남을 이어간다. 젖먹이 아기와 남편을 소중하게 여기지만 김일범의 한결같은 사랑에도 행복해 한다. 서민기가 아내와 김일범의 밀회를 눈치채고, 세 사람의 욕망은 팽팽한 긴장을 불러온다. 사랑과 집착으로 뒤엉킨 삼각관계. 배신감과 상실감에서 비롯된 살의 속에 세 사람은 서로 다른 해피엔딩을 꿈꾸는데...', '1999-12-11', 6.563, 7.4736, 100, '정지우', 71, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (616219, '발광하는 현대사', '발광하는 현대사', 'movie', 'https://image.tmdb.org/t/p/w500/4QeepC7oD3XAByFIkHfmd83fLJU.jpg', 'https://image.tmdb.org/t/p/original/shH1PjPD7pjEZg0fJtWXlHa3Do7.jpg', '한 사람의 결혼으로 관계가 끝난 줄 알았던 섹스파트너 ''현대''와 ''민주''. 하지만 멈출 수 없는 욕망에 성적으로 타락해가는 ''현대''와 가질 수 없는 것에 대한 욕망을 포기하지 못하는 ''민주'', 그리고 두 사람과 복잡하게 얽힌 인물들의 적나라하고 추악한 욕망까지…', '2019-07-18', 4.3, 5.1276, 93, '조성규', 11, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (838209, '파묘', '파묘', 'movie', 'https://image.tmdb.org/t/p/w500/tw0i3kkmOTjDjGFZTLHKhoeXVvA.jpg', 'https://image.tmdb.org/t/p/original/6EO11KoiMMG29ISaQrm2G5DCe1X.jpg', '미국 LA, 거액의 의뢰를 받은 무당 화림과 봉길은 기이한 병이 대물림되는 집안의 장손을 만난다. 조상의 묫자리가 화근임을 알아챈 화림은 이장을 권하고, 돈 냄새를 맡은 최고의 풍수사 상덕과 장의사 영근이 합류한다. 절대 사람이 묻힐 수 없는 악지에 자리한 기이한 묘. 상덕은 불길한 기운을 느끼고 제안을 거절하지만, 화림의 설득으로 결국 파묘가 시작되고… 나와서는 안될 것이 나왔다.', '2024-02-22', 7.531, 7.3466, 133, '장재현', 615, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (679057, '가슴 큰 태희', '가슴 큰 태희', 'movie', 'https://image.tmdb.org/t/p/w500/aKoGgpKn6N04kWQp03LSAweN3dn.jpg', 'https://image.tmdb.org/t/p/original/v7eMYrYpcTJORioMKMgjnzyewWH.jpg', '곧 결혼을 앞둔 예비 신혼 부부 차욱과 민주. 차욱은 직장 후배인 용우네 부부에게 커플 여행을 제안한다. 지연은 불편한 여행이 마음에 들지 않지만 용우의 직장 상사라 어쩔 수 없이 승낙하게 된다.  함께 여행을 가기로 확정이 되고 차욱은 평소 눈여겨 보던 지연과 함께 할 수 있도록 계획을 세운다. 민주는 차욱의 강요에 어쩔 수 없이 계획에 동참하게 된다.  여행 당일 민주는 결국 지연에게 모든 것을 털어놓고 지연은 차욱을 반대로 이용해 먹기로 한다.​', '2020-02-27', 5.167, 7.7272, 79, '이동준', 6, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (591322, '어린 의뢰인', '어린 의뢰인', 'movie', 'https://image.tmdb.org/t/p/w500/tBjIL4jBbHstVvWvCXV7AjZaggR.jpg', 'https://image.tmdb.org/t/p/original/3h2BxJPIwrPoHRzz0RRt8RVHoFs.jpg', '인생 최대 목표는 오직 성공뿐인 변호사 정엽. 주변에 무관심한 그에게 다빈과 민준 남매가 자꾸 귀찮게 얽힌다. 오랫동안 기다렸던 대형 로펌 합격 소식을 듣게 된 정엽은 믿을 수 없는 사실을 알게 된다. 10살 소녀 다빈이 7살 남동생을 죽였다는 충격적인 자백. 뒤늦게 미안함을 느낀 정엽은 자신의 모든 것을 걸고 다빈의 엄마 지숙에게 숨겨진 진실을 밝히려고 하는데…', '2019-05-22', 8.7, 7.4262, 114, '장규성', 94, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (629028, '미션 파서블', '미션 파서블', 'movie', 'https://image.tmdb.org/t/p/w500/xul24PvmhG1smXsAcOPCeeuKLUN.jpg', 'https://image.tmdb.org/t/p/original/o37Ajo7Ii9L9qi5tGxxAWodyCWt.jpg', '입금만 되면 뭐든 가능해지는 흥신소 사장 우수한 앞에 어느 날 열정 충만 비밀 요원 유다희가 현금 천 만원과 함께 찾아 온다. 무기 밀매 사건을 해결하자며, 대놓고 공조를 요청해 온 것. 혼자일 때보다 둘일 때 더 눈에 띄는 두 사람. 작전을 거듭해 갈수록 사건은 커져만 가고, 형사들이 오해할만한 단서를 여기저기 흘리고 다녀 수배 목록에 오르기도 하지만 아찔한 이 공조를 멈출 수는 없다.', '2021-02-17', 7.495, 7.5702, 104, 'Kim Hyung-joo', 188, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (408349, '내 이웃의 아내', '내 이웃의 아내', 'movie', 'https://image.tmdb.org/t/p/w500/qpW0myP5nCSZbSmOS0IhMJYXVkF.jpg', 'https://image.tmdb.org/t/p/original/7IzjzI50HpcIMZ6t0ZBxLUbU8ls.jpg', '남편이 출장을 간 사이, 윤정은 딸 아이를 친정에 맡기고 이웃 집 남자와 뜨거운 밀월 여행을 떠난다. 법, 도덕, 상식 같은 건 모두 다 잊어버리고 밥 먹다가 하고 씻다가 하고 걷다가 하고 테니스 치다가 하는, 오로지 본능만을 느끼는 두 남녀의 2박 3일. 그 끝날 줄 모르는 욕정이 그녀의 전신을 휘감는다.', '2016-07-28', 4.4, 8.1002, 80, 'Jung Dae-man', 7, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (530254, '마녀', '마녀', 'movie', 'https://image.tmdb.org/t/p/w500/abWjmAyjSWqNo6C5ty3UZTZIYDz.jpg', 'https://image.tmdb.org/t/p/original/f8ng3EDMLkuTMupe4TjgiJS1r0S.jpg', '10년 전 의문의 사고가 일어난 시설에서 홀로 탈출한 후 모든 기억을 잃은 자윤. 나이도, 이름도 모르는 자신을 거두고 키워준 노부부의 보살핌으로  씩씩하고 밝은 여고생으로 자라났다. 어려운 집안사정을 돕기 위해 상금이 걸린 오디션 프로그램에 출연한 자윤, 방송이 나간 직후부터 의문의 인물들이 그녀 앞에 나타난다. 자윤의 주변을 맴돌며 날카롭게 지켜보는 남자 귀공자, 그리고 과거 사고가 일어난 시점부터 사라진 아이를 찾던 닥터 백과 미스터 최까지 자신은 전혀 기억하지 못하는 그들의 등장으로, 자윤은 혼란에 휩싸이게 되는데...', '2018-06-27', 7.882, 7.0667, 125, '박훈정', 695, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (390433, '널 기다리며', '널 기다리며', 'movie', 'https://image.tmdb.org/t/p/w500/9pfo2HYE2TtoJqnfSNJrelp74uT.jpg', 'https://image.tmdb.org/t/p/original/1liJMvtf2nWZl9BBQiAhcIXrk5R.jpg', '15년 전, 내 눈 앞에서 아빠를 죽인 범인이 드디어 세상 밖으로 나왔다.  15년을 기다린 이유는 단 하나!  아빠를 죽인 범인을 쫓는 소녀 ‘희주’ 앞에 유사 패턴의 연쇄살인사건이 발생하고 15년을 기다린 희주의 계획은 전혀 예측하지 못한 새로운 국면을 맞이하게 되는데…  15년의 기다림, 7일간의 추적 그 놈을 잡기 위한 강렬한 추적이 시작된다!', '2016-03-10', 7.233, 7.76, 108, '모홍진', 75, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (391907, '동거의 목적', '동거의 목적', 'movie', 'https://image.tmdb.org/t/p/w500/2XrA9pyHNoxuxNHQmSX3VCtZ7Ev.jpg', 'https://image.tmdb.org/t/p/original/p3KfASmwHwTCkSn5xH2j8LmLDZH.jpg', '신혼생활을 만끽하는 승구와 윤혜. 사진작가인 승구는 출근길 이웃 사촌이면서 선배인 정열과 한눈을 팔다가 신호대기중이던 앞차를 들이받고 엄청난 수리비때문에 괴로워 한다. 몸매 관리에 여념이 없는 윤혜는 어김없이 헬스장에 운동을 하러가고 담당 PT 인 태준의 이별얘기를 듣게 된다. 여자친구 집에서 동거를 하던 태준이 이별과 함꼐 쫓겨나게 되고 오갈 곳 없는 태준에게 윤혜는 자신의 신혼집 방 하나를 세를 놓아 승구의 수리비를 충당하려 하고 승구 역시 윤혜와 앙숙이자 친구인 모델 라라에게 자신의 집 월세를 제안한다. 그리고 그들의 목적(?)있는 동거가 시작되는데….', '2016-03-07', 4.8, 7.6519, 83, 'Joo Sung-woo', 4, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (435601, '브이아이피', '브이아이피', 'movie', 'https://image.tmdb.org/t/p/w500/nAF51unFGuizy0dOnmn74VytRLt.jpg', 'https://image.tmdb.org/t/p/original/nx0SKrYEQLvrvFQI9OZ0nJeiVUM.jpg', '국정원과 CIA의 기획으로 북에서 온 VIP 김광일이 살인사건의 유력한 용의자로 지목된다. 본능적으로 그가 범인임을 직감한 경찰 채이도가 VIP를 뒤쫓지만 국정원 요원 박재혁의 비호로 번번이 용의선상에서 벗어난다. CIA와 국정원 간의 ‘기획 귀순자’를 둘러싼 알력 다툼, 경찰의 봐주기 수사부터 검찰과의 거래, 여기에 북한 정치 상황 지형도까지 얽히는데...', '2017-08-23', 7.733, 7.9179, 128, '박훈정', 221, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (79224, '최종병기 활', '최종병기 활', 'movie', 'https://image.tmdb.org/t/p/w500/gaXSEQ2XzkFnKxYIvkqj4Tidltk.jpg', 'https://image.tmdb.org/t/p/original/l9KInBleoVHFB2TXxChn6pjlDxz.jpg', '50만 포로가 끌려간 병자호란, 치열했던 전쟁의 한 복판에 역사가 기록하지 못한 위대한 신궁이 있었다.  역적의 자손이자 조선 최고의 신궁 남이. 유일한 피붙이인 누이 자인의 행복만을 바라며 살아간다.어렵사리 맞이한 자인의 혼인날, 가장 행복한 순간에 청나라 정예부대(니루)의 습격으로 자인과 신랑 서군이 포로로 잡혀가고 만다. 남이는 아버지가 남겨준 활에 의지해 청군의 심장부로 거침없이 전진한다.귀신과도 같은 솜씨로 청나라 정예부대(니루)를 하나 둘씩 처치하는 남이, 한 발 한 발 청군의 본거지로 접근해간다. 남이의 신묘한 활솜씨를 알아챈 청의 명장 쥬신타는 왕자 도르곤과 부하들을 지키기 위해 남이를 추격하기 시작한다. 날아오는 방향을 예측할 수 없는 곡사를 사용하는 남이와 무시무시한 파괴력을 가진 육량시를 사용하는 쥬신타, 가장 소중한 것을 지키기 위한 사상 최대 활의 전쟁을 시작한다.', '2011-08-10', 7.235, 7.6111, 122, '김한민', 277, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (444143, '특이점이 온 영화', '특이점이 온 영화', 'movie', 'https://image.tmdb.org/t/p/w500/puWxBzjZVYcNT7ytOgMxkmFMlA4.jpg', 'https://image.tmdb.org/t/p/original/uXFHWMuYo1fhV2PTKoNNNO6BKgQ.jpg', '', '2017-03-07', 4, 6.4476, 82, 'Kong Ja-kwan', 5, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (384127, '남과 여', '남과 여', 'movie', 'https://image.tmdb.org/t/p/w500/3k4gDtGX8RPCGMJHTbgRVOwKk10.jpg', 'https://image.tmdb.org/t/p/original/ihKRS6P88bKlYK4nV5j6ccLn9hf.jpg', '핀란드의 하얀 설원 헬싱키. 아이들의 국제학교에서 만난 상민과 기홍은, 먼 북쪽의 캠프장을 향해 우연히 동행하게 된다. 폭설로 도로가 끊기고, 아무도 없는 하얀 숲 속의 오두막에서 둘은 깊이 안게 되고, 서로의 이름도 모른 채 헤어지게 된다. 8개월 후, 서울. 핀란드에서의 시간을 설원이 보여 준 꿈이라 여기고 일상으로 돌아온 상민 앞에 거짓말처럼 기홍이 다시 나타나고 둘은 걷잡을 수 없는 끌림 속으로 빠져든다.', '2016-02-25', 6.718, 6.8764, 115, '이윤기', 71, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (437542, '딸의 친구', '딸의 친구', 'movie', 'https://image.tmdb.org/t/p/w500/bR1ID2VvQIHrWKdToWKc3mIpeyW.jpg', 'https://image.tmdb.org/t/p/original/As12wwHuVa9Jtnd6XHX58RkzBFc.jpg', '"전 연하는 싫어요" 원기는 오래 전 아내를 잃고 홀로 지방으로 내려와 펜션 일을 하고 있다. 그러던 어느 날 서울에서 대학생활을 하던 원기의 딸 은지와 친구인 세영이 방학동안 원기의 펜션에 놀러와 지내게 되고 원기는 딸의 친구인 세영이 죽은 자신의 아내와 너무도 닮은 모습에 자기도 모르게 점차 끌리게 된다. 그러던 중 세영의 도발적인 유혹에 원기는 넘지 말아야할 선을 넘어버리고 마는데...', '2017-01-19', 4.2, 8.0855, 93, 'Choi Woo-seong', 4, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (813079, '타겟', '타겟', 'movie', 'https://image.tmdb.org/t/p/w500/xSSAK4QZGyvjkef978bv1i1UQ07.jpg', 'https://image.tmdb.org/t/p/original/elqCaVi6Amkx5hzPsJ3Km5Ru3Yg.jpg', '평범한 직장인 수현은 이사 후 세탁기를 중고거래로 구매하지만, 고장 난 세탁기를 받고 사기를 당했다는 사실을 알게 된다. 잠적한 판매자를 찾아내는데 성공한 수현은 그의 게시글마다 사기꾼이라는 댓글을 남겨 거래를 방해한다. 그날 이후 수현에게는 정체 모를 전화, 주문한 적 없는 음식 배달, 한밤 중 찾아오는 의문의 남자들까지 소름 끼치는 일들이 연이어 벌어진다. 개인 정보는 모두 유출되었고, 집안 곳곳에는 낯선 흔적들이 발견되면서 서서히 모든 일상이 파괴되기 시작한다. 드디어 본격적인 수사가 진행되고, 주형사와 중고거래 판매자의 집을 찾아간 수현은 그곳에서 시체를 발견하는데…', '2023-08-30', 6.821, 6.6235, 101, '박희곤', 78, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (11658, '태극기 휘날리며', '태극기 휘날리며', 'movie', 'https://image.tmdb.org/t/p/w500/9ZfNS44SZQd13EVUSu0VwEo7y18.jpg', 'https://image.tmdb.org/t/p/original/oqaKsofz49zjNhi48sxQIq8U73X.jpg', '1950년 6월. 서울 종로에서 가족의 생계를 책임지기 위해 열심히 살아가는 진태는 힘든 생활 속에도 약혼녀 영신과의 결혼과, 세상에서 가장 소중하게 생각하는 동생 진석의 대학진학을 위해 언제나 활기차고 밝은 생활을 해 나간다. 6월의 어느 날, 한반도에 전쟁이 일어났다는 호외가 배포되면서 평화롭기만 하던 서울은 순식간에 싸이렌 소리와 폭발음, 그리고 사람들의 비명 소리로 가득해진다. 이에 남쪽으로 피난을 결정한 진태는 영신과 가족들을 데리고 수많은 피난행렬에 동참하지만, 피난열차를 타기 위해 도착한 대구역사에서 거대한 운명의 소용돌이에 말려들고 만다.', '2004-02-05', 7.989, 19.7796, 148, '강제규', 744, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (18438, '김씨 표류기', '김씨 표류기', 'movie', 'https://image.tmdb.org/t/p/w500/jRrdzFcJUTz9yb6A5quSQrvhJDB.jpg', 'https://image.tmdb.org/t/p/original/t9T6jKk2TqDqzpWTCMSeMNjYcX7.jpg', '자살시도가 실패로 끝나 한강의 밤섬에 불시착한 남자. 죽는 것도 쉽지 않자 일단 섬에서 살아보기로 한다. 모래사장에 쓴 HELP가 HELLO로 바뀌고 무인도 야생의 삶도 살아볼 만하다고 느낄 무렵, 익명의 쪽지가 담긴 와인병을 발견하고 그의 삶은 알 수 없는 희망으로 설레기 시작한다. 한편 자신의 좁고 어두운 방이 온 지구이자 세상인 여자. 홈페이지 관리, 하루 만보 달리기 등 그녀만의 생활리듬도 있다. 유일한 취미인 달사진 찍기에 열중하던 어느 날, 저 멀리 한강의 섬에서 낯선 모습을 발견하고 그에게 리플을 달아주기로 하는 그녀는 3년 만에 자신의 방을 벗어나 그를 향해 달려가는데...', '2009-05-14', 7.922, 7.3714, 116, '이해준', 722, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1006026, '우리가족같이', '우리가족같이', 'movie', 'https://image.tmdb.org/t/p/w500/16Vz6OuUcwA1sxOa4e5c12QJDWp.jpg', NULL, '', '2018-10-29', 9, 5.3414, 93, NULL, 2, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (387847, '친구 누나', '친구누나', 'movie', 'https://image.tmdb.org/t/p/w500/5J0SWa3BEYdWfvMgtOJIBAMSPQf.jpg', 'https://image.tmdb.org/t/p/original/jCOC4DEPiUSBwHVF49CRXHWAfw6.jpg', '"누나, 그냥 우리집에서 살래요?"  섹시한 친구 누나와의 위험한 동거가 시작된다!  준수는 절친 희규의 누나 희진이 사기를 당해 오갈 곳이 없어진 사실을 알고 동거를 제안한다. 그날부터 시작된 두 사람의 위험한 동거. 친남매처럼 친하지만 절대로 친남매는 될 수 없는 두 성인 남녀는 자꾸만 야릇한 분위기를 풍기기 시작하고, 준수는 벽 너머에 잠들어 있을 희진의 생각에 잠 못드는 밤이 많아진다. 준수가 뭔가 변하고 있단 사실을 눈치 챈 여자친구 미나는 일부러 희진이 있는 집 안에서 준수를 유혹한다. 여자친구냐, 친구누나냐. 결코 답을 찾을 수 없는 난제가 준수 앞에 펼쳐진다.', '2016-03-10', 4.3, 7.1961, 84, 'Chae Gil-byeong', 10, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (313108, '국제시장', '국제시장', 'movie', 'https://image.tmdb.org/t/p/w500/rmZ4qkpDVdTgjwliJ84aJ43hStt.jpg', 'https://image.tmdb.org/t/p/original/wcMlVCKjTIT3g3fQNo5iXo586mk.jpg', '1950년대 한국전쟁 이후로부터 현재에 이르기까지 격변의 시대를 관통하며 살아온 우리 시대 아버지 덕수, 그는 하고 싶은 것도 되고 싶은 것도 많았지만 평생 단 한번도 자신을 위해 살아본 적이 없다. ‘괜찮다’ 웃어 보이고 ‘다행이다’ 눈물 훔치며 힘들었던 그때 그 시절, 오직 가족을 위해 굳세게 살아온 우리들의 아버지 이야기가 지금부터 시작된다.', '2014-12-17', 7.398, 7.0208, 126, '윤제균', 133, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (252509, '우리별 일호와 얼룩소', '우리별 일호와 얼룩소', 'movie', 'https://image.tmdb.org/t/p/w500/3OFIRkoUb5LTr24Siymbp3RxOJi.jpg', 'https://image.tmdb.org/t/p/original/kTUNeH0lWPpDOYEm8vwWATmDZxq.jpg', '어느 날 갑자기, 마법에 의해 소심한 얼룩소로 변해버린 ‘경천’. 영문도 모른 체 ‘소각자’에게 쫓기는 신세가 된 얼룩소 경천은 화장지 마법사 ‘멀린’의 도움으로 가까스로 구출된다.  한편 수명이 다해 지구로 추락하던 인공위성 ‘일호’ 역시 ‘멀린’의 마법으로 소녀의 모습으로 탄생하게 된다.  하지만 동물들과 얼룩소 경천을 팔아 넘기려는 사냥꾼 ‘오사장’과 마법에 걸린 사람들을 태워버리려는 소각자 등 검은 괴물들의 위협은 점점 더 가까워져 오는데…  과연 ‘얼룩소 경천’과 ‘로봇소녀 일호’ 화장지 마법사 ‘멀린’과 멧돼지 ‘북쪽마녀’까지 사상 최강의 마법드림팀은 악의 무리에 맞서 세상을 구해낼 수 있을까?', '2014-02-20', 7.19, 7.3262, 90, 'Chang Hyung-yun', 29, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (702454, '스와핑 : 친구의 아내2', '스와핑 : 친구의 아내2', 'movie', 'https://image.tmdb.org/t/p/w500/8NGBIQbpQaSzc2OWIN1BdOMAv7M.jpg', 'https://image.tmdb.org/t/p/original/5hQSm7FEGWnd0JnwjpMYyuP4p3m.jpg', '거부할 수 없는 제안, 욕망에 눈을 뜨다! 민호와 정식은 둘도 없는 친구 사이다. 그런데 정식이 사업 실패로 빚쟁이들한테 시달려 괴로워하자 민호는 자신의 집까지 빌려주면서 근처로 이사 오길 권한다. 어느 날, 두 부부는 술자리를 하던 중, 민호의 아내 소연이 불임으로 아이를 가질 수 없다는 고민을 털어놓는다. 그리고 정식의 아내 주희에게 자신을 대신해 남편의 아이를 낳아 주면 빚을 전부 갚아주겠다는 파격적인 제안을 한다. 제안을 승락한 날, 친구 정식과 아내가 섹스하는 걸 지켜 본 민호는 너무 괴로워하고, 그런 민호를 위해 소연도 옷을 벗는데...', '2018-07-19', 5, 6.5582, 70, 'Yoo Hae-jong', 1, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (437109, '악녀', '악녀', 'movie', 'https://image.tmdb.org/t/p/w500/2arvz5fsrE1BmlbjbBHSiLltlLq.jpg', 'https://image.tmdb.org/t/p/original/labMpUVoAqNlHTKiu7KsoZT0v9d.jpg', '조직의 킬러로 자란 숙희는 보스이자 연인이었던 중상의 복수를 위해 마약조직 하나를 박살낸다. 사건 직후 구속된 숙희는 국가정보원으로부터 10년간 국가를 위해 임무를 수행하면 자유를 주겠다는 거래를 제안받는다. 뱃속에 중상의 아기가 자라고 있음을 안 숙희는 새로운 삶을 위해 제안을 받아들이고 암살요원으로서의 생활을 시작한다. 한편 숙희를 철저히 감시, 통제하기 위해 국정원 요원 현수가 비밀리에 접근한다. 둘 사이의 관계가 가까워질 즈음 예상치 못한 인물의 등장으로 숙희의 거짓된 삶은 철저히 부서지기 시작한다.', '2017-06-08', 6.917, 7.4354, 123, '정병길', 745, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1316719, '얼굴', '얼굴', 'movie', 'https://image.tmdb.org/t/p/w500/gKxhGFwbaMq9LMnKJrsuZGodULk.jpg', 'https://image.tmdb.org/t/p/original/wduUhYLGaYSD2mSu7YHd09l1N6j.jpg', '태어나서 아무것도 볼 수 없었던 시각장애인임에도 불구하고 세상에서 가장 아름다운 도장을 만드는 장인으로 거듭난 임영규와 그의 아들 임동환에게 경찰에게서 한 통의 전화가 걸려온다. 40년 전 실종된 아내이자 어머니 정영희의 백골 사체가 발견되었다는 것. 얼굴조차 몰랐던 어머니가 살해됐을 가능성도 있다는 이야기를 듣게 된 임동환은 아버지 임영규의 다큐멘터리를 촬영하던 PD 김수진과 함께 어머니의 죽음을 추적하게 된다. 그리고 그 과정에서 만난, 40년 전 어머니와 함께 청계천 의류 공장에서 일했던 이들의 기억을 통해 가려진 진실을 마주하게 되는데……', '2025-09-11', 7, 5.3353, 102, '연상호', 16, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (453992, '박열', '박열', 'movie', 'https://image.tmdb.org/t/p/w500/1fjBtHc5tERLVZGWsSiwvUVLErk.jpg', 'https://image.tmdb.org/t/p/original/wt1CVgqkXJLTU28Se1g3HbyZBQq.jpg', '1923년, 관동대지진 이후 퍼진 괴소문으로 6천여 명의 무고한 조선인이 학살된다. 사건을 은폐하기 위해, 관심을 돌릴 화젯거리가 필요했던 일본내각은 불령사를 조직해 항일운동을 하던 조선 청년 박열을 대역사건의 배후로 지목한다. 일본의 계략을 눈치챈 박열은 동지이자 연인인 가네코 후미코와 함께  일본 황태자 폭탄 암살 계획을 자백하고, 사형까지 무릅쓴 역사적인 재판을 시작하는데...', '2017-06-28', 7.387, 7.4464, 129, '이준익', 31, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (123913, '勇立忍者', '勇立忍者', 'movie', 'https://image.tmdb.org/t/p/w500/gO7DJCcMKW6hV36fm5aLeCRlIHg.jpg', 'https://image.tmdb.org/t/p/original/lWpcuG0hwvu8PcXkryqPxyNjRoC.jpg', '', '1978-01-01', 7, 6.1721, 84, '하지강', 2, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (660360, '노량: 죽음의 바다', '노량: 죽음의 바다', 'movie', 'https://image.tmdb.org/t/p/w500/WqgLrAbPnEfgn7WP7J2IvL1Z9V.jpg', 'https://image.tmdb.org/t/p/original/ksZTspehDCC4PCZN8ci31pFT6yp.jpg', '임진왜란 발발로부터 7년이 지난 1598년 12월. 이순신은 왜군의 수장이던 도요토미 히데요시가 갑작스럽게 사망한 뒤 왜군들이 조선에서 황급히 퇴각하려 한다는 것을 알게 된다. 왜군을 완벽하게 섬멸하는 것이 이 전쟁을 올바르게 끝나는 것이라 생각한 이순신은 명나라와 조명연합함대를 꾸려 왜군의 퇴각로를 막고 적들을 섬멸하기로 결심한다. 하지만 왜군의 뇌물 공세에 넘어간 명나라 도독 진린은 왜군에게 퇴로를 열어주려 하고, 설상가상으로 왜군 수장인 시마즈의 살마군까지 왜군의 퇴각을 돕기 위해 노량으로 향하는데…', '2023-12-20', 6.34, 7.0315, 152, '김한민', 156, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (465603, '스와핑: 친구의 아내', '스와핑: 친구의 아내', 'movie', 'https://image.tmdb.org/t/p/w500/pPJSi1vcaN2YQjG4AzRM4b3mdIQ.jpg', 'https://image.tmdb.org/t/p/original/pcUN3xAov1UqKGo91m2gP2j7Wy.jpg', '일 욕심이 많은 아내 혜주를 위해 가정주부가 되기로 결심한 성식. 홀로 살림을 하느라 고군분투하는 성식의 바로 옆집에 친구 준석 부부가 이사 온다. 준석의 아내 은영에게 살림을 배우게 된 성식. 처음에는 말 잘 통하는 친구 같았던 성식과 은영은 곧 틈만 나면 자신의 아내와 남편 몰래 서로를 탐하게 되고, 이를 알아차린 준석과 혜주 또한 그동안 참아왔던 욕망에 눈을 뜨는데...', '2016-11-15', 3.8, 7.7987, 80, 'Hong Seong-soo', 5, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (134126, '회사원', '회사원', 'movie', 'https://image.tmdb.org/t/p/w500/ggOJ1bKbqt4qOb8L7JvWxmebIx1.jpg', 'https://image.tmdb.org/t/p/original/lWLM8cGkmscrLWYwIPPGmNDXqO9.jpg', '겉으로는 평범한 금속 제조 회사지만 알고 보면 ''살인''이 곧 실적인, 살인청부회사 내 영업 2부 과장 지형도. 한치의 실수도 범하지 않는 냉정함과 차분함으로 유능함을 인정받으며 회사에서 시키는 대로 앞만 보고 달려온 10년, 어렸을 적 자신의 모습과 닮은 알바생 훈을 만나게 된다.  훈과의 임무 수행 중, 순간의 망설임을 느낀 그는 집이고 학교고 가족이었을 만큼 전부였던 회사의 뜻을 처음으로 거스르게 된다.  훈의 가족과의 만남으로 처음으로 일상의 행복을 느끼는 형도. 그런 그를 늘 예의주시하던 기획이사 종태는 형도의 변화를 눈치채는데….', '2012-10-11', 6.813, 7.1555, 96, '임상윤', 193, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (842033, '괴기맨숀', '괴기맨숀', 'movie', 'https://image.tmdb.org/t/p/w500/fv0M8kyW95FpsrhoLTSCcEVR6hf.jpg', 'https://image.tmdb.org/t/p/original/mGLBObg2JwEwRzsWYCVCunTlszo.jpg', '공포 웹툰 작가 지우는 아이디어를 찾아 괴기맨숀이라 불리는 허름한 아파트에 도착한다. 표정을 알 수 없는 중년의 관리인은 이 아파트에서 일어났던 기묘한 사건들에 대해 이야기보따리를 풀어내고, 504호, 708호… 지우는 사연을 들을수록 홀리기라도 한 듯 괴기맨숀에 점점 집착하게 되는데...! 미스터리한 맨숀! 5개의 에피소드! 괴이하고 섬뜩한 현실 공포가 온다!', '2021-06-30', 7.227, 5.6759, 107, '조바른', 231, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (589174, '담보', '담보', 'movie', 'https://image.tmdb.org/t/p/w500/b6clzuYNbizWFUtcpLBsp00zXNe.jpg', 'https://image.tmdb.org/t/p/original/nwhk3FW2k19CokUBZYWAvtNFIcK.jpg', '1993년 인천, 거칠고 까칠한 사채업자 두석과 종배는 떼인 돈 받으러 갔다가 얼떨결에 9살 승이를 담보로 맡게 된다. 뜻도 모른 채 담보가 된 승이와 승이 엄마의 사정으로 아이의 입양까지 책임지게 된 두석과 종배. 하지만 부잣집으로 간 줄 알았던 승이가 엉뚱한 곳에 있다는 것을 알게 된 두 사람은 승이를 데려와 돌보게 된다. 예고 없이 찾아온 아이에게 인생을 담보 잡힌 두석과 종배. 빚 때문에 아저씨들에게 맡겨진 담보 승이. 두석, 종배, 승이 세 사람은 어느덧 서로에게 특별한 존재가 되는데...', '2020-09-29', 8.391, 7.8046, 113, 'Kang Dae-gyu', 69, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1306816, '좀비딸', '좀비딸', 'movie', 'https://image.tmdb.org/t/p/w500/aASLRiO8p9xLIvG9EHXSyZ71sPl.jpg', 'https://image.tmdb.org/t/p/original/gT7MXlPs7ohpdefR5cdgdPx1zsf.jpg', '댄스 열정을 불태우는 사춘기 딸 수아와 함께 티격태격 일상을 보내는 맹수 전문 사육사 정환. 어느 날 전 세계를 강타한 좀비 바이러스에 감염된 딸 수아를 지키기 위해 정환은 어머니 밤순이 사는 바닷가 마을 은봉리로 수아와 함께 향한다. 감염자를 색출해 내려는 사회 분위기 속에서 수아가 어렴풋이 사람 말을 알아듣고, 평소 좋아하던 춤과 할머니 밤순의 따끔한 효자손 맛에 반응하는 모습을 발견한다. 절대 수아를 포기할 수 없는 정환은 호랑이 사육사의 오랜 경험을 살려 좀비딸 트레이닝에 돌입하는데...', '2025-07-30', 6.828, 7.3957, 114, '필감성', 29, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (549590, '동네사람들', '동네사람들', 'movie', 'https://image.tmdb.org/t/p/w500/fL5OHCA7jXhvq4MOJAdVpJJzBF4.jpg', 'https://image.tmdb.org/t/p/original/vRl2GlAx1MWdnTYf3VGCKnbDx6i.jpg', '여고생이 사라졌지만 너무나 평온한 시골의 한적한 마을, 기간제 교사로 새로 부임 온 외지 출신 체육교사 ‘기철(마동석)’은 동네 분위기가 심상치 않음을 감지한다. 실종된 여고생의 유일한 친구 ''유진(김새론)''만이 친구가 납치된 거라 확신하여 사건을 쫓고, 의도치 않게 ‘유진’과 함께 사라진 소녀를 찾기 위해 나선 ‘기철’은 누군가에 의해 그녀의 흔적들이 사라지고 있다는 사실을 알게 되는데...', '2018-11-07', 7.447, 7.3529, 99, 'Im Jin-soon', 94, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (517991, '공작', '공작', 'movie', 'https://image.tmdb.org/t/p/w500/uTiYfP9ESTHl1tHw2VJzqdxEtvF.jpg', 'https://image.tmdb.org/t/p/original/fReqenpUkU83y7rpEMscE5EjoDr.jpg', '1993년, 북한 핵 개발을 둘러싸고 한반도의 위기가 고조된다. 정보사 소령 출신으로 안기부에 스카우트된 박석영은 ‘흑금성’이라는 암호명으로 북핵의 실체를 캐기 위해 북의 고위층 내부로 잠입하라는 지령을 받는다. 안기부 해외실장 최학성과 대통령 외에는 가족조차도 그의 실체를 모르는 가운데 대북사업가로 위장해 베이징 주재 북 고위간부 리명운에게 접근한 흑금성. 그는 수 년에 걸친 공작 끝에, 리명운과 두터운 신의를 쌓고 그를 통해서, 북한 권력층의 신뢰를 얻는데 성공한다. 그러나, 1997년. 남의 대선 직전에 흑금성은 남과 북의 수뇌부 사이 은밀한 거래를 감지한다. 조국을 위해 굳은 신념으로 모든 것을 걸고 공작을 수행했던 그는 걷잡을 수 없는 갈등에 휩싸이는데…', '2018-08-08', 7.364, 7.3585, 137, '윤종빈', 209, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1279, '사마리아', '사마리아', 'movie', 'https://image.tmdb.org/t/p/w500/tO5jMPnb7I25MafLUZKRBVPHCae.jpg', 'https://image.tmdb.org/t/p/original/lvWOPNKEKEFDUfYyWOz62N2T2D9.jpg', '"인도에 바수밀다 라는 창녀가 있었어. 그런데 그 창녀랑 잠만 자고 나면 남자들이 모두 독실한 불교 신자가 된데.. 날 바수밀다 라고 불러줄래? "  유럽 여행을 갈 돈을 모으기 위해 채팅에서 만난 남자들과 원조교제를 하는 여고생 여진과 재영. 여진이 재영인 척 남자들과 채팅을 하고 전화를 걸어 약속을 잡으면, 재영이 모텔에서 남자들과 만나 원조교제를 한다. 여진은 재영이 남자들을 만나기 전 화장을 해주고, 그녀가 남자들을 만나고 있는 동안 밖에서 기다린다. 낯 모르는 남자들과 만나 섹스를 하면서도 항상 웃음을 잃지 않는 재영. 여진은 남자들과의 만남과 섹스에 의미를 부여하는 재영을 여진은 이해 할 수가 없다. 여진에게 어린 여고생들의 몸을 돈을 주고 사는 남자들은 모두 더럽고 불결한 존재일 뿐이다. 그러던 어느 날, 모텔에서 남자와 만나던 재영은 갑자기 들이닥친 경찰들을 피해 창문에서 뛰어 내려 여진의 눈 앞에서 죽게 된다.  "돈 안 받을게요. 지난번 돈도 돌려줄게요. 그럼 편해지죠?"  재영의 죽음에 커다란 충격을 받은 여진은 재영의 죽음을 위로하기 위해 재영의 수첩에 적혀 있는 남자들을 차례로 찾아간다. 재영 대신 남자들과 원조교제를 하는 여진. 원조 교제 후 재영이 전에 받았던 돈을 여진이 차례로 돌려주자 남자들은 오히려 평안을 얻게 된다. 남자들과의 잠자리 이후 남자들을 독실한 불교 신자로 이끌었던 인도의 바수밀다와 같이 여진 또한 관계를 맺은 남자들을 차례로 정화해 나간다.  인간도 아닌 새끼. 그 어린 게 들어갈 구멍이 어디 있다고…  사건 현장에 나갔다가 우연히 옆 모텔을 보게 된 형사 영기는 모텔에서 남자와 함께 나오는 여자가 자신의 딸 여진임을 알게 된다. 아내 없이 오직 하나뿐인 딸만을 바라보며 살아온 영기에게 딸의 매춘은 엄청난 충격으로 다가오고, 이후 영기는 계속해서 여진을 미행하기 시작한다. 하루하루 남자들을 만나는 여진을 미행하던 영기는 여진과 만나는 남자들에게 접근하기 시작하는데…', '2004-03-05', 6.966, 6.5073, 95, '김기덕', 250, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (57474, '얼굴없는 미녀', '얼굴없는 미녀', 'movie', 'https://image.tmdb.org/t/p/w500/bMh7kSfB8gvxltYxbWl9c7RXsB3.jpg', 'https://image.tmdb.org/t/p/original/bIrHdysJFCxGqCXNjWWUysoPvoz.jpg', '아무도 오지 않은 파티의 주인공 지수는 붉은 핏물의 욕조 속에서 발견된다. 그녀는 지적이고 매혹적이지만 천국과 지옥을 오가는 경계선 장애로 정신과 전문의 석원의 상담을 받게 된다. 석원은 지수의 병이 누군가에게 버림받을지도 모른다는 위기감에서 생기는 마음의 병이라는 것을 알고 안타까워하지만, 병원을 떠나게 되고. 그로부터 1년 뒤, 더욱 불안하고 위태로워진 지수와 안정되어 보이지만 더욱 차가워진 석원은 아주 우연히 만나게 된다. 석원과 지수는 환자와 의사가 아닌 친구 사이로 서로의 속내를 보여주며 자연스럽게 가까워지고, 석원에게 마음을 열기 시작한 지수는 아무에게도 말하지 못한 가슴 속 사랑의 상처를 고백한다. 그녀를 도와주던 석원은 최면상태에서 지난 사랑을 회상하는 지수의 아름다운 모습과 누군가를 갈망하는 그녀의 몸짓에 흔들린다. 결국 자신의 욕망을 이기지 못하고 최면 속의 지수와 관계를 갖기에 이른다. 남편과의 새로운 출발을 위해 석원에게 작별인사를 하는 지수. 하지만, 최면을 통해 그녀의 몸은 가질 수 있었지만 마음은 가질 수 없는 현실 때문에 괴로워하는 석원은 마지막 만남에서, 다시는 지수를 볼 수 없다는 불안감에 해서는 안될 일을 벌이는데…', '2004-08-06', 5.4, 6.7495, 104, 'Kim In-shik', 17, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (121491, '연가시', '연가시', 'movie', 'https://image.tmdb.org/t/p/w500/5b9zIJ4AptjotWGsjPXox01rx5u.jpg', 'https://image.tmdb.org/t/p/original/61O5T8LT32NMRomUusjFmABMVIn.jpg', '고요한 새벽녘 한강에 뼈와 살가죽만 남은 참혹한 몰골의 시체들이 떠오른다. 이를 비롯해 전국 방방곡곡의 하천에서 변사체들이 발견되기 시작하는데… 원인은 숙주인 인간의 뇌를 조종하여 물 속에 뛰어들도록 유도해 익사시키는 ‘변종 연가시’. 짧은 잠복기간과 치사율 100%, 4대강을 타고 급속하게 번져나가는 ‘연가시 재난’은 대한민국을 초토화시킨다. 사망자들이 기하급수적으로 늘어나게 되자 정부는 비상대책본부를 가동해 감염자 전원을 격리 수용하는 국가적인 대응태세에 돌입하지만, 이성을 잃은 감염자들은 통제를 뚫고 물가로 뛰쳐나가려고 발악한다. 한편, 일에 치여 가족들을 챙기지 못했던 제약회사 영업사원 재혁은 자신도 모르는 사이에 연가시에 감염 되어버린 아내와 아이들을 살리기 위해 치료제를 찾아 고군분투한다. 그 가운데 그는 재난사태와 관련된 심상치 않은 단서를 발견하고 사건 해결에 나서게 되는데…', '2012-07-05', 6.597, 6.2721, 109, 'Park Jung-woo', 113, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (566397, '남산의 부장들', '남산의 부장들', 'movie', 'https://image.tmdb.org/t/p/w500/eUMI51eeUxpS6wDNJoPEncAI9q5.jpg', 'https://image.tmdb.org/t/p/original/m0Zp6dlmjfpolhMWx6KHJvmFlOk.jpg', '1979년 10월 26일, 중앙정보부장 김규평이 대한민국 대통령을 암살한다. 이 사건의 40일전, 미국에서는 전 중앙정보부장 박용각이 청문회를 통해 전 세계에 정권의 실체를 고발하며 파란을 일으킨다. 혁명 동지의 배신으로 발칵 뒤집힌 청와대가 박용각의 처리를 명하자 김규평은 원만한 수습을 위해 직접 박용각을 만나 회유한다. 상황은 일단락되는 듯 보였지만 김규평은 맹목적인 충성으로 폭주하는 경호실장 곽상천과 2인자 경쟁을 벌이는 한편 실체를 가늠하기 힘든 대통령의 비밀조직에 압박을 느끼며 점차 불안에 휩싸인다.', '2020-01-22', 7.096, 7.8986, 113, '우민호', 146, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (610251, '하얼빈', '하얼빈', 'movie', 'https://image.tmdb.org/t/p/w500/xrqAcOddbmWfxDxuGHChR4QmscA.jpg', 'https://image.tmdb.org/t/p/original/biJctq3zk4Km3hYkRQWN91yt0rY.jpg', '1908년 함경북도 신아산에서 안중근이 이끄는 독립군들은 일본군과의 전투에서 큰 승리를 거둔다. 대한의군 참모중장 안중근은 만국공법에 따라 전쟁포로인 일본인들을 풀어주게 되고, 이 사건으로 인해 독립군 사이에서는 안중근에 대한 의심과 함께 균열이 일기 시작한다. 1년 후, 블라디보스토크에는 안중근을 비롯해 우덕순, 김상현, 공부인, 최재형, 이창섭 등 빼앗긴 나라를 되찾기 위해 마음을 함께하는 이들이 모이게 된다. 이토 히로부미가 러시아와 협상을 위해 하얼빈으로 향한다는 소식을 접한 안중근과 독립군들은 하얼빈으로 향하고, 내부에서 새어 나간 이들의 작전 내용을 입수한 일본군들의 추격이 시작되는데…', '2024-12-24', 7.513, 4.9355, 108, '우민호', 40, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (361539, '함정', '함정', 'movie', 'https://image.tmdb.org/t/p/w500/vI6dRKxESSnXJWsP7F7XYkZTnXS.jpg', 'https://image.tmdb.org/t/p/original/zjzb6fCn797CfmO4eRCMV8kFkzP.jpg', '5년째 아이가 없는 부부, 준식과 소연. 소연은 기분 전환을 위해 준식과 휴대폰도 터지지 않는 외딴 섬으로 여행을 떠나고, 그 곳에서 인터넷을 통해 우연히 알게 된 한 맛집에 가게 된다.  그곳의 허름하고 험악한 분위기의 불안한 기운이 감돌지만 이들이 온 것을 눈치챈 주인 성철은 보자마자 너무나도 친절하게 대하고 준식과 소연은 점점 경계를 풀게 된다.  화기애애한 분위기 속에 해가 지고 성철의 환대에 준식과 소연은 하룻밤만 묵고 가기로 하는데, 이때부터 의문의 묘한 분위기가 이들을 덮쳐오기 시작한다.  그 때 성철은 소연을 알아보는 듯 하며 알 수 없는 말을 건네는데...  함정에 빠뜨리려는 자와 빠져 나가려는 자의 목숨을 건 대결이 시작된다!', '2015-09-10', 6.261, 6.6281, 96, 'Kwon Hyung-jin', 23, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (437633, '리얼', '리얼', 'movie', 'https://image.tmdb.org/t/p/w500/9olCCHvaM8Oij0BxoOo00jcKmW.jpg', 'https://image.tmdb.org/t/p/original/jF1Gv9yjxOKKkwi0j6MCdJCh1dx.jpg', '카지노 ‘시에스타’ 오픈을 앞둔 조직의 보스 장태영(김수현) 앞에  암흑가 대부 조원근(성동일)이 카지노의 소유권을 주장하며 나타난다.  조원근의 개입으로 카지노를 빼앗길 위기에 처한 장태영은  자금 문제를 해결하기 위해 투자자를 찾아 나선다.  어느 날, 이름뿐만 아니라 생김새마저 똑같은 의문의 투자자(김수현)가 나타나  자금은 물론 조원근까지 해결해주겠다는 제안을 한다.  의문의 투자자의 등장으로 조원근과 카지노를 차지하기 위한 전쟁이 시작되고  이들을 둘러 싼 거대한 비밀과 음모의 정체가 서서히 드러난다.  오직 진짜만이 모든 것을 갖는다!', '2017-06-28', 5.328, 6.4654, 137, 'Lee Sa-rang', 67, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1248482, '조건섹스 ： 라스트 원나잇', '조건섹스 ： 라스트 원나잇', 'movie', 'https://image.tmdb.org/t/p/w500/aZmCDAAx1G1FdZmFEBxsXVjPB9r.jpg', 'https://image.tmdb.org/t/p/original/b9QlwTGrtKYcJNTHXnRHr3Rlcy6.jpg', '', '2024-02-09', 10, 7.6968, 70, 'Lee Ta-chi', 2, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (675308, '호텔 레이크', '호텔 레이크', 'movie', 'https://image.tmdb.org/t/p/w500/hCr1FiejbRJBUjFZyZF5c8O9HGp.jpg', 'https://image.tmdb.org/t/p/original/zYnbFFXPe4IfCtFtaIWigYrdqLP.jpg', '유미가 어린 동생을 맡기기 위해 엄마의 친구인 경선의 호텔로 찾아간다. 두 자매를 가족처럼 반기는 호텔 레이크 사장 경선과 이상한 이야기만 늘어 놓는 유일한 메이드 예린. 그 곳에서 기이한 사건과 충격적인 비밀을 마주하게 되는데...', '2020-04-29', 6.3, 7.3774, 101, '윤은경', 26, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (398222, '용주골', '용주골', 'movie', 'https://image.tmdb.org/t/p/w500/z71W04S43PfM4Vdvz3NgGLEF7He.jpg', 'https://image.tmdb.org/t/p/original/xvOcGiZDIsGak2s7oENhJdU17uS.jpg', '은밀하고 가장 뜨거운 바로 그 곳! 사상 최대의 방송사고(!?)가 시작된다! 용주골의 생계형 건달 용화(민도윤)는 발길이 끊긴 손님들과 악덕 돈줄 강회장(박종환)에게 빚 독촉을 받다가 온라인에 유행하는 성인방송국을 시작하기로 결심한다. 용주골의 선수 끝판왕 섹시 BJ 마샬(이채담)을 내세워 순식간에 엄청난 반응을 끌어 모으는 용화. 성깔 있는 질투화신 BJ 방울(진서현)까지 가세해 순식간에 둘은 뜨거운 BJ 인기경쟁을 시작하는데... 과연, 이들의 화끈한 온라인 섹시스캔들은 성공할 수 있을까!??', '2015-11-19', 4.5, 6.951, 94, 'Choi Woo-seong', 4, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (270759, '일대일', '일대일', 'movie', 'https://image.tmdb.org/t/p/w500/upveqhqTATvMcVDTZvIlv4dwQ2D.jpg', 'https://image.tmdb.org/t/p/original/pxiLyTDe09V1crB2pyAnce4jQXB.jpg', '5월 9일, 한 여고생이 잔인하게 살해당한다. 살인 용의자 7인과 그들에게 테러를 감행하는 ‘그림자’ 7인. 이들의 정체는 무엇인가? 이들 중 당신은 누구인가?', '2014-05-22', 6.185, 6.5612, 122, '김기덕', 46, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (783110, '밀수', '밀수', 'movie', 'https://image.tmdb.org/t/p/w500/ayLXqPZCu3uaLLhXiqvw5NBb7Lw.jpg', 'https://image.tmdb.org/t/p/original/vZaIAIX5XcXLsF4jRSp5x7wsRzn.jpg', '1970년대, 바닷가에 인접한 작은 마을 군천엔 절친인 두 해녀 춘자와 진숙, 그리고 진숙의 동생이 살고 있다. 그들은 생계를 위해 항상 물 속에서 해산물들을 채집하는 일을 한다. 하지만 해변 근처에 공장들이 하나 둘 지어지면서, 해녀들의 생계에 곤란이 생기고 선원들은 생계를 위해서 밀수 일에 뛰어들게 된다. 그렇게 시작된 밀수업은 진숙의 가족이 감당하기 벅찰만큼 규모가 커지고 마을의 평화도 점차 깨지기 시작한다.', '2023-07-26', 6.514, 7.7391, 129, '류승완', 69, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (542836, '협상', '협상', 'movie', 'https://image.tmdb.org/t/p/w500/imd5SWNlfs0uoaDftLvb9ZlgLKr.jpg', 'https://image.tmdb.org/t/p/original/3BSAzy9aXXWCBvJCgLgPxLuquEk.jpg', '어떠한 상황에서도 냉철함을 잃지 않던 최고의 협상가 하채윤은 긴급 투입된 현장에서 인질과 인질범 모두 사망하는 사건을 겪고 충격에 휩싸인다. 그로부터 10일 후, 경찰청 블랙리스트에 오른 국제 범죄조직의 무기 밀매업자 민태구가 태국에서 한국 경찰과 기자를 납치하고 그녀를 협상 대상으로 지목한다. 이유도 목적도 조건도 없이 사상 최악의 인질극을 벌이는 민태구와 그를 멈추기 위해 한치도 물러설 수 없는 협상가 하채윤. 남은 시간 12시간, 목숨을 건 일생일대의 협상이 시작된다!', '2018-09-19', 7.061, 6.2694, 114, '이종석', 155, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (2440, '공동경비구역 JSA', '공동경비구역 JSA', 'movie', 'https://image.tmdb.org/t/p/w500/6pZw6KFwrADsS4HYfJe8AHMwpQh.jpg', 'https://image.tmdb.org/t/p/original/z7w6ACQJTeGYASr1plSwfRe6Ytk.jpg', '비무장지대 수색 중 지뢰를 밟아 대열에서 낙오된 이수혁 병장은 북한군 중사 오경필과 전사 정우진의 도움으로 다행히 목숨을 건진다. 이를 계기로 그들은 친해졌고 이수혁 병장은 군사분계선을 넘어 그들을 만나러 간다. 그러던 어느날 그들이 만나는 장면을 북한군에게 들키고 친형제처럼 친하게 지내던 그들은 서로 총부리를 겨눈다. 그리고 판문점 공동경비구역 내 북한 초소에서 총성이 울린다. 사건의 진상을 밝히기 위해 중립국 감독위원회 소속의 한국계 스위스인 소피 장 소령이 파견된다. 그녀는 진실을 밝히기 위해 그들을 만나는데...', '2000-09-09', 7.825, 7.2731, 110, '박찬욱', 783, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (21115, '바람의 파이터', '바람의 파이터', 'movie', 'https://image.tmdb.org/t/p/w500/dz0Rnu1F8LB75D54EgJSzYwuW2r.jpg', 'https://image.tmdb.org/t/p/original/h9lQKuyioiPh6RfNsR2IyAt1b5l.jpg', '한국인이 일본인을 위한 종처럼 여겨지던 일제시대, 소년 최배달은 머슴 범수를 통해 택견을 배우며 강한 파이터의 꿈을 키운다. 그러나 독립운동에 연류된 범수가 자취를 감추고 스승을 잃은 배달은 비행사가 되기 위해 일본으로 밀항하기에 이른다. 하지만 항공학교에서 그를 기다리는 것은 상상을 넘어선 차별 뿐. 조센징이라는 차별에 대한 분노로 교관을 때려 눕히는 배달. 그러나 맨 손의 그에게 사무라이의 후예인 가토 대위가 살기어린 진검을 겨누고, 배달은 칼날에 등을 보인 채 도주하고 마는데...', '2004-08-12', 7.1, 7.4686, 120, '양윤호', 175, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (560527, '내안의 그놈', '내안의 그놈', 'movie', 'https://image.tmdb.org/t/p/w500/ofhf0Tn7hnBtboiUEuVj5IZyD3g.jpg', 'https://image.tmdb.org/t/p/original/f5xCw22fOR6DgDRCpDFGkPbKbmY.jpg', '옥상에서 떨어진 고등학생 동현이 길을 가던 엘리트 아재 판수를 덮치면서 제대로 바뀐다!? 게다가 판수는 동현의 몸으로 첫사랑 미선과 존재도 몰랐던 딸 현정을 만나게 되는데… 대유잼의 향연, 넌 이미 웃고 있다!', '2019-01-09', 7.801, 6.3988, 122, '강효진', 146, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (619166, '양자물리학', '양자물리학', 'movie', 'https://image.tmdb.org/t/p/w500/5UKX6L0WnxNZOonN5bkwKOFiMhI.jpg', 'https://image.tmdb.org/t/p/original/3p59KRj3cSHYNUHv3NrZVkeF0Fh.jpg', '‘생각이 현실을 만든다’라는 양자물리학적 신념을 인생의 모토로 삼은 유흥계의 화타 ‘이찬우’. 어느 날 유명 연예인이 연루된 마약 파티 사건을 눈치챈다. “불법 없이! 탈세 없이!” 이 바닥에서도 혁신이 일어나야 한다고 믿는 그는 오랫동안 알고지낸 범죄정보과 계장 ‘박기헌’에게 이 정보를 흘린다. 단순한 사건이라고 생각했던 마약파티가 연예계는 물론 검찰, 정치계까지 연루된 거대한 마약 스캔들임을 알게 된 ''이찬우''. 이제는 살기 위해 거대 권력과 맞서야 하는 상황. ''이찬우’는 ‘박기헌’ 계장을 비롯해 황금인맥을 자랑하는 업계 퀸 ‘성은영’ 등 업계 에이스들과 함께 이 사건을 파헤치기로 한다. 9월, 부패 권력에 통쾌하게 맞서라! 생각은 현실을 만드니까!', '2019-09-25', 6.05, 7.0202, 119, 'Lee Seong-tae', 20, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (390845, '맛있는 비행', '맛있는 비행', 'movie', 'https://image.tmdb.org/t/p/w500/kw7QEMiIFW7EjZQSRO9ebKls21k.jpg', 'https://image.tmdb.org/t/p/original/7MXxVfzj77qA6aV3cOnj1AZnyDg.jpg', '홍콩(?)행 기내 서비스가 시작됩니다! 광활한 창공에서 펼쳐지는 리얼 19금 연애담! 청순가련의 대명사였지만 아이돌과의 섹스 스캔들로 도망친 여배우, 그녀의 모든 커리어를 망쳐 버린 발랑 까진 아이돌, 그녀에게 절대 충성하는 열혈 매니저, 그리고 이제는 섹시한 승무원이 된 매니저의 전 여친까지! 절대 만나선 안 될 네 사람이 비행기 안에서 마주쳤다. 도망칠 수 없는 그곳에서 지나치게 발칙하고 지독하게 화끈한 로맨스가 펼쳐진다.', '2015-11-01', 4.3, 6.7323, 97, 'Choi Sang-hoon', 69, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (19588, '두사부일체', '두사부일체', 'movie', 'https://image.tmdb.org/t/p/w500/eKg1t2dkiO5cWv251sIytgEKLj0.jpg', 'https://image.tmdb.org/t/p/original/ovLJAwkA28f8lwLL5PqfmnkyLk1.jpg', '타고난 카리스마로 한국 조직사회에서 급부상하고있는 영동파 두목 계두식. 명동파를 접수하고 조직 수뇌부들과 처음으로 회의를 하게 된다. 큰 형님에게 떨어진 명령은 고등학교 졸업장. 수하 상두와 대가리는 두목을 학교로 보내기 위해 사립고교에 기부금 입학을 시키게 되는데...', '2001-12-14', 6.038, 6.0372, 98, '윤제균', 26, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (133601, '이웃사람', '이웃사람', 'movie', 'https://image.tmdb.org/t/p/w500/xVvKWcqiHFMT5EcllYyTOUu95gu.jpg', 'https://image.tmdb.org/t/p/original/9S0TLAQAjVfBvMTnla3WV64NJYN.jpg', '죽은 소녀도,  살인마도,  그를 막는 사람들도 모두  202호 소녀의 죽음, 그리고 열흘 간격으로 발생하는 연쇄살인사건  범인의 실마리는 잡히지 않고, 강산맨션의 이웃사람들은 공포에 떤다.  그러던 중 이웃사람들은 수십 만원대의 수도세, 사건발생일마다 배달시키는 피자,  사체가 담긴 가방과 똑 같은 가방을 사 간 102호 남자를 의심하기 시작한다.  그리고 살인마 또한 이웃사람들을 눈치채기 시작하고, 두 번째 소녀의 죽음을 막기 위한  마지막 대결이 시작되는데…', '2012-08-22', 7.296, 7.0319, 110, 'Kim Hwi', 93, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (492008, '검객', '검객', 'movie', 'https://image.tmdb.org/t/p/w500/cpthM8fEZoPGRcROtEJnOZGXEvY.jpg', 'https://image.tmdb.org/t/p/original/5lmhjGvg5ddXbTXzeNJfU4qpIeh.jpg', '광해군 폐위 후, 스스로 자취를 감춘 조선 최고의 검객 태율. 한편, 조선을 사이에 둔 청과 명의 대립으로 혼란은 극에 달하고, 청나라 황족 구루타이는 무리한 요구를 해대며 조선을 핍박한다. 백성들의 고통이 날로 더해가던 중, 구루타이의 수하들에 의해 태율의 딸이 공녀로 잡혀가고 만다. 세상을 등진 채 조용히 살고자 했던 조선 최고의 검객 태율은 딸을 구하기 위한 자비 없는 검을 휘두르기 시작하는데...', '2020-09-23', 7.509, 6.9939, 100, 'Choi Jae-hoon', 281, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (87332, '완벽한 파트너', '완벽한 파트너', 'movie', 'https://image.tmdb.org/t/p/w500/vjfjxlRNP2BH6RAFHoE8QNwXwEU.jpg', 'https://image.tmdb.org/t/p/original/cbfJ35FoAxUy8DC02McfZaVZx5y.jpg', '지금 당신에게 필요한건 화끈한 연애다!젊은 남자의 기발한 아이디어가 좋다. 아이디어를 훔치는 선생 ''희숙''!젊은 여자의 불타는 창작의욕이 끌린다. 재능을 꽃피워주는(?) 선생 ''준석''!슬럼프에 빠진 두 선생과 짜릿한 영감을 주는 제자의 아슬아슬한 만남!서로 속고 속이는 네 남녀의 화끈 짜릿한 연애가 시작된다!', '2011-11-17', 5.1, 4.9407, 125, 'Park Hun-soo', 11, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (602295, '유체이탈자', '유체이탈자', 'movie', 'https://image.tmdb.org/t/p/w500/jsJluzrVEkQBYYkTNj3FQJ0LkAM.jpg', 'https://image.tmdb.org/t/p/original/9GVaQMfv8uhIKWQdDUxP02intKW.jpg', '교통사고 현장에서 눈을 뜬 한 남자. 거울에 비친 낯선 얼굴과 이름, 자신이 누구인지 기억이 나지 않는다.  잠시 후, 또 다른 사람의 몸에서 깨어난 남자. 그는 12시간마다 몸이 바뀐다는 사실을 깨닫게 되고, 자신을 둘러싼 사람들 사이의 연결고리를 찾기 시작한다. 모두가 혈안이 되어 쫓고 있는 사람이 바로 자신임을 직감한 남자, 자신을 찾기 위한 사투를 시작하는데…', '2021-10-17', 6.384, 7.2736, 108, 'Yoon Jae-geun', 82, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (607844, '모가디슈', '모가디슈', 'movie', 'https://image.tmdb.org/t/p/w500/oeu5TgAd0MrHplBIvCFpt9AIEBm.jpg', 'https://image.tmdb.org/t/p/original/5lxs92IwlmU9m2tzHL05pqxZsht.jpg', '유엔 가입을 위해 다수의 투표권을 지닌 아프리카 대륙에서 열심히 외교 활동을 벌이던 1990년. 소말리아의 수도 모가디슈에서도 남북의 외교전은 불이 붙는다. 한신성 주소말리아 한국 대사와 안기부 출신의 강대진 참사관, 북한의 림용수 대사와 태준기 참사관은 함정을 파거나 거짓 정보를 흘려가며 서로를 견제한다. 한편 소말리아의 상황은 불안하기 그지없다. 부패한 독재정권을 몰아내려는 반군과 정부군의 대치는 1990년 12월 30일 반군이 수도 모가디슈에 입성하면서 내전으로 번진다. 통신은 물론 항공편마저 끊겨 아수라장이 된 모가디슈. 북한 대사관 사람들은 반군의 공격으로 갈 곳을 잃고, 한신성 대사는 도움을 요청한 북한 사람들을 관저로 들이는데...', '2021-07-28', 7.074, 7.4728, 121, '류승완', 188, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1174128, '동화지만 청불입니다', '동화지만 청불입니다', 'movie', 'https://image.tmdb.org/t/p/w500/mkQE7ZOhBMoVhDFbwLiJ43T5GzX.jpg', 'https://image.tmdb.org/t/p/original/1E2WVVwN0L8KtgvmtaHhER3DpvO.jpg', '동화 작가가 꿈이지만 현실은 불법 음란물 단속팀 새내기인 단비는 스타 작가를 찾던 성인 웹소설계 대부 황대표와 우연한 사고로 노예 계약을 맺게 되면서 하루아침에 19금 소설을 쓰게 된다. 생전 접한 적 없는 장르를 집필하는 데 난항을 겪던 단비는 음란물 단속을 하다 권태기에 빠진 선배 정석의 응원과, 친구들의 생생한 경험담에 힘입어 어느새 자신도 알지 못했던 성스러운 재능을 발견하게 되는데…', '2025-01-08', 7.438, 7.2513, 110, '이종석', 16, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (270143, '베드', '베드', 'movie', 'https://image.tmdb.org/t/p/w500/vTSJKOthj778xb4oKFJk2MIeUfq.jpg', 'https://image.tmdb.org/t/p/original/yI8TCJodRtc0Fw6L8MeciyIJtBb.jpg', '우울증에 걸린 우유부단한 성격의 남자 B(장혁진), 자신의 성적 욕구를 위해서라면 불륜도 마다하지 않는 지루함이 싫고 일탈이 필요하지만 그런 자신의 굴레를 벗고 싶지 않은 E(이민아). 그리고 유능한 커리어 우먼과 충실한 부인을 동시에 갈망하는 가정이 필요했던 남자의 아내 D (김나미), 이들 세 사람의 퍼즐게임 같이 뒤엉키는데…', '2012-10-07', 4, 7.3418, 89, '박철수', 4, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (373961, '속눈썹이 긴 여자', '속눈썹이 긴 여자', 'movie', 'https://image.tmdb.org/t/p/w500/elnT1NC6qlRGpTfxksiO9c8aYiI.jpg', 'https://image.tmdb.org/t/p/original/6wOkBLpHj9UvReeNNE0H4A7inNJ.jpg', '카메라맨 남규가 찍은 사진 한장이 주간지에 실리는데 사진내용은 한쌍의 남녀가 차에 치이는 장면이었다. 그 사고로 죽은 여인은 모회사의 상무인 동진의 아내였으며 남자는 카메라맨의 애인인 숙진의 동생이었다. 며칠후 숙진의 동생이 자살한 시체로 발견된다. 그러자 죽은 여자의 남편인 동진이가 살인 용의자로 지목되게 된다. 그러자 숙진은 동진이가 살해할 위인이 못된다는 것을 입증하려는 듯이 그와 결혼한다. 이에 남규는 숙진을 빼앗긴 분풀이로 동진이가 바로 살인범인 것을 강조한다. 그러나 경찰의 수사결과 동진의 혐의는 없어지고 재산을 탐내 사건을 조작한 진범들이 체포된다.', '1970-11-21', 0, 6.8197, 90, '임권택', 0, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (265851, '우는 남자', '우는 남자', 'movie', 'https://image.tmdb.org/t/p/w500/qWPNb1qYmaL5eExuNzOyKkn5aR.jpg', 'https://image.tmdb.org/t/p/original/c1fDKwLbInSP6AzTFUtiajJ4uGv.jpg', '낯선 미국 땅에 홀로 남겨져 냉혈한 킬러로 살아온 곤.  조직의 명령으로 타겟을 제거하던 중 예상치 못한 실수를 저지르고, 그는 자신의 삶에 깊은 회의를 느낀다. 그런 그에게 조직은 또 다른 명령을 내리고, 곤은 마지막 임무가 될 타겟을 찾아 자신을 버린 엄마의 나라, 한국을 찾는다. 남편과 딸을 잃고, 치매에 걸린 엄마를 돌보며 하루하루 절망 속에서 살아가고 있는 여자, 모경. 엄청난 사건에 연루된 것도 모른 채 일만 파고들며 술과 약이 없으면 잠을 이루지 못하던 그녀 앞에 딸의 죽음 뒤에 감춰진 진실을 알려주겠다는 한 남자가 다가온다.  잃을 것이 없는 남자와 남은 게 없는 여자, 그들이 절벽의 끝에서 만났다', '2014-06-04', 7.222, 7.5277, 117, '이정범', 279, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (766369, '브로큰', '브로큰', 'movie', 'https://image.tmdb.org/t/p/w500/kgSFFG6HbyzSHOZCwf03iwokDhW.jpg', 'https://image.tmdb.org/t/p/original/t0gMBj6bglENkhulbUsmNwfREht.jpg', '어느 날 하나뿐인 동생 석태가 시체로 돌아왔다. 그리고 동생의 아내 문영은 자취를 감췄다. 동생이 죽고 진실이 잠든 밤, 분노가 깨어났다. 사건의 실마리를 찾던 민태는, 자신과 같은 흔적을 쫓는 소설가 호령을 만나고 그의 베스트셀러 야행에서 동생의 죽음이 예견되었다는 사실을 알게 된다. 얽혀버린 진실 사이에서 혼란스러운 가운데, 형제가 몸담았던 조직과 경찰까지 개입하며 서로가 서로를 쫓고 민태는 동생이 죽은 그날 밤의 진실을 밝히기 위해 분노의 추적을 시작한다.', '2025-02-05', 6.162, 6.2997, 100, 'Kim Jin-hwang', 34, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (84768, '오래된 정원', '오래된 정원', 'movie', 'https://image.tmdb.org/t/p/w500/jO9pWGTGiBXZc60MLjnjspnHpKN.jpg', 'https://image.tmdb.org/t/p/original/cbmFxHhO3ZZDnxsFMqYuScZ3J7h.jpg', '80년대 군부독재에 반대하다가 젊음을 온통 감옥에서 보낸 현우(지진희 분). 17년이 지난 눈 내리는 어느 겨울, 교도소를 나선다. 변해 버린 가족과 서울풍경, 핸드폰이란 물건까지, 모든 것이 그에게는 낯설기만 하다. 단 한 사람, 감옥에 있던 17년 동안 한번도 만나지 못했던 지갑 속 사진의 얼굴만이 익숙하게 다가온다. 잊을 수 없는 그 얼굴, 바로 한윤희(염정아 분)다. 며칠 후, 현우의 어머니는 그에게 한윤희의 편지를 건넨다. "소식 들었니? 한선생, 죽었어." 1980년, 도피생활을 하던 현우는 그를 숨겨줄 사람으로 한윤희를 소개받는다. 윤희는 첫눈에 봐도 당차고 씩씩하다. 자신은 운동권이 아니라고 미리 선언하지만, 사회주의자라는 현우의 말에 "아... 그러세요? 어서 씻기나 하세요, 사회주의자 아저씨!" 라며 웃는다. 현우는 그런 윤희와의 갈뫼에서의 생활에, 마치 딴 세상에 온 듯 한 평화로움을 느낀다. 그렇게 6개월이 지난 후, 동료들이 모두 붙잡혔다는 서울 소식에 갈등하던 현우는 갈뫼를 떠날 결심을 한다. 그리고 윤희는 그를 잡고 싶지만 잡을 수가 없다. 그렇게 그들은 헤어지고 17년이 흐른다. 다시 현재...그는 그들의 오래된 정원을 찾을 수 있을까? 윤희의 흔적이 고스란히 남겨져 있는 갈뫼를 다시 찾은 현우. 그는 윤희가 그에게 남긴 일기와 그림을 찾으며 17년 전의 과거로 빠져든다. 과연, 그는 그곳에서 그토록 꿈꾸었던 그들의 오래된 정원을 찾을 수 있을까?', '2006-09-24', 6.389, 7.3269, 112, '임상수', 17, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (386871, '관음증', '관음증', 'movie', 'https://image.tmdb.org/t/p/w500/3YeuIKucsgbwAFHV5jHC7mX7Mha.jpg', 'https://image.tmdb.org/t/p/original/vzHuYklMztypx3LWXkGLSGikGCB.jpg', '전직 사진 기자였지만 불미스러운 사건으로 해고 당한 후 지금은 파파라치로 생계를 유지하는 재훈. 깔끔한 일 처리로 정평이 나 있는 그의 주된 일은 불륜현장을 포착하는 것이다. 어느 날 재훈은 묘령의 여인으로부터 쌍둥이 여동생을 관찰해 달라는 의뢰를 받는다. 의뢰인의 여동생이 성상담 클리닉을 운영하는 의사라는 사실을 알게 된 재훈은 호기심에 그녀를 찾아가 상담을 받는다. 그리고 그날부터 그녀를 몰래 관찰하기 시작한다. 시간이 지날수록 여의사에게 집착하며 관음증 증세를 보이는 재훈. 예상치 못한 그의 행동에 여의사의 언니는 사건 의뢰를 취소하지만 이미 재훈의 관음증과 여의사의 도발은 도를 넘었다. 그러던 중 의뢰인과 여의사가 쌍둥이가 아닌 동일 인물이라는 것과 자신을 파멸시키기 위한 의도적 행동이었음을 알게 된 재훈은 자해를 해 두 눈을 멀게 한다. 앞을 보지 못하는 재훈의 관음증은 사라졌을까? 과연 재훈은 변태 성욕자였을까? 아니면 진심으로 여의사를 사랑했던 한 남자였을까?', '2016-02-25', 4.2, 7.4678, 100, 'Lee Sang-Bin', 6, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (451997, '불한당: 나쁜 놈들의 세상', '불한당: 나쁜 놈들의 세상', 'movie', 'https://image.tmdb.org/t/p/w500/bW9tePApxcM2QmvOgeEfQippM2I.jpg', 'https://image.tmdb.org/t/p/original/zJ2uTOvMJOZu97L1EVo5HqdEdsN.jpg', '범죄조직의 1인자를 노리는 재호와 세상 무서운 것 없는 패기 넘치는 신참 현수는 교도소에서 만나 서로에게 끌리고 끈끈한 의리를 다져간다. 출소 후, 함께 권력을 차지하기 위해 의기투합하던 중, 두 사람의 숨겨왔던 야망이 조금씩 드러나고, 서로에 대해 새로운 사실을 알게 되면서 그들의 관계는 흔들리기 시작하는데…', '2017-05-17', 7.163, 5.8092, 120, '변성현', 135, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (280019, '황제를 위하여', '황제를 위하여', 'movie', 'https://image.tmdb.org/t/p/w500/xNELPRzugre05vFC36ilVfkerCF.jpg', 'https://image.tmdb.org/t/p/original/GEs4UyFZ4p25OvAa4idDi9VWjB.jpg', '촉망 받는 야구선수였지만 승부조작에 연루된 후 모든 것을 잃게 된 ‘이환’(이민기).  빠져 나갈 곳 없는 인생의 밑바닥에서 이환은  사채업과 도박판을 주름 잡는 부산 최대 규모의 조직,  황제 캐피탈의 대표 ‘상하’(박성웅)를 만나게 된다.  돈 앞에선 냉정하지만  자신의 식구들은 의리와 신뢰로 이끄는 상하.  이환의 잠재력을 본능적으로 알아 본 상하는  다른 조직원들의 우려와 반대에도 불구하고, 그를 자신의 세계로 끌어들인다.  이긴 놈만 살아남는 도박판 같은 세상.  상하의 절대적인 신임 속에서 이환은  타고난 승부근성과 거침없는 행보로 점점 자신의 영역을 넓히고,  감춰두었던 야망을 키워가는데…!', '2014-06-11', 5.719, 4.8108, 104, '박상준', 57, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (460448, '어린 아내', '어린 아내', 'movie', 'https://image.tmdb.org/t/p/w500/hcL83rs9t8mVwu6UbVZCG1bzmd0.jpg', 'https://image.tmdb.org/t/p/original/7sBvP9jyVIUykJCvRIo9D6tEbWI.jpg', '친구 딸 ‘성혜’가 종환의 집에 들어오면서 시끌시끌한 동거가 시작된다. 그녀는 집안을 난장판으로 만드는 것은 물론, 집에서 친구들과 술을 마시거나 남자친구와의 섹스를 즐기며 종환을 귀찮게 한다. 그러던 어느 날, 종환이 남자친구와 싸운 후 울고 있는 성혜의 마음을 달래주면서 점점 두 사람은 같이 있는 시간이 길어지고, 서로에게 의지하게 된다. 그렇게 성혜와 종환은 서로의 마음 한 켠에 자리 잡게 되면서 그리워한다. 결국 둘은 걷잡을 수 없이 서로에게 빠져들고 마는데...', '2016-07-04', 3, 6.9517, 85, 'Hwa Ni', 2, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1239596, '산골 나그네', '산골 나그네', 'movie', 'https://image.tmdb.org/t/p/w500/ajiVkRkZ0pf1sROrnpgQXJeq0X.jpg', 'https://image.tmdb.org/t/p/original/ulM2yXrFC2cxsjN3LOijHpZ3BYq.jpg', '눈보라가 휘날리는 날 낯선 여인이 덕돌이네 집앞에 허기져서 쓰러진다. 덕돌이는 그녀를 구해 한가족처럼 산다. 그러나 그녀는 밤만 되면 물레방아에 숨겨둔 남편을 위해 몰래 밥을 나른다. 그는 바로 문화재인 대금의 명인 곽파람이었다. 덕돌이는 가희를 사랑하게 되나 가희는 곽파람이 부는 대금소리에 끌려 남편을 찾는다.', '1978-11-17', 8, 5.9778, 90, '문여송', 1, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (709792, '오! 꿈의 나라', '오! 꿈의 나라', 'movie', 'https://image.tmdb.org/t/p/w500/5N4233LY7wsyc3t20gCf5pq3YYT.jpg', 'https://image.tmdb.org/t/p/original/dYPUd6R18TEK79dJcbwzF1ToDxS.jpg', '광주민중항쟁이 무력으로 진압된 이후 종수는 계엄당국의 수사를 피해 고향의 형 뻘 되는 태호를 찾아 동두천으로 온다. 그는 전남대의 학생이며 야학의 교사이며 광주항쟁에서의 활동 때문에 쫓기는 신세다. 태호는 미군부대의 스넥 바에서 일하지만 실제 본업은 미제 물건장사이다. 한 몫 벌어 미국으로 떠버리는 것이 인생의 목표인 태호와 미군 때문에 거칠 대로 거칠어진 양공주들과의 생활에서 종수는 동화되지 못하며, 한편으로는 광주항쟁의 기억으로 인해 괴로운 나날을 보낸다.', '1989-01-15', 3.5, 6.3055, 90, 'Jang Dong-hong', 1, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (571786, '걸캅스', '걸캅스', 'movie', 'https://image.tmdb.org/t/p/w500/v1sfULur2KiJIPGiXjGTDWNWxG.jpg', 'https://image.tmdb.org/t/p/original/tUjjNaogeMPP4sw1U7Baxk1Oj1U.jpg', '민원실 퇴출 0순위 전직 전설의 형사 미영과 민원실로 밀려난 현직 꼴통 형사 지혜. 집에서는 눈만 마주쳐도 으르렁 대는 시누이 올케 사이인 두 사람은 민원실에 신고접수를 하기 위해 왔다가 차도에 뛰어든 한 여성을 목격하고 그녀가 48시간 후 업로드가 예고된 디지털 성범죄 사건의 피해자란 사실을 알게 된다. 강력반, 사이버 범죄 수사대, 여성청소년계까지 경찰 내 모든 부서들에서 복잡한 절차와 인력 부족을 이유로 사건이 밀려나자 미영과 지혜는 비공식 수사에 나서기로 결심한다. 수사가 진전될수록 형사의 본능이 꿈틀대는 미영과 정의감에 활활 불타는 지혜는 드디어 용의자들과 마주할 기회를 잡게 되는데...', '2019-05-09', 6.953, 6.6555, 107, '정다원', 74, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (349345, '나는 소망한다 내게 금지된 것을', '나는 소망한다 내게 금지된 것을', 'movie', 'https://image.tmdb.org/t/p/w500/85lDzujGyiw3PIR5j5BURRclMDn.jpg', NULL, '27세의 강민주(최진실)는 대학원에서 심리학을 전공한 후 여성문제 상담소에서 일한다. 세상은 절망의 텍스트일 뿐이라고 말하는 그녀는 어릴 적 아버지가 어머니에게 가한 폭행 때문에 성에 대한 왜곡된 시각을 지니고 있다. 상담소에서 여러 형태의 남성폭력을 접한 민주는 남성에 대한 분노로 상징적인 복수를 계획한다. 당대의 톱스타이자 여성들의 우상인 백승하(임성민)를 납치하기로 한 것. 그의 죄목은 여성들에게 남성에 대한 환상을 심어준 것이다. 민주의 심복 황남기는 그를 민주의 아파트로 납치하고 승하를 사육하기 시작한다. 외부에서는 경찰들의 포위망이 좁혀지는 가운데 세 사람은 폭행과 토론을 시작하는데....', '1994-02-09', 5, 6.2936, 115, '장길수', 1, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (1268127, '휴민트', '휴민트', 'movie', 'https://image.tmdb.org/t/p/w500/f7sCSLEPRfV2fWQ0RYOtHhnHXuG.jpg', 'https://image.tmdb.org/t/p/original/5KFThZkdBEQkp9gPWWWNb5CI5yD.jpg', '비밀도, 진실도 차가운 얼음 바다에 수장되는 블라디보스토크에서 서로 다른 목적을 가진 이들이 격돌하는 이야기', '2026-02-11', 0, 7.6365, 120, '류승완', 0, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (340067, '나의 절친 악당들', '나의 절친 악당들', 'movie', 'https://image.tmdb.org/t/p/w500/1tOITCWrf2zziEaDAQv1SlcEl5f.jpg', 'https://image.tmdb.org/t/p/original/mfMOqnhDoicZ7xvj1xyKDEjIE0K.jpg', '의문의 사고현장, 사라진 돈가방  계획에 없던 그날, 모든 것이 달라졌다!  인턴 지누에게 첫 번째 임무가 내려진다. 그동안 감시해온 차량의 이동라인을 완벽하게 파악해 상세히 보고하는 것. 하지만, 뒤쫓던 차가 대형트럭과 충돌하면서 그의 임무 수행은 순식간에 실패로 돌아간다. 한편, 사고수습을 위해 달려온 렉카차 운전자 나미는 반파된 차량 뒷좌석에서 수상한 가방을 발견하고, 그녀를 뒤쫓아온 지누 역시 가방의 정체를 알게 되면서 함께 나눠 갖기로 한다.  하지만 이때부터 두 사람은 가방을 되찾으려는 일당의 표적이 되고, 위험천만한 상황 앞에 놓인 지누와 나미는 악랄한 추격에 맞서 더 지독한 악당이 되기로 결심하는데...  있는 자들을 향한 나쁜 놈들의 짜릿한 반격!  이제부터 우리는 진짜 악당이 된다!', '2015-06-25', 5.208, 6.4393, 109, '임상수', 12, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (41245, '박하사탕', '박하사탕', 'movie', 'https://image.tmdb.org/t/p/w500/zxCr6MBF7BPr4r8RiYyuNps4DWN.jpg', 'https://image.tmdb.org/t/p/original/frgkz9c6Kzn0en6tlwpR2C3vjkC.jpg', '1999년 봄, 마흔 살이 된 영호는 가리봉 봉우회 야유회에 허름한 행색으로 나타난다. 20년 전 첫사랑 순임과 소풍을 왔던 그 곳에서, 그는 아무도 끼워 주지 않는 틈을 비집고 들어가 광기어린 행동을 보인다.  직업도 가족도 모두 잃고, 삶의 막장에 다다른 영호는 철로 위에서 ''나 다시 돌아갈래''라고 절규한다. 영호의 절규는 기차의 기적소리를 뚫고 시간을 거슬러 올라간다. 사흘 전 봄, 94년 여름, 87년 봄, 84년 가을, 80년 5월, 그리고 마지막 79년 가을. 마침내, 영호는 스무 살 첫사랑 순임을 만난다.', '2000-01-01', 7.464, 7.748, 135, '이창동', 278, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (30843, '서양골동양과자점 앤티크', '서양골동양과자점 앤티크', 'movie', 'https://image.tmdb.org/t/p/w500/7qDdIZbuplDPNI0rLZaoY3xYlx3.jpg', 'https://image.tmdb.org/t/p/original/cHDaR8kaFzZPLaI1GdpqxW0Z8yb.jpg', '단 것은 질색하면서 손님이 대부분 여자라는 이유만으로 케이크 가게를 차린 엉뚱한 사장 진혁. 한적한 주택가 골목길에 자리잡은 서양골동품점을 개조해, 몇 백만 원짜리 앤틱 식기에 케이크를 담아 내오고 새벽 2시까지 영업을 하는 별난 케이크숍 ‘앤티크’를 오픈하고 업계 최고라 불리는 파티쉐 선우까지 영입한다. 그런데 선우는 하필이면 고교시절 진혁에게 사랑을 고백해왔던 껄끄러운 동창생! 거기다 누구나 첫눈에 반하게 만드는 ‘마성의 게이’로 끊임없이 남자 문제를 일으키는 통에 몇 달째 직원조차 구하기 힘들다. 결국 선우의 케이크 맛에 홀딱 반한 케이크광 기범이 주방 보조이자 견습생으로 들어오고, 진혁을 도련님이라고 부르며 그림자처럼 따라다니는 보디가드 수영이 서빙을 맡게 된다. 마침내 본격적인 영업을 시작한 앤티크는 잘생긴 남자들만 모인 케이크숍으로 입소문이 나면서 연일 성업이다. 그런데 이 네 남자, 멀끔한 겉모습들과는 달리 무언가 수상하다! 남자들과는 거침없이 복잡한 연애를 즐기는 마성의 게이 선우가 어찌된 일인지 여자 앞에만 서면 벌벌 떠는 심각한 여성공포증이 있고, 곱상한 외모와는 정반대로 거친 성격의 기범은 알고 보니 최연소 동양챔피언이었던 전직 복서로 밝혀지고, 몸짱 보디가드 수영은 허우대가 무색한 사고뭉치로 오히려 늘 진혁의 보살핌을 받고 있다. 가장 의뭉스런 일은 수다쟁이 호색한 진혁이 가족만 나타나면 품행 방정한 재벌 2세 도련님으로 돌변하는 것인데…! 겉만 보곤 도저히 알 수 없는 알쏭달쏭 네 남자, 다들 무슨 사연일까?', '2008-11-13', 6.2, 6.9729, 109, '민규동', 64, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (107235, '건축학개론', '건축학개론', 'movie', 'https://image.tmdb.org/t/p/w500/fxKyRHx54Vbiwk98fhFqTXu3e3w.jpg', 'https://image.tmdb.org/t/p/original/mhYkTN7wcb53nzEerIt0RSojLCw.jpg', '생기 넘치지만 숫기 없던 스무 살, 건축학과 승민은 건축학개론 수업에서 처음 만난 음대생 서연에게 반한다. 함께 숙제를 하게 되면서 차츰 마음을 열고 친해지지만, 자신의 마음을 표현하는 데 서툰 순진한 승민은 입 밖에 낼 수 없었던 고백을 마음 속에 품은 채 작은 오해로 인해 서연과 멀어지게 된다. 서른 다섯의 건축가가 된 승민 앞에 15년 만에 불쑥 나타난 서연. 당황스러움을 감추지 못하는 승민에게 서연은 자신을 위한 집을 설계해달라고 한다. 자신의 이름을 건 첫 작품으로 서연의 집을 짓게 된 승민, 함께 집을 완성해 가는 동안 어쩌면 사랑이었을지 모를 그때의 기억이 되살아나 두 사람 사이에 새로운 감정이 쌓이기 시작하는데...', '2012-03-22', 7.352, 6.9777, 118, '이용주', 135, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (477378, '깜보', '깜보', 'movie', 'https://image.tmdb.org/t/p/w500/bPwP0CMo2iaMFnEDQ01QycFe6J3.jpg', NULL, '밀수 혐의로 복역 5년 만에 출감한 깜보(장두이)는 공범이었던 동일을 찾아간다. 그러나 동일이 자신을 배신하고 미국으로 건너갔다는 소식만 전해 듣는다. 설상가상으로 그는 소매치기 제비(박중훈)에게 금시계를 뺏앗은 일로 인해 살인누명까지 쓰고 전국에 수배되기에 이른다.  이제 깜보는 아내와 자식이 기다리는 고향으로도 가지 못하는 신세가 된다. 살인누명을 벗기 위해 그는 제비를 찾아 나서게 되고, 둘은 곧 친해지게 된다. 제비와 깜보는 살인의 뒷배경에 코브라라는 거물이 있다는 것을 알아낸다. 결국 코브라의 제안에 그들은 돈을 받고 다시 한 번 누명을 쓰고 수감된다.  출감 후, 깜보와 제비는 돈을 가지고 깜보의 고향에 돌아간다. 그러나 고향에 도착한 깜보는 자신을 배신한 친구 동일이 자신의 부인과 아이와 함께 살림을 꾸리고 목장을 경영하고 있는 것을 보게 된다.', '1986-03-15', 5, 5.6435, 100, 'Hwang-rim Lee', 1, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (42384, '가루지기', '가루지기', 'movie', 'https://image.tmdb.org/t/p/w500/35sluk2cRZsDHzn0jSIK3SfSrlg.jpg', 'https://image.tmdb.org/t/p/original/wGk3QhflKUXft8eN1sAHBnkzm3t.jpg', '음양의 불일치로 기센 아낙네들이 주도권을 잡은 마을, 떡장수를 하는 청년 강쇠는 밤일 제대로 하는 남정네 하나 없는 마을에서도 단연 부실 랭킹 1위! 온 마을 아낙네들의 놀림거리로 살아간다. 그러던 강쇠의 굴욕인생에 어느 날 일생일대의 사건이 일어났으니!  우연히 만난 음양통달 도사님에게 비책을 전해 듣고 500% 가득 찬 양기로 돌아온 변강쇠!!! 졸지에 마을 최고 완소남으로 변신한 강쇠는 천지를 뒤흔드는 막강파워로 아낙네들은 물론 온 동네 동물들마저 놀라게 만드는 상상초월 활약을 펼친다. 이제 그 앞에 펼쳐진 것은 온갖 산해진미를 싸들고 줄을 선 아낙네들의 들이대기 러시와 조선 방방곡곡에서 쏟아지는 스포트라이트!  조선 최고의 거물로 인생역전에 성공한 강쇠, 그러나 마냥 행복할 것만 같던 그의 앞날에 감당할 수 없는 큰 시련이 다가오는데…', '2008-04-30', 5.777, 4.7522, 120, '신한솔', 47, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (435603, '싱글라이더', '싱글라이더', 'movie', 'https://image.tmdb.org/t/p/w500/4sd0UOlaIlaH486WHq20KGvKFOU.jpg', 'https://image.tmdb.org/t/p/original/eoZEmBq7R29c2Ma6OcHInyIZR6w.jpg', '증권회사의 지점장 강재훈. 안정된 직장과 반듯한 가족, 나름 성공한 인생이라 생각했다. 어느 날 부실채권 사건으로 모든 것을 잃어버린 그는 가족이 있는 호주로 떠난다. 그러나 다른 삶을 준비하는 아내 수진의 모습을 보고 선뜻 다가가지 못하고 돌연 자취를 감추는데...', '2017-02-22', 7.237, 6.7503, 97, 'Lee Zoo-young', 38, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (408620, '아수라', '아수라', 'movie', 'https://image.tmdb.org/t/p/w500/hrkpHTjBeuEaxNJetjCPtNsi5bv.jpg', 'https://image.tmdb.org/t/p/original/1Q9xEpkSTBgJISMZFLiPt96Jlhs.jpg', '강력계 형사 한도경은 이권과 성공을 위해 각종 범죄를 저지르는 악덕시장 박성배의 뒷일을 처리해주는 대가로 돈을 받는다. 악에 계속 노출되는 사이,  말기 암 환자인 아내의 병원비를 핑계로 돈 되는 건 뭐든 하는 악인의 길로 들어서게 된 한도경. 그의 약점을 쥔 독종 검사 김차인과 검찰 수사관 도창학은 그를 협박하고 이용해 박성배의 비리와 범죄 혐의를 캐려 한다. 각자의 이익과 목적을 위해 한도경의 목을 짓누르는 검찰과 박성배. 그 사이 태풍의 눈처럼 되어 버린 한도경은, 자신을 친형처럼 따르는 후배 형사 문선모를  박성배의 수하로 들여보내고, 살아남기 위해 혈안이 된 나쁜 놈들 사이에서 서로 물지 않으면 물리는 지옥도가 펼쳐진다.', '2016-09-28', 6.809, 7.0829, 132, '김성수', 115, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (57361, '황해', '황해', 'movie', 'https://image.tmdb.org/t/p/w500/nuZvoEcYkIIQLMIMbQ72dmlyDJD.jpg', 'https://image.tmdb.org/t/p/original/lnxXvGylX41RRTuSXIEM7P0eBYu.jpg', '연변에서 택시를 모는 구남은 빚더미에 쌓여 구질구질한 일상을 살아간다. 한국으로 돈 벌러 간 아내는 6개월째 소식이 없고, 돈을 불리기 위해 마작판에 드나들지만 항상 잃을 뿐이다. 어느 날 살인청부업자 면가에게서 한국 가서 사람 한 명 죽이고 오라는 제안을 받는다. 절박한 현실에서 선택의 여지가 없는 구남은 빚을 갚기 위해, 그리고 아내를 만나기 위해 황해를 건넌다. 매서운 바다를 건너 서울로 온 구남은 틈틈이 살인의 기회를 노리면서 동시에 아내의 행방을 수소문하지만, 자신의 눈 앞에서 목표물이 살해 당하는 것을 목격한 구남은 누명을 쓴 채 경찰의 추적을 피해 도망 친다.', '2010-12-22', 7.345, 7.2485, 141, '나홍진', 545, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (354275, '지금은맞고그때는틀리다', '지금은맞고그때는틀리다', 'movie', 'https://image.tmdb.org/t/p/w500/rWk5GaMmgtNQkOI50CpW4QDb0Om.jpg', 'https://image.tmdb.org/t/p/original/vOPqsZ8DFfbeuwqjFh5hGW47nTD.jpg', '실수로 영화감독 함춘수는 수원에 하루 일찍 내려간다. 다음날 특강을 기다리며 들른 복원된 궁궐에서 윤희정이라는 화가를 만난다. 둘은 윤의 작업실에 가서 윤의 그림을 구경하고, 저녁에는 회에다 소주를 많이 마신다. 거기서 가까워지는 두 사람. 다른 카페로 이동한 두 사람은 술을 더 마신다. 거기서 누군가의 질문 때문에 함은 자신의 결혼한 사실을 할 수 없이 말하게 되고, 윤은 함에게 많이 실망하게 된다…  이런 비슷한 만남과 헤어짐의 이야기가 다시 한 번 이어진다. 여자가 더 목소리가 위축되어 있고, 몸도 굽어져 있다. 둘이 돌아다니는 데는 비슷한데, 여기선 남자가 옷도 벗고 그런다.', '2015-09-24', 7, 6.5377, 121, '홍상수', 159, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (23538, '비열한 거리', '비열한 거리', 'movie', 'https://image.tmdb.org/t/p/w500/4RoOAqRKgjvTyNDTYVpICiaAgIX.jpg', 'https://image.tmdb.org/t/p/original/nHeUqmbEjtth8XqaTgyw85WNXBQ.jpg', '삼류조폭조직의 2인자 병두. 조직의 보스와 치고 올라오는 후배들 틈에서 제대로 된 기회한번 잡지 못하는 그는, 조직 내에서도 하는 일이라곤 떼인 돈 받아주기 정도인 별볼일 없는 인생이다. 병든 어머니와 두 동생까지 책임져야 하는 그에게 남은 것은 쓰러져가는 철거촌 집 한 채 뿐. 삶의 무게는 스물아홉 병두의 어깨를 무겁게 짓누른다.  어렵사리 따낸 오락실 경영권마저 보스를 대신에 감방에 들어가는 후배에게 뺏긴 병두는 다시 한번 절망에 빠지지만, 그런 그에게도 기회가 온다. 조직의 뒤를 봐주는 황회장이 은밀한 제안을 해온 것. 황회장은 미래를 보장할 테니 자신을 괴롭히는 부장검사를 처리해달라는 부탁을 한다. 병두, 고심 끝에 위험하지만 빠른 길을 선택하기로 한다.  황회장의 손을 잡음으로써 가족들의 생계를 걱정하지 않아도 되게 된 병두는 영화감독이 되어 자신을 자신을 찾아온 동창 민호와의 우정도, 첫사랑 현주와의 사랑도 키워나가며 이제야 인생을 사는 것 같다는 생각을 한다. 그렇게 새로운 삶에 대한 꿈을 키워나가던 어느 날, 병두는 동창 민호에게 그 누구에게도 털어놓지 못했던 속내를 털어놓게 되는데…', '2006-10-17', 7.021, 7.4912, 141, '유하', 215, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (180651, '전설의 주먹', '전설의 주먹', 'movie', 'https://image.tmdb.org/t/p/w500/rk6zNA8ZKH4Uf0RxTp91prE8kkX.jpg', 'https://image.tmdb.org/t/p/original/WofAoNy0PNie9r0IUe38oqxxKw.jpg', '학창시절, 화려한 무용담들을 남기며 학교를 평정했던 파이터들 중 진짜 최강자는 누구였을까?  한때 ‘전설’이라 불렸던 그들이 맞붙어 승부를 가리는 TV파이트 쇼 ‘전설의 주먹’.  세월 속에 흩어진 전국 각지의 파이터들이 하나 둘씩 등장하고, 쇼는 이변을 속출하며 뜨겁게  달아오른다. 그리고 화제 속에 등장한 전설의 파이터 세 사람에 전국민의 시선이 집중된다.', '2013-04-10', 7.083, 7.1537, 153, '강우석', 54, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (103750, '돈의 맛', '돈의 맛', 'movie', 'https://image.tmdb.org/t/p/w500/5wBYDAOVgPHGZzREG2mbVRzA3xv.jpg', 'https://image.tmdb.org/t/p/original/n8aPq7Hfcc4BZu3znLY1kFMqNpJ.jpg', '대한민국을 돈으로 지배하는 재벌 백씨 집안의 탐욕스러운 안주인 금옥. 돈에 중독되어 살아온 자신의 삶을 모욕적으로 느끼는 그녀의 남편 윤회장. 백씨 집안의 은밀한 뒷일을 도맡아 하며 돈 맛을 알아가는 비서 영작. 그런 영작에게 묘한 감정을 느끼며 다가가는 장녀 나미. 돈을 지배한, 돈에 지배된 그들의 얽히고 설킨 권력, 욕정, 집착의 관계들. 이 시대 최고의 맛! 돈의 맛에 중독된 대한민국 최상류층의 숨겨진 이야기가 공개된다.', '2012-05-17', 5.5, 7.8811, 115, '임상수', 63, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (10355, '쉬리', '쉬리', 'movie', 'https://image.tmdb.org/t/p/w500/5XzSBzlXsvP1WMkqggtrsY8U0Zt.jpg', 'https://image.tmdb.org/t/p/original/kwZvgDGG0gZdhOuV0fjEm32PYep.jpg', '국가 비밀기관 OP의 특수요원인 중원과 장길은 최근 일어난 암살 사건을 수사 중이다. 제보를 약속한 무기밀매상 보스 임봉주가 눈앞에서 저격당하자, 둘은 저격 스타일을 보고 북한 특수요원 이방희가 활동을 재개했음을 안다.  북에서는 이방희의 특수교관이었던 박무영이 북한 특수 8군단과 함께 내려오고 유중원과 이장길은 최근의 암살이 국방부에서 개발한 CTX와 관련이 있다는 사실을 알게 된다. 이를 깨달은 둘은 국방과학 연구소로 향하지만 이미 박무영이 CTX를 탈취한 상태다.  항상 적은 한 발 앞서 OP의 상황을 알게되고 OP 내부에서는 서로를 의심하게 된다. 명현과 결혼을 앞둔 중원은 명현을 피신시키는데...', '1999-02-13', 6.428, 7.0736, 123, '강제규', 181, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (711978, '가슴 큰 울 엄마 2', '가슴 큰 울 엄마 2', 'movie', 'https://image.tmdb.org/t/p/w500/3qotZafIXzrgq7SUmHsBY6onRcU.jpg', 'https://image.tmdb.org/t/p/original/vawcE8k02PmvrAgZE4BuwOcf6Hs.jpg', '민수와 재혁은 사이좋은 부자지간이다. 그런데 어느날 아버지 민수가 젊은 새엄마 다희를 데려오고 재혁은 방황하다 집을 나가버리게 된다. 집을 나간 재혁이를 우연히 만난 다희의 친구 나연. 재혁을 잡아 둘이 이야기를 한다. 나연은 다희를 부르고... 다희는 재혁과 함께 집으로 돌아간다. 재혁이 돌아왔지만 크게 신경을 쓰지 않는 민수. 재혁은 다희에게 품은 감정을 말해버린다. 한편, 다희와 재혁의 사이를 못마땅해 하는 민수는 나연을 불러 시간을 가진다. 한편 그런 민수를 보며 다희가 걱정되는 나연은 새로운 계획을 세우는데....​', '2020-05-27', 4.429, 7.2718, 69, '이동준', 7, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (571648, '지푸라기라도 잡고 싶은 짐승들', '지푸라기라도 잡고 싶은 짐승들', 'movie', 'https://image.tmdb.org/t/p/w500/aA2o9i2DhGXptIcDQLLRjVmkLft.jpg', 'https://image.tmdb.org/t/p/original/8SPp11OFAferF7GnK9ATMihIMWp.jpg', '가업으로 물려받은 사업에 실패하고 사우나에서 야간 알바를 하는 중만. 치매 노모를 모시고 살며 경제적으로도 쪼들리던 그는 어느날 로커룸에서 거액의 현금 다발이 든 돈 가방을 발견하고 그 돈을 자기가 가지기로 마음먹는다. 세관 공무원 태영은 사채업자에게 큰돈을 빌려 사업을 하는 애인 연희에게 투자 명목으로 빌려주지만 연희는 잠적하고, 사채업자의 압박이 시작된다. 그러던 중 연희로 의심되는 여성의 사체가 발견된다. 주식투자로 빚을 지고 남편의 폭력에 시달리던 미란은 돈을 벌기 위해 접대부로 일하는데, 손님으로 만난 진태가 남편을 죽여주겠다고 제안하자 솔깃한다. 이후 각자 다른 욕망을 가진 이들의 관계가 하나둘 밝혀지기 시작한다.', '2020-02-19', 7.095, 6.8425, 108, 'Kim Yong-hoon', 268, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (421928, '럭키', '럭키', 'movie', 'https://image.tmdb.org/t/p/w500/32ZO0IREGvASVhb2XPnlYNgkCtX.jpg', 'https://image.tmdb.org/t/p/original/3wy4UTqaSwP1luw14SxMO5kxq5M.jpg', '냉혹한 킬러 형욱은 사건 처리 후 우연히 들른 목욕탕에서 비누를 밟고 넘어져 과거의 기억을 잃게 된다. 인기도, 삶의 의욕도 없어 죽기로 결심한 무명배우 재성은 신변 정리를 위해 들른 목욕탕에서 그런 형욱을 보게 되고, 자신과 그의 목욕탕 키를 바꿔 도망친다. 이후 형욱은 자신이 재성이라고 생각한 채, 배우로 성공하기 위해 노력하는데…', '2016-10-13', 7.089, 6.1999, 112, 'Lee Kae-byeok', 140, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (269494, '끝까지 간다', '끝까지 간다', 'movie', 'https://image.tmdb.org/t/p/w500/2MCy07o0FHQYjigKim5bHF78267.jpg', 'https://image.tmdb.org/t/p/original/u0os34ctKo55sx6krTbO381ohNR.jpg', '어머니의 장례식 날, 급한 연락을 받고 경찰서로 향하던 형사 고건수.  아내의 이혼 통보, 갑작스런 내사 소식까지,  스트레스 폭발 직전의 건수는 실수로 사람을 치는 사고를 일으키고 만다.  되돌릴 수 없는 상황! 어떻게든 모면해야 하는 건수는  누구도 찾을 수 없는 곳, 바로 어머니의 관 속에 시체를 숨기는데...', '2014-05-29', 7.068, 7.1251, 111, '김성훈', 480, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (373959, '그 여자를 쫓아라', '그 여자를 쫓아라', 'movie', 'https://image.tmdb.org/t/p/w500/txTuI8OVe5r9pTyomMEewyjE46l.jpg', 'https://image.tmdb.org/t/p/original/uIAX64VYh0iT8M47nUxVYyDgEsX.jpg', '6.25 당시 어느 국민학교에 은닉했던 금괴를 괴한들이 발굴 후 살인사건이 일어난다. 이 소식을 들은 아미는 홍콩에서 살해된 것으로 알려진 아버지 민충식을 찾아 귀국하는데, 아미의 귀국과 더불어 주위에서 강력사건이 연발한다. 위장한 경찰이 아미의 신변을 보호하며 수사를 벌이는데, 살해된 것으로 알려진 민충식이 배후에서 조종한 것이였다. 그는 북괴 간첩이며 아미의 아버지도 아닌 아미의 원수였다. 결국 간첩단은 일망 타진되고, 금괴까지도 찾아내는데 성공한다.', '1970-07-26', 0, 6.2611, 86, '임권택', 0, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (123377, '피에타', '피에타', 'movie', 'https://image.tmdb.org/t/p/w500/xduKNVJjbUqlPYow57LD5KaHj8G.jpg', 'https://image.tmdb.org/t/p/original/iOmGHgU3qhCMTBcf73m528risb.jpg', '끔찍한 방법으로 채무자들의 돈을 뜯어내며 살아가는 남자 ‘강도(이정진)’. 피붙이 하나 없이 외롭게 자라온 그에게 어느 날 ‘엄마’라는 여자(조민수)가 불쑥 찾아 온다. 여자의 정체에 대해 끊임없이 의심하며 혼란을 겪는 강도. 태어나 처음 자신을 찾아온 그녀에게 무섭게 빠져들기 시작한다. 그러던 어느 날 여자는 사라지고, 곧이어 그와 그녀 사이의 잔인한 비밀이 드러나는데…', '2012-09-06', 7.074, 6.6924, 104, '김기덕', 399, 0);
