INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (245684, '흑백요리사: 요리 계급 전쟁', '흑백요리사: 요리 계급 전쟁', 'drama', 'https://image.tmdb.org/t/p/w500/tsEIrmV6SIbEVqPZimWqXGvbFcw.jpg', 'https://image.tmdb.org/t/p/original/p63GY5JaHX4fine4fgQkhSoqc6r.jpg', '경력과 장르를 가리지 않는다. 그저 요리만 잘하면 된다. 레스토랑 셰프부터 방구석 요리왕까지, 맛에 일가견이 있는 사람들의 경쟁. 그 어디에서도 볼 수 없던 치열한 요리 대결이 시작된다.', '2024-09-17', 8.5, 26.1098, 60, '김학민', 58, 0);
