INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (73036, '냉장고를 부탁해', '냉장고를 부탁해', 'drama', 'https://image.tmdb.org/t/p/w500/q0ZjzXScH2bZgqIWlT2xAQOPAH8.jpg', 'https://image.tmdb.org/t/p/original/uBp9d5J58yzjafKiWsz7cdctmIY.jpg', '2014년 12월 JTBC에서 방영을 시작한 요리 프로그램. 처치 곤란 천덕꾸러기 냉장고 속 재료들의 신분상승 프로젝트. 대한민국 최고의 셰프들이 당신의 냉장고를 탈탈 털어드립니다. 격조 높은 요리 토크쇼, 냉장고를 부탁해.', '2014-11-17', 8.5, 22.0718, 90, NULL, 4, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (99966, '지금 우리 학교는', '지금 우리 학교는', 'drama', 'https://image.tmdb.org/t/p/w500/d9yefq8dNke4UbuqStBtUcO9TxD.jpg', 'https://image.tmdb.org/t/p/original/8hp2CuGnw1iP5dLBVMAPUv23swx.jpg', '좀비 바이러스 발생의 시발점이 된 고등학교. 이곳에 갇힌 학생들은 필사적으로 탈출구를 찾아야만 한다. 그렇지 않으면 감염되어 좀비가 될 뿐.', '2022-01-28', 8.3, 21.667, 65, 'Chun Sung-il', 4229, 0);
