INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (72237, '최강전사 미니특공대', '최강전사 미니특공대', 'drama', 'https://image.tmdb.org/t/p/w500/4TzCyUOUWEMRU5Aq3JBSv0zNJJj.jpg', 'https://image.tmdb.org/t/p/original/nVwNws9cPuuXRYAjmee8MX0lu3O.jpg', '수 천년 전, 힘없고 약한 동물들은 스스로를 지키기 위해 특별한 능력을 가진 동물들을 선발하여 특공대를 조직하였다. 그들은 전 세계로 퍼져나가 위험에 빠진 동물들을 구하고 그들의 세력을 점차 확장시켜 나갔다. 오늘날 그들은 뛰어난 과학 기술을 바탕으로 막강한 힘을 키워 세계 평화에 기여하고 있다.', '2014-09-03', 6, 15.4803, 11, NULL, 4, 0);
