INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (79070, '검법남녀', '검법남녀', 'drama', 'https://image.tmdb.org/t/p/w500/w3vY4iqn1Go7zsoRCKqRfGXTPDq.jpg', 'https://image.tmdb.org/t/p/original/it0fRj6zOV9o5rIzxmjqqSAAS8t.jpg', '모든 접촉은 흔적을 남긴다! 범죄에도, 그리고 인생에도. 그리하여 완전 범죄란 없다. 그러나 그들의 공조는 완전하다. 피해자를 부검하는 괴짜 법의학자와 가해자를 수사하는 초짜 검사의 아주 특별한 공조가 펼쳐진다. 완벽주의에 괴팍한 성격을 가진 법의학자인 백범과 포토메모리 능력을 가졌지만 허당미 가득한 검사 은솔의 공조 수사를 다룬 드라마.', '2018-05-14', 6.897, 9.2922, 30, 'Son Hyung-Suk', 39, 0);
