INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (231280, '굿보이', '굿보이', 'drama', 'https://image.tmdb.org/t/p/w500/cARQJDG8E2wY854UjVQPtFsjuvE.jpg', 'https://image.tmdb.org/t/p/original/8l1BN0IIjHmRyW0oDfUfs3F6F4N.jpg', '폭력과 범죄가 난무하는 세상. 경찰이 된 챔피언 운동선수들이 탁월한 능력으로 잔악무도한 악당들을 상대한다.', '2025-05-31', 8.723, 9.4424, NULL, 'Sim Na-yeon', 137, 0);
