INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (197067, '이상한 변호사 우영우', '이상한 변호사 우영우', 'drama', 'https://image.tmdb.org/t/p/w500/yv57TccCkgdy3St7rspBPKROeRK.jpg', 'https://image.tmdb.org/t/p/original/tmgtlnBnoFvk52xZBO7Z0pTmN9b.jpg', '2022년 6월 ENA에서 방영을 시작한 드라마. 천재적인 두뇌의 소유자이면서 동시에 자폐 스펙트럼 장애를 가진 영우는 강점과 약점을 한 몸에 지니고 있다. 영우의 강점은 우리들 대부분이 범접할 수 없을 만큼 탁월하지만, 영우의 약점은 우리들 대부분이 깜짝 놀랄 만큼 취약하다. 서울대 로스쿨을 수석 졸업하고 변호사 시험에 합격한 우영우가 대형로펌 법무법인 한바다의 변호사가 된다. 신입 변호사이자 자폐 스펙트럼 장애를 가진 여성으로서 그녀는 법정 안팎에서 다양한 난관을 헤쳐 간다.', '2022-06-29', 8.48, 8.6561, 70, 'Moon Ji-won', 894, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (7011, '빼꼼', 'Bernard', 'drama', 'https://image.tmdb.org/t/p/w500/23gJcNWCqLCzMRBlRqKvMozSUeV.jpg', 'https://image.tmdb.org/t/p/original/dg1gRMrZIoZo2PmvqRAh6zxUSCC.jpg', '사고뭉치 덜렁이에 호기심 많은 빼꼼이 도시로 오게 되면서 벌어지는 각종 사건과, 조금 모자란 듯 좌충우돌 실수투성이지만 무언가를 끊임없이 시도하고 도전하는 과정에서 친근한 감동과 웃음을 주는 애니메이션', '2006-12-18', 5.602, 8.1743, 3, NULL, 49, 0);
