INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (65143, '태양의 후예', '태양의 후예', 'drama', 'https://image.tmdb.org/t/p/w500/uzsPygxgGvVFMUCsK562leiBbpO.jpg', 'https://image.tmdb.org/t/p/original/o9Z8O0gdi6Qvvzk86RdnnBjBGDq.jpg', '낯선 땅 극한의 환경 속에서 사랑과 성공을 꿈꾸는 젊은 군인과 의사들을 통해 삶의 가치를 담아낸 블록버스터급 휴먼 멜로 드라마로 유럽의 발칸 반도에 위치한 가상 국가 우르크를 배경으로 전쟁과 질병으로 얼룩진 기상 이변 속에서 낯선 땅에 파병된 군인과 의사들을 통해 극한 상황 속에서도 사랑하고 연애하는 사람들의 전우애와 동기애를 담은 작품.', '2016-02-24', 8.368, 7.5391, 60, '백상훈', 778, 0);
