INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (99490, '한 번 다녀왔습니다', '한번 다녀왔습니다', 'drama', 'https://image.tmdb.org/t/p/w500/yNtwQZx9IcAuY1lUdx0npJqPUVK.jpg', 'https://image.tmdb.org/t/p/original/trOVoa8uRgD3HkZFtbldFQ0B6Xk.jpg', '바람 잘 날 없는 송가네의 파란만장한 스토리로, 이혼으로 시작해 결국 사랑과 가족애로 뭉치는 송가네 식구들과 사람 사는 냄새 풍기는 시장 사람들의 이야기를 다루는 작품. 용주시장에서 닭집을 운영하는 옥분은 요즘 행시 출신 5급사무관 영훈과 결혼할 막내딸 다희 때문에 어깨 뽕이 하늘을 찌른다. 정작 결혼 당사자인 막내딸 다희는 인턴생활에 쪼들려 결혼 준비는커녕 잡일에 시달려 잠잘 시간도 없이 바쁘기만 하고. 소아병원 내과의인 둘째딸 나희는 같은 병원에서 근무 중인 남편 규진과 점점 파국에 치닫는 결혼생활 때문에 지쳐만 간다. 마침내, 정신없이 결혼식을 치른 막내딸 다희는 상상 초월할 광경을 목격하는데...', '2020-03-28', 8.033, 6.8653, 35, 'Yang Hui-seung', 15, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (136915, '캐치! 티니핑', '캐치! 티니핑', 'drama', 'https://image.tmdb.org/t/p/w500/rY8QGWz7xdsBx6Em1WnpqQZ2oIU.jpg', 'https://image.tmdb.org/t/p/original/yPLWd31uUImEaeEA7qI28jGTjgR.jpg', '티니핑을 캐치하기 위해 지구에 온 이모션 왕국의 로미 공주! 베이커리 하트로즈에서 사촌언니를 도우며 일상을 보내지만, 티니핑이 나타나면 마법의 콤팩트로 티니핑을 캐치한다. 항상 옆을 지켜주는 로열 티니핑들과 어려움을 극복해가는 로미는 과연 티미핑을 모두 캐치하고 왕국으로 돌아 갈 수 있을까?', '2020-03-19', 7, 8.6736, 13, NULL, 4, 0);
