INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (18493, '아내의 유혹', '아내의 유혹', 'drama', 'https://image.tmdb.org/t/p/w500/2cJG73BzMj17p4KOkAwtClA20Zn.jpg', 'https://image.tmdb.org/t/p/original/34dZsnOC762ybcVNkpz0Fxs06cF.jpg', '바닷가, 물에 빠진 은재(장서희)는 제발 뱃속 아기만이라도 살려달라며 절규하고, 먼발치에서 바라보던 교빈(변우민)과 애리(김서형)은 고개를 돌려서 가버린다. 이때 은재는 가물가물해져가는 의식속에서 지나간 과거들이 하나씩 스쳐간다. 시간은 과거로 돌아가고, 고등학생 은재는 애리를 앞에 앉혀놓고 메이크업을 해주며 서로 웃는다. 잠시 후 학교에 간 은재는 꽃다발을 자신에게 건네는 교빈이 부끄러워 자리를 뜨고 만다. 다시 시간은 흐르고, 은재는 화려한 웨딩드레스를 입고서 교빈과 결혼식을 올리고…', '2008-11-03', 5.1, 8.5398, 35, NULL, 7, 0);
