INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (76241, '드라마 스테이지', '드라마 스테이지', 'drama', 'https://image.tmdb.org/t/p/w500/rTThC8x5n8Fd0U47PZuhGULURi5.jpg', 'https://image.tmdb.org/t/p/original/tYaciF3cvxq3S50NRCqQbAtt4Pt.jpg', '단막극은 드라마와 영화의 경계에 존재한다. 드라마에서 자기만의 세계를 보여준 연출가와 영화에서 실험적인 스타일을 보여준 연출가들이 모였다. 사회적 통찰을 보여주는 사회파 미스터리에서 촌철살인의 풍자극까지 다양한 작품을 선보이며, 이 작품들은 이 시대를 비추는 ''거울'' 이라는 키워드로 묶인다.', '2017-12-02', 4, 7.4617, 60, NULL, 3, 0);
