INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (110534, 'D.P.', 'D.P.', 'drama', 'https://image.tmdb.org/t/p/w500/ufovksqVTNogMdU5LlCVbJSiMVa.jpg', 'https://image.tmdb.org/t/p/original/yFNGc3OR81NGdJL3yZCBrjDIluf.jpg', '탈영병을 잡는다. 이등병 준호에게 떨어진 새로운 임무. 그는 탈영병들을 추적하며 지독하게 고통스러운 현실을 마주한다. 그리고 아무리 도망쳐도 벗어날 수 없다는 것도 알게 된다.', '2021-08-27', 8.014, 7.6498, 50, '김보통', 252, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (75820, '미스터 션샤인', '미스터 션샤인', 'drama', 'https://image.tmdb.org/t/p/w500/uSavP0BSfnyUaJe62f0ZTXIHLs8.jpg', 'https://image.tmdb.org/t/p/original/gQwa6X2nmTHkmDgAifU4wacNqp4.jpg', '2018년 7월 tvN에서 방영을 시작한 드라마. 신미양요(1871년)때 부모를 잃고 미 해군 군함 콜로라도 호에 승선해 미국에 떨어진 노비 출신 소년 유진(이병헌). 미국으로 건너가 갖은 차별을 이겨내고 군인이 된 그는 자신을 버린 조국인 조선으로 와 주둔하게 된다. 그에게 조선이란 제 부모를 때려죽인 나라이자, 자신이 도망쳐 나온 나라였으며, 양반들이 개화의 탈을 쓰고 앞다투어 매국을 하는 야만의 나라일 뿐이었다. 그러던 중 그는 남들 몰래 조선의 독립을 위해 싸우는 조선 최고 명문가의 영애, 애신(김태리)을 만나게 되는데...', '2018-07-07', 8.46, 8.0559, 75, '이응복', 176, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (156888, '마스크걸', '마스크걸', 'drama', 'https://image.tmdb.org/t/p/w500/urnfhsTOFtLuW61GFKS3OXCDMZl.jpg', 'https://image.tmdb.org/t/p/original/sfagVOgXVONyDAOI4BjnofLcYpv.jpg', '외모 콤플렉스를 가진 여자. 낮에는 평범한 직장인이지만, 밤이면 마스크로 얼굴을 가린 채 인터넷 방송 BJ로 변신한다. 그러던 중, 예기치 않은 불운한 사건이 연거푸 그녀의 삶을 엄습하는데...', '2023-08-18', 7.4, 7.0733, NULL, 'Kim Yong-hoon', 172, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (69087, '보이스', '보이스', 'drama', 'https://image.tmdb.org/t/p/w500/87dqnH6x5wSLR8Tr3jkW0zSyGRH.jpg', 'https://image.tmdb.org/t/p/original/i8iujCYtGOG8f6ui90ADs5NxHKb.jpg', '우리가 목숨걸고 지킨 ''3분''은 누군가의 인생이다. 상담원이라는 별명으로 불리며 가장 변방으로 취급 받지만, 사실 삶과 죽음을 가르는 가장 긴박한 순간들이 모인 ''112 신고센터''. ''3분 도착, 5분 현장 확인, 10분 검거''의 긴박한 타임 리밋 속에서 범죄현장의 골든타임을 사수하는 112 신고센터 대원들의 치열한 기록을 생생하게 담아내고, 우리 인생의 골든타임, 결코 포기해서는 안되는 그 순간의 용기에 대해 이야기한다. 범죄 현장의 골든타임을 사수하는 112 신고센터 대원들의 치열한 기록을 그린 드라마', '2017-01-14', 7.3, 6.1598, 60, 'Ma Jin-won', 68, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (121135, '속아도 꿈결', '속아도 꿈결', 'drama', 'https://image.tmdb.org/t/p/w500/30GtnXViH3QFlq8x7j3yW36qUwc.jpg', 'https://image.tmdb.org/t/p/original/k0nzf7GFmKUaBqfUGvlzD5d4Iv1.jpg', '서로 다른 문화의 금가네와 한가네 두 집안이 부모의 황혼 재혼으로 하나의 가족이 되어 가는 이야기를 그리는 드라마', '2021-03-29', 6.8, 7.5227, 30, NULL, 4, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (259015, '그놈은 흑염룡', '그놈은 흑염룡', 'drama', 'https://image.tmdb.org/t/p/w500/mi6Hx6pO1H557TJqyEcBwGvSRD3.jpg', 'https://image.tmdb.org/t/p/original/4Xer0oaXautbLRfJQOrlmPSCfN1.jpg', '2000년 온라인 게임에서 만난 첫사랑 오빠 "ID : 흑염룡". 그러나 그는 체인을 두른 패션으로 나타난 중2병, 아니 진짜 중2 였다! 그와의 흑역사를 남긴 채 10여년이 지나고, 새로 부임한 연하의 본부장에게서 흑염룡의 향기가 느껴진다. 혜진양의 동명 웹툰 원작', '2025-02-17', 7.769, 8.0078, 60, NULL, 93, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (68157, '삼시세끼 어촌편', '삼시세끼 어촌편', 'drama', 'https://image.tmdb.org/t/p/w500/tZCKvLfEsU6PVgjuHNNYACoksq0.jpg', 'https://image.tmdb.org/t/p/original/aevkKyYU1fTazDdkBd5XEEVBlwc.jpg', '2015년 1월 tvN에서 방영을 시작한 리얼리티쇼. 나영석 PD가 연출을 맡았다. 농촌을 벗어난 삼시세끼, 이번엔 어촌이다. 자급자족 어부 라이프를 슬로건으로 전라남도 신안군 흑산면 만재도와 전라남도 고흥군 도양읍 득량도를 오가며 정성스러운 한 끼를 찾아 떠나는출연진들의 고군분투 생존기를 그린다. 전작에 이어 환상의 케미를 자랑하는 차승원과 유해진 콤비, 이서진과 에릭, 윤균상 삼형제들과 그들을 찾아오는 게스트들이 등장하며, 전작보다 더욱 더 업그레이드된 요리들이 시청자의 눈을 현혹한다.', '2015-01-23', 8.1, 7.1975, 100, '나영석', 7, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (79603, '당신 참 예쁘다', '당신 참 예쁘다', 'drama', 'https://image.tmdb.org/t/p/w500/rTydXk0FoNkcoSiCBYeqRdaSer9.jpg', 'https://image.tmdb.org/t/p/original/6Zx9JBQjpfxP3dZbp7VgLYKjdee.jpg', '', '2011-04-04', 10, 7.927, 30, 'Kim Woo Sun', 1, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (88463, '아스달 연대기', '아스달 연대기', 'drama', 'https://image.tmdb.org/t/p/w500/raa566oA0cquXcS1b83TrWePJtT.jpg', 'https://image.tmdb.org/t/p/original/uDSnb7xvPziZedUzlrz3Za0YOz7.jpg', '그곳에서 모든 것이 시작됐다. 태고의 땅 아스. 권력을 향한 욕망, 새로운 사회에 대한 열망, 그리고 가슴 뛰는 사랑을 위해 치열하게 살아간 사람들이 있었다. 그 중심에 선 두 인물, 은섬과 타곤. 그들은 각각 어떠한 국가를 만들려 하는가. 결국 누가 그곳을 차지하게 되는가.', '2019-06-01', 7.743, 7.2232, 60, '김원석', 76, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (93643, 'TMI NEWS', 'TMI SHOW', 'drama', 'https://image.tmdb.org/t/p/w500/wJ779QoklVnX1LHoD4zyKeCfRpb.jpg', NULL, 'Mnet의 수요일 밤을 책임질 세계 최초 글로벌 아이돌 정보 과부하 차트쇼', '2019-04-25', 0, 9.7744, NULL, NULL, 0, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (70593, '킹덤', '킹덤', 'drama', 'https://image.tmdb.org/t/p/w500/zXfQcdTx0jxbH5Atpwjvb5z5VjE.jpg', 'https://image.tmdb.org/t/p/original/jRhJlV4inm8wAAqTeHUX5HpjZcc.jpg', '2019년 1월 Netflix에서 방영을 시작한 좀비물. 병든 왕을 둘러싸고 흉흉한 소문이 떠돈다. 왕에게 이상한 일이 벌어지고 있다는 걸 알게 된 왕세자 이창이 왕을 진료한 의원을 찾아 나선다. 어둠에 뒤덮인 조선, 기이한 역병에 신음하는 산하. 동래 지휼현에 왔다가 역병의 실체를 보게 되고, 호위무사인 무영과 함께 이 병이 전국적으로 퍼져나가는 걸 막기 위해 싸운다. 정체 모를 악에 맞서 백성을 구원할 희망은 오직 세자뿐인데...', '2019-01-25', 8.223, 7.2297, NULL, '김은희', 1165, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (293613, '피지컬: 아시아', '피지컬: 아시아', 'drama', 'https://image.tmdb.org/t/p/w500/7GbXnv3kvmATU0p6E5gC1AiNqtc.jpg', 'https://image.tmdb.org/t/p/original/823qOjKt0V0N9S6h2uoqu1IA15f.jpg', '8개국을 대표하는 피지컬 최강자들이 국가의 명예를 걸고 대결한다. 극한의 체력과 인내심의 한계를 건 치열한 전투 끝에 단 하나의 국기만이 남게 된다.', '2025-10-28', 7.359, 8.2883, NULL, '장호기', 32, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (285432, '지지고 볶는 여행', '지지고 볶는 여행', 'drama', 'https://image.tmdb.org/t/p/w500/gXhp7WslhyaDqb1LvCliQDMrbPl.jpg', 'https://image.tmdb.org/t/p/original/6cBWZ1Yc14gcioFUs7a20uwk3oK.jpg', '''지지고 볶고, 사랑하며 속 끓고 사는 것이 인생'' 이라는 캐치프레이즈 아래 나는 솔로 유니버스 내에서 여러 의미로 화제가 된 남녀 출연자들이 여행을 떠나는 과정에서 두 사람을 같은 방에 몰아넣는 지극히 남규홍 PD 스러운상황을 곁들인 리얼리티 여행 예능을 표방하고 있다.', '2025-02-28', 10, 3.4394, NULL, NULL, 1, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (197583, '사랑할 때까지', '사랑할 때까지', 'drama', 'https://image.tmdb.org/t/p/w500/lHgVbmtSFi01X05DRYk8k0bTNBO.jpg', 'https://image.tmdb.org/t/p/original/7PGR8ZbyJlcCgnC66yoDFQkhN2C.jpg', '변호사였던 남편과 사별한 뒤 안경 회사를 운영하며 꿋꿋하게 4남매를 길러낸 송 여사를 중심으로 시어머니, 아들·딸, 손자·손녀 등 대가족의 진솔한 삶을 그리는 홈드라마', '1996-04-01', 10, 7.315, NULL, NULL, 1, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (18495, '논스톱', '논스톱', 'drama', 'https://image.tmdb.org/t/p/w500/elXJzhz1dM0lO7fK2BfO2pVtC7l.jpg', 'https://image.tmdb.org/t/p/original/6HBi1vfb70PfeTx78BKv2md42mm.jpg', '문화 대학교의 밴드 동아리인 논스톱 밴드를 주무대로 펼쳐지는 대학생들의 사랑과 우정을 담은 청춘 시트콤 프로그램', '2000-05-15', 4.4, 8.4541, 25, NULL, 5, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (226529, '조명가게', '조명가게', 'drama', 'https://image.tmdb.org/t/p/w500/rTfS6UsdHNGdpSBL8RmEgaBoJrz.jpg', 'https://image.tmdb.org/t/p/original/bGcMuFVzW0LitMJWSzp4EjmzQ0b.jpg', '어두운 골목길 끝을 환하게 밝혀주는 조명가게는 오늘도 심야영업 중이다. 조명가게 사장은 한 분의 손님이 오더라도 장사를 한다는 원칙을 고수하며 매일 밤 손님들을 기다린다.', '2024-12-04', 8.415, 7.8497, 45, '강풀', 229, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (79069, '내일도 맑음', '내일도 맑음', 'drama', 'https://image.tmdb.org/t/p/w500/2F2RhfiIOFFDIOcmYx0eLqUY1gE.jpg', 'https://image.tmdb.org/t/p/original/4vWtb5Mta7QB9Q5H0WcwclyeDzI.jpg', '흙수저 무스펙 주인공이 그려내는 7전8기 인생 리셋 스토리와 주변 가족들의 살맛나는 이야기를 그린 드라마', '2018-05-07', 5.8, 7.4175, 35, NULL, 4, 0);
INSERT OR REPLACE INTO contents (tmdb_id, title, title_en, content_type, poster_url, backdrop_url, overview, release_date, rating, popularity, runtime, director, vote_count, is_adult) VALUES (57433, '힘내요, 미스터 김!', '힘내요, 미스터 김!', 'drama', 'https://image.tmdb.org/t/p/w500/cGh4xyixgKOeSl9Pu08WPUyOlHj.jpg', 'https://image.tmdb.org/t/p/original/cjGYMpMEAxBj2XlbX7BnFCDc6fd.jpg', '졸지에 각기 성(姓)이 다른 네 명의 아이들 보호자이자 야무진 손끝으로 주부들의 각광을 받는 아파트 입주청소부 겸 가사도우미 김태평의 따뜻한 가족애와 달달한 로맨스를 그린 가족극.', '2012-11-05', 0, 7.3647, 35, NULL, 0, 0);

